        public int fnAddItem(uint uInOrUPOrDel, string sItemCode, string sItemDescription, string sCreatedDate, double fUnitCost, string sType, string sStatus, string sRemarks, string sUnit, string sOthers, Double OpeningQuantity, string sPurchaseType, string sItemTypeCode, string sCreatedBy, string sLocation, string sHSNCode, string sDrawingNo, string TypeofStorage, decimal FixedCost)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (uInOrUPOrDel)
                {
                    case Global.uINSERT:
                        {
                            SQLCmd = new SqlCommand(@"Insert into ItemMaster(ItemCode,ItemDescription,CreatedDate,UnitCost,Type,Status,Remarks,Units,Others,OpeningQuantity,PurchaseType,ItemTypeCode,CreatedBy,AvailableQty,Location,HSNSACCode,DrawingNo,TypeofStorage,FixedCost)
                                                        values('" + sItemCode.Trim() + "','" + sItemDescription.Trim() + "','" + sCreatedDate + "','" + fUnitCost + "','" + sType + "','" + sStatus + "','" + sRemarks + "','" + sUnit + "','" + sOthers + "','" + OpeningQuantity + "','" + sPurchaseType + "','" + sItemTypeCode + "','" + sCreatedBy + "','0.0','" + sLocation + "','" + sHSNCode + "','" + sDrawingNo + "','" + TypeofStorage + "','" + FixedCost + "')", SQLCon);
                            break;
                        }
                    case Global.uUPDATE:
                        {
                            SQLCmd = new SqlCommand("Update ItemMaster set ItemDescription='" + sItemDescription.Trim() + "',Status='" + sStatus + "',FixedCost='" + FixedCost + "',Remarks='" + sRemarks + "',Units='" + sUnit + "',Others='" + sOthers + "',PurchaseType='" + sPurchaseType + "', Location='" + sLocation + "', HSNSACCode='" + sHSNCode + "',DrawingNo='" + sDrawingNo + "',TypeofStorage='" + TypeofStorage + "' where ItemCode='" + sItemCode + "'", SQLCon);
                            break;
                        }
                    case Global.uDELETE:
                        {
                            SQLCmd = new SqlCommand("Delete from ItemMaster where ItemCode='" + sItemCode + "'", SQLCon);
                            break;
                        }

                    case 5:
                        {
                            SQLCmd = new SqlCommand("Update ItemMaster set FixedCost='" + FixedCost + "' where ItemCode='" + sItemCode + "'", SQLCon);
                            break;
                        }

                    case 6:
                        {
                            SQLCmd = new SqlCommand("Update KanBanElectronicsItemMaster set UnitCost='" + fUnitCost + "' where ItemCode='" + sItemCode + "'", SQLCon);
                            break;
                        }

                    case 7:
                        {
                            SQLCmd = new SqlCommand("Update KanBanItemMaster set UnitCost='" + fUnitCost + "' where ItemCode='" + sItemCode + "'", SQLCon);
                            break;
                        }

                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }

