        public int fnAddItemCostHistory(uint uInOrUPOrDel, string sItemCode, double OldUnitCost, double fUnitCost, string sUpdatedBy)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (uInOrUPOrDel)
                {
                    case 0:
                        {
                            SQLCmd = new SqlCommand(@"Insert into ItemCostUpdateHistory([ItemCode],[OldUnitCost],[UnitCost],[UpdatedBy])
                                                        values('" + sItemCode.Trim() + "','" + OldUnitCost + "','" + fUnitCost + "','" + sUpdatedBy + "')", SQLCon);
                            break;
                        }

                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;

            }
        }
        //bhavya added for reports 
        public DataTable fnLoadEnabledReports(string loginId)
        {
            DataTable dtReports = new DataTable();

            try
            {
                SQLCon.Open();

                SQLCmd = new SqlCommand(
                    @"SELECT ReportName 
              FROM UserReports 
              WHERE LoginId = @LoginId AND IsEnabled = 1",
                    SQLCon);
                SQLCmd.Parameters.AddWithValue("@LoginId", loginId);

                using (SqlDataReader reader = SQLCmd.ExecuteReader())
                {
                    dtReports.Load(reader); // Fill DataTable directly
                }

                SQLCon.Close();
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                if (SQLCon.State == ConnectionState.Open) SQLCon.Close();
            }

            return dtReports;
        }





        public DataSet fnItemList(string sItemCode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sItemCode == null)
                    SQLCmd = new SqlCommand("SET DATEFORMAT dmy; Select  RTRIM(LTRIM([ItemCode])) as [ItemCode],[ItemDescription],convert(date,[CreatedDate],105) as [CreatedDate],[Type],[Status],[Remarks] ,[Others],[MinStockQty],Issue,[Receipt],[OpeningQuantity],[DrawingNo],[AvailableQty],[Units],round([UnitCost],2)as UnitCost,StockValue=(UnitCost * AvailableQty),ItemTypeCode,ID,HSNSACCode from ItemMaster where [Type]!='Kan Ban' and [Status]!='Deactive'", SQLCon);
                else
                    SQLCmd = new SqlCommand("SET DATEFORMAT dmy; Select RTRIM(LTRIM([ItemCode])) as [ItemCode],[ItemDescription],convert(date,[CreatedDate],105) as[CreatedDate],[UnitCost],[Type],[Status],[Remarks],[Others],[MinStockQty] ,[Issue],[Receipt] ,[OpeningQuantity],[ClosingQuantity],[StockValue],[Units],[PurchaseType] ,[AvailableQty],[ItemTypeCode],[CreatedBy],[ID],Location,HSNSACCode FROM [ItemMaster] where ItemCode='" + sItemCode + "' and  [Type]!='Kan Ban' and [Status]!='Deactive'", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

