        public DataSet fnItemMasterServiceItems(string sItemCode)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet(); // Ensure a fresh dataset for each call

                if (sItemCode == null)
                    SQLCmd = new SqlCommand("SET DATEFORMAT dmy; Select ID, RTRIM(LTRIM([ItemCode])) as [ItemCode],[ItemDescription] from ItemMaster where [Type]='Service(Non-Inventory)' and [Status]!='Deactive'", SQLCon);
                else
                    SQLCmd = new SqlCommand("SET DATEFORMAT dmy; Select  ID,RTRIM(LTRIM([ItemCode])) as [ItemCode],[ItemDescription],HSNSACCode FROM [ItemMaster] where ID='" + sItemCode + "' and [Type]='Service(Non-Inventory)'", SQLCon);

                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);

                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                return null;
            }
            finally
            {
                SQLCon.Close(); // Ensure connection is closed
            }
        }


        public DataSet fnStandardCostItemList(string sID)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sID == null)
                {
                    SQLCmd = new SqlCommand(@"Select  HSNSACCode,[ItemCode],[ItemDescription], UnitCost,[Units],[AvailableQty],'0.0' as [SixMonths],
                                            '0.0' as [TwelveMonths],'1' as ReqQty,'1' as IGSTRate,'1' as IGSTAmount,'1' as SGSTRate,
                                            '1' as SGSTAmount,'1' as CGSTRate,'1' as CGSTAmount,'0' as BOMQty,'' as BOMProjectList,
                                            UnitCost as StandardCost,'0' as DiffrenceinPer,'0' as DiffrenceinRs,'0' as LatestPurchasePrice   FROM [ItemMaster] where Id=''", SQLCon);
                }
                // else
                // SQLCmd = new SqlCommand(@"Select HSNSACCode,[ItemCode],[ItemDescription],[CreatedDate],ROUND(UnitCost,2) as [UnitCost],[Type],[Status],[Remarks],[Others]
                //  ,[MinStockQty],[Issue],[Receipt],[OpeningQuantity],[ClosingQuantity],[StockValue]
                //  ,[Units],[PurchaseType],[AvailableQty],[ItemTypeCode],[CreatedBy],[ID],[Location],'1' as ReqQty FROM [ItemMaster] where ID='" + sID + "' and  [Type]!='Kan Ban'", SQLCon);


                else
                {
                    SQLCmd = new SqlCommand(@"SELECT
                                            IM.HSNSACCode,
                                            IM.ItemCode,
                                            IM.ItemDescription,
                                            IM.CreatedDate,
                                            ROUND(IM.UnitCost, 2) AS UnitCost,
                                            IM.[Type],
                                            IM.[Status],
                                            IM.Remarks,
                                            IM.Others,
                                            IM.MinStockQty,
                                            IM.Issue,
                                            IM.Receipt,
                                            IM.OpeningQuantity,
                                            IM.ClosingQuantity,
                                            IM.StockValue,
                                            IM.Units,
                                            IM.PurchaseType,
                                            IM.AvailableQty,
                                            IM.ItemTypeCode,
                                            IM.CreatedBy,
                                            IM.ID,
                                            IM.Location,
                                            '1' AS ReqQty,
                                            EIL.Location AS ItemLocation     
                                        FROM ItemMaster AS IM
                                        LEFT JOIN ERPItemLocation AS EIL
                                            ON EIL.ItemCode = IM.ItemCode
                                        WHERE ID='" + sID + "'  AND IM.[Type] <> 'Kan Ban'", SQLCon);
                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

