        public DataSet filterStockBalance_old(string type, string storeName, string subStore, string Category)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (type == "Without BatchWise")
                {
                    SQLCmd = new SqlCommand($@"
                                    DECLARE @StoreName NVARCHAR(100) = '{storeName}';     
                                    DECLARE @Floor     NVARCHAR(50)  = '{subStore}';    
                                    DECLARE @Location  NVARCHAR(100) = NULL;    
                                    DECLARE @ItemCode  NVARCHAR(100) = NULL;    

                                    SELECT
                                        IM.ItemCode,
                                        IM.ItemDescription,
    
                                        CONVERT(date, IM.CreatedDate, 105) AS CreatedDate,
                                        IM.UnitCost,
                                        IM.[Type],
                                        IM.[Status],
                                        IM.Remarks,
                                        IM.Others,
                                        IM.MinStockQty,
                                        IM.StockValue,
                                        IM.Units,
                                        IM.PurchaseType,
                                        IM.AvailableQty,
                                        IM.ItemTypeCode,
                                        IM.CreatedBy,
                                        IM.ID,

   
                                        ItemLocation = (
                                            SELECT STRING_AGG(EIL.Location, ',')
                                            FROM ERPItemLocation AS EIL
                                            WHERE EIL.ItemCode = IM.ItemCode
                                              AND (@StoreName IS NULL OR EIL.Store   = @StoreName)
                                              AND (@Floor     IS NULL OR EIL.Floor   = @Floor)
                                              AND (@Location  IS NULL OR EIL.Location = @Location)
                                        ),

  
                                        BatchCodes = (
                                            SELECT STRING_AGG(CAST(L.BatchCode AS NVARCHAR(100)), '/')
                                            FROM ERPInventoryLogs AS L
                                            WHERE L.ItemCode = IM.ItemCode
                                              AND L.BatchCode IS NOT NULL
        
                                              AND (
                                                  @Location IS NULL
                                                  OR L.ItemLocation = @Location
                                                  OR EXISTS (
                                                      SELECT 1
                                                      FROM ERPItemLocation E
                                                      WHERE E.ItemCode = IM.ItemCode
                                                        AND (@StoreName IS NULL OR E.Store   = @StoreName)
                                                        AND (@Floor     IS NULL OR E.Floor   = @Floor)
                                                        AND (@Location  IS NULL OR E.Location = @Location)
                                                                           AND E.Location = L.ItemLocation
                                                  )
                                              )
                                        )
                                    FROM ItemMaster AS IM
                                    WHERE
                                        (@ItemCode IS NULL OR IM.ItemCode = @ItemCode) and AvailableQty > 0", SQLCon);
                }
                else if (type == "BatchWise")
                {

                    if (storeName != null && subStore == null)
                    {
                        SQLCmd = new SqlCommand($@"
                                               
                                                DECLARE @StoreName NVARCHAR(100) = '{storeName}';  
                                                DECLARE @Floor     NVARCHAR(50)  = NULL;  
                                                DECLARE @Location  NVARCHAR(100) = NULL;  

                                                SELECT
                                                    L.ItemCode,
                                                    MIN(L.ItemDescription) AS ItemDescription,          
                                                       MIN(L.CreatedDate)     AS CreatedDate,                
                                                    Ageing = DATEDIFF(DAY, MIN(L.GINServerTime), GETDATE()),  
                                                    SUM(L.RemainingQty)    AS AvailableQty,               
                                                    AVG(L.UnitCost)        AS UnitCost,                  
                                                    StockValue = SUM(L.RemainingQty * L.UnitCost),       
                                                    L.BatchCode,
                                                    L.ItemLocation,
                                                    MIN(L.GINServerTime)   AS FirstGINServerTime,
                                                    MAX(L.GINServerTime)   AS LastGINServerTime,
                                                  
                                                    MIN(E.Store)           AS StoreName,
                                                    MIN(E.Floor)           AS StoreFloor
                                                FROM ERP_Database.dbo.ItemMaster       AS IM
                                                INNER JOIN ERP_Database.dbo.ERPInventoryLogs AS L
                                                        ON L.ItemCode = IM.ItemCode
                                                LEFT  JOIN ERP_Database.dbo.ERPItemLocation  AS E
                                                        ON E.ItemCode = L.ItemCode
                                                       AND E.Location = L.ItemLocation
                                                WHERE
                                                    L.RemainingQty > 0
                                                    AND (
                                                       
                                                         (@StoreName IS NULL AND @Floor IS NULL AND @Location IS NULL)
                                                        
                                                         OR (
                                                             (@StoreName IS NULL OR E.Store   = @StoreName)
                                                             AND (@Floor     IS NULL OR E.Floor   = @Floor)
                                                             AND (@Location  IS NULL OR E.Location = @Location)
                                                         )
                                                    )
                                                GROUP BY
                                                    L.ItemCode,
                                                    L.BatchCode,
                                                    L.ItemLocation
                                                ORDER BY
                                                    L.ItemCode,
                                                    L.BatchCode", SQLCon);
                    }

                    if (subStore != null && storeName == null)
                    {
                        SQLCmd = new SqlCommand($@"
                                               
                                                DECLARE @StoreName NVARCHAR(100) = NULL;  
                                                DECLARE @Floor     NVARCHAR(50)  = {subStore};  
                                                DECLARE @Location  NVARCHAR(100) = NULL;  

                                                SELECT
                                                    L.ItemCode,
                                                    MIN(L.ItemDescription) AS ItemDescription,          
                                                       MIN(L.CreatedDate)     AS CreatedDate,                
                                                    Ageing = DATEDIFF(DAY, MIN(L.GINServerTime), GETDATE()),  
                                                    SUM(L.RemainingQty)    AS AvailableQty,               
                                                    AVG(L.UnitCost)        AS UnitCost,                  
                                                    StockValue = SUM(L.RemainingQty * L.UnitCost),       
                                                    L.BatchCode,
                                                    L.ItemLocation,
                                                    MIN(L.GINServerTime)   AS FirstGINServerTime,
                                                    MAX(L.GINServerTime)   AS LastGINServerTime,
                                                  
                                                    MIN(E.Store)           AS StoreName,
                                                    MIN(E.Floor)           AS StoreFloor
                                                FROM ERP_Database.dbo.ItemMaster       AS IM
                                                INNER JOIN ERP_Database.dbo.ERPInventoryLogs AS L
                                                        ON L.ItemCode = IM.ItemCode
                                                LEFT  JOIN ERP_Database.dbo.ERPItemLocation  AS E
                                                        ON E.ItemCode = L.ItemCode
                                                       AND E.Location = L.ItemLocation
                                                WHERE
                                                    L.RemainingQty > 0
                                                    AND (
                                                       
                                                         (@StoreName IS NULL AND @Floor IS NULL AND @Location IS NULL)
                                                        
                                                         OR (
                                                             (@StoreName IS NULL OR E.Store   = @StoreName)
                                                             AND (@Floor     IS NULL OR E.Floor   = @Floor)
                                                             AND (@Location  IS NULL OR E.Location = @Location)
                                                         )
                                                    )
                                                GROUP BY
                                                    L.ItemCode,
                                                    L.BatchCode,
                                                    L.ItemLocation
                                                ORDER BY
                                                    L.ItemCode,
                                                    L.BatchCode", SQLCon);
                    }
                    //  }
                    // else {

                    if (storeName != null && subStore != null)
                    {
                        SQLCmd = new SqlCommand($@"
                                               
                                                DECLARE @StoreName NVARCHAR(100) = '{storeName}';  
                                                DECLARE @Floor     NVARCHAR(50)  = {subStore};  
                                                DECLARE @Location  NVARCHAR(100) = NULL;  

                                                SELECT
                                                    L.ItemCode,
                                                    MIN(L.ItemDescription) AS ItemDescription,          
                                                       MIN(L.CreatedDate)     AS CreatedDate,                
                                                    Ageing = DATEDIFF(DAY, MIN(L.GINServerTime), GETDATE()),  
                                                    SUM(L.RemainingQty)    AS AvailableQty,               
                                                    AVG(L.UnitCost)        AS UnitCost,                  
                                                    StockValue = SUM(L.RemainingQty * L.UnitCost),       
                                                    L.BatchCode,
                                                    L.ItemLocation,
                                                    MIN(L.GINServerTime)   AS FirstGINServerTime,
                                                    MAX(L.GINServerTime)   AS LastGINServerTime,
                                                  
                                                    MIN(E.Store)           AS StoreName,
                                                    MIN(E.Floor)           AS StoreFloor
                                                FROM ERP_Database.dbo.ItemMaster       AS IM
                                                INNER JOIN ERP_Database.dbo.ERPInventoryLogs AS L
                                                        ON L.ItemCode = IM.ItemCode
                                                LEFT  JOIN ERP_Database.dbo.ERPItemLocation  AS E
                                                        ON E.ItemCode = L.ItemCode
                                                       AND E.Location = L.ItemLocation
                                                WHERE
                                                    L.RemainingQty > 0
                                                    AND (
                                                       
                                                         (@StoreName IS NULL AND @Floor IS NULL AND @Location IS NULL)
                                                        
                                                         OR (
                                                             (@StoreName IS NULL OR E.Store   = @StoreName)
                                                             AND (@Floor     IS NULL OR E.Floor   = @Floor)
                                                             AND (@Location  IS NULL OR E.Location = @Location)
                                                         )
                                                    )
                                                GROUP BY
                                                    L.ItemCode,
                                                    L.BatchCode,
                                                    L.ItemLocation
                                                ORDER BY
                                                    L.ItemCode,
                                                    L.BatchCode", SQLCon);
                    }
                    else if (storeName == null && subStore == null)
                    {



                        SQLCmd = new SqlCommand($@"
                                               
                                                DECLARE @StoreName NVARCHAR(100) = NULL;  
                                                DECLARE @Floor     NVARCHAR(50)  = NULL;  
                                                DECLARE @Location  NVARCHAR(100) = NULL;  

                                                SELECT
                                                    L.ItemCode,
                                                    MIN(L.ItemDescription) AS ItemDescription,          
                                                       MIN(L.CreatedDate)     AS CreatedDate,                
                                                    Ageing = DATEDIFF(DAY, MIN(L.GINServerTime), GETDATE()),  
                                                    SUM(L.RemainingQty)    AS AvailableQty,               
                                                    AVG(L.UnitCost)        AS UnitCost,                  
                                                    StockValue = SUM(L.RemainingQty * L.UnitCost),       
                                                    L.BatchCode,
                                                    L.ItemLocation,
                                                    MIN(L.GINServerTime)   AS FirstGINServerTime,
                                                    MAX(L.GINServerTime)   AS LastGINServerTime,
                                                  
                                                    MIN(E.Store)           AS StoreName,
                                                    MIN(E.Floor)           AS StoreFloor
                                                FROM ERP_Database.dbo.ItemMaster       AS IM
                                                INNER JOIN ERP_Database.dbo.ERPInventoryLogs AS L
                                                        ON L.ItemCode = IM.ItemCode
                                                LEFT  JOIN ERP_Database.dbo.ERPItemLocation  AS E
                                                        ON E.ItemCode = L.ItemCode
                                                       AND E.Location = L.ItemLocation
                                                WHERE
                                                    L.RemainingQty > 0
                                                    AND (
                                                       
                                                         (@StoreName IS NULL AND @Floor IS NULL AND @Location IS NULL)
                                                        
                                                         OR (
                                                             (@StoreName IS NULL OR E.Store   = @StoreName)
                                                             AND (@Floor     IS NULL OR E.Floor   = @Floor)
                                                             AND (@Location  IS NULL OR E.Location = @Location)
                                                         )
                                                    )
                                                GROUP BY
                                                    L.ItemCode,
                                                    L.BatchCode,
                                                    L.ItemLocation
                                                ORDER BY
                                                    L.ItemCode,
                                                    L.BatchCode", SQLCon);
                    }

                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet filterStockBalance(string type,
                                  string storeName,
                                  string subStore,
                                  string Category)          // Category is still unused
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();

                /*--------------------------------------------------
                 * 1.  WITHOUT BATCH-WISE (unchanged)
                 *-------------------------------------------------*/
                if (false)//type == "Without BatchWise" &&
                {
                    SQLCmd = new SqlCommand($@"
                        DECLARE @StoreName NVARCHAR(100) = {(storeName == null ? "NULL" : $"'{storeName}'")};
                        DECLARE @Floor     NVARCHAR(50)  = {(subStore == null ? "NULL" : $"'{subStore}'")};
                        DECLARE @Location  NVARCHAR(100) = NULL;   -- always NULL in current signature
                        DECLARE @ItemCode  NVARCHAR(100) = NULL;   -- add UI later if needed

                        SELECT
                            IM.ItemCode,
                            IM.ItemDescription,
                            CONVERT(date, IM.CreatedDate, 105) AS CreatedDate,
                            IM.UnitCost,
                            IM.[Type],
                            IM.[Status],
                            IM.Remarks,
                            IM.Others,
                            IM.MinStockQty,
                            IM.StockValue,
                            IM.Units,
                            IM.PurchaseType,
                            IM.AvailableQty,
                            IM.ItemTypeCode,
                            IM.CreatedBy,
                            IM.ID,

                            /* locations that match the same filters */
                            ItemLocation = (
                                SELECT STRING_AGG(EIL.Location, ',')
                                FROM ERPItemLocation AS EIL
                                WHERE EIL.ItemCode = IM.ItemCode
                                  AND (@StoreName IS NULL OR EIL.Store   = @StoreName)
                                  AND (@Floor     IS NULL OR EIL.Floor   = @Floor)
                                  AND (@Location  IS NULL OR EIL.Location = @Location)
                            ),

                            /* batch codes only for the locations above */
                            BatchCodes = (
                                SELECT STRING_AGG(CAST(L.BatchCode AS NVARCHAR(100)), '/')
                                FROM ERPInventoryLogs AS L
                                WHERE L.ItemCode = IM.ItemCode
                                  AND L.BatchCode IS NOT NULL
                                  AND EXISTS (
                                      SELECT 1
                                      FROM ERPItemLocation E
                                      WHERE E.ItemCode = IM.ItemCode
                                        AND E.Location = L.ItemLocation
                                        AND (@StoreName IS NULL OR E.Store   = @StoreName)
                                        AND (@Floor     IS NULL OR E.Floor   = @Floor)
                                        AND (@Location  IS NULL OR E.Location = @Location)
                                  )
                            )

                        FROM ItemMaster AS IM
                        WHERE IM.AvailableQty > 0
                          AND (@ItemCode IS NULL OR IM.ItemCode = @ItemCode) 
                          /* >>>  real filter: keep only items that sit in the chosen place  <<< */
                          AND EXISTS (
                              SELECT 1
                              FROM ERPItemLocation EIL
                              WHERE EIL.ItemCode = IM.ItemCode
                                AND (@StoreName IS NULL OR EIL.Store   = @StoreName)
                                AND (@Floor     IS NULL OR EIL.Floor   = @Floor)
                                AND (@Location  IS NULL OR EIL.Location = @Location)
                          );", SQLCon);



                }



                if (type == "Without BatchWise")
                {

                    SQLCmd = new SqlCommand($@"
                   DECLARE @StoreName NVARCHAR(100) = {(storeName == null ? "NULL" : $"'{storeName}'")};
                    DECLARE @Floor     NVARCHAR(50) = {(subStore == null ? "NULL" : $"'{subStore}'")};
                    DECLARE @Location  NVARCHAR(100) = NULL; --kept for future UI
                 DECLARE @ItemCode  NVARCHAR(100) = NULL;

                                                SELECT
                                IM.ItemCode,
                                IM.ItemDescription,
                                CONVERT(date, IM.CreatedDate, 105) AS CreatedDate,
                                IM.UnitCost,
                                IM.[Type],
                                IM.[Status],
                                IM.Remarks,
                                IM.Others,
                                IM.MinStockQty,
                                IM.StockValue,
                                IM.Units,
                                IM.PurchaseType,
                                IM.AvailableQty,
                                IM.ItemTypeCode,
                                IM.CreatedBy,
                                IM.ID,

                                /* all locations (blank if none) */
                                ISNULL((
                                    SELECT STRING_AGG(EIL.Location, ',')
                                    FROM ERPItemLocation EIL
                                    WHERE EIL.ItemCode = IM.ItemCode
                                      AND(@StoreName IS NULL OR EIL.Store = @StoreName)
                                      AND(@Floor     IS NULL OR EIL.Floor = @Floor)
                                ), '')                                          AS ItemLocation,

                                /* batch codes that belong to those locations */
                                ISNULL((
                                    SELECT STRING_AGG(CAST(L.BatchCode AS NVARCHAR(100)), '/')
                                    FROM ERPInventoryLogs L
                                    WHERE L.ItemCode = IM.ItemCode
                                      AND L.BatchCode IS NOT NULL
                                      AND EXISTS(
                                          SELECT 1
                                          FROM ERPItemLocation E
                                          WHERE E.ItemCode = IM.ItemCode
                                            AND E.Location = L.ItemLocation
                                            AND(@StoreName IS NULL OR E.Store = @StoreName)
                                            AND(@Floor     IS NULL OR E.Floor = @Floor)
                                      )
                                ), '')                                          AS BatchCodes

                            FROM ItemMaster IM
                            WHERE 1 = 1
                              /* -----  optional filters  ----- */
                              AND(@ItemCode IS NULL OR IM.ItemCode = @ItemCode)
                              AND(@StoreName IS NULL OR EXISTS(SELECT 1
                                                                 FROM ERPItemLocation EIL
                                                                 WHERE EIL.ItemCode = IM.ItemCode
                                                                   AND EIL.Store = @StoreName))
                              AND(@Floor IS NULL OR EXISTS(SELECT 1
                                                             FROM ERPItemLocation EIL
                                                             WHERE EIL.ItemCode = IM.ItemCode
                                                               AND EIL.Floor = @Floor))
                              /* comment / uncomment next line if you want to keep zero-stock rows */
                               AND IM.AvailableQty > 0
                            ; ", SQLCon);


                }



                /*--------------------------------------------------
                 * 2.  BATCH-WISE – one flexible query
                 *-------------------------------------------------*/
                else if (type == "BatchWise")
                {
                    /*--------------------------------------------------
                     * Build the three predicates dynamically.
                     * We still declare the variables inside SQL so that
                     * the plan cache is not polluted by concatenated values.
                     *-------------------------------------------------*/
                    var storePred = storeName == null
                        ? "(@StoreName IS NULL)"
                        : "E.Store = @StoreName";

                    var floorPred = subStore == null
                        ? "(@Floor IS NULL)"
                        : "E.Floor = @Floor";

                    /* Location is always NULL in the current call signature */
                    const string locationPred = "(@Location IS NULL OR E.Location = @Location)";

                    SQLCmd = new SqlCommand($@"
                DECLARE @StoreName NVARCHAR(100) = {(storeName == null ? "NULL" : $"'{storeName}'")};
                DECLARE @Floor     NVARCHAR(50)  = {(subStore == null ? "NULL" : $"'{subStore}'")};
                DECLARE @Location  NVARCHAR(100) = NULL;

                SELECT
                    L.ItemCode,
                    MIN(L.ItemDescription)   AS ItemDescription,
                    MIN(L.CreatedDate)       AS CreatedDate,
                    Ageing       = DATEDIFF(DAY, MIN(L.GINServerTime), GETDATE()),
                    SUM(L.RemainingQty)      AS AvailableQty,
                    AVG(L.UnitCost)          AS UnitCost,
                    StockValue   = SUM(L.RemainingQty * L.UnitCost),
                    L.BatchCode,
                    L.ItemLocation,
                    MIN(L.GINServerTime)     AS FirstGINServerTime,
                    MAX(L.GINServerTime)     AS LastGINServerTime,
                    MIN(E.Store)             AS StoreName,
                    MIN(E.Floor)             AS StoreFloor
                FROM ERP_Database.dbo.ItemMaster       AS IM
                JOIN ERP_Database.dbo.ERPInventoryLogs AS L
                     ON L.ItemCode = IM.ItemCode
                LEFT JOIN ERP_Database.dbo.ERPItemLocation AS E
                     ON E.ItemCode = L.ItemCode
                    AND E.Location = L.ItemLocation
                WHERE L.RemainingQty > 0
                  AND (
                          (@StoreName IS NULL AND @Floor IS NULL AND @Location IS NULL)
                       OR ({storePred} AND {floorPred} AND {locationPred})
                      )
                GROUP BY L.ItemCode, L.BatchCode, L.ItemLocation
                ORDER BY L.ItemCode, L.BatchCode", SQLCon);
                }
                else
                {
                    throw new ArgumentException("Invalid type. Use 'BatchWise' or 'Without BatchWise'.");
                }

                /*--------------------------------------------------
                 * 3.  Common execution
                 *-------------------------------------------------*/
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                return null;
            }
            finally
            {
                if (SQLCon.State == ConnectionState.Open)
                    SQLCon.Close();
            }
        }





