        public DataSet fnPOlistforview(int iCase, string sFromdate, string sTodate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"select po.[DBOMNo],DATEDIFF(day,convert(date,po.[PODeliveryDate],105), GETDATE()) AS [POLateBy],convert(date,po.[PODeliveryDate],105) as PODeliveryDate,po.[ProjectCode],
                                              pj.[ProjectDescription],po.[VendorCode],vn.[VendorName],po.[PreparedBy],po.[POPreparedDate],
                                              po.[ItemCode],itm.ItemDescription,po.[RequariedQty],po.[RemainingQty],po.[UnitPrice],po.[Amount],po.[POGeneratedBy],
                                              po.[POGeneratedDate],po.[Remarks]  ,[PMName],[PMApprovedDate],[MHName],[MHApprovedDate],[MHApproved],[PurchaseCommitee],[PCAuthoriseDate],[FinalizedBy],[FinalizedDate] ,[FinanceApproverName],[FinanceApprovedDate],[FinalStatus], [FinalComment] from [PurchaseOrder] po join [dbo].[ProjectMaster] pj on po.ProjectCode=pj.ProjectCode 
                                              join [dbo].[Vendors] vn on po.VendorCode=vn.VendorCode join [dbo].[ItemMaster] itm on po.ItemCode=itm.ItemCode 
                                              where po.[RemainingQty]!='0' and (po.AuthoriedBy!='Deleted'or po.POGeneratedBy!='Deleted') and po.POGeneratedBy is not null  order by po.[DBOMNo] desc", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand(@"select po.[DBOMNo],DATEDIFF(day,convert(date,po.[PODeliveryDate],105), GETDATE()) AS [POLateBy],convert(date,po.[PODeliveryDate],105) as PODeliveryDate,po.[ProjectCode],
                                              pj.[ProjectDescription],po.[VendorCode],vn.[VendorName],po.[PreparedBy],po.[POPreparedDate],po.[PMName],convert(date,po.[PMApprovedDate],105) as[PMApprovedDate],po.[MHName],convert(date,po.[MHApprovedDate],105) as[MHApprovedDate],po.[PurchaseCommitee],convert(date,po.[PCAuthoriseDate],105) as[PCAuthoriseDate],
                                              po.[ItemCode],itm.ItemDescription,po.[RequariedQty],po.[RemainingQty],po.[UnitPrice],po.[Amount] ,po.[POGeneratedBy],
                                              po.[POGeneratedDate],po.[Remarks],[FinalStatus], [FinalComment] from [PurchaseOrder] po join [dbo].[ProjectMaster] pj on po.ProjectCode=pj.ProjectCode 
                                              join [dbo].[Vendors] vn on po.VendorCode=vn.VendorCode join [dbo].[ItemMaster] itm on po.ItemCode=itm.ItemCode 
                                              where po.[RemainingQty]!='0' and (po.AuthoriedBy!='Deleted'or po.POGeneratedBy!='Deleted') and po.POGeneratedBy is not null and  
                                              (convert(date,[POGeneratedDate],105) >= '" + sFromdate + "' AND convert(date,[POGeneratedDate],105) <= '" + sTodate + "')  order by po.[DBOMNo] desc ", SQLCon);
                        break;

                    case 2:
                        SQLCmd = new SqlCommand(@"SELECT [DBOMNo] as [PO No],P.VendorCode,
                                                    V.VendorName,P.[ItemCode], IM.ItemDescription,[RequariedQty],[RemainingQty] ,[POGeneratedBy],convert(date,[POGeneratedDate],105) as [POGeneratedDate],convert(date,[PODeliveryDate],105) as [PO DeliveryDate],convert(date,R.[Date],105) AS [GIN Date],
                                                    CASE WHEN [RemainingQty] =0 THEN 'GIN' WHEN ([RemainingQty]<RequariedQty and RemainingQty>0) THEN 'Partial GIN'  ELSE 'Pending' END as GINStatus,
                                                    DATEDIFF(day,convert(date,P.[PODeliveryDate],105), convert(date,R.[Date],105)) AS [PO Late By] FROM [PurchaseOrder] p join ProjectMaster PM on P.[ProjectCode]=PM.[ProjectCode] 
                                                    Join Vendors V on P.VendorCode=V.VendorCode join ItemMaster IM on P.Itemcode=IM.ItemCode
                                                    left join Receipt R on p.DBOMNo=R.RefNumber and p.ItemCode=R.ItemCode
                                                where convert(date,[PODeliveryDate],105)>='" + sFromdate + "' and convert(date,[PODeliveryDate],105)<='" + sTodate + "' and POGeneratedBy is not null and POGeneratedBy!='Deleted'", SQLCon);
                        break;

                    case 3:
                        SQLCmd = new SqlCommand(@"select po.[DBOMNo],DATEDIFF(day,convert(date,po.[PODeliveryDate],105), GETDATE()) AS [POLateBy],po.[PreparedBy],
                                                    L.Department from [PurchaseOrder] po  join Login L on po.PreparedBy=L.UserName
                                                    where po.[RemainingQty]!='0' and (po.AuthoriedBy!='Deleted'or po.POGeneratedBy!='Deleted')  and DATEDIFF(day,convert(date,po.[PODeliveryDate],105), GETDATE())>0 and po.POGeneratedBy is not null", SQLCon);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand(@"select PO.PreparedBy, COUNT(PO.PreparedBy ) as Nos from [PurchaseOrder] po 
                                                    join Login L on po.PreparedBy=L.UserName
                                                    where po.[RemainingQty]!='0' and (po.AuthoriedBy!='Deleted'or po.POGeneratedBy!='Deleted') and po.POGeneratedBy is not null group by PO.PreparedBy", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnPOlistCompleteview(int iCase, string sFromdate, string sTodate)
        {
            try
            {
                SQLDataset = new DataSet();
