        public DataSet fnWIPProjectListCount(int iCase, string sFromdate, string sTodate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"select [ProjectCode] from [ProjectMaster] where Status='WIP' and [ProjectType]!='' order by id desc", SQLCon);

                        break;

                    case 1:
                        SQLCmd = new SqlCommand(@"select [ProjectCode] from [ProjectMaster] where Status='WIP' and [ProjectType]!='' and (convert(date,[DateCreated],105)>='" + sFromdate + "'  and convert(date,[DateCreated],105)<='" + sTodate + "' ) order by id desc", SQLCon);
                        break;

                    case 2:
                        SQLCmd = new SqlCommand(@"select [ProjectType], COUNT([ProjectType]) as Nos from [ProjectMaster] where Status='WIP' and [ProjectType]!='' group by [ProjectType]", SQLCon);
                        break;

                    case 3:
                        SQLCmd = new SqlCommand(@"select [ProjectType], COUNT([ProjectType]) as Nos  from [ProjectMaster] where Status='WIP'  and [ProjectType]!='' and (convert(date,[DateCreated],105)>='" + sFromdate + "'  and convert(date,[DateCreated],105)<='" + sTodate + "' ) group by [ProjectType]", SQLCon);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand(@"select ProjectStatus  from ProjectStatus where ProjectStatus='Shipped'  and (convert(date,[StatusChangedDate],105)>='" + sFromdate + "'  and convert(date,[StatusChangedDate],105)<='" + sTodate + "')", SQLCon);
                        break;

                    case 5:
                        SQLCmd = new SqlCommand(@"select ProjectStatus from ProjectStatus where ProjectStatus='Installation completed'  and (convert(date,[StatusChangedDate],105)>='" + sFromdate + "'  and convert(date,[StatusChangedDate],105)<='" + sTodate + "' )", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


