                                            join [dbo].[ItemMaster] itm on ind.ItemCode=itm.ItemCode where (convert(date,ind.[IndentDate],105) >= '" + sFromdate + "' AND convert(date,ind.[IndentDate],105) <= '" + sTodate + "') order by [IndentNoList] desc", SQLCon);
                else
                    SQLCmd = new SqlCommand(@"select ind.[IndentNo],ind.[ProjectCode],pj.[ProjectDescription],ind.[ItemCode],itm.ItemDescription,ind.[IndentBy],ind.[IndentDate],
                                            ind.[IndentQty],ind.[IndentRemainingQty],ind.[Remarks] from Indent ind join [dbo].[ProjectMaster] pj on ind.ProjectCode=pj.ProjectCode 
                                            join [dbo].[ItemMaster] itm on ind.ItemCode=itm.ItemCode where ind.[ProjectCode]='" + Projectcode + "'  order by [IndentNoList] desc", SQLCon);
