            }
        }

        public DataSet fnWOlist(int iSearch, string sItemCode, string sFrom, string sTo)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iSearch)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"SELECT a.[JWNumber],a.PMName,a.MHName,a.PurchaseCommitee,a.[WONumber],a.[GINNo],a.[IPItemCode],a.[IPOrderQty],a.[OPItemCode],
                                              b.ItemDescription,a.[OPOrderQty],a.[ProjectCode],PM.ProjectDescription,a.[VendorCode],c.VendorName,a.[UnitCost],a.[TotalCost],a.[JobIssueStatus],a.[PreparedBy],
                                              a.[AuthorisedBy],a.[WOgeneratedDate],a.[WOGeneratedBy],a.[WOStatus],a.[IPRemainingOrderQty] ,a.[WorkDescription],
                                              a.[OPRemainingQty] FROM WorkOrder a join ItemMaster b on  a.OPItemCode=b.ItemCode join Vendors c on a.VendorCode=c.VendorCode join ProjectMaster PM on a.ProjectCode=PM.ProjectCode
                                                order by a.id desc", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand("SELECT a.[JWNumber],a.[WONumber],a.[GINNo],a.[IPItemCode],a.[IPOrderQty],a.[OPItemCode],b.ItemDescription,a.[OPOrderQty],a.[VendorCode],c.VendorName,a.[UnitCost],a.[TotalCost],a.[JobIssueStatus],a.[PreparedBy],a.[AuthorisedBy],a.[WOgeneratedDate],a.[WOGeneratedBy],a.[WOStatus],a.[IPRemainingOrderQty] ,a.[WorkDescription],a.[OPRemainingQty] FROM WorkOrder a join ItemMaster b on  a.OPItemCode=b.ItemCode join Vendors c on a.VendorCode=c.VendorCode  where a.WOStatus='Open'  and a.OPRemainingQty!=0 and (a.WOGeneratedBy!=''and a.WOGeneratedBy is not null) order by a.id desc", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand(@"SELECT a.[JWNumber],a.PMName,a.MHName,a.PurchaseCommitee,a.[WONumber],a.[GINNo],a.[IPItemCode],a.[IPOrderQty],a.[OPItemCode],
                                              b.ItemDescription,a.[OPOrderQty],a.[ProjectCode],PM.ProjectDescription,a.[VendorCode],c.VendorName,a.[UnitCost],a.[TotalCost],a.[JobIssueStatus],a.[PreparedBy],
                                              a.[AuthorisedBy],a.[WOgeneratedDate],a.[WOGeneratedBy],a.[WOStatus],a.[IPRemainingOrderQty] ,a.[WorkDescription],
                                              a.[OPRemainingQty] ,[GMName] ,[FinalizedBy],PCAuthoriseDate,[WOPreparedDate],[PMApprovedDate],[MHApprovedDate],[FinalizedDate] FROM WorkOrder a join ItemMaster b on  a.OPItemCode=b.ItemCode join Vendors c on a.VendorCode=c.VendorCode join ProjectMaster PM on a.ProjectCode=PM.ProjectCode
                                               where (CONVERT(date,a.WOgeneratedDate,105)>='" + sFrom + "' and CONVERT(date,a.WOgeneratedDate,105)<='" + sTo + "') or (CONVERT(date,a.PMApprovedDate,105)>='" + sFrom + "' and CONVERT(date,a.PMApprovedDate,105)<='" + sTo + "')  order by a.id desc", SQLCon);
                        break;


                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


