                        SQLCmd = new SqlCommand("Select 'Vendor Approve' as [Type], [VendorCode] as [Code],[VendorName] as  [Name],'' as CustomerName, [CreatedBy],[CreatedDate], DATEDIFF(day, convert(date,[CreatedDate], 105), '" + sVendorCode + "') as [No of days delayed] from Vendors where Approved = '0' or Approved is null Union all Select 'Project Approve' as [Type],ProjectCode,ProjectDescription,Customer as CustomerName,CreatedBy, DateCreated, DATEDIFF(day, convert(date, DateCreated, 105), '" + sVendorCode + "') as [No of days delayed]  from Projectmaster where [Status] = '' and AccountsApprovedby is null and CONVERT(date, DateCreated, 105) >= '2021-01-01' union all Select 'Warranty Expired' as [Type], ProjectCode,ProjectDescription,Customer as CustomerName,CreatedBy,WarrantyCloseDate, DATEDIFF(day, convert(date, WarrantyCloseDate, 105), '" + sVendorCode + "') as [No of days delayed] from Projectmaster where ProjectCode like '%-W%' and Status = 'WIP' and CONVERT(date, WarrantyCloseDate,105)<= '" + sVendorCode + "' and WarrantyCloseDate is not null", SQLCon);
                        break;
                    case 5:
                        SQLCmd = new SqlCommand("Select 'Vendor Approve' as [Type], [VendorCode] as [Code],[VendorName] as  [Name],'' as CustomerName, [CreatedBy],[CreatedDate], DATEDIFF(day, convert(date,[CreatedDate], 105), '" + sVendorCode + "') as [No of days delayed] from Vendors where Approved = '0' or Approved is null", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

