        public DataSet fnPOPackingGST(string sPONo, string sTaxName)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sPONo == null)
                    SQLCmd = new SqlCommand("Select * from [POPackingForwarding]  order by VendorName asc", SQLCon);
                else
                {
                    if (sTaxName == "Packing & Forwarding")
                    {
                        SQLCmd = new SqlCommand(@"  select SUM(COALESCE(PackingForwarding, 0)) AS Amount,
    MAX(COALESCE(PFIGSTRate, 0)) AS IGSTRate,
    SUM((COALESCE(PackingForwarding, 0) * COALESCE(PFIGSTRate, 0)) / 100) AS IGSTAmount,
    MAX(COALESCE(PFSGSTRate, 0)) AS SGSTRate,
    SUM((COALESCE(PackingForwarding, 0) * COALESCE(PFSGSTRate, 0)) / 100) AS SGSTAmount,
    MAX(COALESCE(PFCGSTRate, 0)) AS CGSTRate,
    SUM((COALESCE(PackingForwarding, 0) * COALESCE(PFCGSTRate, 0)) / 100) AS CGSTAmount
     FROM Receipt
        WHERE GINNumber = '" + sPONo + "'", SQLCon);
                    }
                    else if (sTaxName == "Transportation / Freight")
                    {
                        SQLCmd = new SqlCommand(@"select   SUM(COALESCE(TransportationFreight, 0)) AS Amount,    
    MAX(COALESCE(TFIGSTRate, 0)) AS IGSTRate,
    SUM((COALESCE(TransportationFreight, 0) * COALESCE(TFIGSTRate, 0)) / 100) AS IGSTAmount,    
    MAX(COALESCE(TFSGSTRate, 0)) AS SGSTRate,
    SUM((COALESCE(TransportationFreight, 0) * COALESCE(TFSGSTRate, 0)) / 100) AS SGSTAmount,    
    MAX(COALESCE(TFCGSTRate, 0)) AS CGSTRate,
    SUM((COALESCE(TransportationFreight, 0) * COALESCE(TFCGSTRate, 0)) / 100) AS CGSTAmount
            FROM Receipt  where GINNumber='" + sPONo + "'", SQLCon);
                    }

                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

