        public DataSet fnWARItemList(int iCase, string sCustomerCode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand("Select * from CustomerMaster  order by customername asc", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand("Select CustomerName from CustomerMaster Where CusCode='" + sCustomerCode + "' ", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand("Select CustomerName from CustomerMaster Where Approved=0 or Approved is null", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand("Select * from CustomerMaster Where CustomerName='" + sCustomerCode + "'", SQLCon);
                        break;
                    case 4:
                        SQLCmd = new SqlCommand("Select CustomerName,CusCode from CustomerMaster order by customername asc", SQLCon);
                        break;
                    case 5:
                        SQLCmd = new SqlCommand(@"
        WITH WARItems AS (
            SELECT  
                [TransactionLogID],
                [TransactionNumber],
                [TransactionBy],
                [TransactionDate],
                [Action],
                [TableName],
                [TransactionDateTime],
                LEFT(
                    LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action))),
                    CHARINDEX(' ', LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action))) + ' ') - 1
                ) AS WARCost,
                LTRIM(
                    RIGHT(
                        LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action))),
                        LEN(LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action)))) - 
                        CHARINDEX(' ', LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action))) + ' ')
                    )
                ) AS ItemCode
            FROM 
                [ERP_Database].[dbo].[ERPTransactionLog]
            WHERE
                Action LIKE 'Latest WAR Updated %'
        )
        SELECT * FROM WARItems;", SQLCon);
                        break;



                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

