        public DataSet fnProjectListProgress(string sProjectCodes)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sProjectCodes == null)
                    SQLCmd = new SqlCommand("Select ProjectDescription,ManufactureName,ProjectCode,Customer,[CreatedBy], convert(date,DateCreated ,105)as [DateCreated],TransferProject,[AccountsApprovedby],[AccountsApprovedDate],[GMApproved] ,[GMApprovedDate],Type,Status,ProjectCost,Remarks,ProjectType,ProjectProcess,CreatedBy,Id,SystemSubType ,CustomerCode,BOMProject,project8020,customizationlevel,[WarrantyStartsFrom] from ProjectMaster order by [Status] desc", SQLCon);
                else
                    SQLCmd = new SqlCommand($@"
                                    SELECT
                      MachineBOM.ProjectBOMCode,
                      MachineBOM.ProductNo,
                      PB.ProductCode,
                      MachineBOM.ItemName,
                      ItemMaster.ItemDescription,
                      MachineBOM.Quantity AS BOMQty,
	                  ISNULL((SELECT SUM(IssuedQuantity) FROM Issued where Project_Code=MachineBOM.ProjectCode and ProductNo=MachineBOM.ProductNo and Item_Code=MachineBOM.ItemName), 0) as IssuedQty,
	                  MachineBOM.Quantity - ISNULL((SELECT SUM(IssuedQuantity) FROM Issued where Project_Code=MachineBOM.ProjectCode and ProductNo=MachineBOM.ProductNo and Item_Code=MachineBOM.ItemName), 0) AS BOMBalanceIssueQty,
	                  isNULL((SELECT TOP (1)
			                --pob.PONumber,
		                --	pob.ProjectCode,
			                --pob.ProductNo,
			                --pob.ItemCode,

			                -- PO qty per project
			                --Max(pob.POQuantity) AS TotalPOQty,

			                -- Received qty per project
			                --ISNULL(SUM(r.Quantity), 0) AS TotalReceivedQty,

			                -- Remaining qty
			                Max(pob.POQuantity) - ISNULL(SUM(r.Quantity), 0) AS RemainingQty

		                FROM PurchaseOrderBOM pob

		                LEFT JOIN Receipt r 
			                ON r.RefNumber = pob.PONumber
			                AND r.ItemCode = pob.ItemCode
			                AND r.ProductNo = pob.ProductNo
			                AND r.BOMProjectCode = pob.ProjectCode
			                --join PurchaseOrder PO on PO.DBOMNo = pob.PONumber
			                where  pob.ProjectCode = MachineBOM.ProjectCode  and pob.ItemCode=MachineBOM.ItemName and pob.ProductNo = MachineBOM.ProductNo --'CUS-2025-09-CSM-126724' --and pob.ItemCode='ELE-62IN-000014'

		                GROUP BY 
			                pob.PONumber,
			                pob.ProjectCode,
			                pob.ProductNo,
			                pob.ItemCode

		                ), 0) AS [Pending PO QTY],

		                 isNULL((SELECT TOP (1)
			                --pob.PONumber,
		                --	pob.ProjectCode,
			                --pob.ProductNo,
			                --pob.ItemCode,

			                -- PO qty per project
			                --Max(pob.POQuantity) AS TotalPOQty,

			                -- Received qty per project
			                --ISNULL(SUM(r.Quantity), 0) AS TotalReceivedQty,

			                -- Remaining qty
			                --Max(pob.POQuantity) - ISNULL(SUM(r.Quantity), 0) AS RemainingQty
			                MAX(PO.VendorCode)

		                FROM PurchaseOrderBOM pob

		                LEFT JOIN Receipt r 
			                ON r.RefNumber = pob.PONumber
			                AND r.ItemCode = pob.ItemCode
			                AND r.ProductNo = pob.ProductNo
			                AND r.BOMProjectCode = pob.ProjectCode
			                join PurchaseOrder PO on PO.DBOMNo = pob.PONumber
			                where  pob.ProjectCode = MachineBOM.ProjectCode  and pob.ItemCode=MachineBOM.ItemName and pob.ProductNo = MachineBOM.ProductNo --'CUS-2025-09-CSM-126724' --and pob.ItemCode='ELE-62IN-000014'

		                GROUP BY 
			                pob.PONumber,
			                pob.ProjectCode,
			                pob.ProductNo,
			                pob.ItemCode

		                ), '-') AS VendorCode,
	                 ItemMaster.AvailableQty,
                      MachineBOM.ProjectCode,
                      MachineBOM.MfgPartNo,
                      MachineBOM.Make,
                      MachineBOM.Specification,
                      ItemMaster.Location,
                      MachineBOM.Vendor,
                      MachineBOM.DrawingNo,
                      MachineBOM.ExtraItem,
                      MachineBOM.ProjectStatus,
                      MachineBOM.AddedBy,
                      MachineBOM.AddedDate,
                      MachineBOM.ReturnQty,
                      MachineBOM.POQty,
                      MachineBOM.ProductType,
                      MachineBOM.FixedCost
                FROM [ERP_Database].[dbo].[MachineBOM] AS MachineBOM
                LEFT JOIN ProjectBOM AS PB 
                    ON PB.ProjectCode = MachineBOM.ProjectCode 
                   AND PB.ProductNo = MachineBOM.ProductNo
                INNER JOIN ItemMaster 
                    ON ItemMaster.ItemCode = MachineBOM.ItemName
                WHERE MachineBOM.ProjectCode IN (
                {sProjectCodes}

                )
 
                order by itemcode;", SQLCon);
                SQLCmd.CommandTimeout = 5000;
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
