        public DataSet fnPOPendingList(int iCase, string stodadate, string syesterdaydate, string PO)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"SELECT [DBOMNo],[PreparedBy],convert(date,POPreparedDate,105) as POPreparedDate FROM [PurchaseOrder] 
                                              where convert(date,POPreparedDate,105) between '" + syesterdaydate + "'  and '" + stodadate + "' and (AuthoriedBy IS NULL or AuthoriedBy='') group by dbomno,PreparedBy,POPreparedDate order by POPreparedDate asc", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand(@"SELECT [DBOMNo],convert(date,POPreparedDate,105) as POPreparedDate, [PreparedBy],[PMName] ,[MHName], [PurchaseCommitee]
                                              FROM [PurchaseOrder]  where convert(date,POPreparedDate,105) between '" + syesterdaydate + "'  and '" + stodadate + "' and ([POApproved]='1') and ([PurchaseCommitee]!='' or PurchaseCommitee is not null) and ([POGeneratedBy]='' or POGeneratedBy is null) and (AuthoriedBy IS NOT NULL and AuthoriedBy!='' and AuthoriedBy!='Deleted') group by  [DBOMNo],convert(date,POPreparedDate,105),[PreparedBy],[PMName] ,[MHName], [PurchaseCommitee] order by convert(date,POPreparedDate,105) desc", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand(@"SELECT [DBOMNo],convert(date,POPreparedDate,105) as POPreparedDate, [PreparedBy],[PMName] ,[MHName], [PurchaseCommitee]
                                              FROM [PurchaseOrder]  where convert(date,POPreparedDate,105) between '" + syesterdaydate + "'  and '" + stodadate + "' and ([POApproved]='0') and ([PurchaseCommitee]!='' or PurchaseCommitee is not null) and (AuthoriedBy IS NOT NULL and AuthoriedBy!='' and AuthoriedBy!='Deleted') group by [DBOMNo],convert(date,POPreparedDate,105),[PreparedBy],[PMName] ,[MHName], [PurchaseCommitee] order by convert(date,POPreparedDate,105) desc", SQLCon);
                        break;

                    case 3:
                        SQLCmd = new SqlCommand(@"SELECT TRIM([POGeneralTerms]) as POGeneralTerms FROM [POGeneralTerms]  where [PONo]='" + PO + "' and [POGeneralTerms]!='' order by ID asc", SQLCon);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand(@"SELECT [POTermsType] FROM [POGeneralTerms] where [POTermsType] is not null GROUP BY [POTermsType]", SQLCon);
                        break;

                    case 5:
                        SQLCmd = new SqlCommand(@"SELECT TRIM([POGeneralTerms]) as POGeneralTerms FROM [POGeneralTerms]  where [POTermsType]='" + PO + "' and [POGeneralTerms]!='' order by ID asc", SQLCon);
                        break;


                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

