        public DataSet fnPOTrackList(int iCase, string sPONO)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                if (iCase == 1)
                {
                    SQLCmd = new SqlCommand(@"SELECT row_number() over(order by P.ID desc) as [SlNo],[DBOMNo] as [PO/WO No]
                                              ,PM.ProjectDescription, V.VendorName,P.[ItemCode], IM.ItemDescription,'Purahase Order' as [PurchaseType], CASE WHEN [RemainingQty] =0 THEN 'GIN' WHEN ([RemainingQty]<RequariedQty and RemainingQty>0) THEN 'Partial GIN'  ELSE 'Pending' END as GINStatus, DATEDIFF(day,convert(date,P.[OADate],105), GETDATE()) AS [POLateBy],FinalRemarks,[OADate]
                                              FROM [PurchaseOrder] p join ProjectMaster PM on P.[ProjectCode]=PM.[ProjectCode] Join Vendors V on P.VendorCode=V.VendorCode join ItemMaster IM on P.Itemcode=IM.ItemCode
                                              where convert(date,[POGeneratedDate],105)>='2019-10-01' and convert(date,[POGeneratedDate],105)<='2030-01-01' and P.DBOMNo='" + sPONO + "' and P.POGeneratedBy is not null  union all  SELECT row_number() over(order by W.ID desc) as [SlNo], W.WONumber as [PO/WO No],PM.ProjectDescription,V.VendorName,W.[OPItemCode], IM.ItemDescription,'Work Order' as [PurchaseType], CASE WHEN W.OPRemainingQty =0 THEN 'GIN' WHEN (W.OPRemainingQty< W.OPOrderQty and W.OPRemainingQty>0) THEN 'Partial GIN'  ELSE 'Pending' END as GINStatus, DATEDIFF(day,convert(date,W.[WODeliveryDate],105), GETDATE()) AS [POLateBy], FinalRemarks,'' as OADate from [WorkOrder] W join ProjectMaster PM on W.[ProjectCode]=PM.[ProjectCode]  Join Vendors V on W.VendorCode=V.VendorCode join ItemMaster IM on W.OPItemCode=IM.ItemCode where convert(date,W.[WOgeneratedDate],105)>='2019-10-01' and convert(date,W.[WOgeneratedDate],105)<='2030-01-01'  and W.WONumber='" + sPONO + "'  and W.WOGeneratedBy is not null ", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

