        public DataSet fnGetFilteredERPInventoryFIFOLogs(string fromDate, string toDate, string projectPrefix, string categoryPrefix)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();

                string query = @"SELECT InventoryFIFOlogs.ItemCode
                                  , InventoryFIFOlogs.IndentQty
                                  ,InventoryFIFOlogs.ProjectCode
                                  ,InventoryFIFOlogs.IndentNo
                                  ,InventoryFIFOlogs.Remarks
                                  ,[GINNumber]
                                  ,[BatchCode]
                                  ,[Location]
                                  ,[PickedBatchCode]
                                  ,[PickedLocation]
                                  ,[FIFOFollowed]
                                  ,[IndentPickedBy]
                                  ,[IssuedBy]
                                  ,[CreateDate]
                                  ,[AssignQty]
                                            FROM InventoryFIFOlogs left join Indent ON Indent.IndentNo = InventoryFIFOlogs.IndentNo
                            WHERE 1 = 1  AND Indent.Status = 'Closed'";

                if (!string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(toDate))
                    query += $" AND CONVERT(datetime, InventoryFIFOlogs.CreateDate, 105) BETWEEN CONVERT(datetime, '{fromDate}', 105) AND CONVERT(datetime, '{toDate}', 105)";
                // query += $" AND CreatedDate BETWEEN CONVERT(datetime, '{fromDate}', 105) AND CONVERT(datetime, '{toDate}', 105)";


                if (!string.IsNullOrEmpty(projectPrefix))
                    query += $" AND InventoryFIFOlogs.ProjectCode LIKE '{projectPrefix}%'";

                if (!string.IsNullOrEmpty(categoryPrefix))
                    query += $" AND InventoryFIFOlogs.ItemCode LIKE '{categoryPrefix}%'";

                //if (!string.IsNullOrEmpty(itemPrefix))
                //  query += $" AND ItemCode LIKE '{itemPrefix}%'";

                SQLCmd = new SqlCommand(query, SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();

                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }



