        public DataSet fnGetFilteredERPInventoryCurrentStock(string ItemCode, string location, string unitCost, string StockCost)
        {

            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();

                string baseQuery = "FROM ItemMaster WHERE 1=1";

                //string unitCostStr = unitCost.ToString();

                //  if (!string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(toDate))
                //    baseQuery += $" AND CONVERT(datetime, IndentDate, 105) BETWEEN CONVERT(datetime, '{fromDate}', 105) AND CONVERT(datetime, '{toDate}', 105)";

                //if (unitCost > -1)
                baseQuery += $" AND AvailableQty > 0";

                if (!string.IsNullOrEmpty(location))
                    baseQuery += $" AND Location LIKE '{location}%'";

                if (!string.IsNullOrEmpty(ItemCode))
                    baseQuery += $" AND ItemCode LIKE '{ItemCode}%'";

                if (!string.IsNullOrEmpty(unitCost))
                    baseQuery += $" AND unitCost > '{unitCost}'";

                if (!string.IsNullOrEmpty(StockCost))
                    baseQuery += $" AND StockValue > '{StockCost}'";



                // Query 1: Get filtered data
                string dataQuery = "SELECT * " + baseQuery;
                SQLCmd = new SqlCommand(dataQuery, SQLCon);
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset, "FilteredData");

                // Query 2: Get sum of IndentQty
                string sumQuery = "SELECT SUM(AvailableQty) AS TotalAvailableQty " + baseQuery;
                SQLCmd = new SqlCommand(sumQuery, SQLCon);
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset, "TotalAvailableQty");

                // Query 3: Get sum of Unit Cost
                string sumStockValue = "SELECT SUM(StockValue) AS TotalStockValue " + baseQuery;
                SQLCmd = new SqlCommand(sumStockValue, SQLCon);
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset, "TotalStockValue");




                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }



