        public double fnGetTotalRemainingQty(string ItemCode, string IndentNo)
        {
            try
            {
                SQLCon.Open();
                double totalQty = 0;

                string query = "SELECT SUM(RemainingQty) FROM ERPInventoryLogs WHERE 1=1";

                if (!string.IsNullOrEmpty(ItemCode))
                {
                    query += " AND ItemCode = @ItemCode";
                }

                if (!string.IsNullOrEmpty(IndentNo))
                {
                    query += " AND IndentNo = @IndentNo";
                }

                SQLCmd = new SqlCommand(query, SQLCon);

                if (!string.IsNullOrEmpty(ItemCode))
                {
                    SQLCmd.Parameters.AddWithValue("@ItemCode", ItemCode);
                }

                if (!string.IsNullOrEmpty(IndentNo))
                {
                    SQLCmd.Parameters.AddWithValue("@IndentNo", IndentNo);
                }

                object result = SQLCmd.ExecuteScalar();
                SQLCon.Close();

                if (result != DBNull.Value && result != null)
                {
                    totalQty = Convert.ToDouble(result);
                }

                return totalQty;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return 0;
            }
        }

