        public DataSet fnIndentExcel(string sIndentNo, string sPrint)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                if (sIndentNo != null && sPrint == null)
                {
                    //SQLCmd = new SqlCommand(@"SELECT I.[ItemCode],IM.ItemDescription,I.BOMQty,I.[IndentQty] as Qty
                    //                    FROM [Indent] I join ItemMaster IM on I.ItemCode=IM.ItemCode where I.IndentNo='" + sIndentNo + "'", SQLCon);


                    SQLCmd = new SqlCommand(@"
                                    SELECT 
                                            I.[ItemCode],
                                            IM.ItemDescription,
                                            I.BOMQty,
                                            I.[IndentQty] AS Qty,
                                            ISNULL(EI.BatchCode, '-') AS BatchCode,
                                            ISNULL(EI.Location, '-') AS Location
                                        FROM [Indent] I
                                        JOIN ItemMaster IM ON I.ItemCode = IM.ItemCode
                                        LEFT JOIN ERPInventoryIndent EI 
                                            ON I.IndentNo = EI.IndentNo AND I.ItemCode = EI.ItemCode
                                        WHERE I.IndentNo = '" + sIndentNo + "'", SQLCon);


                    // Use parameterized query to avoid SQL injection

                }
                else if (sIndentNo != null && sPrint != null)
                {
                    SQLCmd = new SqlCommand(@"SELECT I.[ItemCode],IM.ItemDescription,I.BOMQty,I.[IndentQty] as Qty
                                          FROM [Indent] I join ItemMaster IM on I.ItemCode=IM.ItemCode where I.IndentNo='" + sIndentNo + "'", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnPRExcel(string sPONo)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                if (sPONo != null)
                {
                    SQLCmd = new SqlCommand(@"Select row_number() over(partition by P.DBOMNo order by P.DBOMNo) as [SlNo],P.ItemCode,IM.ItemDescription,'' as [Old ItemCode],
                                            IM.AvailableQty as [Stock],isnull(P.[SixMonths],0) as [6Month],BOMQty as BOM,P.[RequariedQty] as ReqQty,P.[UnitPrice] as UnitCost ,
                                            (P.RequariedQty *P.[UnitPrice]) as [Amount],BOMProjectList as [BOM Project List]
                                            from PurchaseOrder P join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join ItemMaster IM on P.ItemCode=IM.Itemcode join Vendors V on P.VendorCode=V.VendorCode where [DBOMNo]='" + sPONo + "'", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnBOMIndent(string sIndentNo, string sBOM)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                if (sIndentNo != null && sBOM == null)
                {
                    SQLCmd = new SqlCommand(@"SELECT  I.[IndentNo],I.[ItemCode],IM.ItemDescription,Im.Units,IM.AvailableQty,I.[ProjectCode],PM.ProjectDescription,PM.Customer,PM.BOMProject
                                         ,I.[IndentBy],I.[IndentDate],I.[IndentQty] as ReqQty,I.[IndentRemainingQty],I.[Remarks]
                                          FROM [Indent] I join ItemMaster IM on I.ItemCode=IM.ItemCode join ProjectMaster PM on I.ProjectCode=PM.ProjectCode where I.IndentNo='" + sIndentNo + "' and I.Status='Open' order by IM.Location desc", SQLCon);
                }
                else if (sIndentNo != null && sBOM != null)
                {
                    SQLCmd = new SqlCommand(@"SELECT  I.[IndentNo],I.[ItemCode] as ItemName,IM.ItemDescription,Im.Units,IM.AvailableQty,I.[ProjectCode],PM.ProjectDescription,PM.Customer
                                            ,I.[IndentBy],I.[IndentDate],I.[IndentQty],I.[IndentRemainingQty],I.[Remarks],I.[ProjectBOMCode],I.[ProductNo],I.[BOMQty] as Quantity,'' as IssuedQuantity 
                                            FROM [Indent] I join ItemMaster IM on I.ItemCode=IM.ItemCode join ProjectMaster PM on I.ProjectCode=PM.ProjectCode where I.IndentNo='" + sIndentNo + "' and I.Status='Open'  order by IM.Location desc", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


