        public int fnGenarateWorkOrder(uint uInOrUPOrDel, string sWONumber, string sItemCode, string sQty, string sVendorCode, string fUnitCost, string fTotalCost, string sWOGeneratedBy, string sWOgeneratedDate, string sWorkDescription, string sProjectCode, string sDGRefno, string sWODeliveryDate, string sProjectStatus, double IGSTRate, double IGSTAmount, double SGSTRate, double SGSTAmount, double CGSTRate, double CGSTAmount, double FinalNetAmount, string PaymentTerm, string DeliveryTerm)
        {
            Global GlobalClass = new Global();
            //string 
            try
            {
                SQLCon.Open();
                switch (uInOrUPOrDel)
                {
                    case Global.uUPDATE:
                        {
                            SQLCmd = new SqlCommand("Update WorkOrder set IPOrderQty='" + sQty + "',IPRemainingOrderQty='" + sQty + "',DGRefno='" + sDGRefno + "' where WONumber='" + sWONumber + "' and IPItemCode='" + sItemCode + "'", SQLCon);
                            break;
                        }

                    case Global.uINSERT:
                        {
                            SQLCmd = new SqlCommand("Update WorkOrder set OPOrderQty='" + sQty + "',OPRemainingQty='" + sQty + "',VendorCode='" + sVendorCode + "',UnitCost='" + fUnitCost + "',TotalCost='" + fTotalCost + "',WOGeneratedBy='" + sWOGeneratedBy + "',WOgeneratedDate='" + sWOgeneratedDate + "',WorkDescription='" + sWorkDescription + "',ProjectCode='" + sProjectCode + "',DGRefno='" + sDGRefno + "',WODeliveryDate='" + sWODeliveryDate + "', ProjectStatus='" + sProjectStatus + "',IGSTRate='" + IGSTRate + "',IGSTAmount='" + IGSTAmount + "',SGSTRate='" + SGSTRate + "',SGSTAmount='" + SGSTAmount + "',CGSTRate='" + CGSTRate + "',CGSTAmount='" + CGSTAmount + "',FinalNetAmount='" + FinalNetAmount + "',PaymentTerm='" + PaymentTerm + "',DeliveryTerm='" + DeliveryTerm + "' where WONumber='" + sWONumber + "' and OPItemCode='" + sItemCode + "'", SQLCon);
                            break;
                        }

                    case 44:
                        {
                            SQLCmd = new SqlCommand(@"Update WorkOrder set WorkOrder.IPUnitCost=ItemMaster.UnitCost
                                                      from WorkOrder WorkOrder join ItemMaster ItemMaster
                                                      on WorkOrder.IPItemCode=ItemMaster.ItemCode  where WorkOrder.WONumber='" + sWONumber + "'", SQLCon);
                            break;
                        }
                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }

