        public DataSet fnDeliveryTermPO(string Date)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (Date == null)
                    SQLCmd = new SqlCommand("Select * from DeliveryTermMaster", SQLCon);
                else
                    SQLCmd = new SqlCommand($@"DECLARE @SelectedDate DATE = '{Date}';
                    DECLARE @DaysDiff INT = DATEDIFF(DAY, CAST(GETDATE() AS DATE), @SelectedDate);

                                    SELECT TOP 1
                        ID,
                        DeliveryCode,
                        DeliveryTerms,
                        @DaysDiff AS DaysFromToday
                    FROM DeliveryTermMaster
                    WHERE Status = 'Active'
                      AND MinDays IS NOT NULL
                      AND @DaysDiff BETWEEN MinDays AND MaxDays
                    ORDER BY ABS(MinDays -@DaysDiff); ", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset, "DeliveryTermMasterList");
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

