        public DataSet fnGetIndentMachineBOM(string sProjectBOMCode, string sProductNo, string sProjectcode, string sItemCode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sProjectBOMCode != null && sProductNo != null && sProjectcode != null && sItemCode == null)
                {
                    SQLCmd = new SqlCommand(@"SELECT m.[ItemName] as ItemCode,im.ItemDescription,m.[ProjectBOMCode] ,m.[ProductNo],m.[ProjectCode],m.[Quantity],im.AvailableQty,im.Units,
                                              im.ID,m.IssuedQty as IssuedQuantity,(m.[Quantity]-m.IssuedQty) as IndentQty FROM [MachineBOM] m join ItemMaster im on m.ItemName=im.ItemCode 
                                              where m.ProjectBOMCode='" + sProjectBOMCode + "'  and m.ProjectCode='" + sProjectcode + "' and m.ProductNo='" + sProductNo + "' and im.[Type]!='Kan Ban' and im.[Status]!='Deactive'", SQLCon);
                }
                else if (sProjectBOMCode != null && sProductNo != null && sProjectcode != null && sItemCode != null)
                {
                    SQLCmd = new SqlCommand(@"SELECT m.[ItemName],im.ItemDescription,m.[ProjectBOMCode] ,m.[ProductNo],m.[ProjectCode],m.[Quantity],im.AvailableQty,im.Units,
                                              im.ID,m.IssuedQty as IssuedQuantity,(m.[Quantity]-m.IssuedQty) as IndentQty FROM [MachineBOM] m join ItemMaster im on m.ItemName=im.ItemCode 
                                              where m.[ItemName]='" + sItemCode + "' and m.ProjectBOMCode='" + sProjectBOMCode + "'  and m.ProjectCode='" + sProjectcode + "' and m.ProductNo='" + sProductNo + "' and im.[Type]!='Kan Ban' and im.[Status]!='Deactive'", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

