        public int fnAddProductTreeView(uint uInOrUPOrDel, int iParentID, string ItemCode, double Quantity, string MfgPartNo, string Make, string Specification, string Location, string Vendor, string DrawingNo, string TreeViewCreatedBy, string TreeViewAuthorisedBy, string Version, string ProductType, Decimal FixedCost)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (uInOrUPOrDel)
                {
                    case Global.uINSERT:
                        {                                                                                                                                                                                                                                                                                     //        int iParentID, string , int , string , string , string , string , string , string , string , string )
                            SQLCmd = new SqlCommand("Insert into TreeViewItems([ParentID],[ItemCode],[Quantity],[MfgPartNo],[Make],[Specification],[Location],[Vendor],[DrawingNo],[TreeViewCreatedBy],[TreeViewAuthorisedBy],Version,ProductType,FixedCost) values('" + iParentID + "','" + ItemCode + "','" + Quantity + "','" + MfgPartNo + "','" + Make + "','" + Specification + "','" + Location + "','" + Vendor + "','" + DrawingNo + "','" + TreeViewCreatedBy + "','" + TreeViewAuthorisedBy + "','" + Version + "','" + ProductType + "','" + FixedCost + "')", SQLCon);
                            break;
                        }
                    case Global.uUPDATE:
                        {
                            SQLCmd = new SqlCommand("Update TreeViewItems set Quantity='" + Quantity + "' where ItemCode='" + ItemCode + "' and ParentID='" + iParentID + "' and  Version='" + Version + "'", SQLCon);
                            break;
                        }
                    case Global.uDELETE:
                        {
                            SQLCmd = new SqlCommand("Delete  from TreeViewItems where ParentID='" + iParentID + "' and ItemCode='" + ItemCode + "' and Version='" + Version + "'", SQLCon);
                            break;
                        }
                    case 6:
                        {
                            SQLCmd = new SqlCommand("Update TreeViewItems set ProductType='" + ProductType + "' where ItemCode='" + ItemCode + "' and ParentID='" + iParentID + "' and  Version='" + Version + "'", SQLCon);
                            break;
                        }
                    case 8:
                        {
                            SQLCmd = new SqlCommand("Update TreeViewItems set FixedCost='" + FixedCost + "' where ItemCode='" + ItemCode + "' and ParentID='" + iParentID + "' and  Version='" + Version + "'", SQLCon);
                            break;
                        }
                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }

