        public int fnAddSalesProductName(uint uInOrUPOrDel, int iParentID, int NodeID, string ProductName, string ImageIndex, string BOMCreatedBy, string BOMAuthorisedBy, string ProductCode, string ProductDescription, string ProductCost, string SalesCost)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (uInOrUPOrDel)
                {
                    case Global.uINSERT:
                        {
                            SQLCmd = new SqlCommand(@"Insert into SalesProductTreeView([ParentID],[NodeID],[Name],[ImageIndex],[BOMCreatedBy],[BOMAuthorisedBy],[ProductCode],ProductDescription,ProductCost,SalesCost) 
                                                    values('" + iParentID + "','" + NodeID + "','" + ProductName + "','" + ImageIndex + "','" + BOMCreatedBy + "','" + BOMAuthorisedBy + "','" + ProductCode + "','" + ProductDescription + "','" + ProductCost + "','" + SalesCost + "')", SQLCon);
                            break;
                        }
                    case Global.uUPDATE:
                        {
                            SQLCmd = new SqlCommand("Update SalesProductTreeView set Name='" + ProductName + "',ProductCode='" + ProductCode + "',ProductDescription='" + ProductDescription + "',ProductCost='" + ProductCost + "',SalesCost='" + SalesCost + "' where NodeID='" + NodeID + "' ", SQLCon);
                            break;
                        }
                    case Global.uDELETE:
                        {
                            SQLCmd = new SqlCommand("Delete  from SalesProductTreeView where NodeID='" + NodeID + "'", SQLCon);
                            break;
                        }
                    case 6:
                        {
                            SQLCmd = new SqlCommand("Update SalesProductTreeView set ProductDescription='" + ProductDescription + "',ProductCost='" + ProductCost + "',SalesCost='" + SalesCost + "' where ProductCode='" + ProductCode + "'", SQLCon);
                            break;
                        }

                    case 7:
                        {
                            SQLCmd = new SqlCommand("Update SalesProductTreeView set Name='" + ProductName + "' where NodeID='" + iParentID + "' ", SQLCon);
                            break;
                        }

                    case 8:
                        {
                            SQLCmd = new SqlCommand("Update [SalesProductTreeView] set [OldProductCost]=[ProductCost]", SQLCon);
                            break;
                        }

                    case 9:
                        {
                            SQLCmd = new SqlCommand("Update [SalesProductTreeView] set [ProductCost]=(ProductCost+(ProductCost * '" + ProductName + "'))", SQLCon);
                            break;
                        }
                    case 10:
                        {
                            SQLCmd = new SqlCommand("Update [SalesProductTreeView] set [ProductCost]=(ProductCost+(ProductCost * '" + ProductName + "'))", SQLCon);
                            break;
                        }
                    case 11:
                        {
                            SQLCmd = new SqlCommand("Update [SalesProductTreeView] set [OTCProductCost]=(ProductCost+(ProductCost * '" + ProductName + "'))", SQLCon);
                            break;
