        public DataSet getKanbanItenList(string sProjectCode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sProjectCode == null && sProjectCode == null)
                    SQLCmd = new SqlCommand("Select * from ProjectBOM", SQLCon);
                else
                    SQLCmd = new SqlCommand($@" ;WITH IssuedAgg AS (
                                                SELECT 
                                                    Item_Code,
                                                    1 as ProductNo,
                                                    Projectcode,
                                                    SUM(unitprice) AS SumIssuedPrice,      -- change to AVG/MAX/MIN as needed
                                                    COUNT(*) AS IssueCount 
                                                FROM KanBanElectronicsIssuedFG where Projectcode= '{sProjectCode}' GROUP BY Item_Code, Projectcode )
                                                Select 
                                                ID,
                                                KanBanElectronicsProjectBOM.Projectcode AS ProjectBOMCode,
                                                1 AS ProductNo,
                                                ItemCode AS ItemName,
                                                ItemDescription AS ItemDescription,
                                                BOMQuantity AS Quantity,
                                                ia.IssueCount AS IssuedQuantity,
                                                0 AS AvailableQty,
                                                Unitprice AS UnitCost,
                                                Unitprice AS FixedCost,
                                                Unitprice AS Unitprice,
                                                (Unitprice * ia.IssueCount) AS IssueCost,
                                                ROUND((BOMQuantity * Unitprice), 2) AS BOMAmount,
                                                CAST(NULL AS DECIMAL(18,2)) AS LatestCost,
                                                0 AS RevisionNo,
                                                0 AS DrawingNo,
                                                '' AS Status,
                                                AddedBy,
                                                AddedDate,
                                                [ItemType] AS ProductType,
                                                '' AS PODATE
                                                FROM KanBanElectronicsProjectBOM 
                                                LEFT JOIN IssuedAgg ia
                                                ON ia.Item_Code    = KanBanElectronicsProjectBOM.ItemCode
                                                AND ia.Projectcode = KanBanElectronicsProjectBOM.Projectcode
                                                where KanBanElectronicsProjectBOM.Projectcode = '" + sProjectCode + "'", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


        public DataSet getKanbanDetails(string sProjectCode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sProjectCode == null && sProjectCode == null)
                    SQLCmd = new SqlCommand("Select * from ProjectBOM", SQLCon);
                else
                    SQLCmd = new SqlCommand($@";WITH IssuedAgg AS
                                                (
                                                    SELECT 
                                                        Projectcode,
                                                        SUM(unitprice) AS unitprice  -- or AVG/MAX/MIN as you need
                                                    FROM KanBanElectronicsIssuedFG
                                                    WHERE Projectcode = '{sProjectCode}'
                                                    GROUP BY Projectcode
                                                )
                                                SELECT 
                                                    p.Projectcode,
                                                    SUM(p.BOMQuantity) AS Quantity,
                                                    SUM(p.BOMQuantity * p.unitprice) AS ProjectCost,
                                                    ISNULL(MAX(ia.unitprice), 0) AS IssuedAmount
                                                FROM KanBanElectronicsProjectBOM AS p
                                                LEFT JOIN IssuedAgg AS ia
                                                    ON ia.Projectcode = p.Projectcode
                                                WHERE p.Projectcode = '{sProjectCode}'
                                                GROUP BY p.Projectcode;
                                                ", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                // MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

