        public double fnMachineBOMProdutcost(string costType, string projectCode, string productNo)
        {
            double withoutBOM = 0;

            try
            {
                SQLCon.Open();

                if (costType == "FixedCost")
                {
                    SQLCmd = new SqlCommand(@"select SUM(Quantity * FixedCost)  from MachineBOM where ProductNo=@productNo and ProjectCode=@projectCode", SQLCon);
                    SQLCmd.Parameters.AddWithValue("@productNo", productNo);
                    SQLCmd.Parameters.AddWithValue("@projectCode", projectCode);

                }
                else if (costType == "projectCost")
                {
                    SQLCmd = new SqlCommand(@"WITH PB_PARENTS AS (
                                                -- Get parent rows (SlNo = 1, 2, 3, 4...) with their ProductNo
                                                SELECT
                                                    ProjectCode,
                                                    ProductNo as ParentProductNo,  -- e.g., 1, 7, 12...
                                                    SlNo as ParentSlNo,            -- e.g., 1, 2, 3...
                                                    ISNULL(Deleted, 0) as Deleted,
                                                    ROW_NUMBER() OVER (
                                                        PARTITION BY ProjectCode, CAST(SlNo AS INT)
                                                        ORDER BY SlNo ASC
                                                    ) as rn
                                                FROM dbo.ProjectBOM
                                                WHERE
                                                    ProjectCode = @projectCode
                                                    AND SlNo = CAST(SlNo AS INT)  -- Parents only: 1, 2, 3 (not 1.01)
                                            ),
                                            PB_ALL AS (
                                                -- All rows with their parent SlNo
                                                SELECT
                                                    ProjectCode,
                                                    ProductNo,
                                                    CAST(SlNo AS INT) as ParentSlNo  -- 1.01→1, 2.01→2
                                                FROM dbo.ProjectBOM
                                                WHERE ProjectCode =@projectCode 
                                            )
                                            SELECT
                                                COALESCE(SUM(mb.Quantity * mb.FixedCost), 0) as TotalFixedCost
                                                --COALESCE(SUM(mb.IssuedQty * mb.FixedCost), 0)

                                            FROM dbo.MachineBOM mb
                                            INNER JOIN PB_ALL pba 
                                                ON pba.ProjectCode = mb.ProjectCode
                                                AND pba.ProductNo = TRY_CAST(mb.ProductNo AS INT)  -- Match MachineBOM ProductNo to ProjectBOM ProductNo
                                            INNER JOIN PB_PARENTS pbp
                                                ON pbp.ProjectCode = pba.ProjectCode
                                                AND pbp.ParentSlNo = pba.ParentSlNo
                                            WHERE
                                                mb.ProjectCode = @projectCode
                                                --AND pbp.rn = 1
                                                AND pbp.Deleted = 0;", SQLCon);
                    //SQLCmd.Parameters.AddWithValue("@productNo", productNo);
                    SQLCmd.Parameters.AddWithValue("@projectCode", projectCode);
                }
                else if (costType == "projectIsseCost")
                {
                    //SQLCmd = new SqlCommand(@"select SUM(IssuedQty * FixedCost)  from MachineBOM where ProjectCode=@projectCode", SQLCon);
                    SQLCmd = new SqlCommand(@"WITH PB_PARENTS AS (
                                            -- Get parent rows (SlNo = 1, 2, 3, 4...) with their ProductNo
                                            SELECT
                                                ProjectCode,
                                                ProductNo as ParentProductNo,  -- e.g., 1, 7, 12...
                                                SlNo as ParentSlNo,            -- e.g., 1, 2, 3...
                                                ISNULL(Deleted, 0) as Deleted,
                                                ROW_NUMBER() OVER (
                                                    PARTITION BY ProjectCode, CAST(SlNo AS INT)
                                                    ORDER BY SlNo ASC
                                                ) as rn
                                            FROM dbo.ProjectBOM
                                            WHERE
                                                ProjectCode = @projectCode
                                                AND SlNo = CAST(SlNo AS INT)  -- Parents only: 1, 2, 3 (not 1.01)
                                        ),
                                        PB_ALL AS (
                                            -- All rows with their parent SlNo
                                            SELECT
                                                ProjectCode,
                                                ProductNo,
                                                CAST(SlNo AS INT) as ParentSlNo  -- 1.01→1, 2.01→2
                                            FROM dbo.ProjectBOM
                                            WHERE ProjectCode = @projectCode 
                                        )
                                        SELECT
                                           -- COALESCE(SUM(mb.Quantity * mb.FixedCost), 0) as TotalFixedCost,
                                            COALESCE(SUM(mb.IssuedQty * mb.FixedCost), 0)

                                        FROM dbo.MachineBOM mb
                                        INNER JOIN PB_ALL pba 
                                            ON pba.ProjectCode = mb.ProjectCode
                                            AND pba.ProductNo = TRY_CAST(mb.ProductNo AS INT)  -- Match MachineBOM ProductNo to ProjectBOM ProductNo
                                        INNER JOIN PB_PARENTS pbp
                                            ON pbp.ProjectCode = pba.ProjectCode
                                            AND pbp.ParentSlNo = pba.ParentSlNo
                                        WHERE
                                            mb.ProjectCode = @projectCode
                                            --AND pbp.rn = 1
                                            AND pbp.Deleted = 0;", SQLCon);
                    //SQLCmd.Parameters.AddWithValue("@productNo", productNo);
                    SQLCmd.Parameters.AddWithValue("@projectCode", projectCode);

                }
                else
                {
                    SQLCmd = new SqlCommand(@"select SUM(IssuedQty * FixedCost)  from MachineBOM where ProductNo=@productNo and ProjectCode=@projectCode", SQLCon);
                    SQLCmd.Parameters.AddWithValue("@productNo", productNo);
                    SQLCmd.Parameters.AddWithValue("@projectCode", projectCode);

                }


                // SQLCmd.Parameters.AddWithValue("@productNo", productNo);
                // SQLCmd.Parameters.AddWithValue("@projectCode", projectCode);

                var result = SQLCmd.ExecuteScalar();

                if (result != DBNull.Value && result != null)
                {
                    withoutBOM = (int)Convert.ToDouble(result); // will return 0 or 1
                }

                SQLCon.Close();
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error fetching WithoutBOM status: " + ex.Message);
                SQLCon.Close();
                withoutBOM = 0;
            }

            return withoutBOM;
        }


        public int FastUpdateMachineBOMFixedCosts(string sProjectCode)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();

                SQLCmd = new SqlCommand(@"-- UPDATE query based on working preview
                                            UPDATE M
                                            SET FixedCost = ISNULL(
                                                (SELECT TOP 1 PO.UnitPrice
                                                 FROM [ERP_Database].[dbo].[PurchaseOrder] PO
                                                 WHERE PO.ItemCode = M.ItemName
                                                    AND PB.CreatedDate IS NOT NULL 
                                                 ORDER BY 
                                                    CASE 
                                                        WHEN CONVERT(DATETIME, PO.POPreparedDate, 105) <= CONVERT(DATETIME, PB.CreatedDate, 105) THEN 0 
                                                        ELSE 1 
                                                    END,
                                                    ABS(DATEDIFF(DAY, 
                                                        CONVERT(DATETIME, PB.CreatedDate, 105), 
                                                        CONVERT(DATETIME, PO.POPreparedDate, 105)
                                                    ))
                                                ), 
                                                ISNULL(
                                                    (SELECT TOP 1 IM.UnitCost 
                                                     FROM [ERP_Database].[dbo].[ItemMaster] IM 
                                                     WHERE IM.ItemCode = M.ItemName),
                                                    0
                                                )
                                            )
                                            FROM [ERP_Database].[dbo].[MachineBOM] M
                                            INNER JOIN [ERP_Database].[dbo].[ProjectBOM] PB
                                                ON M.ProjectCode = PB.ProjectCode
                                                AND M.ProductNo = PB.ProductNo
                                                AND M.ProjectBOMCode = PB.ProjectBOMCode
                                            WHERE M.ProjectCode ='" + sProjectCode + "' ;  -- Replace with actual project code", SQLCon);



                //  SQLCmd.Parameters.AddWithValue("@ProjectCode", sProjectCode);
                // SQLCmd.Parameters.AddWithValue("@ProductNo", sProductNo);
                SQLCmd.CommandTimeout = 500;
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return 0;
            }
        }


        public DataSet fnUpdateMachineBOMFixedCost(string itemcode, string AddedDate)
        {

            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                SQLCmd = new SqlCommand(@"-- ============================================
                                            -- BOM FIXED COST CALCULATION
                                            -- Finds correct fixed cost for MachineBOM items based on AddedDate
                                            -- Logic: Latest PO price before or on BOM AddedDate
                                            -- ============================================

                                            DECLARE @BOM_ItemCode VARCHAR(100) = @itemcode;  -- Change to your item
                                            DECLARE @BOM_AddedDate VARCHAR(10) = @AddedDate;      -- Change to BOM AddedDate (DD-MM-yyyy)

                                            -- Convert string date to datetime
                                            DECLARE @TargetDate DATETIME;
                                            SET @TargetDate = CONVERT(DATETIME, @BOM_AddedDate, 105);  -- 105 = DD-MM-yyyy format

                                            -- ============================================
                                            -- STEP 1: Get PO Price directly from linked Receipt-PO
                                            -- Priority 1: PO.UnitPrice where PO.POGeneratedDate <= BOM.AddedDate
                                            -- ============================================
                                            ;WITH ValidPOs AS (
                                                -- All POs for this item before or on BOM AddedDate
                                                SELECT 
                                                    PO.ID,
                                                    PO.ItemCode,
                                                    PO.UnitPrice,
                                                    PO.POGeneratedDate,
                                                    PO.DBOMNo,
                                                    ROW_NUMBER() OVER (ORDER BY PO.POGeneratedDate DESC, PO.ID DESC) as rn_latest
                                                FROM [ERP_Database].[dbo].[PurchaseOrder] PO
                                                WHERE PO.ItemCode = @BOM_ItemCode
                                                    AND PO.UnitPrice IS NOT NULL
                                                    AND PO.POGeneratedDate IS NOT NULL
                                                    AND CONVERT(DATETIME, PO.POGeneratedDate, 105) <= @TargetDate
                                            ),
                                            LatestPO AS (
                                                -- Get the latest PO before BOM AddedDate
                                                SELECT 
                                                    ItemCode,
                                                    UnitPrice AS FixedCostFromPO,
                                                    POGeneratedDate,
                                                    DBOMNo
                                                FROM ValidPOs
                                                WHERE rn_latest = 1
                                            ),
                                            -- ============================================
                                            -- STEP 2: Fallback to Receipt WAR cost if no PO found
                                            -- ============================================
                                            ReceiptCost AS (
                                                SELECT TOP 1
                                                    R.ItemCode,
                                                    R.UnitCost AS FixedCostFromReceipt,
                                                    R.GINServerDate
                                                FROM [ERP_Database].[dbo].[Receipt] R
                                                WHERE R.ItemCode = @BOM_ItemCode
                                                    AND R.GINServerDate <= @TargetDate
                                                ORDER BY R.GINServerDate DESC
                                            ),
                                            -- ============================================
                                            -- STEP 3: First ever price as ultimate fallback
                                            -- ============================================
                                            FirstEverPrice AS (
                                                SELECT TOP 1
                                                    PO.ItemCode,
                                                    PO.UnitPrice AS FirstEverFixedCost
                                                FROM [ERP_Database].[dbo].[PurchaseOrder] PO
                                                WHERE PO.ItemCode = @BOM_ItemCode
                                                    AND PO.UnitPrice IS NOT NULL
                                                    AND PO.UnitPrice > 0
                                                ORDER BY PO.ID ASC
                                            )
                                            -- ============================================
                                            -- FINAL RESULT: Choose best available fixed cost
                                            -- ============================================
                                            SELECT 
                                                @BOM_ItemCode AS ItemCode,
                                                @BOM_AddedDate AS BOMAddedDate,
                                                @TargetDate AS TargetDateConverted,
    
                                                -- Priority 1: PO Price (latest before AddedDate)
                                                PO.FixedCostFromPO,
                                                PO.POGeneratedDate AS PO_Date,
                                                PO.DBOMNo AS PO_Number,
    
                                                -- Priority 2: Receipt WAR Cost
                                                RC.FixedCostFromReceipt,
                                                RC.GINServerDate AS Receipt_Date,
    
                                                -- Priority 3: First ever price
                                                FP.FirstEverFixedCost,
	                                              PO.FixedCostFromPO as LatestPO,      -- Priority 1: Latest PO before AddedDate
                                                    RC.FixedCostFromReceipt as LatestReceipt, -- Priority 2: Latest Receipt WAR before AddedDate  
                                                    FP.FirstEverFixedCost as FirstFixedCost,
    
                                                -- FINAL SELECTED FIXED COST (in priority order)
                                                COALESCE(
                                                    PO.FixedCostFromPO,      -- Priority 1: Latest PO before AddedDate
                                                    RC.FixedCostFromReceipt, -- Priority 2: Latest Receipt WAR before AddedDate  
                                                    FP.FirstEverFixedCost    -- Priority 3: First ever PO price
                                                ) AS CorrectFixedCost,
    
                                                -- Source indicator
                                                CASE 
                                                    WHEN PO.FixedCostFromPO IS NOT NULL THEN 'FROM_PO'
                                                    WHEN RC.FixedCostFromReceipt IS NOT NULL THEN 'FROM_RECEIPT_WAR'
                                                    WHEN FP.FirstEverFixedCost IS NOT NULL THEN 'FROM_FIRST_EVER_PRICE'
                                                    ELSE 'NOT_FOUND'
                                                END AS CostSource

                                            FROM (SELECT 1 AS dummy) D
                                            LEFT JOIN LatestPO PO ON 1=1
                                            LEFT JOIN ReceiptCost RC ON 1=1
                                            LEFT JOIN FirstEverPrice FP ON 1=1;", SQLCon);



                SQLCmd.Parameters.AddWithValue("@itemcode", itemcode);
                SQLCmd.Parameters.AddWithValue("@AddedDate", AddedDate);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


