        public int UpdateMachineBOMFixedCost(string ProjectCode)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();

                SQLCmd = new SqlCommand(@"UPDATE MB
                                            SET MB.IssuedQty = ISNULL(X.NetQty, 0)
                                            FROM [ERP_Database].[dbo].[MachineBOM] MB

                                            LEFT JOIN
                                            (
                                                SELECT 
                                                    ItemCode,
                                                    ProductNo,
                                                    ProjectCode,
                                                    SUM(Qty) AS NetQty
                                                FROM
                                                (
                                                    -------------------------
                                                    -- ✅ NORMAL INDENT ISSUE
                                                    -------------------------
                                                    SELECT 
                                                        I.Item_Code AS ItemCode,
                                                        I.ProductNo,
                                                        I.Project_Code AS ProjectCode,
                                                        SUM(ISNULL(I.IssuedQuantity,0)) AS Qty
                                                    FROM Issued I
                                                    GROUP BY I.Item_Code, I.ProductNo, I.Project_Code

                                                    UNION ALL

                                                    -------------------------
                                                    -- ✅ JOB ISSUE
                                                    -------------------------
                                                    SELECT 
                                                        J.ItemCode,
                                                        w.ProductNo,
                                                        W.ProjectCode,
                                                        SUM(ISNULL(J.IssuedQuantity,0)) AS Qty
                                                    FROM JobIssue J
                                                    JOIN WorkOrder W 
                                                        ON J.WONumber = W.WONumber 
                                                        AND J.ItemCode = W.IPItemCode
                                                    GROUP BY J.ItemCode, W.ProductNo, W.ProjectCode

                                                    UNION ALL

                                                    -------------------------
                                                    -- ❌ INDENT RETURN
                                                    -------------------------
                                                    SELECT 
	                                                    IR.ItemCode,
	                                                    Issued.ProductNo,
	                                                    IR.ProjectCode,
	                                                    -SUM(ISNULL(IR.Quantity,0)) AS Qty
	                                                FROM ItemReturn IR left join Issued on Issued.Indent_Number = IR.IndentNumber and Issued.Item_Code = IR.ItemCode
	                                                GROUP BY IR.ItemCode, Issued.ProductNo, IR.ProjectCode

                                                    UNION ALL

                                                    -------------------------
                                                    -- ❌ JOB RETURN
                                                    -------------------------
                                                     SELECT 
                                                        IR.ItemCode,
                                                        WorkOrder.ProductNo,
                                                        IR.ProjectCode,
                                                        -SUM(ISNULL(IR.Quantity,0)) AS Qty
                                                    FROM ItemReturnJobIssued IR left join WorkOrder on WorkOrder.IPItemCode = IR.ItemCode and WorkOrder.ProjectCode =  IR.ProjectCode
                                                    GROUP BY IR.ItemCode, WorkOrder.ProductNo,IR.ProjectCode


                                                ) AS AllData

                                                GROUP BY ItemCode, ProductNo, ProjectCode

                                            ) X
                                                ON MB.ItemName = X.ItemCode
                                                AND (MB.ProductNo = X.ProductNo OR X.ProductNo IS NULL)
                                                AND MB.ProjectCode = X.ProjectCode

                                            WHERE MB.ProjectCode = @ProjectCode;", SQLCon);

                SQLCmd.Parameters.AddWithValue("@ProjectCode", ProjectCode);

                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                //  MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }
