        public DataSet fnMachineBOMProdutViewItems(int iCase, string sProductNo, string sProjectCode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand("Select W.IPItemCode,im.ItemDescription,W.WONumber as [PO/WO/Indent No],IPOrderQty,W.ProjectCode,PM.ProjectDescription,PM.Customer,W.VendorCode,V.VendorName from [WorkOrder] W join ItemMaster im on W.IPItemCode=im.ItemCode join Vendors V on W.VendorCode=V.VendorCode join ProjectMaster PM on W.ProjectCode=PM.ProjectCode Where W.ProductNo='" + sProductNo + "' and W.ProjectCode='" + sProjectCode + "'  union all Select W.ItemCode,im.ItemDescription,W.PONumber,POQuantity,W.ProjectCode,PM.ProjectDescription,PM.Customer,PO.VendorCode,V.VendorName from PurchaseOrderBOM W join ItemMaster im on W.ItemCode=im.ItemCode join PurchaseOrder PO on W.ItemCode=PO.ItemCode and W.PONumber=PO.DBOMNo join Vendors V on PO.VendorCode=V.VendorCode join ProjectMaster PM on W.ProjectCode=PM.ProjectCode  Where W.ProductNo='" + sProductNo + "' and W.ProjectCode='" + sProjectCode + "' union all  Select W.Item_Code,im.ItemDescription,W.Indent_Number,IssuedQuantity,W.Project_Code,PM.ProjectDescription,PM.Customer,'' as VendorCode,'' as VendorName  from Issued W join ItemMaster im on W.Item_Code=im.ItemCode join ProjectMaster PM on W.Project_Code=PM.ProjectCode Where W.ProductNo='" + sProductNo + "' and W.Project_Code='" + sProjectCode + "'", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand(@"SELECT  mb.ID, mb.[ProjectBOMCode],mb.[ProductNo],mb.[ItemName],im.ItemDescription,im.AvailableQty,mb.[Quantity],isnull(mb.IssuedQty,0) as IssuedQuantity, isnull([POQty],0) as [POQty]
                                           ,ProductType FROM [MachineBOM] mb join ItemMaster im on mb.ItemName=im.ItemCode 
                                           Where mb.ProductNo='" + sProductNo + "' and mb.ProjectCode='" + sProjectCode + "'order by ID desc", SQLCon);
                        break;
                    // case 2:
                    ////shreeshail remove column
                    //SQLCmd = new SqlCommand(@" SELECT  mb.ID, mb.[ProjectBOMCode],mb.[ProductNo],mb.[ItemName],im.ItemDescription,mb.[Quantity],mb.IssuedQty as IssuedQuantity,im.AvailableQty,im.UnitCost,mb.FixedCost,iss.unitprice as IssueCost,
                    //                   ROUND((mb.Quantity*im.FixedCost),2)as BOMAmount,round('',2)as LatestCost,mb.RevisionNo,im.DrawingNo,im.[Status],mb.AddedBy,mb.AddedDate,ProductType,'' as PODATE FROM [MachineBOM] mb join ItemMaster im on mb.ItemName=im.ItemCode  join Issued iss on mb.ItemName=iss.Item_Code and  mb.ProductNo = iss.ProductNo AND   mb.ProjectCode = iss.Project_Code
                    //                   Where mb.ProductNo='" + sProductNo + "' and mb.ProjectCode='" + sProjectCode + "'order by BOMAmount desc", SQLCon);

                    //shreeshail remove column

                    // First, get IssuedQty to decide the query
                    case 2:
                        SQLCmd = new SqlCommand(@"
                                   ;WITH IssuedAgg AS (
                                SELECT 
                                    Item_Code,
                                    ProductNo,
                                    Project_Code,
                                    SUM(unitprice) AS SumIssuedPrice,      -- change to AVG/MAX/MIN as needed
                                    COUNT(*) AS IssueCount
                                FROM Issued
                                GROUP BY Item_Code, ProductNo, Project_Code
                            )
                            SELECT 
                                mb.ID,
                                mb.ProjectBOMCode,
                                mb.ProductNo,
                                mb.ItemName,
                                im.ItemDescription,
                                mb.Quantity,
                                mb.IssuedQty AS IssuedQuantity,
                                im.AvailableQty,
                                im.UnitCost,
                                mb.FixedCost,
                               CASE WHEN ISNULL(mb.IssuedQty, 0) >= 1 THEN mb.IssuedQty*mb.FixedCost ELSE 0 END AS IssueCost,
                                ROUND((mb.Quantity * im.FixedCost), 2) AS BOMAmount,
                                CAST(NULL AS DECIMAL(18,2)) AS LatestCost,
                                mb.RevisionNo,
                                im.DrawingNo,
                                im.Status,
                                mb.AddedBy,
                                mb.AddedDate,
                                mb.ProductType,
                                '' AS PODATE,
                                ia.IssueCount
                            FROM MachineBOM mb
                            JOIN ItemMaster im 
                              ON mb.ItemName = im.ItemCode
                            LEFT JOIN IssuedAgg ia
                              ON ia.Item_Code    = mb.ItemName
                             AND ia.ProductNo    = mb.ProductNo
                             AND ia.Project_Code = mb.ProjectCode
                            WHERE mb.ProductNo   =  @ProductNo
                              AND mb.ProjectCode = @ProjectCode
                            ORDER BY BOMAmount DESC;", SQLCon);
                        // CASE WHEN ISNULL(mb.IssuedQty, 0) >= 1 THEN ia.SumIssuedPrice ELSE 0 END AS IssueCost, this line rk changed
                        SQLCmd.Parameters.AddWithValue("@ProductNo", sProductNo);
                        SQLCmd.Parameters.AddWithValue("@ProjectCode", sProjectCode);
                        break;
                    //case 3:
                    //    SQLCmd = new SqlCommand(@" SELECT  mb.ID, mb.[ProjectBOMCode],mb.[ProductNo],mb.[ItemName],im.ItemDescription,mb.[Quantity],mb.IssuedQty as IssuedQuantity,im.AvailableQty,im.UnitCost,mb.FixedCost,iss.unitprice as IssueCost,
                    //                       ROUND((mb.Quantity*im.FixedCost),2)as BOMAmount,round('',2)as LatestCost,mb.RevisionNo,im.DrawingNo,im.[Status],mb.RefItemCode,mb.AddedBy,mb.AddedDate,ProductType,'' as PODATE FROM [MachineBOM] mb join ItemMaster im on mb.ItemName=im.ItemCode join Issued iss on mb.ItemName=iss.Item_Code and  mb.ProjectCode = iss.Project_Code  AND mb.ProductNo = iss.ProductNo
                    //                       Where mb.ProductNo='" + sProductNo + "' and mb.ProjectCode='" + sProjectCode + "'order by mb.ID asc", SQLCon);
                    //    break;
                    case 3:
                        SQLCmd = new SqlCommand(@"
             SELECT 
            mb.ID,
            mb.ProjectBOMCode,
            mb.ProductNo,
            mb.ItemName,
            im.ItemDescription,
            mb.Quantity,
            mb.IssuedQty AS IssuedQuantity,
            im.AvailableQty,
            im.UnitCost,
            mb.FixedCost,
            CASE 
                WHEN ISNULL(mb.IssuedQty, 0) >= 1 THEN ISNULL(iss.unitprice, 0)
                ELSE 0
            END AS IssueCost,
            ROUND((mb.Quantity * ISNULL(im.FixedCost, 0)), 2) AS BOMAmount,
            ROUND(NULL, 2) AS LatestCost,
            mb.RevisionNo,
            im.DrawingNo,
            im.Status,
            mb.RefItemCode,
            mb.AddedBy,
            mb.AddedDate,
            ProductType,
            '' AS PODATE
        FROM MachineBOM mb
        JOIN ItemMaster im 
            ON mb.ItemName = im.ItemCode
        LEFT JOIN Issued iss 
            ON mb.ItemName = iss.Item_Code 
            AND mb.ProductNo = iss.ProductNo 
            AND mb.ProjectCode = iss.Project_Code
        WHERE mb.ProductNo = @ProductNo 
            AND mb.ProjectCode = @ProjectCode
        ORDER BY mb.ID ASC", SQLCon);

                        SQLCmd.Parameters.AddWithValue("@ProductNo", sProductNo);
                        SQLCmd.Parameters.AddWithValue("@ProjectCode", sProjectCode);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand(@"select * from PurchaseOrder as P1 where P1.ProjectCode='" + sProjectCode + "' and POGeneratedDate !='' " +
                                              "and POGeneratedDate is not null and POGeneratedBy!='' and POGeneratedBy!='Deleted' and " +
                                              "P1.ID=(select MAX(P2.ID) from PurchaseOrder AS P2 where P2.ProjectCode='" + sProjectCode + "' and P1.ItemCode=P2.ItemCode " +
                                              "and POGeneratedDate!='' and POGeneratedDate is not null and POGeneratedBy!='' and POGeneratedBy!='Deleted') " +
                                              "order by ID", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


