        public DataSet fnProductBOMList(string sParentid, string sName)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sName == null && sParentid == null)
                {
                    SQLCmd = new SqlCommand("Select * from ProductTreeView", SQLCon);
                }
                else if (sName != null && sParentid == null)
                {
                    SQLCmd = new SqlCommand("Select * from SalesProductTreeView Where ProductCode='" + sName + "'", SQLCon);
                }

