        public int fnUpdateMachinBOMPO(uint InOrUPOrDel, string POQty, string ItemName, string ProjectCode, string ProductNo)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (InOrUPOrDel)
                {
                    case 1:
                        {
                            SQLCmd = new SqlCommand("update [MachineBOM] set POQty=(IsNull(POQty, 0) + '" + POQty + "') where ItemName='" + ItemName + "' and ProjectCode='" + ProjectCode + "' and ProductNo='" + ProductNo + "'", SQLCon);
                            break;
                        }
                    case 2:
                        {
                            SQLCmd = new SqlCommand("update [MachineBOM] set POQty=(IsNull(POQty, 0) - '" + POQty + "') where ItemName='" + ItemName + "' and ProjectCode='" + ProjectCode + "' and ProductNo='" + ProductNo + "'", SQLCon);
                            break;
                        }
                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }

        //bhavya added  to check whether the pproject is present or not in purchaseorderbom

        // Check if the item exists
        public bool CheckIfItemExists(string PONumber, string ItemCode, string ProjectCode, string ProductNo)
        {
            string query = "SELECT COUNT(1) FROM PurchaseOrderBOM WHERE PONumber = @PONumber AND ItemCode = @ItemCode AND ProjectCode = @ProjectCode AND ProductNo = @ProductNo";

            using (SqlCommand cmd = new SqlCommand(query, SQLCon))
            {
                cmd.Parameters.AddWithValue("@PONumber", PONumber);
                cmd.Parameters.AddWithValue("@ItemCode", ItemCode);
                cmd.Parameters.AddWithValue("@ProjectCode", ProjectCode);
                cmd.Parameters.AddWithValue("@ProductNo", ProductNo);

                SQLCon.Open();
                int count = Convert.ToInt32(cmd.ExecuteScalar());
                SQLCon.Close();

                return count > 0;
            }
        }

