        public DataSet fnVersionProductBOMList(string sParentid, string sVersion)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sParentid != null && sVersion != null)
                {
                    SQLCmd = new SqlCommand(@"SELECT tv.[ParentID],tv.[ItemCode],im.ItemDescription,tv.[MfgPartNo],tv.[Make],tv.[Specification],tv.[Location],
                                            tv.[Vendor],im.[DrawingNo],tv.[Quantity],im.[Type],ROUND(im.UnitCost,2) as UnitCost,ROUND(im.FixedCost,2) as FixedCost,ROUND((tv.Quantity*im.FixedCost),2) as Amount,
                                            round('',2)as LatestCost,Version,ProductType FROM [TreeViewItems] tv join ItemMaster im on tv.[ItemCode]=im.ItemCode 
                                            Where ParentID='" + sParentid + "' and Version='" + sVersion + "' order by tv.ID asc", SQLCon);
                }
                else if (sParentid != null && sVersion == null)
                {
                    SQLCmd = new SqlCommand(@"SELECT tv.[ParentID],tv.[ItemCode],im.ItemDescription,tv.[MfgPartNo],tv.[Make],tv.[Specification],tv.[Location],
                                            tv.[Vendor],im.[DrawingNo],tv.[Quantity],im.[Type],ROUND(im.UnitCost,2) as UnitCost,ROUND(im.FixedCost,2) as FixedCost,ROUND((tv.Quantity*im.FixedCost),2) as Amount,
                                            round('',2)as LatestCost,Version,ProductType FROM [TreeViewItems] tv join ItemMaster im on tv.[ItemCode]=im.ItemCode 
                                            Where ParentID='" + sParentid + "' order by Amount desc", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
