        public DataSet fnEXCELProductBOMList(string sParentid, string sVersion)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sParentid != null)
                {

                    SQLCmd = new SqlCommand(@"SELECT ROW_NUMBER() OVER (ORDER BY tv.[ItemCode]) AS [Slno],tv.[ItemCode],im.ItemDescription,im.FixedCost,
                                              tv.[MfgPartNo],tv.[Make],tv.[Quantity],ROUND(im.UnitCost,2) as UnitCost,tv.[Specification],im.[Type],tv.[Location],tv.[Vendor],tv.[DrawingNo],tv.[Version],'' as [ProductType]
                                              FROM [TreeViewItems] tv join ItemMaster im on tv.[ItemCode]=im.ItemCode Where ParentID='" + sParentid + "' and tv.Version='" + sVersion + "'", SQLCon);
                }
                else
                {
                    if (sVersion == null)
                    {
                        SQLCmd = new SqlCommand(@"SELECT  [ProductCode],[Name] ,[ProductDescription],[SalesCost],[ProductCost] as [ProductPrice] FROM [SalesProductTreeView] Where [ImageIndex] !=0", SQLCon);
                    }
                    else
                    {
                        SQLCmd = new SqlCommand(@"SELECT  [ProductCode],[Name] ,[ProductDescription],[SalesCost],[ProductCost] as [ProductPrice] FROM [SalesProductTreeView] Where ParentID ='" + sVersion + "'", SQLCon);
                    }
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
        public string fnGetLastProjectBOMCode()
        {
            try
            {
                dtLastCode = new DataTable();
                SQLDataset = new DataSet();
                SQLCon.Open();
                SQLCmd = new SqlCommand("select * from  ProjectBOM where ProjectBOMNumber=(select max(ProjectBOMNumber) from ProjectBOM)", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset, "LastProjectBOMCode");
                dtLastCode = SQLDataset.Tables["LastProjectBOMCode"];
                if (dtLastCode.Rows.Count > 0)
                    sLastCode = dtLastCode.Rows[0]["ProjectBOMCode"].ToString();
                else
                    sLastCode = string.Empty;
                SQLCon.Close();
                return sLastCode;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return string.Empty;
            }
        }

        public DataSet fnCheckLogin(int iCase, string sUserName, string sPassword, double uVersion)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand("Select *,DATEDIFF (day,PasswordChangeDate,getdate()) as PasswordExpiryDays from Login where UserName='" + sUserName + "' and LoginPassword='" + sPassword + "'", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand("Select * from Login where AuthorisedPreson='" + sUserName + "'", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand("Select * from Login where AuthorisedPerson2='" + sPassword + "'", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand("Select ERPVersion from Login where UserName='" + sUserName + "'  and LoginPassword='" + sPassword + "'", SQLCon);
                        break;
                    case 4:
                        SQLCmd = new SqlCommand("Select *,DATEDIFF (day,PasswordChangeDate,getdate()) as PasswordExpiryDays from Login where UserName='" + sUserName + "'", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }

            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

