        public DataTable fnGetChargesByDescription(string poNumber)
        {
            SqlCommand cmd = new SqlCommand(@"SELECT TaxDescription, Amount 
                                      FROM [POPackingForwarding]
                                      WHERE PONo = @poNumber 
                                      AND TaxDescription IN ('Transportation / Freight', 'Packing & Forwarding')", SQLCon);

            cmd.Parameters.AddWithValue("@poNumber", poNumber);

            SqlDataAdapter da = new SqlDataAdapter(cmd);
            DataTable dt = new DataTable();
            da.Fill(dt);
            return dt;
        }




