        public DataSet WoOrderDataset(string wonumber)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (wonumber == null)
                    SQLCmd = new SqlCommand(" select JWNumber,[WONumber],isnull(OPItemCode,'Empty') as ItemCode,[UnitCost],VendorCode,OPRemainingQty,[OPOrderQty]  FROM [WorkOrder] W join ProjectMaster PM on W.ProjectCode=PM.ProjectCode  where WOStatus='Open'   and  OPRemainingQty!=0 and (WOGeneratedBy!=''and WOGeneratedBy is not null) order by WONumber desc", SQLCon);//shreeshail is remove and PM.Status='WIP'
                //select JWNumber,[WONumber],isnull(OPItemCode,'Empty') as ItemCode,[UnitCost],VendorCode,OPRemainingQty,[OPOrderQty]  FROM [WorkOrder] where WOStatus='Open'  and OPRemainingQty!=0 and (WOGeneratedBy!=''and WOGeneratedBy is not null) order by WONumber desc
                else
                    SQLCmd = new SqlCommand(@"select w.jwnumber,w.WONumber,w.OPItemCode as ItemCode,im.ItemDescription,im.HsnSacCode,w.UnitCost as UnitPrice,w.VendorCode,v.VendorName,v.GSTCode,w.OPRemainingQty as RemainingQty ,w.OPOrderQty as RequariedQty,
                                                (w.UnitCost*w.OPRemainingQty) as Amount,0.0 as DiscRate,0.0 as DiscAmount,w.PreparedBy,w.ProjectCode,pm.ProjectDescription,pm.Customer,isnull(w.[IGSTRate],0) as IGSTRate ,isnull(w.[IGSTAmount],0) as IGSTAmount,isnull(w.[SGSTRate],0) as SGSTRate ,isnull(w.[SGSTAmount],0) as SGSTAmount 
                                                ,isnull(w.[CGSTRate],0) as CGSTRate,isnull(w.[CGSTAmount],0) as CGSTAmount,w.WOgeneratedDate,0.0 as Freight,0.0 as CustomsDuty,0.0 as CustomsDutyAmt,0.0 as Cess,0.0 as CessAmt,0.0 as CDIGST,0.0 as CDIGSTAmt,Country  from WorkOrder w join ItemMaster IM on w.OPItemCode=im.ItemCode 
                                                join Vendors v on w.VendorCode=v.VendorCode join ProjectMaster pm on w.ProjectCode=pm.ProjectCode where [WONumber]='" + wonumber + "' and WOStatus='Open' and  OPRemainingQty!=0 and (WOGeneratedBy!=''and WOGeneratedBy is not null)", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }

        }

