        public DataSet fnGetFilteredIndentERPInventorylog(string fromDate, string toDate, string projectPrefix, string categoryPrefix)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();

                string query = "SELECT * FROM ERPInventoryIndent WHERE 1=1";

                if (!string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(toDate))
                    query += $" AND CONVERT(datetime, IndentDate, 105) BETWEEN CONVERT(datetime, '{fromDate}', 105) AND CONVERT(datetime, '{toDate}', 105)";
                // query += $" AND CreatedDate BETWEEN CONVERT(datetime, '{fromDate}', 105) AND CONVERT(datetime, '{toDate}', 105)";


                if (!string.IsNullOrEmpty(projectPrefix))
                    query += $" AND ProjectCode LIKE '{projectPrefix}%'";

                if (!string.IsNullOrEmpty(categoryPrefix))
                    query += $" AND ItemCode LIKE '{categoryPrefix}%'";

                //if (!string.IsNullOrEmpty(itemPrefix))
                //  query += $" AND ItemCode LIKE '{itemPrefix}%'";

                SQLCmd = new SqlCommand(query, SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();

                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnGetFilteredIndentERPInventorylogtest(string fromDate, string toDate, string projectPrefix, string categoryPrefix, string status, string indentNumber)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();

                string baseQuery = "FROM ERPInventoryIndent WHERE 1=1";

                if (!string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(toDate))
                    baseQuery += $" AND CONVERT(datetime, IndentDate, 105) BETWEEN CONVERT(datetime, '{fromDate}', 105) AND CONVERT(datetime, '{toDate}', 105)";

                if (!string.IsNullOrEmpty(projectPrefix))
                    baseQuery += $" AND ProjectCode LIKE '{projectPrefix}%'";

                if (!string.IsNullOrEmpty(categoryPrefix))
                    baseQuery += $" AND ItemCode LIKE '{categoryPrefix}%'";

                if (!string.IsNullOrEmpty(status))
                    baseQuery += $" AND Status LIKE '{status}%'";

                if (!string.IsNullOrEmpty(indentNumber))
                    baseQuery += $" AND IndentNo LIKE '{indentNumber}%'";

                // Query 1: Get filtered data
                string dataQuery = "SELECT * " + baseQuery;
                SQLCmd = new SqlCommand(dataQuery, SQLCon);
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset, "FilteredData");

                // Query 2: Get sum of IndentQty
                string sumQuery = "SELECT SUM(IndentQty) AS TotalIndentQty " + baseQuery;
                SQLCmd = new SqlCommand(sumQuery, SQLCon);
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset, "TotalIndentQty");

                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }




