        public int GetERPInventoryReceivedQty_test(string itemCode)
        {
            int totalReceivedQty = 0;

            string connectionString = "your_connection_string_here";
            string query = @"SELECT ISNULL(SUM(ReceivedQtY), 0) 
                     FROM [ERP_Database].[dbo].[ERPInventoryLogs]
                     WHERE ItemCode = @ItemCode";

            using (SqlConnection conn = new SqlConnection(connectionString))
            {
                using (SqlCommand cmd = new SqlCommand(query, conn))
                {
                    cmd.Parameters.AddWithValue("@ItemCode", itemCode);

                    conn.Open();
                    object result = cmd.ExecuteScalar();
                    if (result != DBNull.Value)
                    {
                        totalReceivedQty = Convert.ToInt32(result);
                    }
                }
            }

            return totalReceivedQty;
        }

        public void GetERPInventoryReceivedQty(string itemCode, string QtyName)
        {
            int totalReceivedQty = 0;

            SQLDataset = new DataSet();
            SQLCon.Open();

            if (!string.IsNullOrEmpty(itemCode))
            {
                switch (QtyName)
                {
                    case "ReceivedQtY":
                        {
                            SQLCmd = new SqlCommand(
                            "SELECT ISNULL(SUM(ReceivedQtY), 0) " +
                            "FROM [ERP_Database].[dbo].[ERPInventoryLogs] " +
                            "WHERE ItemCode = @ItemCode", SQLCon);

                            SQLCmd.Parameters.AddWithValue("@ItemCode", itemCode);
                            break;
                        }
                    case "RemainingQty":
                        {
                            SQLCmd = new SqlCommand(
                            "SELECT ISNULL(SUM(RemainingQty), 0) " +
                            "FROM [ERP_Database].[dbo].[ERPInventoryLogs] " +
                            "WHERE ItemCode = @ItemCode", SQLCon);

                            SQLCmd.Parameters.AddWithValue("@ItemCode", itemCode);
                            break;
                        }
                    case "IssuedQty":
                        {
                            SQLCmd = new SqlCommand(
                            "SELECT ISNULL(SUM(IssuedQty), 0) " +
                            "FROM [ERP_Database].[dbo].[ERPInventoryLogs] " +
                            "WHERE ItemCode = @ItemCode", SQLCon);

                            SQLCmd.Parameters.AddWithValue("@ItemCode", itemCode);
                            break;
                        }


                }


                object result = SQLCmd.ExecuteScalar();
                if (result != DBNull.Value)
                {
                    totalReceivedQty = Convert.ToInt32(result);
                }

                //MessageBox.Show(totalReceivedQty.ToString(), QtyName);


            }

            SQLCon.Close();
        }

