                                 SELECT WithoutBOM 
                                FROM PurchaseOrder 
                                 WHERE DBOMNo = @sPONumber", SQLCon);
                    // Declare the parameter and set its value
                    SQLCmd.Parameters.AddWithValue("@sPONumber", sPONumber);

                    // Execute the query and retrieve the result

                    var withoutBOM = SQLCmd.ExecuteScalar(); // ExecuteScalar will return the value of WithoutBOM

                    // Check if the WithoutBOM column is true (1)
                    if (withoutBOM != DBNull.Value && Convert.ToBoolean(withoutBOM))
                    {
                        SQLCmd = new SqlCommand(@"select P.DBOMNo,P.ProjectCode,PM.ProjectDescription,PM.Customer,P.ItemCode,IM.ItemDescription,IM.HsnSacCode,P.VendorCode,V.VendorName,V.GSTCode,P.RemainingQty,P.UnitPrice,P.RequariedQty,CASE WHEN FXRate is NULL THEN(P.UnitPrice*P.RequariedQty)/1 else CAST((P.UnitPrice*P.RequariedQty)/FxRate AS DECIMAL(16,2)) end as Amount,(P.UnitPrice*P.RequariedQty) as POAmount,P.[POGeneratedDate],P.[Remarks],P.[PMMHRemarks],P.[PCRemarks],
                                                     P.PreparedBy,isnull(P.[IGSTRate],0) as IGSTRate ,isnull(P.[IGSTAmount],0) as IGSTAmount,isnull(P.[SGSTRate],0) as SGSTRate ,isnull(P.[SGSTAmount],0) as SGSTAmount ,isnull(P.[CGSTRate],0) as CGSTRate,isnull(P.[CGSTAmount],0) as CGSTAmount,isnull(P.[DiscRate],0) as DiscRate,
                                                      isnull(P.[DiscAmount],0) as DiscAmount,0.0 as Freight,0.0 as CustomsDuty,0.0 as CustomsDutyAmt,0.0 as Cess,0.0 as CessAmt,0.0 as CDIGST,0.0 as CDIGSTAmt,P.Currency,P.FXRate,Country FROM PurchaseOrder P join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join ItemMaster IM on P.ItemCode=IM.Itemcode 
                                                      join Vendors V on P.VendorCode=V.VendorCode where P.DBOMNo ='" + sPONumber + "' and P.RemainingQty!=0 and P.POGeneratedBy!='' and P.POGeneratedBy!='Deleted'", SQLCon);









                        //

                        //SQLCmd = new SqlCommand(@"select P.DBOMNo,P.ProjectCode,PM.ProjectDescription,PM.Customer,P.ItemCode,IM.ItemDescription,IM.HsnSacCode,P.VendorCode,V.VendorName,V.GSTCode,P.RemainingQty,P.UnitPrice,P.RequariedQty,CASE WHEN FXRate is NULL THEN(P.UnitPrice*P.RequariedQty)/1 else CAST((P.UnitPrice*P.RequariedQty)/FxRate AS DECIMAL(16,2)) end as Amount,(P.UnitPrice*P.RequariedQty) as POAmount,P.[POGeneratedDate],P.[Remarks],P.[PMMHRemarks],P.[PCRemarks],
                        //                              P.PreparedBy,isnull(P.[IGSTRate],0) as IGSTRate ,isnull(P.[IGSTAmount],0) as IGSTAmount,isnull(P.[SGSTRate],0) as SGSTRate ,isnull(P.[SGSTAmount],0) as SGSTAmount ,isnull(P.[CGSTRate],0) as CGSTRate,isnull(P.[CGSTAmount],0) as CGSTAmount,isnull(P.[DiscRate],0) as DiscRate,
                        //                               isnull(P.[DiscAmount],0) as DiscAmount,0.0 as Freight,0.0 as CustomsDuty,0.0 as CustomsDutyAmt,0.0 as Cess,0.0 as CessAmt,0.0 as CDIGST,0.0 as CDIGSTAmt,P.Currency,P.FXRate,Country FROM PurchaseOrder P join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join ItemMaster IM on P.ItemCode=IM.Itemcode 
                        //                               join Vendors V on P.VendorCode=V.VendorCode where P.DBOMNo ='" + sPONumber + "' and P.RemainingQty!=0 and P.POGeneratedBy!='' and P.POGeneratedBy!='Deleted'", SQLCon);



                        //SQLCmd = new SqlCommand(@"select P.DBOMNo,P.ProjectCode,PM.ProjectDescription,PM.Customer,P.ItemCode,
                        // POB.ProjectCode AS BOMProjectCode,  
                        //    POB.ProductNo AS ProductNo,
                        //IM.ItemDescription,IM.HsnSacCode,P.VendorCode,V.VendorName,V.GSTCode,P.RemainingQty,P.UnitPrice,P.RequariedQty,CASE WHEN FXRate is NULL THEN(P.UnitPrice*P.RequariedQty)/1 else CAST((P.UnitPrice*P.RequariedQty)/FxRate AS DECIMAL(16,2)) end as Amount,(P.UnitPrice*P.RequariedQty) as POAmount,P.[POGeneratedDate],P.[Remarks],P.[PMMHRemarks],P.[PCRemarks], P.PreparedBy,isnull(P.[IGSTRate],0) as IGSTRate ,isnull(P.[IGSTAmount],0) as IGSTAmount,isnull(P.[SGSTRate],0) as SGSTRate ,isnull(P.[SGSTAmount],0) as SGSTAmount ,isnull(P.[CGSTRate],0) as CGSTRate,isnull(P.[CGSTAmount],0) as CGSTAmount,isnull(P.[DiscRate],0) as DiscRate, isnull(P.[DiscAmount],0) as DiscAmount,0.0 as Freight,0.0 as CustomsDuty,0.0 as CustomsDutyAmt,0.0 as Cess,0.0 as CessAmt,0.0 as CDIGST,0.0 as CDIGSTAmt,P.Currency,P.FXRate,Country FROM PurchaseOrder P join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join ItemMaster IM on P.ItemCode=IM.Itemcode   join Vendors V on P.VendorCode=V.VendorCode	JOIN   PurchaseOrderBOM POB ON P.DBOMNo = POB.PONumber AND P.ItemCode = POB.ItemCode where P.DBOMNo ='" + sPONumber + "' and P.RemainingQty!=0 and P.POGeneratedBy!='' and P.POGeneratedBy!='Deleted'", SQLCon);

                    }
                    else
                    {
                        SQLCmd = new SqlCommand(@"
                    SELECT 
        P.DBOMNo,
        P.ProjectCode,
        PM.ProjectDescription,
        PM.Customer,
        P.ItemCode,
        POB.ProjectCode AS BOMProjectCode,
        POB.ProductNo AS ProductNo,
        IM.ItemDescription,
        IM.HsnSacCode,
        P.VendorCode,
        V.VendorName,
        V.GSTCode,

        -- Calculate remaining quantity
        POB.POQuantity - ISNULL(SUM(R.Quantity), 0) AS RemainingQty,

        P.UnitPrice,
        POB.POQuantity AS RequariedQty,
        
        CASE 
            WHEN P.FXRate IS NULL OR P.FXRate = 0 
                THEN (P.UnitPrice * POB.POQuantity)
            ELSE 
                CAST((P.UnitPrice * POB.POQuantity) / P.FXRate AS DECIMAL(16,2))
        END AS Amount,

        (P.UnitPrice * POB.POQuantity) AS POAmount,

        P.POGeneratedDate,
        P.PreparedBy,

        ISNULL(P.IGSTRate, 0) AS IGSTRate,
        ISNULL(P.IGSTAmount, 0) AS IGSTAmount,
        ISNULL(P.SGSTRate, 0) AS SGSTRate,
        ISNULL(P.SGSTAmount, 0) AS SGSTAmount,
        ISNULL(P.CGSTRate, 0) AS CGSTRate,
        ISNULL(P.CGSTAmount, 0) AS CGSTAmount,
        ISNULL(P.DiscRate, 0) AS DiscRate,
        ISNULL(P.DiscAmount, 0) AS DiscAmount,

        0.0 AS Freight,
        0.0 AS CustomsDuty,
        0.0 AS CustomsDutyAmt,
        0.0 AS Cess,
        0.0 AS CessAmt,
        0.0 AS CDIGST,
        0.0 AS CDIGSTAmt,

        P.Currency,
        P.FXRate,
        Country,

       -- Aggregate text/ntext fields
        MAX(CAST(P.Remarks AS VARCHAR(MAX))) AS Remarks,
        MAX(CAST(P.PMMHRemarks AS VARCHAR(MAX))) AS PMMHRemarks,
        MAX(CAST(P.PCRemarks AS VARCHAR(MAX))) AS PCRemarks

    FROM 
        PurchaseOrder P
        JOIN ProjectMaster PM ON P.ProjectCode = PM.ProjectCode
        JOIN ItemMaster IM ON P.ItemCode = IM.ItemCode
        JOIN Vendors V ON P.VendorCode = V.VendorCode
        JOIN PurchaseOrderBOM POB 
            ON P.DBOMNo = POB.PONumber 
            AND P.ItemCode = POB.ItemCode
        LEFT JOIN Receipt R 
            ON R.RefNumber = POB.PONumber 
            AND R.ItemCode = POB.ItemCode 
            AND R.BOMProjectCode = POB.ProjectCode 
            AND R.ProductNo = POB.ProductNo

    WHERE 
        P.DBOMNo =@PONumber
        AND P.POGeneratedBy != ''
        AND P.POGeneratedBy != 'Deleted'
        AND P.RemainingQty != 0

    GROUP BY 
        P.DBOMNo,
        P.ProjectCode,
        PM.ProjectDescription,
        PM.Customer,
        P.ItemCode,
        POB.ProjectCode,
        POB.ProductNo,
        IM.ItemDescription,
        IM.HsnSacCode,
        P.VendorCode,
        V.VendorName,
        V.GSTCode,
        P.UnitPrice,
        POB.POQuantity,
        P.POGeneratedDate,
        P.PreparedBy,
        P.IGSTRate,
        P.IGSTAmount,
        P.SGSTRate,
        P.SGSTAmount,
        P.CGSTRate,
        P.CGSTAmount,
        P.DiscRate,
        P.DiscAmount,
        P.Currency,
        P.FXRate,
        Country

    HAVING 
        POB.POQuantity - ISNULL(SUM(R.Quantity), 0) > 0;

                                  
                        ", SQLCon);

                        // SQLCmd = new SqlCommand(@"SELECT P.DBOMNo, P.ProjectCode, PM.ProjectDescription, PM.Customer, P.ItemCode, POB.ProjectCode AS BOMProjectCode, POB.ProductNo AS ProductNo, IM.ItemDescription, IM.HsnSacCode, P.VendorCode, V.VendorName, V.GSTCode, P.RemainingQty, P.UnitPrice, POB.POQuantity AS RequariedQty, CASE WHEN FXRate IS NULL THEN (P.UnitPrice * POB.POQuantity) / 1 ELSE CAST((P.UnitPrice * POB.POQuantity) / FxRate AS DECIMAL(16,2)) END AS Amount, (P.UnitPrice * POB.POQuantity) AS POAmount, P.POGeneratedDate, P.Remarks, P.PMMHRemarks, P.PCRemarks, P.PreparedBy, ISNULL(P.IGSTRate, 0) AS IGSTRate, ISNULL(P.IGSTAmount, 0) AS IGSTAmount, ISNULL(P.SGSTRate, 0) AS SGSTRate, ISNULL(P.SGSTAmount, 0) AS SGSTAmount, ISNULL(P.CGSTRate, 0) AS CGSTRate, ISNULL(P.CGSTAmount, 0) AS CGSTAmount, ISNULL(P.DiscRate, 0) AS DiscRate, ISNULL(P.DiscAmount, 0) AS DiscAmount, 0.0 AS Freight, 0.0 AS CustomsDuty, 0.0 AS CustomsDutyAmt, 0.0 AS Cess, 0.0 AS CessAmt, 0.0 AS CDIGST, 0.0 AS CDIGSTAmt, P.Currency, P.FXRate, Country FROM PurchaseOrder P JOIN ProjectMaster PM ON P.ProjectCode = PM.ProjectCode JOIN ItemMaster IM ON P.ItemCode = IM.ItemCode JOIN Vendors V ON P.VendorCode = V.VendorCode JOIN PurchaseOrderBOM POB ON P.DBOMNo = POB.PONumber AND P.ItemCode = POB.ItemCode WHERE P.DBOMNo = @PONumber AND P.RemainingQty != 0 AND P.POGeneratedBy != '' AND P.POGeneratedBy != 'Deleted' AND NOT EXISTS (SELECT 1 FROM Receipt R WHERE R.RefNumber = POB.PONumber AND R.ItemCode = POB.ItemCode AND R.BOMProjectCode = POB.ProjectCode AND R.ProductNo = POB.ProductNo)", SQLCon);
                        // Ensure parameter name matches @PONumber in query
                        SQLCmd.Parameters.AddWithValue("@PONumber", sPONumber);

                        using (SqlDataReader reader = SQLCmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                Console.WriteLine($"Pending GIN - DBOMNo: {reader["DBOMNo"]}, Item: {reader["ItemCode"]}, Project: {reader["ProjectCode"]}, Product: {reader["ProductNo"]}");
                            }
                            // Close the reader explicitly (optional here due to 'using' statement)
                            reader.Close();
                        }
                    }



                }

                else if (sPONumber == null && Table != null)
                {
                    SQLCmd = new SqlCommand("select DBOMNo,P.ProjectCode,ItemCode,VendorCode,RemainingQty,UnitPrice,RequariedQty,AuthoriedBy FROM PurchaseOrder P join ProjectMaster PM on P.ProjectCode=PM.ProjectCode where RemainingQty!=0 and POGeneratedBy!='' and POGeneratedBy!='Deleted' ", SQLCon); //shreeshail removed form where condtion and PM.Status='WIP'
                    //select DBOMNo,ProjectCode,ItemCode,VendorCode,RemainingQty,UnitPrice,RequariedQty,AuthoriedBy FROM PurchaseOrder where RemainingQty!=0 and POGeneratedBy!='' and POGeneratedBy!='Deleted'
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

