        public int fnUpdatePoProcess(uint InOrUPOrDel, string PONumber, string ApprovedBy, string ApprovedDate, string remarks)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (InOrUPOrDel)
                {
                    case 1:
                        {
                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET PMName='" + ApprovedBy + "',[PMApproved]='1',PMApprovedDate='" + ApprovedDate + "',PMRemarks='" + remarks + "' WHERE DBOMNo='" + PONumber + "' ", SQLCon);

                            break;
                        }
                    case 2:
                        {
                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET MHName='" + ApprovedBy + "',[MHApproved]='1',MHApprovedDate='" + ApprovedDate + "',PMMHRemarks='" + remarks + "'WHERE DBOMNo='" + PONumber + "'", SQLCon);

                            break;
                        }
                    case 3:
                        {
                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET PurchaseCommitee='" + ApprovedBy + "',PCAuthoriseDate='" + ApprovedDate + "',PCRemarks='" + remarks + "' WHERE DBOMNo='" + PONumber + "'", SQLCon);
                            break;
                        }

                    case 4:
                        {
                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET FinanceApproverName='" + ApprovedBy + "',FinanceApprovedDate='" + ApprovedDate + "',FinanceRemarks='" + remarks + "' WHERE DBOMNo='" + PONumber + "'", SQLCon);
                            break;
                        }

                    case 5:
                        {
                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET FinalizedBy='" + ApprovedBy + "',FinalizedDate='" + ApprovedDate + "',POApproved=0,FinalizedRemarks='" + remarks + "' WHERE DBOMNo='" + PONumber + "'", SQLCon);
                            break;
                        }


                    case 6:
                        {
                            SQLCmd = new SqlCommand("Insert into  POGeneralTerms ([PONo],[POGeneralTerms],[AddedBy]) values ('" + PONumber + "','" + remarks + "','" + ApprovedBy + "')", SQLCon);
                            break;
                        }

                    case 7:
                        {
                            SQLCmd = new SqlCommand("Delete FROM  POGeneralTerms where [PONo]='" + PONumber + "'", SQLCon);
                            break;
                        }
                    case 8:
                        {
                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET FinalizedBy='" + ApprovedBy + "',FinalizedDate='" + ApprovedDate + "',POApproved=1,FinalizedRemarks='" + remarks + "',GMName='--' WHERE DBOMNo='" + PONumber + "'", SQLCon);
                            break;
                        }

                    case 9:
                        {
                            // PO total (Amount + GST) <= 50000 — Purchase Committee can fully approve (no OM/GM)
                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET PurchaseCommitee='" + ApprovedBy + "',PCAuthoriseDate='" + ApprovedDate + "',PCRemarks='" + remarks + "',OMName='--',OMRemarks='--',OMApproved=1,OMApprovedDate='" + ApprovedDate + "',GMName='--',POApproved=1 WHERE DBOMNo='" + PONumber + "'", SQLCon);
                            break;
                        }
                    case 10:
                        {
                            // PO total (Amount + GST) > 50000 — PC done; OM (Vivek G) still required
                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET PurchaseCommitee='" + ApprovedBy + "',PCAuthoriseDate='" + ApprovedDate + "',PCRemarks='" + remarks + "',OMApproved=0,POApproved=0 WHERE DBOMNo='" + PONumber + "'", SQLCon);
                            break;
                        }

                    case 11:
                        {

                            SQLCmd = new SqlCommand("UPDATE PurchaseOrder SET PurchaseCommitee='" + ApprovedBy + "',PCAuthoriseDate='" + ApprovedDate + "',PCRemarks='" + remarks + "' WHERE DBOMNo='" + PONumber + "'", SQLCon);
                            break;
                        }
                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }

