        public Double fnReturnItemList(string sProjectCode, string sitemcode, string sIndentNumber)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sProjectCode != null)
                    SQLCmd = new SqlCommand(" select [ItemCode],sum([Quantity])  as SumQuantity from [ItemReturn] where  [ProjectCode]='" + sProjectCode + "'and [ItemCode]='" + sitemcode + "' and IndentNumber='" + sIndentNumber + "' group by [ItemCode]", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                double dSumQty = Convert.ToDouble(SQLDataset.Tables[0].Rows.Count == 0 ? "0.0" : (SQLDataset.Tables[0].Rows[0]["SumQuantity"].ToString()));
                return dSumQty;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return 0.0;
            }
        }

