        public string fnCreateERPItemLocation(string action, string itemCode, string store, string floor, string location)
        {
            try
            {
                SQLDataset = new DataSet();

                SQLCon.Open();

                string itemLocation_ = location.Substring(location.Length - 1); ;
                if (itemLocation_ == "-")
                {
                    location = location.Substring(0, location.Length - 1);
                }

                switch (action)
                {
                    case "NEW":
                        {
                            SQLCmd = new SqlCommand(@"Insert into ERPItemLocation(ItemCode, Store,Floor, Location)  values
                                                    ('" + itemCode + "','" + store + "','" + floor + "','" + location + "')", SQLCon);
                            break;
                        }
                }
                SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return "Created ERP Item Location...";
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return "Create ERP Item Location faild..";
            }
        }


