        public string fnUpateItemLocationInAllTable(string ItemLocation, string itemcode)
        {

            //MessageBox.Show(ItemLocation,itemcode);

            string itemLocation_ = ItemLocation.Substring(ItemLocation.Length - 1); ;
            if (itemLocation_ == "-")
            {
                ItemLocation = ItemLocation.Substring(0, ItemLocation.Length - 1);
            }
            try
            {
                SQLDataset = new DataSet();

                SQLCon.Open();

                // Combine all update statements into ONE SqlCommand
                SQLCmd = new SqlCommand(
                    "UPDATE ItemMaster SET Location = '" + ItemLocation + "' WHERE ItemCode = '" + itemcode + "';" +
                    "UPDATE ERPItemLocation SET Location = '" + ItemLocation + "' WHERE ItemCode = '" + itemcode + "';" +
                    "UPDATE ERPInventoryIndent SET Location = '" + ItemLocation + "' WHERE ItemCode = '" + itemcode + "';" +
                    "UPDATE ERPInventoryLogs SET ItemLocation = '" + ItemLocation + "' WHERE ItemCode = '" + itemcode + "';",
                    SQLCon
                );

                SQLCmd.ExecuteNonQuery();

                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);

                SQLCon.Close();
                return "Item Master Location updated";
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return "Item Master Location update failed.";
            }
        }


