        //To get the total cost of project...
        public double fnGetProjectCost(string costType, string ProjectCode)
        {
            try
            {
                double totalCost = 0;
                SQLDataset = new DataSet();

                SQLCon.Open();

                switch (costType)
                {
                    case "PROJECT":
                        {
                            SQLCmd = new SqlCommand("SELECT SUM(Quantity * FixedCost) AS TotalCost FROM [ERP_Database].[dbo].[MachineBOM] WHERE ProjectCode = '" + ProjectCode + "';", SQLCon);
                            break;
                        }
                    case "ISSUE":
                        {
                            SQLCmd = new SqlCommand(@"SELECT 
                                SUM(COALESCE(i.Quantity, 0) * COALESCE(im.FixedCost, 0)) AS TotalCost
                            FROM[ERP_Database].[dbo].[Issued] AS i
                            JOIN[ERP_Database].[dbo].[ItemMaster] AS im
                                ON im.ItemCode = i.Item_Code
                            WHERE i.Project_Code = '" + ProjectCode + "';", SQLCon);
                            break;
                        }
                }


                //SQLCmd.ExecuteNonQuery();
                object result = SQLCmd.ExecuteScalar();

                if (result != null && result != DBNull.Value)
                {
                    // Convert safely to decimal
                    totalCost = Convert.ToDouble(result);
                }

                //SQLDadpr = new SqlDataAdapter(SQLCmd);
                //SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return totalCost;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return 0;
            }
        }

        public float fnGetProjectCost_(string costType, string projectCode)
        {
            try
            {
                string sql = costType == "PROJECT"
                    ? @"SELECT SUM(COALESCE(Quantity, 0) * COALESCE(UnitCost, 0)) 
                  FROM [ERP_Database].[dbo].[ProjectBOM] 
                 WHERE ProjectCode = @ProjectCode;"
                    : @"SELECT SUM(COALESCE(i.Quantity, 0) * COALESCE(im.FixedCost, 0))
                  FROM [ERP_Database].[dbo].[Issued] AS i
                  JOIN [ERP_Database].[dbo].[ItemMaster] AS im
                    ON im.ItemCode = i.Item_Code
                 WHERE i.Project_Code = @ProjectCode;";

                var con = new SqlConnection(SQLCon.ConnectionString);
                var cmd = new SqlCommand(sql, con);
                cmd.Parameters.Add("@ProjectCode", SqlDbType.VarChar, 100).Value = projectCode;

                con.Open();
                var result = cmd.ExecuteScalar();
                return (result == null || result == DBNull.Value) ? 0f : Convert.ToSingle(result);
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                return 0f;
            }
        }


