        public int fnERPProjectBOMLock(string action, string projectCode, string ProjectDescription, string CustomerName, bool LockNow, string BOMClosingDate, string LockedBy, string LastUpdatedDate, string Remarks)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (action)
                {
                    case "NEW":
                        {
                            SQLCmd = new SqlCommand("insert into ERPProjectBOMLock([ProjectCode],[ProjectDescription],[CustomerName],[LockNow],[BOMClosingDate],[LockedBy],[LastUpdatedDate], [Remarks])" +
                                "values('" + projectCode + "','" + ProjectDescription + "','" + CustomerName + "','" + LockNow + "','" + BOMClosingDate + "','" + LockedBy + "','" + LastUpdatedDate + "', '" + Remarks + "')", SQLCon);
                            break;
                        }
                    case "UPDATE":
                        {
                            SQLCmd = new SqlCommand("UPDATE ERPProjectBOMLock set LockNow = '" + LockNow + "', BOMClosingDate='" + BOMClosingDate + "', LockedBy='" + LockedBy + "', LastUpdatedDate= '" + LastUpdatedDate + "' where ProjectCode='" + projectCode + "' ", SQLCon);
                            break;
                        }

                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }

