        public DataSet fnGetERPProjectBOMLockLogs(string fromDate, string toDate, string projectCode, string Remarks, string User)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();

                string query = "SELECT * FROM ERPProjectBOMLockLogs WHERE 1=1";

                // if (!string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(toDate))
                // query += $" AND CONVERT(datetime, CreatedDate, 105) BETWEEN CONVERT(datetime, '{fromDate}', 105) AND CONVERT(datetime, '{toDate}', 105)";

                if (!string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(toDate))
                {
                    query += $" AND CreatedDate >= CONVERT(datetime, '{fromDate}', 105) AND CreatedDate <  DATEADD(day, 1, CONVERT(datetime, '{toDate}', 105))";
                }


                // if (!string.IsNullOrEmpty(fromDate) && !string.IsNullOrEmpty(toDate))
                //   query += $" AND [CreatedDate] BETWEEN '{fromDate}' AND '{toDate}'";
                // query += $" AND CreatedDate BETWEEN CONVERT(datetime, '{fromDate}', 105) AND CONVERT(datetime, '{toDate}', 105)";

                if (!string.IsNullOrEmpty(projectCode))
                    query += $" AND ProjectCode LIKE '{projectCode}%'";

                if (!string.IsNullOrEmpty(Remarks))
                    query += $" AND Remarks LIKE '{Remarks}%'";

                if (!string.IsNullOrEmpty(User))
                    query += $" AND ActionMadeBy LIKE '{User}%'";



                //if (!string.IsNullOrEmpty(itemPrefix))
                //  query += $" AND ItemCode LIKE '{itemPrefix}%'";

                SQLCmd = new SqlCommand(query, SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();

                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

