        public DataSet fnprintReceipt(string GINNo, string sWoPO)
        {
            try
            {
                SQLDataset = new DataSet();

                SQLCon.Open();
                if (GINNo == null)
                {  // old code// SELECT id,[GINNumber] FROM [Receipt] where [GINNumber]!='0' group by [GINNumber],id order by id desc
                    SQLCmd = new SqlCommand("  SELECT   [GINNumber] FROM [Receipt] where [GINNumber]!='0' group by [GINNumber] order by [GINNumber] desc", SQLCon);
                }
                else
                {
                    if (sWoPO == "PO")
                    {

                        SQLCmd = new SqlCommand(@"select R.[GINNumber],R.[RefNumber],R.[ItemCode],IM.ItemDescription ,P.[ProjectCode],PM.ProjectDescription,P.VendorCode,R.[SupplierName],P.[POGeneratedDate] as PODate,
                                               R.[Date] as GINDate,P.RequariedQty as POQty,R.[Quantity] as SupplyQty,R.UnitCost as Rate, (R.UnitCost*R.[Quantity]) as Amount ,  R.[SupplierInvoiceNumber] as [Invoice No], R.InvoiceDate  FROM Receipt R join  [PurchaseOrder] P 
                                             on R.RefNumber=P.DBOMNo and R.ItemCode=P.ItemCode join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join ItemMaster IM on R.ItemCode=IM.ItemCode where R.GINNumber='" + GINNo + "' and R.GINNumber!='0'", SQLCon);



                        //string query = @"SELECT R.ItemCode, IM.ItemDescription, SUM(R.Quantity) AS SupplyQty,
                        //SUM(R.UnitCost * R.Quantity) AS Amount, MIN(R.UnitCost) AS Rate, MIN(R.SupplierName) AS SupplierName,
                        //MIN(R.SupplierInvoiceNumber) AS InvoiceNo, MIN(R.InvoiceDate) AS InvoiceDate,
                        //P.ProjectCode, PM.ProjectDescription, P.VendorCode, P.POGeneratedDate AS PODate, P.RequariedQty AS POQty
                        //FROM Receipt R
                        //JOIN PurchaseOrder P ON R.RefNumber = P.DBOMNo AND R.ItemCode = P.ItemCode
                        //JOIN ProjectMaster PM ON P.ProjectCode = PM.ProjectCode
                        //JOIN ItemMaster IM ON R.ItemCode = IM.ItemCode
                        //WHERE R.GINNumber = @GINNo AND R.GINNumber != '0'
                        // GROUP BY R.ItemCode, IM.ItemDescription, P.ProjectCode, PM.ProjectDescription, P.VendorCode, P.POGeneratedDate, P.RequariedQty";


                        // SqlCommand cmd = new SqlCommand(query, SQLCon);
                        // cmd.Parameters.AddWithValue("@GINNo", GINNo);



                    }
                    else if (sWoPO == "WO")
                    {
                        SQLCmd = new SqlCommand(@" select R.[GINNumber],R.[RefNumber],R.[ItemCode],IM.ItemDescription ,W.[ProjectCode],PM.ProjectDescription,W.VendorCode,R.[SupplierName],W.[WOgeneratedDate] as PODate,
                                                    R.[Date] as GINDate,W.OPOrderQty as POQty,R.[Quantity] as SupplyQty,R.UnitCost as Rate, (R.UnitCost*R.[Quantity]) as Amount ,  R.[SupplierInvoiceNumber] as [Invoice No], R.InvoiceDate  FROM Receipt R join  [WorkOrder] W 
                                                    on R.RefNumber=W.WONumber and R.ItemCode=W.OPItemCode join ProjectMaster PM on W.ProjectCode=PM.ProjectCode join ItemMaster IM on R.ItemCode=IM.ItemCode where R.GINNumber='" + GINNo + "' and R.GINNumber!='0'", SQLCon);
                    }
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return SQLDataset;
            }
        }


        public DataSet fnAdvancedReceipt(string GINNo, string sPONo, string sWOPO)
        {
            try
            {
                SQLDataset = new DataSet();

                SQLCon.Open();
                if (GINNo == null & sPONo != null)
                {
                    SQLCmd = new SqlCommand("select *  FROM [POReport]  where [PONo]='" + sPONo + "'", SQLCon);
                }
                else
                {
                    if (sWOPO == "PO")
                    {
                        SQLCmd = new SqlCommand(@"select R.BOMProjectCode,R.[ItemCode],IM.ItemDescription,IM.HSNSACCode ,
                                             R.[Quantity] as SupplyQty,R.UnitCost,(R.UnitCost*R.[Quantity]) as Amount, isnull(P.[DiscRate],0) as DiscRate,isnull(P.[DiscAmount],0) as DiscAmount,
                                             ((R.UnitCost*R.[Quantity])-isnull(P.[DiscAmount],0)) as [Taxable Value],
                                             isnull(P.[SGSTRate],0) as SGSTRate,((((R.UnitCost*R.[Quantity])-isnull(P.[DiscAmount],0))* isnull(P.[SGSTRate],0))/100) as SGSTAmount ,
                                             isnull(P.[CGSTRate],0) as CGSTRate,((((R.UnitCost*R.[Quantity])-isnull(P.[DiscAmount],0))* isnull(P.[CGSTRate],0))/100) as CGSTAmount,
                                             isnull(P.[IGSTRate],0) as IGSTRate,((((R.UnitCost*R.[Quantity])-isnull(P.[DiscAmount],0))* isnull(P.[IGSTRate],0))/100) as IGSTAmount
                                             FROM Receipt R join  [PurchaseOrder] P on R.RefNumber=P.DBOMNo and R.ItemCode=P.ItemCode join ProjectMaster PM 
                                              on P.ProjectCode=PM.ProjectCode join ItemMaster IM on R.ItemCode=IM.ItemCode 
                                              where R.GINNumber='" + GINNo + "' and R.GINNumber!='0'", SQLCon);
                    }
                    else if (sWOPO == "WO")
                    {
                        SQLCmd = new SqlCommand(@"select R.[ItemCode],IM.ItemDescription,IM.HSNSACCode ,
                                                    R.[Quantity] as SupplyQty,R.UnitCost,(R.UnitCost*R.[Quantity]) as Amount,
                                                    (R.UnitCost*R.[Quantity]) as [Taxable Value],
                                                    isnull(W.[SGSTRate],0) as SGSTRate,(((R.UnitCost*R.[Quantity])* isnull(W.[SGSTRate],0))/100) as SGSTAmount ,
                                                    isnull(W.[CGSTRate],0) as CGSTRate,(((R.UnitCost*R.[Quantity])* isnull(W.[CGSTRate],0))/100) as CGSTAmount,
                                                    isnull(W.[IGSTRate],0) as IGSTRate,(((R.UnitCost*R.[Quantity])* isnull(W.[IGSTRate],0))/100) as IGSTAmount
                                                    FROM Receipt R join  WorkOrder W on R.RefNumber=W.WONumber and R.ItemCode=W.OPItemCode join ProjectMaster PM 
                                                    on W.ProjectCode=PM.ProjectCode join ItemMaster IM on R.ItemCode=IM.ItemCode 
                                              where R.GINNumber='" + GINNo + "' and R.GINNumber!='0'", SQLCon);
                    }

                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return SQLDataset;
            }
        }


