        public DataSet fnTransducerReport(int iCase, string fromate, string todate, string sProjectCode)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"SELECT [ItemCode],[ItemDescription],[AvailableQty],[UnitCost] , ([AvailableQty]*[UnitCost]) as [StockValue] FROM [KanBanItemMaster] order by id asc", SQLCon);
                        break;

                    case 1:
                        SQLCmd = new SqlCommand(@"SELECT [ReceiptNo],KR.[ItemCode],KM.[ItemDescription],KR.[Quantity],KR.[UnitCost],convert(date,[IssuedDate],105) as [IssuedDate],[RefNumber] FROM [KanBanReceipt] KR
                                                join [KanBanItemMaster] KM on KR.Itemcode=KM.Itemcode
                                                where convert(date,[IssuedDate],105)>='" + fromate + "' and convert(date,[IssuedDate],105)<='" + todate + "'", SQLCon);
                        break;

                    case 2:
                        SQLCmd = new SqlCommand(@"SELECT[KANProductNo],KR.[Item_Code] as ItemCode,KR.[ItemDescription], [IssueNo],[Issue_Type],convert(date,[IssuedDate],105) as [IssuedDate],[IssuedQuantity],[unitprice],[IssuedBy]FROM [KanBanIssued] KR
                                                
                                                where convert(date,[IssuedDate],105)>='" + fromate + "' and convert(date,[IssuedDate],105)<='" + todate + "' order by KR.ID asc", SQLCon);
                        break;

                    case 3:
                        SQLCmd = new SqlCommand(@"SELECT [KANProductNo],KR.[ItemCode],KM.[ItemDescription],[Quantity],KR.[UnitCost],convert(date,[ProductionDate],105) as [ProductionDate],[ProducedBy] FROM [KanBanProduction] KR
                                                join [KanBanFinishedItemMaster] KM on KR.Itemcode=KM.Itemcode
                                                 where convert(date,[ProductionDate],105)>='" + fromate + "' and convert(date,[ProductionDate],105)<='" + todate + "'", SQLCon);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand(@"SELECT KIFG.[IssueNo],[Item_Code] as ItemCode,KFIM.ItemDescription,KIFG.[Issue_Type],KIFG.[IssuedQuantity],KIFG.[unitprice],
                                                  convert(date,[IssuedDate],105) as [IssuedDate],KIFG.[IssuedBy],KIFG.[Projectcode],PM.ProjectDescription,KIFG.Remarks
                                                  FROM [KanBanIssuedFG] KIFG join KanBanFinishedItemMaster KFIM on KIFG.Item_Code=KFIM.ItemCode join ProjectMaster PM on KIFG.Projectcode=PM.ProjectCode
                                                  where convert(date,[IssuedDate],105)>='" + fromate + "' and convert(date,[IssuedDate],105)<='" + todate + "' union all SELECT KIFG.[IssueNo],[Item_Code] as ItemCode,KIM.ItemDescription,KIFG.[Issue_Type],KIFG.[IssuedQuantity],KIFG.[unitprice],convert(date,[IssuedDate],105) as [IssuedDate],KIFG.[IssuedBy],KIFG.[Projectcode],PM.ProjectDescription,KIFG.Remarks FROM [KanBanIssuedFG] KIFG join KanBanItemMaster KIM on KIFG.Item_Code=KIM.ItemCode join ProjectMaster PM on KIFG.Projectcode=PM.ProjectCode where convert(date,[IssuedDate],105)>='" + fromate + "' and convert(date,[IssuedDate],105)<='" + todate + "'", SQLCon);
                        break;
                    case 5:
