                                                  Where convert(date,[Date],105)>='" + fromate + "' and convert(date,[Date],105)<='" + todate + "' union all Select KBEI.ItemCode,KEM.ItemDescription,CONVERT(date,[Date],105) as Date,Quantity , [UnitPrice],KBEI.[ProjectCode] as ProjectCode,Pm.ProjectDescription as ProjectName,PM.Customer as Customer, [ReturnedBy],IssuedNumber,TransactionNo  from[KanBanElectronicsItemReturn] KBEI join KanBanElectronicsFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode join ProjectMaster PM on KBEI.ProjectCode=PM.ProjectCode Where convert(date,[Date],105)>='" + fromate + "' and convert(date,[Date],105)<='" + todate + "'", SQLCon);
