                                                  where KIFG.[Projectcode]='" + sProjectCode + "' and  (convert(date,[IssuedDate],105)>='" + fromate + "' and convert(date,[IssuedDate],105)<='" + todate + "') union all SELECT KIFG.[IssueNo],[Item_Code] as ItemCode,KIM.ItemDescription,KIFG.[Issue_Type],KIFG.[IssuedQuantity],KIFG.[unitprice],(KIFG.[IssuedQuantity]*KIFG.[unitprice]) as Amount,convert(date,[IssuedDate],105) as [IssuedDate],KIFG.[IssuedBy],KIFG.[Projectcode],PM.ProjectDescription,PM.Customer as Customer,KIFG.Remarks FROM [KanBanIssuedFG] KIFG join KanBanItemMaster KIM on KIFG.Item_Code=KIM.ItemCode join ProjectMaster PM on KIFG.Projectcode=PM.ProjectCode where KIFG.[Projectcode]='" + sProjectCode + "' and  (convert(date,[IssuedDate],105)>='" + fromate + "' and convert(date,[IssuedDate],105)<='" + todate + "') union all Select IssuedNumber, KBEI.ItemCode,KEM.ItemDescription,'ReturnItem' as [Issue_Type],(-1*Quantity),[UnitPrice],((-1*Quantity)*[UnitPrice]) as Amount,CONVERT(date,[Date],105) as Date, [ReturnedBy],KBEI.[ProjectCode] as ProjectCode,Pm.ProjectDescription as ProjectName,PM.Customer as Customer,TransactionNo  from [KanBanItemReturn] KBEI join KanBanItemMaster KEM on KBEI.ItemCode=KEM.ItemCode join ProjectMaster PM on KBEI.ProjectCode=PM.ProjectCode where KBEI.[ProjectCode]='" + sProjectCode + "' and  (convert(date,[Date],105)>='" + fromate + "' and convert(date,[Date],105)<='" + todate + "') union all Select IssuedNumber, KBEI.ItemCode,KEM.ItemDescription,'ReturnFG' as [Issue_Type],(-1*Quantity),[UnitPrice],((-1*Quantity)*[UnitPrice]) as Amount,CONVERT(date,[Date],105) as Date, [ReturnedBy],KBEI.[ProjectCode] as ProjectCode,Pm.ProjectDescription as ProjectName,PM.Customer as Customer,TransactionNo  from [KanBanItemReturn] KBEI join KanBanFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode join ProjectMaster PM on KBEI.ProjectCode=PM.ProjectCode where KBEI.[ProjectCode]='" + sProjectCode + "' and  (convert(date,[Date],105)>='" + fromate + "' and convert(date,[Date],105)<='" + todate + "')", SQLCon);
