                        break;

                    case 18:
                        SQLCmd = new SqlCommand(@"SELECT IM.[ItemCode],im.ItemDescription,im.AvailableQty,ISNULL([Leadtime],1) as[Leadtime],0.0 as [StockAvailableUsageRatio],  SUM(case when(convert(date,i.[IssuedDate],105) >= '" + todate + "' AND convert(date,i.[IssuedDate],105) <= '" + sProjectCode + "') then ISNULL(i.IssuedQuantity,0)  end) AS '6Months', SUM(case when(convert(date,i.[IssuedDate],105) >= '" + fromate + "' AND  convert(date,i.[IssuedDate],105) <= '" + sProjectCode + "') then ISNULL(i.IssuedQuantity,0)  end)  AS '12Months' FROM  KanBanElectronicsItemMaster  IM  join KanBanElectronicsIssued i on IM.ItemCode=i.Item_Code  where (convert(date,i.[IssuedDate],105) >= '" + fromate + "' AND convert(date,i.[IssuedDate],105) <= '" + sProjectCode + "') group by IM.[ItemCode],im.ItemDescription,AvailableQty,Leadtime union all SELECT IM.[ItemCode],im.ItemDescription,im.AvailableQty,ISNULL([Leadtime],1) as [Leadtime],0.0 as [StockAvailableUsageRatio],  SUM(case when(convert(date,i.[IssuedDate],105) >= '" + todate + "'  AND convert(date,i.[IssuedDate],105) <= '" + sProjectCode + "') then ISNULL(i.IssuedQuantity,0) end) AS '6Months',SUM(case when(convert(date,i.[IssuedDate],105) >= '" + fromate + "' AND  convert(date,i.[IssuedDate],105) <= '" + sProjectCode + "') then ISNULL(i.IssuedQuantity,0)  end) AS '12Months' FROM  KanBanElectronicsItemMaster  IM  join KanBanElectronicsIssuedFG i on IM.ItemCode=i.Item_Code  where (convert(date,[IssuedDate],105) >= '" + fromate + "' and [Issue_Type]='ElectronicsItem' AND convert(date,[IssuedDate],105) <= '" + sProjectCode + "') group by IM.[ItemCode],im.ItemDescription,AvailableQty,Leadtime union all SELECT [ItemCode],ItemDescription,AvailableQty, ISNULL([Leadtime],1) as [Leadtime],0.0 as [StockAvailableUsageRatio], 0 as [6Months],0 as [12Months] from KanBanElectronicsItemMaster", SQLCon);
                        break;
                    case 19:
                        SQLCmd = new SqlCommand(@"SELECT IM.[ItemCode],im.ItemDescription,im.AvailableQty,  SUM(case when(convert(date,i.[IssuedDate],105) >= '" + fromate + "' AND convert(date,i.[IssuedDate],105) <= '" + todate + "') then ISNULL(i.IssuedQuantity,0)  end) AS '6Months', SUM(case when(convert(date,i.[IssuedDate],105) >= '" + fromate + "' AND  convert(date,i.[IssuedDate],105) <= '" + sProjectCode + "') then ISNULL(i.IssuedQuantity,0)  end)  AS '12Months' FROM  KanBanItemMaster  IM  join KanBanIssued i on IM.ItemCode=i.Item_Code  where (convert(date,i.[IssuedDate],105) >= '" + fromate + "' AND convert(date,i.[IssuedDate],105) <= '" + sProjectCode + "') group by IM.[ItemCode],im.ItemDescription,AvailableQty union all SELECT IM.[ItemCode],im.ItemDescription,im.AvailableQty,  SUM(case when(convert(date,i.[IssuedDate],105) >= '" + fromate + "'  AND convert(date,i.[IssuedDate],105) <= '" + todate + "') then ISNULL(i.IssuedQuantity,0) end) AS '6Months',SUM(case when(convert(date,i.[IssuedDate],105) >= '" + fromate + "' AND  convert(date,i.[IssuedDate],105) <= '" + todate + "') then ISNULL(i.IssuedQuantity,0)  end) AS '12Months' FROM  KanBanItemMaster  IM  join KanBanIssuedFG i on IM.ItemCode=i.Item_Code  where (convert(date,[IssuedDate],105) >= '" + fromate + "' and [Issue_Type]='TransducerItem' AND convert(date,[IssuedDate],105) <= '" + sProjectCode + "') group by IM.[ItemCode],im.ItemDescription,AvailableQty union all SELECT [ItemCode],ItemDescription,AvailableQty, 0 as [6Months],0 as [12Months] from KanBanItemMaster", SQLCon);
