                                                  where KIFG.[IssueNo]='" + fromate + "' union all SELECT KIFG.[IssueNo],[Item_Code] as ItemCode,KIM.ItemDescription,KIFG.[Issue_Type],KIFG.[IssuedQuantity],KIFG.[unitprice],convert(date,[IssuedDate],105) as [IssuedDate],KIFG.[IssuedBy],KIFG.[Projectcode],PM.ProjectDescription,KIFG.Remarks FROM [KanBanIssuedFG] KIFG join KanBanItemMaster KIM on KIFG.Item_Code=KIM.ItemCode join ProjectMaster PM on KIFG.Projectcode=PM.ProjectCode where KIFG.[IssueNo]='" + fromate + "'", SQLCon);
