        public DataSet fnIssuedListConsalidated(string fromate, string todate)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                if (fromate != null && todate != null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;SELECT ISS.Project_Code as [Project Code],PM.ProjectDescription as [Projct Name],PM.Customer, (Ind.ProjectStatus) as [Project Status], ISS.[IssueNo] , ISS.[Item_Code] as [ItemCode] ,IM.[ItemDescription],IM.HSNSACCode, ISS.[Indent_Number] as [Indent Number] ,
                                            ISS.[Issue_Type] as [Issue Type],convert(date, ISS.[Issue_Date] ,105) as [Issue Date], ISS.[IndentBy],convert(date, ISS.[IndentDate] ,105) as [Indent Date],
                                            ISS.[Quantity], ISS.[IssuedQuantity] as [Issued Qty], ISS.[RaemainingQuantity] as [Rem. Qty], ISS.[unitprice],(ISS.[IssuedQuantity]*ISS.[unitprice]) 
                                            as Amount,Ind.Remarks FROM  [Issued] ISS join [ItemMaster] IM on ISS.[Item_Code]= IM.[ItemCode] join Indent Ind on ISS.[Item_Code] =Ind.ItemCode and Iss.Indent_Number=Ind.IndentNo 
                                            join projectmaster PM on ISS.Project_Code=PM.ProjectCode
                                             where (convert(date,ISS.[Issue_Date] ,105)>='" + fromate + "' and convert(date,ISS.[Issue_Date],105)<='" + todate + "') order by ISS.Project_Code asc", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnIssuedListDepartmentwise(string sDepartment, string fromate, string todate)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                if (sDepartment == null)
                    SQLCmd = new SqlCommand("SET DATEFORMAT dmy;SELECT L.Department FROM [Issued] I join [Login] L on I.IndentBy=L.UserName where  convert(date,[Issue_Date] ,105)>='" + fromate + "' and convert(date,[Issue_Date],105)<='" + todate + "' group by [Department]", SQLCon);
                else
                    SQLCmd = new SqlCommand(@" SET DATEFORMAT dmy;SELECT  ISS.[IssueNo] , ISS.[Item_Code] as [ItemCode] ,IM.[ItemDescription], ISS.[Indent_Number] as [Indent Number],
                                                 ISS.[Issue_Type] as [Issue Type],convert(date, ISS.[Issue_Date] ,105) as [Issue Date], ISS.[IndentBy],convert(date, ISS.[IndentDate] ,105) as [Indent Date],
                                                 ISS.[Quantity], ISS.[IssuedQuantity] as [Issued Qty], ISS.[RaemainingQuantity] as [Rem. Qty], IM.[UnitCost],( ISS.[IssuedQuantity]*IM.[UnitCost]) 
                                                as Amount FROM  [Issued] ISS join [ItemMaster] IM on ISS.[Item_Code]= IM.[ItemCode] join  [Login] L on Iss.IndentBy=L.UserName where L.Department='" + sDepartment + "' and convert(date,ISS.[Issue_Date] ,105)>='" + fromate + "' and convert(date,ISS.[Issue_Date],105)<='" + todate + "' order by convert(date,ISS.[Issue_Date],105)", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnStockValue(string fromdate, string todate)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                if (fromdate != null && todate != null)
                {
                    SQLCmd = new SqlCommand(@"SELECT Ginnumber, convert(date,[Date],105) as GINDate,RefNumber,ItemCode,ItemDescription,Quantity,[Standard Cost],[PurchaseCost]
                                            FROM  (SELECT r.RefNumber, r.GINNumber,convert(date,r.[Date] ,105) as [Date],r.Quantity,r.ItemCode,im.ItemDescription,im.UnitCost as [Standard Cost],r.UnitCost as [PurchaseCost],
                                            ROW_NUMBER() OVER (Partition By r.Itemcode ORDER BY convert(date,[Date] ,105) DESC) rn
				                            FROM  Receipt R join ItemMaster IM on r.ItemCode=im.ItemCode  
		                                    where r.GINNumber!='0' and r.[Type]='Boughtout'  and convert(date,[Date] ,105) between '" + fromdate + "' and '" + todate + "') derivedTable WHERE   derivedTable.rn = 1  order by convert(date,[Date] ,105) asc", SQLCon); //and  derivedTable.[Standard Cost] != derivedTable.PurchaseCost
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnLatestCost()
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                {
                    SQLCmd = new SqlCommand(@"SELECT Ginnumber, convert(date,[Date],105) as GINDate,RefNumber,ItemCode,ItemDescription,Quantity,[Standard Cost],[PurchaseCost]
                                            FROM  (SELECT r.RefNumber,R.ID, r.GINNumber,convert(date,r.[Date] ,105) as [Date],r.Quantity,r.ItemCode,im.ItemDescription,im.UnitCost as [Standard Cost],r.UnitCost as [PurchaseCost],
                                            ROW_NUMBER() OVER (Partition By r.Itemcode ORDER BY R.ID DESC) rn
				                            FROM  Receipt R join ItemMaster IM on r.ItemCode=im.ItemCode  
		                                    where r.GINNumber!='0' and R.RefNumber like 'PO/%' and  r.[Type]='Boughtout') derivedTable WHERE   derivedTable.rn = 1 and  derivedTable.[Standard Cost] != derivedTable.PurchaseCost order by convert(date,[Date] ,105) asc", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnStandardCostPOWO(string sPO, string sWO, string fromdate, string todate)
        {
            try
            {
                SQLCon.Open();
                SQLDataset = new DataSet();
                if (sPO != null && sWO == null && fromdate != null && todate != null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;SELECT  a.RefNumber as PONumber,convert(date,P.POGeneratedDate,105) as PODate,a.Ginnumber,convert(date,a.[Date],105) as GINDate,a.Itemcode, b.Itemdescription,b.ItemTypeCode
                                                 ,a.Quantity,b.UnitCost as Standarcost, (a.[UnitCost] - a.[UnitCost]* (COALESCE(a.[DiscRate], 0)/100)) as PurchaseCost ,SupplierName
                                                 FROM Receipt a left join ItemMaster b on a.Itemcode=b.ItemCode join PurchaseOrder P on a.RefNumber=P.DBOMNo and a.Itemcode=P.ItemCode 
                                                 Where  convert(date,[Date] ,105)>='" + fromdate + "' and convert(date,[Date],105)<='" + todate + "' and GINNumber!='0' and RefNumber like 'PO%'", SQLCon);
                }
                else if (sPO == null && sWO != null && fromdate != null && todate != null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;SELECT a.RefNumber as WONumber,convert(date,W.WOgeneratedDate,105) as WODate, a.Ginnumber,convert(date,a.[Date],105) as GINDate,a.Itemcode, b.Itemdescription,b.ItemTypeCode
                                                 ,a.Quantity,b.UnitCost as Standarcost,(a.[UnitCost] - a.[UnitCost]* (COALESCE(a.[DiscRate], 0)/100)) as PurchaseCost,SupplierName
                                                 FROM Receipt a left join ItemMaster b on a.Itemcode=b.ItemCode join WorkOrder W on a.RefNumber=W.WONumber and a.ItemCode=W.OPItemCode
                                                 Where  convert(date,[Date] ,105)>='" + fromdate + "' and convert(date,[Date],105)<='" + todate + "' and GINNumber!='0' and RefNumber like 'WO%'", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

