        public DataSet fnProjectIssued(int iCase, string sProjectCode, string fromdate, string todate)
        {
            DataSet newset = new DataSet();
            try
            {
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"select [I].[Item_Code] as [ItemCode],[IM].[ItemDescription],IM.HSNSACCode,[I].[unitprice],[I].[IssuedQuantity] as [Issued Qty] ,([I].[unitprice]*[I].[IssuedQuantity] ) as [Amount]
                                            ,I.[IndentBy],convert(date,I.Issue_Date,105) as [Issued Date],[I].[Indent_Number] as [Indent Number], 'Indent Issue' as [IssueType] from [Issued] I join [ItemMaster] IM on[IM].[ItemCode]=[I].[Item_Code]   
                                             where I.[Project_Code]='" + sProjectCode + "'and convert(date,I.[Issue_Date],105)>='" + fromdate + "' and convert(date,I.[Issue_Date],105)<='" + todate + "'  union all SELECT j.[ItemCode],IM.ItemDescription,IM.HSNSACCode,j.unitprice,j.[issuedQuantity],(j.unitprice*j.[issuedQuantity]) as Amount,W.PreparedBy as WorkOrderBy,convert(date,j.[IssueDate],105) as [IssueDate],j.[WONumber],'Job Issue' as [IssueType]  FROM [ERP_Database].[dbo].[JobIssue] j join ItemMaster IM on j.ItemCode=IM.ItemCode join WorkOrder w on j.WONumber= w.WONumber and j.ItemCode=w.IPItemCode where w.ProjectCode='" + sProjectCode + "' and convert(date,j.[IssueDate],105)>='" + fromdate + "' and convert(date,j.[IssueDate],105)<='" + todate + "' union all select IR.Itemcode,IM.ItemDescription,IM.HSNSACCode,IR.unitprice,IR.Quantity,(IR.Quantity * IR.unitprice) as Amount,IR.ReturnedBy,CONVERT(date,IR.[Date],105) as [Return Date], IR.[TransctoinNo],'Indent Return' as [IssueType]   from ItemReturn IR join ItemMaster IM on IR.ItemCode=IM.ItemCode  where IR.[ProjectCode]='" + sProjectCode + "' and CONVERT(date,IR.[Date],105) >='" + fromdate + "' and CONVERT(date,IR.[Date],105) <='" + todate + "' union all select IR.Itemcode,IM.ItemDescription,IM.HSNSACCode,IR.unitprice,IR.Quantity,(IR.Quantity * IR.unitprice) as Amount,IR.ReturnedBy,CONVERT(date,IR.[Date],105) as [Return Date], IR.[TransctoinNo],'Job Return' as [IssueType]  from ItemReturnJobIssued IR join ItemMaster IM on IR.ItemCode=IM.ItemCode  where IR.[ProjectCode]='" + sProjectCode + "' and CONVERT(date,IR.[Date],105) >='" + fromdate + "' and CONVERT(date,IR.[Date],105) <='" + todate + "' union all SELECT [Item_Code] as ItemCode,KFIM.ItemDescription,KFIM.HSNSACCode,KIFG.[unitprice],KIFG.[IssuedQuantity],(KIFG.[IssuedQuantity]*KIFG.[unitprice]) as Amount,KIFG.[IssuedBy],convert(date,[IssuedDate],105) as [IssuedDate],KIFG.[IssueNo],KIFG.[Issue_Type] FROM [KanBanElectronicsIssuedFG] KIFG join KanBanElectronicsFinishedItemMaster KFIM on KIFG.Item_Code=KFIM.ItemCode where KIFG.[Projectcode]='" + sProjectCode + "' and  (convert(date,[IssuedDate],105)>='" + fromdate + "' and convert(date,[IssuedDate],105)<='" + todate + "') union all SELECT [Item_Code] as ItemCode,KIM.ItemDescription,KIM.HSNSACCode,KIFG.[unitprice],KIFG.[IssuedQuantity],(KIFG.[IssuedQuantity]*KIFG.[unitprice]) as Amount,KIFG.[IssuedBy],convert(date,[IssuedDate],105) as [IssuedDate],KIFG.[IssueNo],KIFG.[Issue_Type] FROM [KanBanElectronicsIssuedFG] KIFG join KanBanElectronicsItemMaster KIM on KIFG.Item_Code=KIM.ItemCode  where KIFG.[Projectcode]='" + sProjectCode + "' and  (convert(date,[IssuedDate],105)>='" + fromdate + "' and convert(date,[IssuedDate],105)<='" + todate + "') union all Select KBEI.ItemCode,KEM.ItemDescription,KEM.HSNSACCode,[UnitPrice],Quantity,(Quantity*[UnitPrice]) as Amount, [ReturnedBy],CONVERT(date,[Date],105) as Date,TransactionNo, 'ELC-ReturnItem' as [Issue_Type]  from [KanBanElectronicsItemReturn] KBEI join KanBanElectronicsItemMaster KEM on KBEI.ItemCode=KEM.ItemCode  where KBEI.[ProjectCode]='" + sProjectCode + "' and  (convert(date,[Date],105)>='" + fromdate + "' and convert(date,[Date],105)<='" + todate + "') union all Select  KBEI.ItemCode,KEM.ItemDescription,KEM.HSNSACCode,[UnitPrice],Quantity,(Quantity*[UnitPrice]) as Amount, [ReturnedBy],CONVERT(date,[Date],105) as Date,TransactionNo,'ELC-ReturnFG' as [Issue_Type]  from [KanBanElectronicsItemReturn] KBEI join KanBanElectronicsFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode where KBEI.[ProjectCode]='" + sProjectCode + "' and  (convert(date,[Date],105)>='" + fromdate + "' and convert(date,[Date],105)<='" + todate + "') union all SELECT[Item_Code] as ItemCode,KFIM.ItemDescription,KFIM.HSNSACCode,KIFG.[unitprice],KIFG.[IssuedQuantity],(KIFG.[IssuedQuantity]*KIFG.[unitprice]) as Amount,KIFG.[IssuedBy],convert(date,[IssuedDate],105) as [IssuedDate],KIFG.[IssueNo],KIFG.[Issue_Type] FROM [KanBanIssuedFG] KIFG join KanBanFinishedItemMaster KFIM on KIFG.Item_Code=KFIM.ItemCode where KIFG.[Projectcode]='" + sProjectCode + "' and  (convert(date,[IssuedDate],105)>='" + fromdate + "' and convert(date,[IssuedDate],105)<='" + todate + "') union all SELECT [Item_Code] as ItemCode,KIM.ItemDescription,KIM.HSNSACCode,KIFG.[unitprice],KIFG.[IssuedQuantity],(KIFG.[IssuedQuantity]*KIFG.[unitprice]) as Amount,KIFG.[IssuedBy],convert(date,[IssuedDate],105) as [IssuedDate],KIFG.[IssueNo],KIFG.[Issue_Type] FROM [KanBanIssuedFG] KIFG join KanBanItemMaster KIM on KIFG.Item_Code=KIM.ItemCode where KIFG.[Projectcode]='" + sProjectCode + "' and  (convert(date,[IssuedDate],105)>='" + fromdate + "' and convert(date,[IssuedDate],105)<='" + todate + "') union all Select KBEI.ItemCode,KEM.ItemDescription,KEM.HSNSACCode,[UnitPrice],Quantity,(Quantity*[UnitPrice]) as Amount, [ReturnedBy],CONVERT(date,[Date],105) as Date,TransactionNo, 'TRS-ReturnItem' as [Issue_Type]  from [KanBanItemReturn] KBEI join KanBanItemMaster KEM on KBEI.ItemCode=KEM.ItemCode where KBEI.[ProjectCode]='" + sProjectCode + "' and  (convert(date,[Date],105)>='" + fromdate + "' and convert(date,[Date],105)<='" + todate + "') union all Select KBEI.ItemCode,KEM.ItemDescription,KEM.HSNSACCode,[UnitPrice],Quantity,(Quantity*[UnitPrice]) as Amount, [ReturnedBy],CONVERT(date,[Date],105) as Date,TransactionNo, 'TRS-ReturnFG' as [Issue_Type]  from [KanBanItemReturn] KBEI join KanBanFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode join ProjectMaster PM on KBEI.ProjectCode=PM.ProjectCode where KBEI.[ProjectCode]='" + sProjectCode + "' and  (convert(date,[Date],105)>='" + fromdate + "' and convert(date,[Date],105)<='" + todate + "')", SQLCon);
                        break;
                    case 1:

                        SQLCmd = new SqlCommand(@"SELECT j.[ItemCode],IM.ItemDescription,IM.HSNSACCode,j.unitprice,j.[issuedQuantity],(j.unitprice*j.[issuedQuantity]) as Amount,W.PreparedBy as WorkOrderBy,convert(date,j.[IssueDate],105) as [IssueDate],j.[WONumber] FROM [ERP_Database].[dbo].[JobIssue] j join ItemMaster IM on j.ItemCode=IM.ItemCode join WorkOrder w on j.WONumber= w.WONumber and j.ItemCode=w.IPItemCode where w.ProjectCode='" + sProjectCode + "' and convert(date,j.[IssueDate],105)>='" + fromdate + "' and convert(date,j.[IssueDate],105)<='" + todate + "'", SQLCon);
