        public DataSet fnProjectItemReturn(string sProjectCode, string sFromDate, string sTodate, string sProjectorJob)
        {
            try
            {
                DataSet SQLDataset1 = new DataSet();
                SQLCon.Open();
                if (sProjectorJob == "Project")
                {
                    SQLCmd = new SqlCommand(@"select IR.Itemcode,IM.ItemDescription,IM.HSNSACCode,IR.unitprice,IR.Quantity,(IR.Quantity * IR.unitprice) as Amount,IR.ReturnedBy,CONVERT(date,IR.[Date],105) as [Return Date], IR.[TransctoinNo],'' as [Date]  from ItemReturn IR join ItemMaster IM on IR.ItemCode=IM.ItemCode  where IR.[ProjectCode]='" + sProjectCode + "' and CONVERT(date,IR.[Date],105) >='" + sFromDate + "' and CONVERT(date,IR.[Date],105) <='" + sTodate + "'", SQLCon);
                }
                else
                {
                    SQLCmd = new SqlCommand(@"select IR.Itemcode,IM.ItemDescription,IM.HSNSACCode,IR.unitprice,IR.Quantity,(IR.Quantity * IR.unitprice) as Amount,IR.ReturnedBy,CONVERT(date,IR.[Date],105) as [Return Date], IR.[TransctoinNo],'' as [Date]  from ItemReturnJobIssued IR join ItemMaster IM on IR.ItemCode=IM.ItemCode  where IR.[ProjectCode]='" + sProjectCode + "' and CONVERT(date,IR.[Date],105) >='" + sFromDate + "' and CONVERT(date,IR.[Date],105) <='" + sTodate + "'", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset1);
                SQLCon.Close();
                return SQLDataset1;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
