            public BOMProjectItem(string bomProjectCode, string productNo, double bomQty)
            {
                BOMProjectCode = bomProjectCode;
                ProductNo = productNo;
                BOMQty = bomQty;
            }
        }

        public int GEPoBOM(string sPONumber)
        {
            int withoutBOM = -1;

            try
            {
                SQLCon.Open();

                SQLCmd = new SqlCommand(@"
            SELECT WithoutBOM 
            FROM PurchaseOrder 
            WHERE DBOMNo = @PONumber", SQLCon);

                SQLCmd.Parameters.AddWithValue("@PONumber", sPONumber);

                var result = SQLCmd.ExecuteScalar();

                if (result != DBNull.Value && result != null)
                {
                    withoutBOM = Convert.ToInt32(result); // will return 0 or 1
                }

                SQLCon.Close();
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error fetching WithoutBOM status: " + ex.Message);
                SQLCon.Close();
                withoutBOM = -1;
            }

            return withoutBOM;
        }



        public int fnUpdatePODetails(uint uInOrUPOrDel, string sPOnumber)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();

                if (uInOrUPOrDel == Global.uUPDATE)
                {
                    string fetchQuery = @"
            SELECT POB.ItemCode, POB.ProjectCode, POB.ProductNo, 
                   (POB.POQuantity - ISNULL(SUM(R.Quantity), 0)) AS RemainingQty
            FROM PurchaseOrderBOM POB
            LEFT JOIN Receipt R
              ON R.RefNumber = POB.PONumber
              AND R.ItemCode = POB.ItemCode
              AND R.BOMProjectCode = POB.ProjectCode
              AND R.ProductNo = POB.ProductNo
            WHERE POB.PONumber = @PONumber
            GROUP BY POB.ItemCode, POB.ProjectCode, POB.ProductNo, POB.POQuantity";

                    List<PendingItem> pendingItems = new List<PendingItem>();

                    using (SqlCommand fetchCmd = new SqlCommand(fetchQuery, SQLCon))
                    {
                        fetchCmd.Parameters.AddWithValue("@PONumber", sPOnumber);

                        using (SqlDataReader reader = fetchCmd.ExecuteReader())
                        {
                            while (reader.Read())
                            {
                                pendingItems.Add(new PendingItem(
                                    reader["ItemCode"].ToString(),
                                    reader["ProjectCode"].ToString(),
                                    reader["ProductNo"].ToString(),
                                    Convert.ToDouble(reader["RemainingQty"])
                                ));
                            }
                        }
                    }

                    foreach (PendingItem item in pendingItems)
                    {
                        int result = UpdateRemainingQty(sPOnumber, item.ItemCode, item.ProjectCode, item.ProductNo);
                        if (result > 0)
                        {
                            GlobalClass.iStatus = 1;
                        }
                    }
                }

                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }

        private int UpdateRemainingQty(string sPOnumber, string sItemcode, string sProjectCode, string sProductNo)
        {
            try
            {
                if (SQLCon.State != ConnectionState.Open)
                {
                    SQLCon.Open();
                }
                double totalBOMQty = 0;

                // Fetch total BOM quantity for the given PO number and item code
                string fetchBOMQtyQuery = @"
        SELECT ISNULL(SUM(POB.POQuantity), 0) AS TotalBOMQty
        FROM PurchaseOrderBOM POB
        WHERE POB.PONumber = @PONumber
          AND POB.ItemCode = @ItemCode";

                using (SqlCommand fetchBOMQtyCmd = new SqlCommand(fetchBOMQtyQuery, SQLCon))
                {
                    fetchBOMQtyCmd.Parameters.AddWithValue("@PONumber", sPOnumber);
                    fetchBOMQtyCmd.Parameters.AddWithValue("@ItemCode", sItemcode);

                    object result = fetchBOMQtyCmd.ExecuteScalar();
                    if (result != DBNull.Value)
                    {
                        totalBOMQty = Convert.ToDouble(result);
                    }
                }

                double ginQty = 0;

                // Fetch total GIN quantity from the Receipt table
                string fetchGINQuery = @"
        SELECT ISNULL(SUM(R.Quantity), 0) AS TotalGINQty
        FROM Receipt R
        WHERE R.RefNumber = @PONumber
          AND R.ItemCode = @ItemCode";

                using (SqlCommand fetchGINCmd = new SqlCommand(fetchGINQuery, SQLCon))
                {
                    fetchGINCmd.Parameters.AddWithValue("@PONumber", sPOnumber);
                    fetchGINCmd.Parameters.AddWithValue("@ItemCode", sItemcode);

                    object ginResult = fetchGINCmd.ExecuteScalar();
                    if (ginResult != DBNull.Value)
                    {
                        ginQty = Convert.ToDouble(ginResult);
                    }
                }

                // Calculate the remaining quantity
                double currentRemainingQty = Math.Max(0, totalBOMQty - ginQty);

                // Update the RemainingQty in the PurchaseOrder table
                string updateQuery = @"
        UPDATE PurchaseOrder
        SET RemainingQty = @RemainingQty
        WHERE DBOMNo = @PONumber AND ItemCode = @ItemCode";

                using (SqlCommand updateCmd = new SqlCommand(updateQuery, SQLCon))
                {
                    updateCmd.Parameters.AddWithValue("@RemainingQty", currentRemainingQty);
                    updateCmd.Parameters.AddWithValue("@PONumber", sPOnumber);
                    updateCmd.Parameters.AddWithValue("@ItemCode", sItemcode);

                    return updateCmd.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error updating RemainingQty: {ex.Message}");
                return 0;
            }
            finally
            {
                if (SQLCon.State == ConnectionState.Open)
                {
                    SQLCon.Close();
                }
            }
        }



