        public int fnUpdateWODetails(uint uInOrUPOrDel, double dOPRemainingQty, double dUnitCost, string sItemcode, string sWOnumber)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (uInOrUPOrDel)
                {
                    case Global.uINSERT:
                        {
                            SQLCmd = new SqlCommand("UPDATE WorkOrder SET  TotalCost=(OPOrderQty*UnitCost) WHERE OPItemCode='" + sItemcode + "' and WONumber='" + sWOnumber + "'", SQLCon);
                            break;
                        }
                    case Global.uUPDATE:
                        {
                            SQLCmd = new SqlCommand("UPDATE WorkOrder SET OPRemainingQty='" + dOPRemainingQty + "',UnitCost='" + dUnitCost + "' WHERE OPItemCode='" + sItemcode + "' and WONumber='" + sWOnumber + "'", SQLCon);
                            break;
                        }
                    case Global.uDELETE:
                        {
                            SQLCmd = new SqlCommand("UPDATE WorkOrder SET WOStatus='Closed' WHERE OPItemCode='" + sItemcode + "' and WONumber='" + sWOnumber + "'", SQLCon);
                            break;
                        }
                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;

            }
        }

