        public DataSet fnProjectCostLimitCIP(int iCase, string ProjectCode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {

                    case 0:
                        SQLCmd = new SqlCommand("Select * from ProjectMaster where ProjectCode='" + ProjectCode + "'", SQLCon);
                        break;

                    case 1:
                        SQLCmd = new SqlCommand("  Select CapexAmount as TotalAmount, 'Capex Amount' as UsedAmountType from ProjectMaster  where ProjectCode='" + ProjectCode + "' union all SELECT case when SUM(RequariedQty * [UnitPrice]) is NULL then 0 else SUM(RequariedQty * [UnitPrice]) end  AS TotalAmount, 'PO Amount' as UsedAmountType FROM [PurchaseOrder]  where ProjectCode='" + ProjectCode + "' and AuthoriedBy!='Deleted'", SQLCon);
                        break;

                    case 2:
                        SQLCmd = new SqlCommand("Select CapexAmount as TotalAmount, 'Capex Amount' as UsedAmountType from ProjectMaster  where ProjectCode='" + ProjectCode + "'  union all SELECT case when SUM(unitprice * IssuedQuantity) is NULL then 0 else  SUM(unitprice * IssuedQuantity) end AS TotalAmount, 'Issued Amount' FROM Issued   where Project_Code='" + ProjectCode + "' union all    SELECT case when SUM(unitprice * IssuedQuantity) is NULL then 0 else  SUM(unitprice * IssuedQuantity) end AS TotalAmount, 'Job Issued Amount' FROM JobIssue J join WorkOrder W on J.WONumber=W.WONumber and J.ItemCode=W.IPItemCode   where W.ProjectCode='" + ProjectCode + "'  union all SELECT case when SUM(unitprice * [Quantity]) is NULL then 0 else  SUM(unitprice * [Quantity]*-1) end AS TotalAmount, 'Indent return Amount' FROM [ItemReturn]  where ProjectCode='" + ProjectCode + "'  union all SELECT case when SUM(unitprice * [Quantity]) is NULL then 0 else  SUM(unitprice * [Quantity]*-1) end AS TotalAmount, 'WO return Amount' FROM [ItemReturnJobIssued]  where ProjectCode='" + ProjectCode + "' union all SELECT case when SUM  ([IssuedQuantity]*[unitprice]) is NULL then 0 else SUM ([IssuedQuantity]*[unitprice]) end  as Amount,'KanBan Electronics Issued' FROM [KanBanElectronicsIssuedFG]   where [Projectcode]='" + ProjectCode + "' union all Select case when SUM  ((-1*Quantity)*[UnitPrice]) is NULL then 0 else SUM ((-1*Quantity)*[UnitPrice]) end as Amount,'KanBan Electronics Return' from [KanBanElectronicsItemReturn]  where [ProjectCode]='" + ProjectCode + "' union all SELECT case when SUM  ([IssuedQuantity]*[unitprice]) is NULL then 0 else SUM ([IssuedQuantity]*[unitprice]) end  as Amount,'KanBan Transducer Issued' FROM [KanBanIssuedFG]   where [Projectcode]='" + ProjectCode + "' union all Select case when SUM  ((-1*Quantity)*[UnitPrice]) is NULL then 0 else SUM ((-1*Quantity)*[UnitPrice]) end as Amount,'KanBan Transducer Return' from [KanBanItemReturn]  where [ProjectCode]='" + ProjectCode + "' ", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand("Select CapexAmount as TotalAmount, 'Capex Amount' as UsedAmountType from ProjectMaster  where ProjectCode='" + ProjectCode + "'  union all SELECT case when SUM(unitprice * IssuedQuantity) is NULL then 0 else  SUM(unitprice * IssuedQuantity) end AS TotalAmount, 'Issued Amount' FROM Issued   where Project_Code='" + ProjectCode + "'", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
