                    SQLCmd = new SqlCommand(@"SELECT convert(date,W.[WOgeneratedDate],105) as [WOgeneratedDate],W.[JWNumber] ,W.[WONumber] ,W.[ProjectCode],PM.ProjectDescription as ProjectName, REPLACE(REPLACE(REPLACE(W.ProjectStatus , 'WIP', 'WIP'), 'Shipped', 'Short Shipment'),'Installation completed','Warranty') [Project Status]
                                             ,W.[IPItemCode],Im1.ItemDescription as [IP Item Desc],im1.HSNSACCode,W.[IPOrderQty],(W.[IPOrderQty]) as IssuedQty
	                                         ,W.IPUnitCost as IPItemUnitCost,(W.IPUnitCost * (W.[IPOrderQty])) as Amount,W.[VendorCode],V.VendorName,W.[OPItemCode] ,Im2.ItemDescription,(im2.HSNSACCode) as [HSNSAC Code],W.[OPOrderQty],W.[UnitCost],W.[OPOrderQty]*W.[UnitCost] as [TotalCost]     
                                            FROM [WorkOrder] W Join ProjectMaster PM on W.ProjectCode=PM.ProjectCode left join ItemMaster Im2 on W.OPItemCode=Im2.Itemcode left join ItemMaster Im1 on W.IPItemCode=Im1.ItemCode join Vendors V on W.VendorCode=V.VendorCode  where  convert(date,W.[WOgeneratedDate],105) >='" + fromdate + "'  and convert(date,W.[WOgeneratedDate],105) <='" + todate + "' order by convert(date, W.[WOgeneratedDate],105) asc", SQLCon);
                }

                //                else if (fromdate != null && todate != null && Index == 8)
                //                {
                //                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;select W.JWNumber,W.[WONumber],W.[OPItemCode],Im.ItemDescription,W.VendorCode,V.VendorName,
                //                                             W.[UnitCost],(W.[IPOrderQty]-W.[IPRemainingOrderQty]) as IssuedQty,(W.[UnitCost]*(W.[IPOrderQty]-W.[IPRemainingOrderQty])) as Amount, convert(date,W.[WOgeneratedDate],105) as [WOgeneratedDate]  from WorkOrder W join Itemmaster IM On W.[OPItemCode]=Im.ItemCode 
                //                                             join Vendors V on W.VendorCode=V.VendorCode where W.JobIssueStatus='Open' and (convert(date,W.[WOgeneratedDate],105)>='" + fromdate + "' and convert(date,W.[WOgeneratedDate],105)<='" + todate + "') order by convert(date,W.[WOgeneratedDate],105)", SQLCon);
                //                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
