        public DataSet purchaseOrderList2(string POnumber)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (POnumber == null)
                {
                    SQLCmd = new SqlCommand("Select * from PurchaseOrder where [POGeneratedBy]='' or POGeneratedBy is null order by [DBOMNo] desc ", SQLCon);
                }
                else
                {

                    SQLCmd = new SqlCommand(@"Select P.[ProjectCode],PM.ProjectDescription,IM.HSNSACCode,P.ItemCode,IM.ItemDescription,P.[VendorCode],V.VendorName,IM.AvailableQty,P.[RequariedQty] as ReqQty,P.[RemainingQty],IM.Units,P.[UnitPrice] as UnitCost ,(P.RequariedQty *P.[UnitPrice]) as [Amount],P.PMName,P.MHName,P.PurchaseCommitee,
                                                P.Remarks,P.PreparedBy,  convert(date,P.POGeneratedDate,105) as POGeneratedDate, convert(date,P.PODeliveryDate,105) as PODeliveryDate,isnull(P.[IGSTRate],0) as IGSTRate ,isnull(P.[IGSTAmount],0) as IGSTAmount,isnull(P.[SGSTRate],0) as SGSTRate ,
                                                isnull(P.[SGSTAmount],0) as SGSTAmount ,isnull(P.[CGSTRate],0) as CGSTRate,isnull(P.[CGSTAmount],0) as CGSTAmount,isnull(P.[DiscRate],0) as DiscRate,isnull(P.[DiscAmount],0) as DiscAmount,isnull(P.[SixMonths],0) as SixMonths ,
                                                isnull(P.[TwelveMonths],0) as TwelveMonths,BOMQty,BOMProjectList,P.PurchaseCommitee,P.[RejectReason],P.[PCRemarks],P.[StoresRemarks],P.PMMHRemarks,P.MHName,P.PMName,P.OtherProjects,P.POGeneratedBy,P.GMName,P.OMName,
                                                IM.UnitCost as StandardCost,((((P.[UnitPrice]-IM.UnitCost)/IM.UnitCost)* 100)) as DiffrenceinPer, (P.[UnitPrice]-IM.UnitCost) as DiffrenceinRs,LatestPurchasePrice,P.WithoutBOM ,IM.TargetCost,FinanceApproverName,P.[Currency],[FXRate],GMName
                                                from PurchaseOrder P join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join ItemMaster IM on 
                                                P.ItemCode=IM.Itemcode join Vendors V on P.VendorCode=V.VendorCode where [DBOMNo]='" + POnumber + "'  and (AuthoriedBy!='Deleted'or POGeneratedBy!='Deleted')  order by [DBOMNo] desc", SQLCon);

                    //SQLCmd=new SqlCommand(@"Select P.[ProjectCode], PM.ProjectDescription, IM.HSNSACCode, P.ItemCode,IM.ItemDescription, P.[VendorCode], V.VendorName, IM.AvailableQty, P.[RequariedQty] as ReqQty,P.[RemainingQty], IM.Units, P.[UnitPrice] as UnitCost, (P.RequariedQty * P.[UnitPrice]) as [Amount],P.PMName, P.MHName, P.PurchaseCommitee, P.Remarks, P.PreparedBy,convert(date, P.POGeneratedDate, 105) as POGeneratedDate,convert(date, P.PODeliveryDate, 105) as PODeliveryDate, isnull(P.[IGSTRate], 0) as IGSTRate,isnull(P.[IGSTAmount], 0) as IGSTAmount, isnull(P.[SGSTRate], 0) as SGSTRate,isnull(P.[SGSTAmount], 0) as SGSTAmount, isnull(P.[CGSTRate], 0) as CGSTRate, isnull(P.[CGSTAmount], 0) as CGSTAmount, isnull(P.[DiscRate], 0) as DiscRate, isnull(P.[DiscAmount], 0) as DiscAmount, isnull(P.[SixMonths], 0) as SixMonths,isnull(P.[TwelveMonths], 0) as TwelveMonths, BOMQty, BOMProjectList, P.PurchaseCommitee,P.[RejectReason], P.[PCRemarks], P.[StoresRemarks], P.PMMHRemarks, P.MHName, P.PMName,P.OtherProjects, P.POGeneratedBy, P.GMName, P.OMName,IM.UnitCost as StandardCost, ((((P.[UnitPrice] - IM.UnitCost) / IM.UnitCost) * 100)) as DiffrenceinPer,(P.[UnitPrice] - IM.UnitCost) as DiffrenceinRs, LatestPurchasePrice, P.WithoutBOM, IM.TargetCost,FinanceApproverName, P.[Currency],[FXRate], GMName from PurchaseOrder P join ProjectMaster PM on P.ProjectCode = PM.ProjectCode join ItemMaster IM on P.ItemCode = IM.Itemcode join Vendors V on P.VendorCode = V.VendorCode where [DBOMNo] = '" + POnumber + "' and(AuthoriedBy != 'Deleted'or POGeneratedBy != 'Deleted') order by[DBOMNo] desc", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
