                switch (sCase)
                {
                    case 1:
                        SQLCmd = new SqlCommand(@"Select top 1 Preparedby,POPreparedDate, Remarks from PurchaseOrder where DBOMNo='" + sPONumber + "' union all Select top 1 PMName, PMApprovedDate, PMRemarks from PurchaseOrder where DBOMNo = '" + sPONumber + "'  union all Select top 1 FinalizedBy, FinalizedDate, FinalizedRemarks from PurchaseOrder where DBOMNo = '" + sPONumber + "' union all  Select top 1 PurchaseCommitee, PCAuthoriseDate, PCRemarks from PurchaseOrder where DBOMNo = '" + sPONumber + "' union all select top 1 OMName, OMApprovedDate, OMRemarks from PurchaseOrder where DBOMNo = '" + sPONumber + "' union all Select top 1[FinanceApproverName],[FinanceApprovedDate], [FinanceRemarks] from PurchaseOrder where DBOMNo = '" + sPONumber + "' union all Select top 1 GMName,[GMApprovedDate], RejectReason from PurchaseOrder where DBOMNo = '" + sPONumber + "' union all Select top 1 POUpdateRequestBy,'' as Date, POUpdateRemarks from PurchaseOrder where DBOMNo = '" + sPONumber + "'", SQLCon);
