        public DataSet WorkOrderList(string WOnumber)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (WOnumber == null)
                {
                    SQLCmd = new SqlCommand("Select * from WorkOrder", SQLCon);
                }
                else
                {
                    SQLCmd = new SqlCommand(@"SELECT WO.[WONumber],WO.[IPItemCode],im1.ItemDescription as IPItemDesc,im1.HSNSACCode as IPHSNSACCode ,im1.Units as IPUnit, im1.AvailableQty as IPAQty, 
                                               WO.[IPOrderQty],WO.[OPItemCode],IM2.ItemDescription as OPItemDesc,IM2.HSNSACCode as OPHSNSACCode , IM2.Units as OPUnit, IM2.AvailableQty as OPAQTY
                                              ,WO.[OPOrderQty],WO.[VendorCode],VM.VendorName,WO.[UnitCost],WO.[TotalCost],WO.[JobIssueStatus],WO.[PreparedBy],WO.[AuthorisedBy]
                                              ,WO.[WOgeneratedDate],WO.[WOGeneratedBy],WO.[WOStatus],WO.[IPRemainingOrderQty],WO.[WorkDescription],WO.[OPRemainingQty],WO.[DGRefno],WO.[ProjectCode],PM.ProjectDescription
	                                          ,convert(date,WO.WOgeneratedDate,105) as WOgeneratedDate, convert(date,WO.WODeliveryDate,105) as WODeliveryDate,
                                               isnull(WO.IGSTRate,0) as IGSTRate ,isnull(WO.IGSTAmount,0) as IGSTAmount, isnull(WO.SGSTRate,0) as SGSTRate,isnull(WO.SGSTAmount,0) as SGSTAmount,isnull(WO.CGSTRate,0) as CGSTRate,isnull(WO.CGSTAmount,0) as CGSTAmount,WO.PaymentTerm,WO.DeliveryTerm  
                                                 ,[UserRemarks],[PMMHRemarks],[PCRemarks],RejectReason ,[StoresRemarks],IBOMQty from WorkOrder WO LEFT   JOIN ItemMaster IM2 ON IM2.ItemCode = WO.OPItemCode LEFT   JOIN ItemMaster IM1 ON IM1.ItemCode = WO.IPItemCode join Vendors VM on WO.VendorCode =VM.VendorCode 
                                                join projectmaster PM on WO.ProjectCode=PM.ProjectCode Where WO.[WONumber]='" + WOnumber + "'", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet PrintWorkOrderList(string WOnumber, string IPItem)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (WOnumber != null && IPItem != null)
                {
                    //CONCAT(IM2.ItemDescription,' (Item Code : ',WO.[OPItemCode],'  HSN : ',IM2.HSNSACCode,' )') as [ItemDescription]
                    SQLCmd = new SqlCommand("SELECT CONCAT(im1.ItemDescription,' (Item Code : ',WO.[IPItemCode],'  HSN : ',im1.HSNSACCode,' )') as [ItemDescription],im1.Units, WO.[IPOrderQty] as [Input Qty] from WorkOrder WO LEFT JOIN ItemMaster IM1 ON IM1.ItemCode = WO.IPItemCode  Where WO.[WONumber]='" + WOnumber + "' ", SQLCon);
                }
                else if (WOnumber != null && IPItem == null)
                {
                    SQLCmd = new SqlCommand(@"SELECT CONCAT(IM2.ItemDescription,' (Item Code : ',WO.[OPItemCode],'  HSN : ',IM2.HSNSACCode,' )') as [ItemDescription], IM2.Units, WO.[WorkDescription] as [Work Order Description],WO.[OPOrderQty]as [Quantity],WO.[UnitCost],WO.[TotalCost], CONCAT( isnull(WO.SGSTAmount,0), CHAR(13),CHAR(10),' (',isnull(WO.[SGSTRate],0),'%)') as SGSTAmount ,CONCAT( isnull(WO.CGSTAmount,0), CHAR(13),CHAR(10),' (',isnull(WO.[CGSTRate],0),'%)') as CGSTAmount,CONCAT( isnull(WO.IGSTAmount,0), CHAR(13),CHAR(10),' (',isnull(WO.[IGSTRate],0),'%)') as IGSTAmount
                                               from WorkOrder WO LEFT   JOIN ItemMaster IM2 ON IM2.ItemCode = WO.OPItemCode Where WO.[WONumber]='" + WOnumber + "'", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
