        public DataSet purchaseOrderPrint(string POnumber)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (POnumber == null)
                {
                    SQLCmd = new SqlCommand("Select * from PurchaseOrder where [POGeneratedBy]='' or POGeneratedBy is null order by [DBOMNo] desc ", SQLCon);
                }
                else
                {
                    SQLCmd = new SqlCommand(@"Select  row_number() over(partition by P.DBOMNo order by P.DBOMNo) as [SNo],CONCAT(IM.ItemDescription,' (Item Code : ',P.ItemCode,'  HSN : ',IM.HSNSACCode,' )') as [ItemDescription],P.UOM,
                                            P.[RequariedQty] as [Quantity],P.[UnitPrice] as [UnitPrice] ,P.[Amount] ,CONCAT( isnull(P.[DiscAmount],0), CHAR(13),CHAR(10),' (',isnull(P.[DiscRate],0),'%)') as DiscAmount,CONCAT( isnull(P.SGSTAmount,0), CHAR(13),CHAR(10),' (',isnull(P.[SGSTRate],0),'%)') as SGSTAmount ,
                                           CONCAT( isnull(P.CGSTAmount,0), CHAR(13),CHAR(10),' (',isnull(P.[CGSTRate],0),'%)')  as CGSTAmount,CONCAT( isnull(P.IGSTAmount,0), CHAR(13),CHAR(10),' (',isnull(P.[IGSTRate],0),'%)')  as IGSTAmount,P.POUptoDate from PurchaseOrder P join ItemMaster IM on P.ItemCode=IM.ItemCode  where [DBOMNo]='" + POnumber + "' and (AuthoriedBy!='Deleted'or POGeneratedBy!='Deleted') order by [DBOMNo] desc ", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

