                                          P.Remarks,P.PreparedBy,P.POGeneratedDate,P.PODeliveryDate,isnull(P.[IGSTRate],0) as IGSTRate ,isnull(P.[IGSTAmount],0) as IGSTAmount,isnull(P.[SGSTRate],0) as SGSTRate ,isnull(P.[SGSTAmount],0) as SGSTAmount ,isnull(P.[CGSTRate],0) as CGSTRate,
                                          isnull(P.[CGSTAmount],0) as CGSTAmount,isnull(P.[DiscRate],0) as DiscRate,isnull(P.[DiscAmount],0) as DiscAmount,P.[RejectReason],P.[PCRemarks],P.[StoresRemarks],P.PMMHRemarks,P.OtherProjects,
                                          IM.UnitCost as StandardCost,IM.TargetCost,((((P.[UnitPrice]-IM.UnitCost)/IM.UnitCost)* 100)) as DiffrenceinPer, (P.[UnitPrice]-IM.UnitCost) as DiffrenceinRs,LatestPurchasePrice,P.WithoutBOM,PMName,MHName,PurchaseCommitee,OMName,FinanceApproverName,P.[Currency],[FXRate]  
                                          from PurchaseOrder P join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join ItemMaster IM on 
                                          P.ItemCode=IM.Itemcode join Vendors V on P.VendorCode=V.VendorCode where [DBOMNo]='" + SPonumber + "' and (AuthoriedBy!='Deleted'or POGeneratedBy!='Deleted') order by [DBOMNo] desc", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand(@"Select P.[ProjectCode],PM.ProjectDescription,IM.HSNSACCode,P.ItemCode,IM.ItemDescription,IM.Units,P.[VendorCode],V.VendorName,IM.AvailableQty,P.[RequariedQty] as ReqQty,P.[RemainingQty],P.[UnitPrice] as UnitCost ,P.[Amount],P.AuthoriedBy,
                                          P.Remarks,P.PreparedBy,P.POGeneratedDate,P.PODeliveryDate,isnull(P.[IGSTRate],0) as IGSTRate ,isnull(P.[IGSTAmount],0) as IGSTAmount,isnull(P.[SGSTRate],0) as SGSTRate ,isnull(P.[SGSTAmount],0) as SGSTAmount ,isnull(P.[CGSTRate],0) as CGSTRate,
                                          isnull(P.[CGSTAmount],0) as CGSTAmount,isnull(P.[DiscRate],0) as DiscRate,isnull(P.[DiscAmount],0) as DiscAmount,
                                          isnull(P.[SixMonths],0) as SixMonths ,isnull(P.[TwelveMonths],0) as TwelveMonths,BOMQty,BOMProjectList,P.PurchaseCommitee,P.[RejectReason],P.[PCRemarks],P.[StoresRemarks],P.PMMHRemarks,P.MHName,P.PMName,P.OMName,P.OtherProjects,
                                          IM.UnitCost as StandardCost,((((P.[UnitPrice]-IM.UnitCost)/IM.UnitCost)* 100)) as DiffrenceinPer,IM.TargetCost, (P.[UnitPrice]-IM.UnitCost) as DiffrenceinRs,LatestPurchasePrice,P.WithoutBOM,PMName,MHName,PurchaseCommitee,POUpdateRequestBy ,POUpdateRemarks,FinanceApproverName,P.[Currency],[FXRate]   
                                          from PurchaseOrder P join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join ItemMaster IM on 
                                          P.ItemCode=IM.Itemcode join Vendors V on P.VendorCode=V.VendorCode where [DBOMNo]='" + SPonumber + "' and ([POGeneratedBy]!='' and POGeneratedBy is not null and POGeneratedBy!='Deleted') and (AuthoriedBy IS NOT NULL and AuthoriedBy!='' and AuthoriedBy!='Deleted') order by [DBOMNo] desc", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand(@"Select * from PurchaseOrder  where [DBOMNo]='" + SPonumber + "' and ([POGeneratedBy]!='' and POGeneratedBy is not null and POGeneratedBy!='Deleted') and (AuthoriedBy IS NOT NULL and AuthoriedBy!='' and AuthoriedBy!='Deleted') order by [DBOMNo] desc", SQLCon);
                        break;


                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
