        public DataSet fnGINDeliverDateValue(string SPonumber, string sWonumber)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (SPonumber != null && sWonumber == null)
                {
                    SQLCmd = new SqlCommand(" SET DATEFORMAT dmy; select DATEDIFF (day,p.[PODeliveryDate],r.[InvoiceDate]) as NumberofGINDays from [PurchaseOrder] p join Receipt r on p.DBOMNo=r.RefNumber where DBOMNo='" + SPonumber + "' and (AuthoriedBy!='Deleted'or POGeneratedBy!='Deleted')", SQLCon);
                }
                else if (SPonumber == null && sWonumber != null)
                {
                    SQLCmd = new SqlCommand(" SET DATEFORMAT dmy; select DATEDIFF (day,p.[PODeliveryDate],r.[InvoiceDate]) as NumberofGINDays from [PurchaseOrder] p join Receipt r on p.DBOMNo=r.RefNumber where DBOMNo='" + SPonumber + "' and (AuthoriedBy!='Deleted'or POGeneratedBy!='Deleted')", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
        public DataSet fnPOOrderFilter(uint iFilterType, string sUserName)
        {
            SQLDataset = new DataSet();
            try
            {
                SQLCon.Open();
                switch (iFilterType)
                {
                    case 0:
                        {
                            SQLCmd = new SqlCommand("select * from PurchaseOrder where (AuthoriedBy IS NULL or AuthoriedBy='')", SQLCon);
                            break;
                        }
                    case 1:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where ([POGeneratedBy]='' or POGeneratedBy is null)  and (AuthoriedBy IS not NULL and  AuthoriedBy!='Deleted') and (PMApproved!=1 or PMApproved is null) and PreparedBy='" + sUserName + "'", SQLCon);
                            break;
                        }
                    case 2:
                        {
                            SQLCmd = new SqlCommand("Select  DBOMNo from PurchaseOrder where (POGeneratedBy is not null and POGeneratedBy!='Deleted') and  PurchaseCommitee is not null and [POApproved]='1'  group by DBOMNo order by DBOMNo desc ", SQLCon);
                            break;
                        }

                    case 3:
                        {
                            //SQLCmd = new SqlCommand(@"Select DBOMNo from PurchaseOrder where ([POApproved]='0') and PurchaseCommitee is not null and (AuthoriedBy!='Deleted') and FinalizedBy is not null group by DBOMNo", SQLCon);
                            SQLCmd = new SqlCommand(@"Select DBOMNo from PurchaseOrder where ([POApproved]='0') and OMApproved=1 and PurchaseCommitee is not null and OMName is not null and (AuthoriedBy!='Deleted') and FinalizedBy is not null group by DBOMNo", SQLCon);

                            break;
                        }

                    case 4:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where  ([POApproved]='1') and ([PurchaseCommitee]!='' or PurchaseCommitee is not null)  and (AuthoriedBy!='Deleted') and (POGeneratedBy='' or POGeneratedBy is null) GROUP BY DBOMNo order by DBOMNo desc", SQLCon);
                            break;
                        }


                    case 5:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where ([PMApproved]='1') and [MHApproved] is null  and (AuthoriedBy!='Deleted')  and PMName='" + sUserName + "' group by DBOMNo", SQLCon);
                            break;
                        }

                    case 82:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where [PMApproved]='1' and [MHApproved] is null and PurchaseCommitee is null and AuthoriedBy!='Deleted' and FinalizedBy is null and PMName='" + sUserName + "'   group by DBOMNo", SQLCon);
                            break;
                        }

                    case 6:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where [PMApproved]='1' and [MHApproved]='1' and PurchaseCommitee is null and AuthoriedBy!='Deleted' and FinalizedBy is not null and MHName='" + sUserName + "'   group by DBOMNo", SQLCon);
                            break;
                        }
                    case 7:
                        {
                            SQLCmd = new SqlCommand("Select * from PurchaseOrder where [PMApproved]='1' and [MHApproved]='1' and [POApproved]='0' and PurchaseCommitee='Thilak Kumar' and (AuthoriedBy!='Deleted')", SQLCon);
                            break;
                        }

                    case 8:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where ([POGeneratedBy]!='' or POGeneratedBy is not null) and  AuthoriedBy!='Deleted' and POUpdate='1' group by DBOMNo ", SQLCon);
                            break;
                        }
                    case 9:
                        {
                            SQLCmd = new SqlCommand("SELECT [POUserName] FROM  [POApproveList] where [POApprover]='" + sUserName + "'", SQLCon);
                            break;
                        }

                    case 10:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where [PMApproved]='1' and [MHApproved]='1' and PurchaseCommitee is not null and FinalizedBy is not null  and  AuthoriedBy!='Deleted'  and POApproved='0'  and [FinanceApproverName] is null group by DBOMNo", SQLCon);
                            break;
                        }

                    case 11:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where  [PMApproved]='1' and [MHApproved]='1' and AuthoriedBy!='Deleted' and  PurchaseCommitee is null and FinalizedBy is null and (POGeneratedBy is null or POGeneratedBy!='') GROUP BY DBOMNo order by DBOMNo desc", SQLCon);
                            break;
                        }

                    case 12:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where [PMApproved]='1' and [MHApproved]='1' and PurchaseCommitee is null and AuthoriedBy!='Deleted' and FinalizedBy is not null and MHName='" + sUserName + "'   group by DBOMNo", SQLCon);
                            break;
                        }
                    case 13:
                        {
                            SQLCmd = new SqlCommand("Select DBOMNo from PurchaseOrder where [PMApproved]='1' and [MHApproved]='1' and [POApproved] = '0' and PurchaseCommitee is not null and AuthoriedBy != 'Deleted' and[OMApproved] = '0' and FinalizedBy is not null and [PurchaseCommitee] = '" + sUserName + "'    group by DBOMNo", SQLCon);
                            break;
                        }

                    case 14:
                        {
                            SQLCmd = new SqlCommand("SELECT [POUserName] FROM  [POApproveList] where [POApprover]='" + sUserName + "'", SQLCon);
                            break;
                        }
                    case 15:
                        {
                            //SQLCmd = new SqlCommand("Select  DBOMNo from PurchaseOrder where (POGeneratedBy is not null and POGeneratedBy!='Deleted') and  PurchaseCommitee is not null and [POApproved]='1'  group by DBOMNo order by DBOMNo desc ", SQLCon);
                            SQLCmd = new SqlCommand($@" SELECT PO.DBOMNo
                                                        FROM PurchaseOrder PO
                                                        WHERE NOT EXISTS (
                                                            SELECT 1 
                                                            FROM Receipt R
                                                            WHERE r.RefNumber = PO.DBOMNo
                                                        )
                                                        AND (PO.POGeneratedBy != 'Deleted' OR PO.POGeneratedBy IS NULL)
                                                         group by DBOMNo order by DBOMNo desc;", SQLCon);
                            break;
                        }
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


