        public DataSet fnWOFilter(uint iFilterType, string sUsername)
        {
            SQLDataset = new DataSet();
            try
            {
                SQLCon.Open();
                switch (iFilterType)
                {
                    case 0:
                        {
                            SQLCmd = new SqlCommand("select * from WorkOrder where (AuthorisedBy IS NULL or AuthorisedBy='') order by id desc", SQLCon);
                            break;
                        }
                    case 1:
                        {
                            SQLCmd = new SqlCommand("Select * from WorkOrder where (WOGeneratedBy IS NULL or WOGeneratedBy='') and WOApproved='1' order by id desc", SQLCon);
                            break;
                        }
                    case 2:
                        {
                            SQLCmd = new SqlCommand("Select * from WorkOrder where (WOGeneratedBy IS NOT NULL or WOGeneratedBy!='') and (AuthorisedBy IS NOT NULL and AuthorisedBy!='') order by id desc", SQLCon);
                            break;
                        }

                    case 6:
                        {
                            SQLCmd = new SqlCommand("Select * from WorkOrder where WOApproved='0' order by id desc", SQLCon);
                            break;
                        }
                    case 7:
                        {
                            SQLCmd = new SqlCommand("Select * from WorkOrder where WONUmber='" + sUsername + "' order by id desc", SQLCon);
                            break;
                        }

                    case 31:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where (AuthorisedBy IS not NULL or AuthorisedBy!='') and (WOGeneratedBy IS NULL or WOGeneratedBy='') and PMApproved is null and PreparedBy='" + sUsername + "' group by WONumber", SQLCon);
                            break;
                        }

                    case 32:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where (AuthorisedBy IS not NULL or AuthorisedBy!='') and PMApproved='1' and  MHApproved is null and PMName='" + sUsername + "' group by WONumber", SQLCon);
                            break;
                        }
                    case 82:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where (AuthorisedBy IS not NULL or AuthorisedBy!='') and PMApproved='1' and  MHApproved is null and PMName='" + sUsername + "' group by WONumber", SQLCon);
                            break;
                        }
                    case 29:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where PMApproved='1' and  MHApproved='1' and FinalizedBy is not null and (PurchaseCommitee is null or PurchaseCommitee='') and MHName='" + sUsername + "' group by WONumber", SQLCon);
                            break;
                        }

                    case 80:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where PMApproved='1' and  MHApproved='1' and FinalizedBy is not null and PurchaseCommitee is not null and FinanceApproverName is null group by WONumber", SQLCon);
                            break;
                        }
                    case 161:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where PMApproved='1' and  MHApproved='1' and FinalizedBy is not null and WOApproved='1' and PurchaseCommitee is not null and WOGeneratedBy is null group by WONumber", SQLCon);
                            break;
                        }
                    case 16:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where PMApproved='1' and  MHApproved='1' and FinalizedBy is null and convert(date,WOPreparedDate,105)>='2022-11-29' group by WONumber", SQLCon);
                            break;
                        }

                    case 30:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where WOApproved='0' and PMApproved='1' and  MHApproved='1' and FinalizedBy is not null and PurchaseCommitee is not null and [GMName] is null  group by WONumber", SQLCon);
                            break;
                        }

                    case 3:
                        {
                            SQLCmd = new SqlCommand("select WONumber from WorkOrder where WOApproved='0' and PMApproved='1' and  MHApproved='1' and OMApproved='0' and FinalizedBy is not null and PurchaseCommitee is not null and [GMName] is null  group by WONumber", SQLCon);
