        public int purchaseOrderListDeleted(int iCase, string PONUM, string ItemCode, string DeleteBy, string DeleteDate, string BOMProjectCodes, string ProductNo)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand("INSERT INTO PurchaseOrderItemDeleteHistory([PONo], [ItemCode], [DeleteBy], [DeleteDate], [BOMProjectCodes],[ProductNo]) " +
                               "VALUES ('" + PONUM + "','" + ItemCode + "', '" + DeleteBy + "','" + DeleteDate + "','" + BOMProjectCodes + "','" + ProductNo + "')", SQLCon);

                        break;
                    case 1:
                        SQLCmd = new SqlCommand("Update PurchaseOrder set AuthoriedBy='Deleted',POGeneratedBy='Deleted' where DBOMNo='" + PONUM + "' and ItemCode='" + ItemCode + "'", SQLCon);
                        break;

                }

                GlobalClass.iSuccess = SQLCmd.ExecuteNonQuery();



                SQLCon.Close();
                return GlobalClass.iSuccess;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iSuccess;
            }
        }


