        public DataSet fnItemUsageTable(string fromdate, string sixMonth, string twelveMonth)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (fromdate != null && sixMonth == null && twelveMonth != null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;select RTRIM(LTRIM([Item_Code])) as [Item_Code],ItemDescription,UnitCost,'' as [6 months Usage] ,sum(IssuedQuantity) 
                                            as [12 Months Usage]from (SELECT  RTRIM(LTRIM(i.[Item_Code])) as [Item_Code],im.ItemDescription,im.UnitCost ,i.[Issue_Date] ,i.IssuedQuantity FROM 
                                            [Issued] i  join ItemMaster  IM on i.Item_Code=IM.ItemCode where (convert(date,[Issue_Date],105) >= '" + fromdate + "' AND convert(date,[Issue_Date],105) <= '" + twelveMonth + "') )  as Result  group by Item_Code,ItemDescription,UnitCost", SQLCon);
                }
                if (fromdate != null && sixMonth != null && twelveMonth == null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;select RTRIM(LTRIM([Item_Code])) as [Item_Code],ItemDescription,UnitCost,sum(IssuedQuantity) as [6 months Usage],'' 
                                            as [12 Months Usage] from (SELECT  RTRIM(LTRIM(i.[Item_Code])) as [Item_Code],im.ItemDescription,im.UnitCost ,i.[Issue_Date] ,i.IssuedQuantity FROM 
                                           [Issued] i  join ItemMaster  IM on i.Item_Code=IM.ItemCode where ( convert(date,[Issue_Date],105) >= '" + fromdate + "' AND convert(date,[Issue_Date],105) <= '" + sixMonth + "') )  as Result  group by Item_Code,ItemDescription,UnitCost", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnItemUsage(string fromdate, string sixMonth, string twelveMonth, string sItemcode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (fromdate != null && sixMonth != null && twelveMonth != null && sItemcode == null)
                {
                    SQLCmd = new SqlCommand(@"SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months] FROM [ItemMaster] union all
                                                SELECT i.[Item_Code],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Issue_Date],105) >= '" + sixMonth + "'  AND convert(date,i.[Issue_Date],105) <= '" + twelveMonth + "') then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.[Issue_Date],105) >= '" + fromdate + "' AND convert(date,i.[Issue_Date],105) <= '" + twelveMonth + "') then i.IssuedQuantity  end) AS '12Months' FROM [Issued] i  join ItemMaster  IM on i.Item_Code=IM.ItemCode  where (convert(date,[Issue_Date],105) >= '" + fromdate + "' AND convert(date,[Issue_Date],105) <= '" + twelveMonth + "') group by Item_Code,ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[IssueDate],105) >= '" + sixMonth + "'  AND convert(date,i.[IssueDate],105) <= '" + twelveMonth + "') then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.[IssueDate],105) >= '" + fromdate + "' AND convert(date,i.[IssueDate],105) <= '" + twelveMonth + "') then i.IssuedQuantity  end) AS '12Months' FROM [JobIssue] i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[IssueDate],105) >= '" + fromdate + "' AND convert(date,[IssueDate],105) <= '" + twelveMonth + "') group by i.ItemCode,ItemDescription,UnitCost", SQLCon);
                }
                else if (fromdate != null && sixMonth != null && twelveMonth != null && sItemcode != null)
                {
                    SQLCmd = new SqlCommand(@"SELECT i.[Item_Code],im.ItemDescription,im.UnitCost, SUM(case when(convert(date,i.[Issue_Date],105) >= '" + sixMonth + "'  AND convert(date,i.[Issue_Date],105) <= '" + twelveMonth + "') then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.[Issue_Date],105) >= '" + fromdate + "' AND convert(date,i.[Issue_Date],105) <= '" + twelveMonth + "') then i.IssuedQuantity  end) AS '12Months' FROM [Issued] i  join ItemMaster  IM on i.Item_Code=IM.ItemCode  where Item_Code='" + sItemcode + "' and (convert(date,[Issue_Date],105) >= '" + fromdate + "' AND convert(date,[Issue_Date],105) <= '" + twelveMonth + "') group by Item_Code,ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,im.UnitCost, SUM(case when(convert(date,i.[IssueDate],105) >= '" + sixMonth + "'  AND convert(date,i.[IssueDate],105) <= '" + twelveMonth + "') then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.[IssueDate],105) >= '" + fromdate + "' AND convert(date,i.[IssueDate],105) <= '" + twelveMonth + "') then i.IssuedQuantity  end) AS '12Months' FROM [JobIssue] i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where i.ItemCode='" + sItemcode + "' and (convert(date,[IssueDate],105) >= '" + fromdate + "' AND convert(date,[IssueDate],105) <= '" + twelveMonth + "') group by i.ItemCode,ItemDescription,UnitCost", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

