                switch (iCase)
                {
                    case "All":

                        //SQLCmd = new SqlCommand(@"Declare @FromDate datetime, @SixMonth datetime, @TwelveMonth datetime;
                        //                        SET @FromDate='" + fromdate + "' Set @SixMonth= '" + sixMonth + "' Set @TwelveMonth= '" + twelveMonth + "' SELECT  [ItemCode],[ItemDescription],CASE WHEN CreatedDate='' then DATEADD(day,0,GETDATE()) ELSE CONVERT(date,[CreatedDate],105)end as CreatedDate,[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty])+([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [ItemMaster] where CreatedDate!='' union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanItemMaster] union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanElectronicsItemMaster]   union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanElectronicsFinishedItemMaster]   union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanFinishedItemMaster union all SELECT i.[Item_Code],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.Issue_Date,105) >= @SixMonth  AND convert(date,i.Issue_Date,105) <= @FromDate) then i.Quantity  end) AS '6Months',SUM(case when(convert(date,i.Issue_Date,105) >= @TwelveMonth AND convert(date,i.Issue_Date,105) <= @FromDate) then i.Quantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM Issued i  join ItemMaster  IM on i.Item_Code=IM.ItemCode where (convert(date,Issue_Date,105) >= @TwelveMonth  AND convert(date,Issue_Date,105) <= @FromDate) and (Project_Code!='51423973035' or Project_Code!='613201177001') group by i.Item_Code,ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.IssueDate,105) >= @SixMonth  AND convert(date,i.IssueDate,105) <= @FromDate) then i.issuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.IssueDate,105) >= @TwelveMonth AND convert(date,i.IssueDate,105) <= @FromDate) then i.issuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM JobIssue i  join ItemMaster  IM on i.ItemCode=IM.ItemCode join WorkOrder W on i.WONumber=W.WONumber and i.ItemCode=W.IPItemCode  where (convert(date,IssueDate,105) >= @TwelveMonth AND convert(date,IssueDate,105) <= @FromDate) and (ProjectCode!='51423973035' or ProjectCode!='613201177001') group by i.ItemCode,ItemDescription,IM.UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Date],105) >= @SixMonth  AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1  end) AS '6Months', SUM(case when(convert(date,i.[Date],105) >= @TwelveMonth AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1 end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [ItemReturn] i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[Date],105) >= @TwelveMonth AND convert(date,[Date],105) <= @FromDate) group by i.ItemCode,ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Date],105) >= @SixMonth  AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1  end) AS '6Months', SUM(case when(convert(date,i.[Date],105) >= @TwelveMonth AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM ItemReturnJobIssued i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[Date],105) >= @TwelveMonth AND convert(date,[Date],105) <= @FromDate) group by i.ItemCode,ItemDescription,UnitCost union all SELECT i.[Item_Code],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.IssuedDate,105) >= @SixMonth  AND convert(date,i.IssuedDate,105) <= @FromDate) then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.IssuedDate,105) >= @TwelveMonth AND convert(date,i.IssuedDate,105) <= @FromDate) then i.IssuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanElectronicsIssued i  join ItemMaster  IM on i.Item_Code=IM.ItemCode  where (convert(date,IssuedDate,105) >= @TwelveMonth AND convert(date,IssuedDate,105) <= @FromDate) group by i.Item_Code,im.ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Date],105) >= @SixMonth  AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1  end) AS '6Months', SUM(case when(convert(date,i.[Date],105) >= @TwelveMonth AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1 end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanElectronicsItemReturn i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[Date],105) >= @TwelveMonth AND convert(date,[Date],105) <= @FromDate) group by i.ItemCode,ItemDescription,UnitCost union all SELECT i.[Item_Code],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.IssuedDate,105) >= @SixMonth  AND convert(date,i.IssuedDate,105) <= @FromDate) then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.IssuedDate,105) >= @TwelveMonth AND convert(date,i.IssuedDate,105) <= @FromDate) then i.IssuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanIssued i  join ItemMaster  IM on i.Item_Code=IM.ItemCode  where (convert(date,IssuedDate,105) >= @TwelveMonth AND convert(date,IssuedDate,105) <= @FromDate) group by i.Item_Code,im.ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Date],105) >= @SixMonth  AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity  end) AS '6Months', SUM(case when(convert(date,i.[Date],105) >= @TwelveMonth AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanItemReturn i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[Date],105) >= @TwelveMonth AND convert(date,[Date],105) <= @FromDate) group by i.ItemCode,ItemDescription,UnitCost  union all SELECT i.[Item_Code],'' as ItemDescription,'' as [CreatedDate],'0.0' as UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[IssuedDate],105) >= @SixMonth  AND convert(date,i.[IssuedDate],105) <= @FromDate) then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.[IssuedDate],105) >= @TwelveMonth AND convert(date,i.[IssuedDate],105) <= @FromDate) then i.IssuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanElectronicsIssuedFG] i  where (convert(date,[IssuedDate],105) >= @TwelveMonth AND convert(date,[IssuedDate],105) <= @FromDate) group by i.Item_Code union all SELECT i.[Item_Code],'' as ItemDescription,'' as [CreatedDate],'0.0' as UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[IssuedDate],105) >= @SixMonth  AND convert(date,i.[IssuedDate],105) <= @FromDate) then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.[IssuedDate],105) >= @TwelveMonth AND convert(date,i.[IssuedDate],105) <= @FromDate) then i.IssuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanIssuedFG] i  where (convert(date,[IssuedDate],105) >= @TwelveMonth AND convert(date,[IssuedDate],105) <= @FromDate) group by i.Item_Code", SQLCon);
                        SQLCmd = new SqlCommand($@" DECLARE @Fromdatetime datetime = '{fromdate + " 00:00:00"}'; DECLARE @ToDatetime datetime = '{sixMonth + " 23:59:59"}';

                        WITH AllTransactions AS (
                        Select R.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost as STD_C,R.CDValue as PreviousUnitCost,CONVERT(datetime,R.Date,105) as Date,R.Quantity,R.UnitCost,P.ProjectCode,R.GINNumber as 'TRNNo','PO Reciept' as TransactionType, 'Stores' as Location from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode join PurchaseOrder P on R.RefNumber=P.DBOMNo and r.ItemCode=p.ItemCode

                        Where CONVERT(datetime,R.Date,105)>=@Fromdatetime and CONVERT(datetime,R.Date,105)<=@ToDatetime and R.Refnumber like 'PO%'

                        union ALL

                        Select R.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,0 as PreviousUnitCost,CONVERT(datetime,R.Date,105) as Date,R.Quantity,R.UnitCost,P.ProjectCode,R.GINNumber as 'TRNNo','WO Reciept' as TransactionType, 'Stores' as Location from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode join WorkOrder P on R.RefNumber=P.WoNumber  AND r.ItemCode=p.OPItemCode

                        Where CONVERT(datetime,R.Date,105)>=@Fromdatetime and CONVERT(datetime,R.Date,105)<=@ToDatetime  and R.Refnumber like 'WO%'

                         union ALL 

                        Select R.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,IM.PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, R.Date, 105)) AS Date,
                        R.Quantity,R.UnitCost,'' asProjectCode,R.GINNumber as 'TRNNo','Stock Adjusted' as TransactionType, 'Stores' as Location from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode 

                        Where CONVERT(DATETIME, R.Date, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME, R.Date, 105) <= DATEADD(MINUTE, 5, @ToDatetime)  and R.Refnumber ='0' or R.Refnumber like 'Purchase Items Returned%' 

                        union ALL 

                        Select IR.Itemcode,IM.ItemDescription,IM.Type,IM.Units,Issued.unitprice as UnitCost,0 as PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, IR.Date, 105)) AS Date,
                        IR.Quantity,IM.UnitCost,IR.ProjectCode,TransctoinNo as GINNUber, 'ItemReturned' as TransactionType, 'Stores' as Location from ItemReturn IR join ItemMaster IM on IR.ItemCode=IM.ItemCode 
                        join Issued  ON Issued.indent_number = IR.IndentNumber and Issued.Item_code = IR.Itemcode
                        Where CONVERT(DATETIME, IR.Date, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME, IR.Date, 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

 
                        union ALL
                        Select IR.Itemcode,IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,IM.PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, IR.Date, 105)) AS Date,
                        IR.Quantity,IM.UnitCost,IR.ProjectCode,TransctoinNo as GINNUber, 'ItemReturned-job' as TransactionType, 'Stores' as Location from ItemReturnJobIssued IR join ItemMaster IM on IR.ItemCode=IM.ItemCode

                        Where CONVERT(DATETIME, IR.Date, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME, IR.Date, 105) <= DATEADD(MINUTE, 5, @ToDatetime)  

                        union ALL

                        Select iss.Item_Code AS ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,0 as PreviousUnitCost,   DATEADD(MINUTE, 5, CONVERT(DATETIME, iss.Issue_Date, 105)) AS Date, (iss.IssuedQuantity *-1),iss.unitprice,iss.Project_Code,iss.Indent_Number,'IndentIssued' as TransactionType, 'Stores' as Location from Issued iss join ItemMaster IM on iss.Item_Code=IM.ItemCode

                        Where 

                         CONVERT(DATETIME, iss.Issue_Date, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME, iss.Issue_Date, 105) <= DATEADD(MINUTE, 5, @ToDatetime)

                        union ALL

                        Select j.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,0 as PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, j.IssueDate, 105)) AS Date, (j.IssuedQuantity *-1),j.unitprice,W.ProjectCode,j.WONumber as Refnumber,'JobIssued' as TransactionType, 'Stores' as Location from JobIssue j inner join ItemMaster IM on j.ItemCode=IM.ItemCode join WorkOrder W on j.WONumber=W.WONumber and j.ItemCode=W.IPItemCode

                        Where CONVERT(DATETIME, j.IssueDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME, j.IssueDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

                        union ALL

                         Select R.[ItemCode], IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,0 as PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, R.ReverseGINDate, 105)) AS Date,(R.ReturnQty *-1),R.UnitCost,

                         '' as ProjectCode, R.GINNumber as Refnumber,'ReverseGIN' as TransactionType, 'Stores' as Location   from [RiverseGIN] R join ItemMaster IM on R.ItemCode=IM.ItemCode

                         Where CONVERT(DATETIME, R.ReverseGINDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME, R.ReverseGINDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

                        union ALL

                        Select IM.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,0 as PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, IM.CreatedDate, 105)) AS Date, IM.OpeningQuantity, IM.UnitCost,'' as ProjectCode,'' as Refnumber,'OpeningStock' as TransactionType, 'Stores' as Location from  ItemMaster IM Where IM.OpeningQuantity>=0 

                        union all     

                        select ItemCode,ItemDescription,Type,Units,UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, CreatedDate, 105)) AS Date, OpeningQuantity as Quantity, 

                        UnitCost,'' as ProjectCode,'' as [TRNNo],'KanBanOB' as [TransactionType], 'Transducers' as Location from KanBanItemMaster 

                        union all

                          select ItemCode,ItemDescription,Type,Units,UnitCost,0 as PreviousCost, DATEADD(MINUTE, 5, CONVERT(DATETIME, CreatedDate, 105)) AS Date, OpeningQuantity, 

                        UnitCost,'' as ProjectCode,'' as [TransactionNo],'KanBanOBFG' as [Type], 'Transducers' as Location from KanBanFinishedItemMaster 

                        union all 

                        select KR.[ItemCode],KI.ItemDescription,KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost, DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate, 105)) AS Date,Quantity,

                        KR.[UnitCost],'51423973035' as ProjectCode ,RefNumber as [TransactionNo]  ,'KanBanRecieved' as [Type] , 'Transducers' as Location

                        from [KanBanReceipt] KR join KanBanItemMaster KI on KR.ItemCode=KI.ItemCode

                        Where CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME, IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime)  

                        union all 

                        select KR.[ItemCode],KI.ItemDescription,KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,  DATEADD(MINUTE, 5, CONVERT(DATETIME,[ProductionDate] ,105)) AS Date,Quantity,

                        KR.[UnitCost],'' as ProjectCode,KANProductNo as [TransactionNo],'KanBanProducedFG' as [Type], 'Transducers' as Location

                        from KanBanProduction KR join KanBanFinishedItemMaster KI on KR.ItemCode=KI.ItemCode

                        Where CONVERT(DATETIME, [ProductionDate], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME, [ProductionDate], 105) <= DATEADD(MINUTE, 5, @ToDatetime)

                         union all  

                        SELECT [Item_Code],KR.[ItemDescription],KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate, 105)) AS Date,
                        (IssuedQuantity*-1) as IssuedQuantity ,

                        unitprice,'' as ProjectCode ,KANProductNo as [TransactionNo],'KanBanIssueToFG' as [Type]  , 'Transducers' as Location

                        FROM [KanBanIssued] KR join KanBanItemMaster KI on KR.[Item_Code]=KI.ItemCode

                        Where  CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

                        union all  

                        SELECT [Item_Code],[ItemDescription],KFM.Type,KFM.Units,KFM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate, 105)) AS Date,(IssuedQuantity*-1) as IssuedQuantity,

                        unitprice, ProjectCode,IssueNo as [TransactionNo],CONCAT(Issue_Type,' Issue') as [Type]   , 'Transducers' as Location

                        FROM KanBanIssuedFG KFG join KanBanFinishedItemMaster KFM on KFG.Item_Code=KFM.ItemCode and KFG.Issue_Type='TransducerFG'

                        Where CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime)

                        union all  

                        SELECT [Item_Code],[ItemDescription],KM.Type,KM.Units,KM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate ,105)) AS Date,(IssuedQuantity*-1) as IssuedQuantity
                        ,unitprice,ProjectCode ,IssueNo as [TransactionNo],CONCAT(Issue_Type,' Issue') as [Type]   , 'Transducers' as Location

                        FROM KanBanIssuedFG KFG join KanBanItemMaster KM on KFG.Item_Code=KM.ItemCode and KFG.Issue_Type='TransducerItem'

                        Where  CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime)
 
                        union all 

                        select ItemCode,ItemDescription,Type,Units,UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, CreatedDate, 105)) AS Date, OpeningQuantity as Quantity, 

                        UnitCost,'' as ProjectCode,'' as [TRNNo],'KanBanOB' as [TransactionType] , 'Electronics' as Location from KanBanElectronicsItemMaster 

                        union all

                          select ItemCode,ItemDescription,Type,Units,UnitCost,0 as PreviousCost, DATEADD(MINUTE, 5, CONVERT(DATETIME, CreatedDate, 105)) AS Date, OpeningQuantity, 

                        UnitCost,'' as ProjectCode,'' as [TransactionNo],'KanBanOBFG' as [Type], 'Electronics' as Location from KanBanElectronicsFinishedItemMaster 

                        union all 

                        select KR.[ItemCode],KI.ItemDescription,KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate ,105)) AS Date,Quantity,

                        KR.[UnitCost],'613201177001' as ProjectCode ,RefNumber as [TransactionNo]  ,'KanBanRecieved' as [Type], 'Electronics' as Location

                        from [KanBanElectronicsReceipt] KR join KanBanElectronicsItemMaster KI on KR.ItemCode=KI.ItemCode

                        Where  CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime)
  
                        union all 

                        select KR.[ItemCode],KI.ItemDescription,KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,  DATEADD(MINUTE, 5, CONVERT(DATETIME,[ProductionDate], 105)) AS Date,Quantity,

                        KR.[UnitCost],'' as ProjectCode,KANProductNo as [TransactionNo],'KanBanProducedFG' as [Type], 'Electronics' as Location

                        from KanBanElectronicsProduction KR join KanBanElectronicsFinishedItemMaster KI on KR.ItemCode=KI.ItemCode

                        Where  CONVERT(DATETIME, [ProductionDate], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[ProductionDate], 105) <= DATEADD(MINUTE, 5, @ToDatetime)
  
                        union all  

                        SELECT [Item_Code],KI.[ItemDescription],KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate ,105)) AS Date,
                        (IssuedQuantity*-1) as IssuedQuantity ,

                        unitprice,'' as ProjectCode ,KANProductNo as [TransactionNo],'KanBanIssueToFG' as [Type], 'Electronics' as Location  

                        FROM [KanBanElectronicsIssued] KR join KanBanElectronicsItemMaster KI on KR.[Item_Code]=KI.ItemCode

                        Where  CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime) 
 
                        union all  

                        SELECT [Item_Code],[ItemDescription],KFM.Type,KFM.Units,KFM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate, 105)) AS Date,
                        (IssuedQuantity*-1) as IssuedQuantity,

                        unitprice, ProjectCode,IssueNo as [TransactionNo],CONCAT(Issue_Type,' Issue') as [Type], 'Electronics' as Location   

                        FROM KanBanElectronicsIssuedFG KFG join KanBanElectronicsFinishedItemMaster KFM on KFG.Item_Code=KFM.ItemCode and KFG.Issue_Type='ElectronicsFG'

                        Where  CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

                         union all  

                        SELECT [Item_Code],[ItemDescription],KM.Type,KM.Units,KM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate ,105)) AS Date,
                        (IssuedQuantity*-1) as IssuedQuantity

                        ,unitprice,ProjectCode ,IssueNo as [TransactionNo],CONCAT(Issue_Type,' Issue') as [Type] , 'Electronics' as Location  

                        FROM KanBanElectronicsIssuedFG KFG join KanBanElectronicsItemMaster KM on KFG.Item_Code=KM.ItemCode and KFG.Issue_Type='ElectronicsItem'

                        Where  CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime)  

                        union all

                         Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,
                        Quantity as RecievedQty, 

                        [UnitPrice],KBEI.[ProjectCode],IssuedNumber as [TRNNo],'KanBanItemReturn' as [TransactionType]  , 'Electronics' as Location  

                        from [KanBanElectronicsItemReturn] KBEI join KanBanElectronicsItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)

                        union all  

                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,
                        Quantity as RecievedQty, 

                        [UnitPrice],KBEI.[ProjectCode] ,IssuedNumber as [TRNNo],'KanBanItemReturn' as [TransactionType] , 'Electronics' as Location 

                        from[KanBanElectronicsItemReturn] KBEI join KanBanElectronicsFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)

                        union all 

                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty,

                        [UnitPrice],KBEI.Remarks,TransactionNo as [TRNNo],'KanBanItemStockAdjust' as [TransactionType]  , 'Electronics' as Location 

                        from [KanBanElectronicsItemStockAdjust] KBEI join KanBanElectronicsItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

                        union all 

                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty, 

                        [UnitPrice],KBEI.Remarks,TransactionNo as [TRNNo],'KanBanItemStockAdjust' as [TransactionType], 'Electronics' as Location 

                        from [KanBanElectronicsItemStockAdjust] KBEI join KanBanElectronicsFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime) 



                        union all 

                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty,

                        [UnitPrice],KBEI.Remarks,TransactionNo as [TRNNo],'KanBanItemStockAdjust' as [TransactionType]  , 'Transducers' as Location 

                        from [KanBanItemStockAdjust] KBEI join KanBanItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)

                         union all 

                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty, 

                        [UnitPrice],KBEI.Remarks,TransactionNo as [TRNNo],'KanBanItemStockAdjust' as [TransactionType], 'Transducers' as Location 

                        from [KanBanItemStockAdjust] KBEI join KanBanFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)


                        union all 

                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date] ,105)) AS Date,Quantity as RecievedQty, 

                        [UnitPrice],KBEI.[ProjectCode],IssuedNumber as [TRNNo],'KanBanItemReturn' as [TransactionType]  , 'Transducers' as Location  

                        from [KanBanItemReturn] KBEI join KanBanItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)


                        union all 

                         Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty, 

                        [UnitPrice],KBEI.[ProjectCode] ,IssuedNumber as [TRNNo],'KanBanItemReturn' as [TransactionType] , 'Transducers' as Location 

                        from[KanBanItemReturn] KBEI join KanBanFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)


                        )
                        SELECT *
                        FROM AllTransactions
                        ORDER BY Date, ItemCode;
                        ", SQLCon);
                        break;
                    case "Inward":

                        //SQLCmd = new SqlCommand(@"Declare @FromDate datetime, @SixMonth datetime, @TwelveMonth datetime;
                        //                        SET @FromDate='" + fromdate + "' Set @SixMonth= '" + sixMonth + "' Set @TwelveMonth= '" + twelveMonth + "' SELECT  [ItemCode],[ItemDescription],CASE WHEN CreatedDate='' then DATEADD(day,0,GETDATE()) ELSE CONVERT(date,[CreatedDate],105)end as CreatedDate,[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty])+([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [ItemMaster] where CreatedDate!='' union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanItemMaster] union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanElectronicsItemMaster]   union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanElectronicsFinishedItemMaster]   union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanFinishedItemMaster union all SELECT i.[Item_Code],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.Issue_Date,105) >= @SixMonth  AND convert(date,i.Issue_Date,105) <= @FromDate) then i.Quantity  end) AS '6Months',SUM(case when(convert(date,i.Issue_Date,105) >= @TwelveMonth AND convert(date,i.Issue_Date,105) <= @FromDate) then i.Quantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM Issued i  join ItemMaster  IM on i.Item_Code=IM.ItemCode where (convert(date,Issue_Date,105) >= @TwelveMonth  AND convert(date,Issue_Date,105) <= @FromDate) and (Project_Code!='51423973035' or Project_Code!='613201177001') group by i.Item_Code,ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.IssueDate,105) >= @SixMonth  AND convert(date,i.IssueDate,105) <= @FromDate) then i.issuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.IssueDate,105) >= @TwelveMonth AND convert(date,i.IssueDate,105) <= @FromDate) then i.issuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM JobIssue i  join ItemMaster  IM on i.ItemCode=IM.ItemCode join WorkOrder W on i.WONumber=W.WONumber and i.ItemCode=W.IPItemCode  where (convert(date,IssueDate,105) >= @TwelveMonth AND convert(date,IssueDate,105) <= @FromDate) and (ProjectCode!='51423973035' or ProjectCode!='613201177001') group by i.ItemCode,ItemDescription,IM.UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Date],105) >= @SixMonth  AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1  end) AS '6Months', SUM(case when(convert(date,i.[Date],105) >= @TwelveMonth AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1 end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [ItemReturn] i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[Date],105) >= @TwelveMonth AND convert(date,[Date],105) <= @FromDate) group by i.ItemCode,ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Date],105) >= @SixMonth  AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1  end) AS '6Months', SUM(case when(convert(date,i.[Date],105) >= @TwelveMonth AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM ItemReturnJobIssued i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[Date],105) >= @TwelveMonth AND convert(date,[Date],105) <= @FromDate) group by i.ItemCode,ItemDescription,UnitCost union all SELECT i.[Item_Code],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.IssuedDate,105) >= @SixMonth  AND convert(date,i.IssuedDate,105) <= @FromDate) then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.IssuedDate,105) >= @TwelveMonth AND convert(date,i.IssuedDate,105) <= @FromDate) then i.IssuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanElectronicsIssued i  join ItemMaster  IM on i.Item_Code=IM.ItemCode  where (convert(date,IssuedDate,105) >= @TwelveMonth AND convert(date,IssuedDate,105) <= @FromDate) group by i.Item_Code,im.ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Date],105) >= @SixMonth  AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1  end) AS '6Months', SUM(case when(convert(date,i.[Date],105) >= @TwelveMonth AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity * -1 end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanElectronicsItemReturn i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[Date],105) >= @TwelveMonth AND convert(date,[Date],105) <= @FromDate) group by i.ItemCode,ItemDescription,UnitCost union all SELECT i.[Item_Code],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.IssuedDate,105) >= @SixMonth  AND convert(date,i.IssuedDate,105) <= @FromDate) then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.IssuedDate,105) >= @TwelveMonth AND convert(date,i.IssuedDate,105) <= @FromDate) then i.IssuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanIssued i  join ItemMaster  IM on i.Item_Code=IM.ItemCode  where (convert(date,IssuedDate,105) >= @TwelveMonth AND convert(date,IssuedDate,105) <= @FromDate) group by i.Item_Code,im.ItemDescription,UnitCost union all SELECT i.[ItemCode],im.ItemDescription,'' as [CreatedDate],im.UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[Date],105) >= @SixMonth  AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity  end) AS '6Months', SUM(case when(convert(date,i.[Date],105) >= @TwelveMonth AND convert(date,i.[Date],105) <= @FromDate) then i.Quantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM KanBanItemReturn i  join ItemMaster  IM on i.ItemCode=IM.ItemCode  where (convert(date,[Date],105) >= @TwelveMonth AND convert(date,[Date],105) <= @FromDate) group by i.ItemCode,ItemDescription,UnitCost  union all SELECT i.[Item_Code],'' as ItemDescription,'' as [CreatedDate],'0.0' as UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[IssuedDate],105) >= @SixMonth  AND convert(date,i.[IssuedDate],105) <= @FromDate) then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.[IssuedDate],105) >= @TwelveMonth AND convert(date,i.[IssuedDate],105) <= @FromDate) then i.IssuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanElectronicsIssuedFG] i  where (convert(date,[IssuedDate],105) >= @TwelveMonth AND convert(date,[IssuedDate],105) <= @FromDate) group by i.Item_Code union all SELECT i.[Item_Code],'' as ItemDescription,'' as [CreatedDate],'0.0' as UnitCost,'0.0' as [AvailableQty], SUM(case when(convert(date,i.[IssuedDate],105) >= @SixMonth  AND convert(date,i.[IssuedDate],105) <= @FromDate) then i.IssuedQuantity  end) AS '6Months', SUM(case when(convert(date,i.[IssuedDate],105) >= @TwelveMonth AND convert(date,i.[IssuedDate],105) <= @FromDate) then i.IssuedQuantity  end) AS '12Months',''  as StockValue,'' as [Type],'' as Units,0 as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanIssuedFG] i  where (convert(date,[IssuedDate],105) >= @TwelveMonth AND convert(date,[IssuedDate],105) <= @FromDate) group by i.Item_Code", SQLCon);
                        SQLCmd = new SqlCommand($@" DECLARE @Fromdatetime datetime = '{fromdate + " 00:00:00"}'; DECLARE @ToDatetime datetime = '{sixMonth + " 23:59:59"}';
                            WITH AllTransactions AS (
Select R.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost as STD_C,R.CDValue as PreviousUnitCost,CONVERT(datetime,R.Date,105) as Date,R.Quantity,R.UnitCost,P.ProjectCode,R.GINNumber as 'TRNNo','PO Reciept' as TransactionType, 'Stores' as Location from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode join PurchaseOrder P on R.RefNumber=P.DBOMNo and r.ItemCode=p.ItemCode

Where CONVERT(datetime,R.Date,105)>=@Fromdatetime and CONVERT(datetime,R.Date,105)<=@ToDatetime and R.Refnumber like 'PO%'

union ALL

Select R.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,0 as PreviousUnitCost,CONVERT(datetime,R.Date,105) as Date,R.Quantity,R.UnitCost,P.ProjectCode,R.GINNumber as 'TRNNo','WO Reciept' as TransactionType, 'Stores' as Location from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode join WorkOrder P on R.RefNumber=P.WoNumber  AND r.ItemCode=p.OPItemCode

Where CONVERT(datetime,R.Date,105)>=@Fromdatetime and CONVERT(datetime,R.Date,105)<=@ToDatetime  and R.Refnumber like 'WO%'


union ALL 

Select IR.Itemcode,IM.ItemDescription,IM.Type,IM.Units,Issued.unitprice as UnitCost,0 as PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, IR.Date, 105)) AS Date,
IR.Quantity,IM.UnitCost,IR.ProjectCode,TransctoinNo as GINNUber, 'ItemReturned' as TransactionType, 'Stores' as Location from ItemReturn IR join ItemMaster IM on IR.ItemCode=IM.ItemCode 
join Issued  ON Issued.indent_number = IR.IndentNumber and Issued.Item_code = IR.Itemcode
Where CONVERT(DATETIME, IR.Date, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME, IR.Date, 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

 
union ALL
Select IR.Itemcode,IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,IM.PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, IR.Date, 105)) AS Date,
IR.Quantity,IM.UnitCost,IR.ProjectCode,TransctoinNo as GINNUber, 'ItemReturned-job' as TransactionType, 'Stores' as Location from ItemReturnJobIssued IR join ItemMaster IM on IR.ItemCode=IM.ItemCode

Where CONVERT(DATETIME, IR.Date, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME, IR.Date, 105) <= DATEADD(MINUTE, 5, @ToDatetime)  



union ALL

Select IM.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,0 as PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, IM.CreatedDate, 105)) AS Date, IM.OpeningQuantity, IM.UnitCost,'' as ProjectCode,'' as Refnumber,'OpeningStock' as TransactionType, 'Stores' as Location from  ItemMaster IM Where IM.OpeningQuantity>=0 

union all     

select ItemCode,ItemDescription,Type,Units,UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, CreatedDate, 105)) AS Date, OpeningQuantity as Quantity, 

UnitCost,'' as ProjectCode,'' as [TRNNo],'KanBanOB' as [TransactionType], 'Transducers' as Location from KanBanItemMaster 

union all

  select ItemCode,ItemDescription,Type,Units,UnitCost,0 as PreviousCost, DATEADD(MINUTE, 5, CONVERT(DATETIME, CreatedDate, 105)) AS Date, OpeningQuantity, 

UnitCost,'' as ProjectCode,'' as [TransactionNo],'KanBanOBFG' as [Type], 'Transducers' as Location from KanBanFinishedItemMaster 

union all 

select KR.[ItemCode],KI.ItemDescription,KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost, DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate, 105)) AS Date,Quantity,

KR.[UnitCost],'51423973035' as ProjectCode ,RefNumber as [TransactionNo]  ,'KanBanRecieved' as [Type] , 'Transducers' as Location

from [KanBanReceipt] KR join KanBanItemMaster KI on KR.ItemCode=KI.ItemCode

Where CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME, IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime)  

union all 

select KR.[ItemCode],KI.ItemDescription,KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,  DATEADD(MINUTE, 5, CONVERT(DATETIME,[ProductionDate] ,105)) AS Date,Quantity,

KR.[UnitCost],'' as ProjectCode,KANProductNo as [TransactionNo],'KanBanProducedFG' as [Type], 'Transducers' as Location

from KanBanProduction KR join KanBanFinishedItemMaster KI on KR.ItemCode=KI.ItemCode

Where CONVERT(DATETIME, [ProductionDate], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME, [ProductionDate], 105) <= DATEADD(MINUTE, 5, @ToDatetime)


 
union all 

select ItemCode,ItemDescription,Type,Units,UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, CreatedDate, 105)) AS Date, OpeningQuantity as Quantity, 

UnitCost,'' as ProjectCode,'' as [TRNNo],'KanBanOB' as [TransactionType] , 'Electronics' as Location from KanBanElectronicsItemMaster 

union all

  select ItemCode,ItemDescription,Type,Units,UnitCost,0 as PreviousCost, DATEADD(MINUTE, 5, CONVERT(DATETIME, CreatedDate, 105)) AS Date, OpeningQuantity, 

UnitCost,'' as ProjectCode,'' as [TransactionNo],'KanBanOBFG' as [Type], 'Electronics' as Location from KanBanElectronicsFinishedItemMaster 

union all 

select KR.[ItemCode],KI.ItemDescription,KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate ,105)) AS Date,Quantity,

KR.[UnitCost],'613201177001' as ProjectCode ,RefNumber as [TransactionNo]  ,'KanBanRecieved' as [Type], 'Electronics' as Location

from [KanBanElectronicsReceipt] KR join KanBanElectronicsItemMaster KI on KR.ItemCode=KI.ItemCode

Where  CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime)
  
union all 

select KR.[ItemCode],KI.ItemDescription,KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,  DATEADD(MINUTE, 5, CONVERT(DATETIME,[ProductionDate], 105)) AS Date,Quantity,

KR.[UnitCost],'' as ProjectCode,KANProductNo as [TransactionNo],'KanBanProducedFG' as [Type], 'Electronics' as Location

from KanBanElectronicsProduction KR join KanBanElectronicsFinishedItemMaster KI on KR.ItemCode=KI.ItemCode

Where  CONVERT(DATETIME, [ProductionDate], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME,[ProductionDate], 105) <= DATEADD(MINUTE, 5, @ToDatetime)
  


union all

 Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,
Quantity as RecievedQty, 

[UnitPrice],KBEI.[ProjectCode],IssuedNumber as [TRNNo],'KanBanItemReturn' as [TransactionType]  , 'Electronics' as Location  

from [KanBanElectronicsItemReturn] KBEI join KanBanElectronicsItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)

union all  

Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,
Quantity as RecievedQty, 

[UnitPrice],KBEI.[ProjectCode] ,IssuedNumber as [TRNNo],'KanBanItemReturn' as [TransactionType] , 'Electronics' as Location 

from[KanBanElectronicsItemReturn] KBEI join KanBanElectronicsFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)


union all 

Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date] ,105)) AS Date,Quantity as RecievedQty, 

[UnitPrice],KBEI.[ProjectCode],IssuedNumber as [TRNNo],'KanBanItemReturn' as [TransactionType]  , 'Transducers' as Location  

from [KanBanItemReturn] KBEI join KanBanItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)


union all 

 Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty, 

[UnitPrice],KBEI.[ProjectCode] ,IssuedNumber as [TRNNo],'KanBanItemReturn' as [TransactionType] , 'Transducers' as Location 

from[KanBanItemReturn] KBEI join KanBanFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)


)
SELECT *
FROM AllTransactions
ORDER BY Date, ItemCode;

                        ", SQLCon);
                        break;
                    case "Outward":

                        //SQLCmd = new SqlCommand(@"Declare @FromDate datetime, @SixMonth datetime, @TwelveMonth datetime;
                        //                        SET @FromDate='" + fromdate + "' Set @SixMonth= '" + sixMonth + "' Set @TwelveMonth= '" + twelveMonth + "' SELECT  [ItemCode],[ItemDescription],CASE WHEN CreatedDate='' then DATEADD(day,0,GETDATE()) ELSE CONVERT(date,[CreatedDate],105)end as CreatedDate,[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty])+([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [ItemMaster] where CreatedDate!='' union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanItemMaster] union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanElectronicsItemMaster]   union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQty]*0.223269876),2) as [Inventory Value with OH],'' as [Grading], 0 as [Reserve Amount] FROM [KanBanElectronicsFinishedItemMaster]   union all SELECT  [ItemCode],[ItemDescription],CONVERT(date,[CreatedDate],105) as [CreatedDate],[UnitCost] ,[AvailableQty],'0.0' as [6Months],'0.0' as [12Months],ROUND([UnitCost] *[AvailableQty],2) as StockValue,Type,Units,ROUND(([UnitCost] *[AvailableQ