                        SQLCmd = new SqlCommand($@" DECLARE @Fromdatetime datetime = '{fromdate + " 00:00:00"}'; DECLARE @ToDatetime datetime = '{sixMonth + " 23:59:59"}';
                        WITH AllTransactions AS (

Select R.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost as STD_C,R.CDValue as PreviousUnitCost,CONVERT(datetime,R.Date,105) as Date,R.Quantity,R.UnitCost,P.ProjectCode,R.GINNumber as 'TRNNo','PO Reciept' as TransactionType, 'Stores' as Location from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode join PurchaseOrder P on R.RefNumber=P.DBOMNo and r.ItemCode=p.ItemCode

