Select iss.Item_Code AS ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,0 as PreviousUnitCost,   DATEADD(MINUTE, 5, CONVERT(DATETIME, iss.Issue_Date, 105)) AS Date, (iss.IssuedQuantity *-1),iss.unitprice,iss.Project_Code,iss.Indent_Number,'IndentIssued' as TransactionType, 'Stores' as Location from Issued iss join ItemMaster IM on iss.Item_Code=IM.ItemCode

Where 

 CONVERT(DATETIME, iss.Issue_Date, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME, iss.Issue_Date, 105) <= DATEADD(MINUTE, 5, @ToDatetime)

union ALL

