Where CONVERT(DATETIME, j.IssueDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME, j.IssueDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

 
union ALL
      
SELECT [Item_Code],KR.[ItemDescription],KI.Type,KI.Units,KI.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate, 105)) AS Date,
(IssuedQuantity*-1) as IssuedQuantity ,

unitprice,'' as ProjectCode ,KANProductNo as [TransactionNo],'KanBanIssueToFG' as [Type]  , 'Transducers' as Location

