Where CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
    AND CONVERT(DATETIME,IssuedDate, 105) <= DATEADD(MINUTE, 5, @ToDatetime)

union all  

SELECT [Item_Code],[ItemDescription],KM.Type,KM.Units,KM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,IssuedDate ,105)) AS Date,(IssuedQuantity*-1) as IssuedQuantity
,unitprice,ProjectCode ,IssueNo as [TransactionNo],CONCAT(Issue_Type,' Issue') as [Type]   , 'Transducers' as Location

FROM KanBanIssuedFG KFG join KanBanItemMaster KM on KFG.Item_Code=KM.ItemCode and KFG.Issue_Type='TransducerItem'

Where  CONVERT(DATETIME, IssuedDate, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
