                                                                WITH AllTransactions AS (
                                        Select R.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost as STD_C,R.CDValue as PreviousUnitCost,CONVERT(datetime,R.Date,105) as Date,R.Quantity,R.UnitCost,P.ProjectCode,R.GINNumber as 'TRNNo','PO Reciept' as TransactionType, 'Stores' as Location from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode join PurchaseOrder P on R.RefNumber=P.DBOMNo and r.ItemCode=p.ItemCode

                                        Where CONVERT(datetime,R.Date,105)>=@Fromdatetime and CONVERT(datetime,R.Date,105)<=@ToDatetime and R.ReceiptNo=''

                                        union ALL


                                        Select R.ItemCode, IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,IM.PreviousUnitCost,DATEADD(MINUTE, 5, CONVERT(DATETIME, R.Date, 105)) AS Date,
                                        R.Quantity,R.UnitCost,'' asProjectCode,R.GINNumber as 'TRNNo','Stock Adjusted' as TransactionType, 'Stores' as Location from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode 

                                        Where CONVERT(DATETIME, R.Date, 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                                            AND CONVERT(DATETIME, R.Date, 105) <= DATEADD(MINUTE, 5, @ToDatetime)  and R.Refnumber ='0' or R.Refnumber like 'Purchase Items Returned%' 


                                        union all  

                                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty,

                                        [UnitPrice],KBEI.Remarks,TransactionNo as [TRNNo],'KanBanItemStockAdjust' as [TransactionType]  , 'Electronics' as Location 

                                        from [KanBanElectronicsItemStockAdjust] KBEI join KanBanElectronicsItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime) 

                                        union all 

                                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty, 

                                        [UnitPrice],KBEI.Remarks,TransactionNo as [TRNNo],'KanBanItemStockAdjust' as [TransactionType], 'Electronics' as Location 

                                        from [KanBanElectronicsItemStockAdjust] KBEI join KanBanElectronicsFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime) 



                                        union all 

                                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty,

                                        [UnitPrice],KBEI.Remarks,TransactionNo as [TRNNo],'KanBanItemStockAdjust' as [TransactionType]  , 'Transducers' as Location 

                                        from [KanBanItemStockAdjust] KBEI join KanBanItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)

                                         union all 

                                        Select KBEI.ItemCode,KEM.ItemDescription,KEM.Type,KEM.Units,KEM.UnitCost,0 as PreviousCost,DATEADD(MINUTE, 5, CONVERT(DATETIME,[Date], 105)) AS Date,Quantity as RecievedQty, 

                                        [UnitPrice],KBEI.Remarks,TransactionNo as [TRNNo],'KanBanItemStockAdjust' as [TransactionType], 'Transducers' as Location 

                                        from [KanBanItemStockAdjust] KBEI join KanBanFinishedItemMaster KEM on KBEI.ItemCode=KEM.ItemCode 

                                        Where  CONVERT(DATETIME, [Date], 105) >= DATEADD(MINUTE, 5, @Fromdatetime)
                                            AND CONVERT(DATETIME,[Date], 105) <= DATEADD(MINUTE, 5, @ToDatetime)




                                        )
                                        SELECT *
                                        FROM AllTransactions
                                        ORDER BY Date, ItemCode;
                                        ", SQLCon);
                        break;
                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


