 AND convert(date,IR.Date,105) <= @FromDate) then IR.Quantity*-1  end AS '6 Months Quantity' ,case when(convert(date,IR.Date,105) >= @TwelveMonth 
 AND convert(date,IR.Date,105) <= @FromDate) then IR.Quantity*-1  end AS '12 Months Quantity',IM.UnitCost,IR.ProjectCode,TransctoinNo as GINNUber, 
 'ItemReturned-job' as TransactionType, 'Stores' as Location,'' as ProductCode,'' as ProductName,PM.Status as Status
 from ItemReturnJobIssued IR join ItemMaster IM on IR.ItemCode=IM.ItemCode 
