          SET @SixMonth='" + sixMonth + @"' 
          SET @TwelveMonth='" + twelveMonth + @"' 

         Select IR.Itemcode,IM.ItemDescription,IM.Type,IM.Units,IM.UnitCost,IM.PreviousUnitCost,CONVERT(date,IR.Date,105) as Date,case when(convert(date,IR.Date,105) >= @SixMonth  AND convert(date,IR.Date,105) <= @FromDate) then IR.Quantity*-1  end AS '6 Months Quantity' ,case when(convert(date,IR.Date,105) >= @TwelveMonth  AND convert(date,IR.Date,105) <= @FromDate) then IR.Quantity*-1  end AS '12 Months Quantity',IM.UnitCost as IssuedCost,IR.ProjectCode,TransctoinNo as GINNumber, 'ItemReturned' as TransactionType, 'Stores' as Location,'' 
