                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"SELECT [ProjectCode],[TransferedProjectCode],[TransferedBy] ,(convert(date,[TransferedDate],105)) as [TransferedDate] from ProjectTransferInfo where (convert(date,[TransferedDate],105) >= '" + fromdate + "' AND convert(date,[TransferedDate],105) <= '" + todate + "') order by id asc", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand(@"SELECT [TransactionNo],[ProjectCode],[ProjectStatus],[TallyVoucherNo] ,[Amount],[CapexNo] ,[AssetSerialNo],[Remarks],[StatusChangedUserName],(convert(date,[StatusChangedDate],105)) as StatusChangedDate from ProjectStatusUpdate  where (convert(date,[StatusChangedDate],105) >= '" + fromdate + "' AND convert(date,[StatusChangedDate],105) <= '" + todate + "')  order by id asc", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand(@"SELECT [TransactionNo],[ProjectCode],[ProjectStatus],[InstallationFormNo],[InstallationDate],[PersonSigned],[Designationofsigned],[AssetSerialNo] ,[CustomerFeedback] ,[Remarks],[StatusChangedUserName],(convert(date,[StatusChangedDate],105)) as [StatusChangedDate] from ProjectInstallationStatusUpdate where (convert(date,[StatusChangedDate],105) >= '" + fromdate + "' AND convert(date,[StatusChangedDate],105) <= '" + todate + "')  order by id asc", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand(@"Select 'Main StoresRM' as Source ,[ItemCode],[ItemDescription],convert(date,[CreatedDate],105) as CreatedDate,[OpeningQuantity],[AvailableQty],[UnitCost],(UnitCost * AvailableQty) as StockValue,[type],[Units] from ItemMaster where CreatedDate!='' and Type NOT IN ('FixedAsset','Service(Non-Inventory)','Consumable- Non-Inventory', 'Maintenance') and  ItemCode Not like 'FA-B-%' and  ItemCode Not like 'MNT-%'
