                                                    union all
                                                    SELECT 'Transducer StoresFG' as Source,[ItemCode],[ItemDescription],convert(date,CreatedDate,105) as CreatedDate,OpeningQuantity,[AvailableQty],[UnitCost] ,([AvailableQty]*[UnitCost]) as [StockValue],[type] ,[Units] FROM [KanBanFinishedItemMaster]
                                                    union all
                                                    SELECT 'Electronics StoresRM' as Source, [ItemCode],[ItemDescription],convert(date,CreatedDate,105) as CreatedDate ,OpeningQuantity,[AvailableQty],[UnitCost] , ([AvailableQty]*[UnitCost]) as [StockValue],[type],[Units] FROM [KanBanElectronicsItemMaster]
                                                    union all
