                    //    SQLCmd = new SqlCommand(@"Select 'Main StoresRM' as Source ,[ItemCode],[ItemDescription],convert(date,[CreatedDate],105) as CreatedDate,[AvailableQty],[UnitCost],(UnitCost * AvailableQty) as StockValue,[Type],[Units],'' as [Latest Purchase Price],'' as [GIN Number],	'' as [GIN Date], '' as [Vendor Code], '' as [Vendor Name] from ItemMaster where CreatedDate!='' and Type!='FixedAsset'
                    //                                union all
