                    //                                union all
                    //                                SELECT 'Electronics StoresFG' as Source,[ItemCode],[ItemDescription],convert(date,CreatedDate,105) as CreatedDate,[AvailableQty],[UnitCost] ,([AvailableQty]*[UnitCost]) as [StockValue],[Type] ,[Units],'' as [Latest Purchase Price],'' as [GIN Number],	'' as [GIN Date], '' as [Vendor Code], '' as [Vendor Name] FROM [KanBanElectronicsFinishedItemMaster]", SQLCon);
                    //    break;

                    case 4:
                        SQLCmd = new SqlCommand(@"SELECT * FROM (SELECT 'Main StoresRM' as Source,  R.ItemCode,Im.ItemDescription,CONVERT(date,Im.CreatedDate,105) as CreatedDate,Im.AvailableQty,Im.UnitCost, (Im.AvailableQty*Im.UnitCost) as StockValue,
                                                                    Im.Type,Im.Units, (R.[UnitCost] - R.[UnitCost]* (COALESCE(R.[DiscRate], 0)/100)) as [Latest Purchase Price] , GINNumber as [GIN Number],CONVERT(date,date,105) as [GIN Date],
