                                                Im.Type,Im.Units, R.UnitCost as [Latest Purchase Price] , [KANProductNo] as [GIN Number],CONVERT(date,ProductionDate,105) as [GIN Date],
                                                '' as [Vendor Code], '' as [Vendor Name],'' as RefNumber,ROW_NUMBER() OVER (PARTITION BY R.Itemcode ORDER BY CONVERT(date,ProductionDate,105)  DESC) AS [Top 1 Purchase]
                                                FROM KanBanElectronicsProduction R right join KanBanElectronicsFinishedItemMaster Im on Im.ItemCode=R.ItemCode) groups
                                                WHERE groups.[Top 1 Purchase] = 1
                                                union all
                                                SELECT * FROM (SELECT 'Electronics-FG' as Source,  R.ItemCode,Im.ItemDescription,CONVERT(date,Im.CreatedDate,105) as CreatedDate,Im.AvailableQty,Im.UnitCost, (Im.AvailableQty*Im.UnitCost) as StockValue,
                                                Im.Type,Im.Units, R.UnitCost as [Latest Purchase Price] , [KANProductNo] as [GIN Number],CONVERT(date,ProductionDate,105) as [GIN Date],
                                                '' as [Vendor Code], '' as [Vendor Name],'' as RefNumber,ROW_NUMBER() OVER (PARTITION BY R.Itemcode ORDER BY CONVERT(date,ProductionDate,105)  DESC) AS [Top 1 Purchase]
                                                FROM KanBanElectronicsProduction R right join KanBanElectronicsFinishedItemMaster Im on Im.ItemCode=R.ItemCode) groups
                                                WHERE groups.[Top 1 Purchase] = 2
                                                union all
                                                SELECT * FROM (SELECT 'Electronics-FG' as Source,  R.ItemCode,Im.ItemDescription,CONVERT(date,Im.CreatedDate,105) as CreatedDate,Im.AvailableQty,Im.UnitCost, (Im.AvailableQty*Im.UnitCost) as StockValue,
                                                Im.Type,Im.Units, R.UnitCost as [Latest Purchase Price] , [KANProductNo] as [GIN Number],CONVERT(date,ProductionDate,105) as [GIN Date],
                                                '' as [Vendor Code], '' as [Vendor Name],'' as RefNumber,ROW_NUMBER() OVER (PARTITION BY R.Itemcode ORDER BY CONVERT(date,ProductionDate,105)  DESC) AS [Top 1 Purchase]
                                                FROM KanBanElectronicsProduction R right join KanBanElectronicsFinishedItemMaster Im on Im.ItemCode=R.ItemCode) groups
                                                WHERE groups.[Top 1 Purchase] = 3
                                                union all
                                                SELECT * FROM (SELECT 'Electronics-FG' as Source,  R.ItemCode,Im.ItemDescription,CONVERT(date,Im.CreatedDate,105) as CreatedDate,Im.AvailableQty,Im.UnitCost, (Im.AvailableQty*Im.UnitCost) as StockValue,
                                                Im.Type,Im.Units, R.UnitCost as [Latest Purchase Price] , [KANProductNo] as [GIN Number],CONVERT(date,ProductionDate,105) as [GIN Date],
                                                '' as [Vendor Code], '' as [Vendor Name],'' as RefNumber,ROW_NUMBER() OVER (PARTITION BY R.Itemcode ORDER BY CONVERT(date,ProductionDate,105)  DESC) AS [Top 1 Purchase]
                                                FROM KanBanElectronicsProduction R right join KanBanElectronicsFinishedItemMaster Im on Im.ItemCode=R.ItemCode) groups
                                                WHERE groups.[Top 1 Purchase] = 4
                                                union all
                                                SELECT * FROM (SELECT 'Electronics-FG' as Source,  R.ItemCode,Im.ItemDescription,CONVERT(date,Im.CreatedDate,105) as CreatedDate,Im.AvailableQty,Im.UnitCost, (Im.AvailableQty*Im.UnitCost) as StockValue,
                                                Im.Type,Im.Units, R.UnitCost as [Latest Purchase Price] , [KANProductNo] as [GIN Number],CONVERT(date,ProductionDate,105) as [GIN Date],
                                                '' as [Vendor Code], '' as [Vendor Name],'' as RefNumber,ROW_NUMBER() OVER (PARTITION BY R.Itemcode ORDER BY CONVERT(date,ProductionDate,105)  DESC) AS [Top 1 Purchase]
                                                FROM KanBanElectronicsProduction R right join KanBanElectronicsFinishedItemMaster Im on Im.ItemCode=R.ItemCode) groups
                                                WHERE groups.[Top 1 Purchase] = 5
                                                union all
                                                Select 'Main StoresRM' as Source ,I.[ItemCode],[ItemDescription],convert(date,[CreatedDate],105) as CreatedDate,[AvailableQty],I.[UnitCost],
                                                (I.UnitCost * AvailableQty) as StockValue,I.[Type],[Units],I.[UnitCost] as [Latest Purchase Price],'' as [GIN Number],	convert(date,[CreatedDate],105) as [GIN Date], '' as [Vendor Code],
                                                '' as [Vendor Name],'' as RefNumber,1  AS [Top 1 Purchase] from ItemMaster I where CreatedDate!='' and I.Type!='FixedAsset' and I.ItemCode  not in (select ItemCode from Receipt)", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


        public DataSet fnBOMItemPurchase(string sItemCode, string sIsGroup)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sItemCode != null && sIsGroup == null)
                {
                    SQLCmd = new SqlCommand(@"SELECT M.[ItemName],sum(M.[Quantity]) as BOMQTY FROM [ERP_Database].[dbo].[MachineBOM] M join ProjectMaster PM on M.ProjectCode=PM.ProjectCode 
                                                join ProjectBOM PB on M.ProjectCode=PB.ProjectCode and M.ProductNo=PB.ProductNo  where
                                                PM.[Status]='WIP' and ItemName='" + sItemCode + "'  group by M.ItemName", SQLCon);
                }
                else if (sItemCode != null && sIsGroup != null)
                {
                    SQLCmd = new SqlCommand(@" SELECT M.ProductNo,PB.ProductCode,pb.ProductName, M.[ProjectCode],Pm.ProjectDescription,(M.[Quantity]) as BOMQTY,0.0 as ReqQty,isnull(M.POQty,0) as POQty  
                                                FROM [ERP_Database].[dbo].[MachineBOM] M join ProjectMaster PM on M.ProjectCode=PM.ProjectCode
                                                join ProjectBOM PB on M.ProjectCode=PB.ProjectCode and M.ProductNo=PB.ProductNo  where PM.[Status]='WIP' and
                                                ItemName='" + sItemCode + "' and (M.[Quantity]-M.[IssuedQty])>0", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

