        public DataSet fnVedorCheck(int iCase, string VendorName)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        //SQLCmd = new SqlCommand("Select VendorName from Vendors where VendorName='" + VendorName + "'", SQLCon);  // Select Id from Vendors where Id=(select top 1 id from Vendors  order by id desc)
                        SQLCmd = new SqlCommand("Select VendorName from Vendors where VendorName COLLATE SQL_Latin1_General_CP1_CI_AS='" + VendorName + "'", SQLCon);
                        break;

                    case 1:
                        SQLCmd = new SqlCommand("Select GSTCode from Vendors where GSTCode='" + VendorName + "'", SQLCon);  // Select Id from Vendors where Id=(select top 1 id from Vendors  order by id desc)
                        break;

                    case 2:
                        SQLCmd = new SqlCommand("SELECT [VendorCode] FROM [PurchaseOrder] where VendorCode='" + VendorName + "' union all SELECT [VendorCode] FROM WorkOrder where VendorCode='" + VendorName + "'", SQLCon);  // Select Id from Vendors where Id=(select top 1 id from Vendors  order by id desc)
                        break;

                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


