        public DataSet GINReportTables(string Vendorname, string pono, string fromdate, string todate, int iSelect)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (Vendorname == null && pono == null && iSelect == 10)
                {
                    SQLCmd = new SqlCommand(" SET DATEFORMAT dmy;select [SupplierName],convert(date,[Date],105) as [Date]  FROM [Receipt] where convert(date,[Date],105) between '" + fromdate + "' and '" + todate + "' and SupplierName!='0' and ([RefNumber]  like'WO/JW%' or [RefNumber] like 'PO/%' or GINNumber like 'ITWSIN%') order by SupplierName asc", SQLCon);
                }

                else if (iSelect == 11)
                {
                    SQLCmd = new SqlCommand(@"select a.[GINNumber] FROM [Receipt] a  where convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "'and ([RefNumber]  like'WO/JW%' or [RefNumber] like 'PO/%' or GINNumber like 'ITWSIN%') group by GINNumber ", SQLCon);  //UNION ALL select b.[GINNumber] FROM GINOtherItemReceipt b  where convert(date,b.GINDate,105)>= '" + fromdate + "' and  convert(date,b.GINDate,105)<='" + todate + "' group by GINNumber order by GINNumber asc
                }

                if (Vendorname == null && pono == null && iSelect == 2)
                {
                    SQLCmd = new SqlCommand(" SET DATEFORMAT dmy;select [SupplierName],convert(date,[Date],105) as [Date]  FROM [Receipt] where convert(date,[Date],105) between '" + fromdate + "' and '" + todate + "' and SupplierName!='0' and ([RefNumber] like 'PO/%') order by SupplierName asc", SQLCon);
                }

                else if (iSelect == 4)
                {
                    SQLCmd = new SqlCommand(@"select a.[GINNumber] FROM [Receipt] a  where convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "'and ([RefNumber] like 'PO/%') group by GINNumber UNION ALL select b.[GINNumber] FROM GINOtherItemReceipt b  where convert(date,b.GINDate,105)>= '" + fromdate + "' and  convert(date,b.GINDate,105)<='" + todate + "' group by GINNumber order by GINNumber asc", SQLCon);
                }

                else if (iSelect == 15)
                {
                    SQLCmd = new SqlCommand(@"select a.[VendorName] as [Vendor Name], V.GSTCode, a.[GINNumber], a.[InvoiceNumber], a.[ItemCode], a.ItemDescription,a.HSNCode as HSNSACCode, a.[Quantity], a.[UnitCost], (a.[Quantity] * a.[UnitCost]) as Amount, isnull(a.[DiscRate], 0) as [Disc %],isnull(a.[DiscAmount], 0) as DiscAmount, (a.UnitCost * a.[Quantity]) as TaxableAmount, isnull(a.[SGSTRate], 0) as SGSTRate,isnull(a.[SGSTAmount], 0) as SGSTAmount,isnull(a.[CGSTRate], 0) as CGSTRate, isnull(a.[CGSTAmount], 0) as CGSTAmount,isnull(a.[IGSTRate], 0) as IGSTRate, isnull(a.[IGSTAmount], 0) as IGSTAmount,convert(date, a.[GINDate], 105) as [GIN Date],convert(date, a.[InvoiceDate], 105) as [Invoice Date],a.Ledger,'Service' as TransactionType FROM[GINOtherItemReceipt] a join
                                              Vendors V on a.VendorCode = V.VendorCode where convert(date, a.[GINDate], 105) >= '" + fromdate + "' and  convert(date, a.[GINDate], 105) <= '" + todate + "'", SQLCon);
                }
                else if (Vendorname == null && pono != null && iSelect == 10)
                {
                    //bhavya added
                    SQLCmd = new SqlCommand(@"
    -- Purchase Order Query
  
                    SELECT
        a.[RefNumber] AS[PO Number],
        a.VendorCode,
        a.SupplierName AS[Vendor Name],
        V.GSTCode,
        c.[ProjectCode],
        a.BOMProjectCode, 
        d.[ProjectDescription] AS[Project Name],
        d.[Customer],
        d.Status AS[Project Status],
        a.[GINNumber],
        a.[SupplierInvoiceNumber] AS[Invoice Number],
        a.[ItemCode],
        b.ItemDescription,
        b.HSNSACCode,
        a.[Quantity],
        a.[UnitCost],
        (a.[Quantity] * a.[UnitCost]) AS Amount,
        ISNULL(c.[DiscRate], 0) AS[Disc %],  
        (((a.UnitCost * a.[Quantity]) * ISNULL(c.[DiscRate], 0)) / 100) AS DiscAmount,
        (((a.UnitCost * a.[Quantity]) - ((a.UnitCost * a.[Quantity]) * ISNULL(c.[DiscRate], 0)) / 100)) AS TaxableAmount,
        ISNULL(c.[SGSTRate], 0) AS SGSTRate,
        ((((a.UnitCost * a.[Quantity]) - ((a.UnitCost * a.[Quantity]) * ISNULL(c.[DiscRate], 0)) / 100)) * ISNULL(c.[SGSTRate], 0)) / 100 AS SGSTAmount,
        ISNULL(c.[CGSTRate], 0) AS CGSTRate,
        ((((a.UnitCost * a.[Quantity]) - ((a.UnitCost * a.[Quantity]) * ISNULL(c.[DiscRate], 0)) / 100)) * ISNULL(c.[CGSTRate], 0)) / 100 AS CGSTAmount,
        ISNULL(c.[IGSTRate], 0) AS IGSTRate,
        ((((a.UnitCost * a.[Quantity]) - ((a.UnitCost * a.[Quantity]) * ISNULL(c.[DiscRate], 0)) / 100)) * ISNULL(c.[IGSTRate], 0)) / 100 AS IGSTAmount,
        0 AS[PackingForwarding],
        0 AS[PFIGSTRate],
        0 AS[PFIGSTAmount],
        0 AS[PFSGSTRate],
        0 AS[PFSGSTAmount],
        0 AS[PFCGSTRate],
        0 AS[PFCGSTAmount],
        0 AS[TransportationFreight],
        0 AS[TFIGSTRate],
        0 AS[TFIGSTAmount],
        0 AS[TFSGSTRate],
        0 AS[TFSGSTAmount],
        0 AS[TFCGSTRate],
        0 AS[TFCGSTAmount],
        0 AS[CDPercent],
        0 AS[CDValue],
        0 AS[CDIGSTRate],
        0 AS[CDIGSTAmount],
        0 AS[CDCessRate],
        0 AS[CDCessAmount],
        0 AS[TCSAmount],
        '' AS GrandTotal,
        CONVERT(DATE, c.POGeneratedDate, 105) AS[PO Generated Date],
        CONVERT(DATE, a.[Date], 105) AS[GIN Date],
        CONVERT(DATE, a.[InvoiceDate], 105) AS[Invoice Date],
        CONVERT(DATE, c.PODeliveryDate, 105) AS[Delivery Date],
        CASE
            WHEN DATEDIFF(DAY, CONVERT(DATE, c.PODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) > 0 THEN CONCAT('Delivery late by days : ', DATEDIFF(DAY, CONVERT(DATE, c.PODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)))  
            WHEN DATEDIFF(DAY, CONVERT(DATE, c.PODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) = 0 THEN 'Delivery On Time'
            ELSE CONCAT('Delivery early by days : ', (DATEDIFF(DAY, CONVERT(DATE, c.PODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) * -1)) 
        END AS DeliveryMonitor,
        CASE
            WHEN DATEDIFF(DAY, CONVERT(DATE, c.PODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) > 0 THEN CAST(DATEDIFF(DAY, CONVERT(DATE, c.PODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) *0.0071 * Amount AS DECIMAL(10, 2)) 
            ELSE '0.0'
        END AS Penalty,
        a.Ledger,
        'Purchase Order' AS TransactionType
    FROM[Receipt] a
   JOIN[ItemMaster] b ON a.ItemCode = b.ItemCode
    JOIN[PurchaseOrder] c ON a.RefNumber = c.[DBOMNo] AND a.ItemCode = c.ItemCode
    JOIN[ProjectMaster] d ON c.ProjectCode = d.ProjectCode
    JOIN Vendors V ON a.VendorCode = V.VendorCode
    WHERE a.GINNumber = @pono AND CONVERT(DATE, a.[Date], 105) >= @fromdate AND CONVERT(DATE, a.[Date], 105) <= @todate

    UNION ALL

    --Work Order Query
    SELECT
        a.[RefNumber] AS[PO Number],
        a.VendorCode,
        a.SupplierName AS[Vendor Name],
        V.GSTCode,
        c.[ProjectCode],
        a.BOMProjectCode,
        d.[ProjectDescription] AS[Project Name],
        d.[Customer],
        d.Status AS[Project Status],
        a.[GINNumber],
        a.[SupplierInvoiceNumber] AS[Invoice Number],
        a.[ItemCode],
        b.ItemDescription,
        b.HSNSACCode,
        a.[Quantity],
        a.[UnitCost],
        (a.[Quantity] * a.[UnitCost]) AS Amount,
        ISNULL(a.[DiscRate], 0) AS[Disc %],
        ISNULL(a.[DiscAmount], 0) AS DiscAmount,
        (a.UnitCost * a.[Quantity]) AS TaxableAmount,
        ISNULL(a.[SGSTRate], 0) AS SGSTRate,
        ISNULL(a.[SGSTAmount], 0) AS SGSTAmount,
        ISNULL(a.[CGSTRate], 0) AS CGSTRate,
        ISNULL(a.[CGSTAmount], 0) AS CGSTAmount,
        ISNULL(a.[IGSTRate], 0) AS IGSTRate,
        ISNULL(a.[IGSTAmount], 0) AS IGSTAmount,
        0 AS[PackingForwarding],
        0 AS[PFIGSTRate],
        0 AS[PFIGSTAmount],
        0 AS[PFSGSTRate],
        0 AS[PFSGSTAmount],
        0 AS[PFCGSTRate],
        0 AS[PFCGSTAmount],
        0 AS[TransportationFreight],
        0 AS[TFIGSTRate],
        0 AS[TFIGSTAmount],
        0 AS[TFSGSTRate],
        0 AS[TFSGSTAmount],
        0 AS[TFCGSTRate],
        0 AS[TFCGSTAmount],
        0 AS[CDPercent],
        0 AS[CDValue],
        0 AS[CDIGSTRate],
        0 AS[CDIGSTAmount],
        0 AS[CDCessRate],
        0 AS[CDCessAmount],
        0 AS[TCSAmount],
        '' AS GrandTotal,
        CONVERT(DATE, c.WOgeneratedDate, 105) AS[PO Generated Date],
        CONVERT(DATE, a.[Date], 105) AS[GIN Date],
        CONVERT(DATE, a.[InvoiceDate], 105) AS[Invoice Date],
        CONVERT(DATE, c.WODeliveryDate, 105) AS[Delivery Date],
        CASE
            WHEN DATEDIFF(DAY, CONVERT(DATE, c.WODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) > 0 THEN CONCAT('Delivery late by days : ', DATEDIFF(DAY, CONVERT(DATE, c.WODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105))) 
            WHEN DATEDIFF(DAY, CONVERT(DATE, c.WODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) = 0 THEN 'Delivery On Time'
            ELSE CONCAT('Delivery early by days : ', (DATEDIFF(DAY, CONVERT(DATE, c.WODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) * -1)) 
        END AS DeliveryMonitor,
        CASE
            WHEN DATEDIFF(DAY, CONVERT(DATE, c.WODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) > 0 THEN(DATEDIFF(DAY, CONVERT(DATE, c.WODeliveryDate, 105), CONVERT(DATE, a.[InvoiceDate], 105)) * 0.0071) * ((a.[Quantity] * a.[UnitCost]))
            ELSE '0.0'
        END AS Penalty,
        a.Ledger,
        'Work Order' AS TransactionType
    FROM[Receipt] a
   JOIN[ItemMaster] b ON a.ItemCode = b.ItemCode
    JOIN WorkOrder c ON a.RefNumber = c.WONumber AND a.ItemCode = c.OPItemCode
    JOIN[ProjectMaster] d ON c.ProjectCode = d.ProjectCode
    JOIN Vendors V ON a.VendorCode = V.VendorCode
    WHERE a.GINNumber = @pono AND CONVERT(DATE, a.[Date], 105) >= @fromdate AND CONVERT(DATE, a.[Date], 105) <= @todate

    UNION ALL

    --SIN Query
   SELECT
        a.[RefNumber] AS[PO Number],
        a.VendorCode,
        a.SupplierName AS[Vendor Name],
        V.GSTCode,
        '' AS[ProjectCode],
        a.BOMProjectCode,
        '' AS[Project Name],
        '' AS[Customer],
        '' AS[Project Status],
        a.[GINNumber],
        a.[SupplierInvoiceNumber] AS[Invoice Number],
        a.[ItemCode],
        b.ItemDescription,
        b.HSNSACCode,
        a.[Quantity],
        a.[UnitCost],
        (a.[Quantity] * a.[UnitCost]) AS Amount,
        ISNULL(a.[DiscRate], 0) AS[Disc %],
        ISNULL(a.[DiscAmount], 0) AS DiscAmount,
        (a.UnitCost * a.[Quantity]) AS TaxableAmount,
        ISNULL(a.[SGSTRate], 0) AS SGSTRate,
        ISNULL(a.[SGSTAmount], 0) AS SGSTAmount,
        ISNULL(a.[CGSTRate], 0) AS CGSTRate,
        ISNULL(a.[CGSTAmount], 0) AS CGSTAmount,
        ISNULL(a.[IGSTRate], 0) AS IGSTRate,
        ISNULL(a.[IGSTAmount], 0) AS IGSTAmount,
        0 AS[PackingForwarding],
        0 AS[PFIGSTRate],
        0 AS[PFIGSTAmount],
        0 AS[PFSGSTRate],
        0 AS[PFSGSTAmount],
        0 AS[PFCGSTRate],
        0 AS[PFCGSTAmount],
        0 AS[TransportationFreight],
        0 AS[TFIGSTRate],
        0 AS[TFIGSTAmount],
        0 AS[TFSGSTRate],
        0 AS[TFSGSTAmount],
        0 AS[TFCGSTRate],
        0 AS[TFCGSTAmount],
        0 AS[CDPercent],
        0 AS[CDValue],
        0 AS[CDIGSTRate],
        0 AS[CDIGSTAmount],
        0 AS[CDCessRate],
        0 AS[CDCessAmount],
        0 AS[TCSAmount],
        '' AS GrandTotal,
        '' AS[PO Generated Date],
        CONVERT(DATE, a.[Date], 105) AS[GIN Date],
        CONVERT(DATE, a.[InvoiceDate], 105) AS[Invoice Date],
        '' AS[Delivery Date],
        '' AS DeliveryMonitor,
        '0.0' AS Penalty,
        a.Ledger,
        'SIN' AS TransactionType
    FROM[Receipt] a
   JOIN[ItemMaster] b ON a.ItemCode = b.ItemCode
    JOIN Vendors V ON a.VendorCode = V.VendorCode
    WHERE a.GINNumber = @pono AND CONVERT(DATE, a.[Date], 105) >= @fromdate AND CONVERT(DATE, a.[Date], 105) <= @todate
    AND a.GINNumber LIKE 'ITWSIN%'
", SQLCon);

                    // Use parameterized queries to prevent SQL Injection
                    SQLCmd.Parameters.AddWithValue("@pono", pono);
                    SQLCmd.Parameters.AddWithValue("@fromdate", fromdate);
                    SQLCmd.Parameters.AddWithValue("@todate", todate);


                    //






                    //--------------------


                    //SQLCmd = new SqlCommand(@"select a.[RefNumber] as [PO Number],a.VendorCode,a.SupplierName as [Vendor Name], V.GSTCode,c.[ProjectCode],d.[ProjectDescription] as [Project Name],d.[Customer],
                    //                            d.Status as [Project Status],
                    //                             a.[GINNumber],a.[SupplierInvoiceNumber] as [Invoice Number],a.[ItemCode],b.ItemDescription,b.HSNSACCode,
                    //                            a.[Quantity],a.[UnitCost] ,(a.[Quantity] * a.[UnitCost]) as Amount,isnull(c.[DiscRate],0) as [Disc%],  
                    //                            (((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100) as DiscAmount,
                    //                            (((a.UnitCost*a.[Quantity])-(((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100))) as TaxableAmount, 
                    //                             isnull(c.[SGSTRate],0) as SGSTRate ,((((a.UnitCost*a.[Quantity])-(((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100)) *isnull(c.[SGSTRate],0))/100) as SGSTAmount ,
                    //                             isnull(c.[CGSTRate],0) as CGSTRate ,((((a.UnitCost*a.[Quantity])-(((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100)) *isnull(c.[CGSTRate],0))/100) as CGSTAmount ,
