-1)) end  AS DeliveryMonitor,Case When DATEDIFF(day,convert(date,c.WODeliveryDate,105),convert(date,a.[InvoiceDate],105))>0 then (DATEDIFF(day,convert(date,c.WODeliveryDate,105), convert(date,a.[InvoiceDate],105)) * 0.0071) * ((a.[Quantity] * a.[UnitCost])) else '0.0' end  AS Penalty,a.Ledger,'Work Order' as TransactionType FROM [Receipt] a join  [ItemMaster] b  on a.ItemCode=b.ItemCode join WorkOrder c on a.RefNumber=c.WONumber and a.ItemCode=c.OPItemCode  join [ProjectMaster] d on c.ProjectCode=d.ProjectCode join Vendors V on a.VendorCode=V.VendorCode where a.GINNumber='" + pono + "' and  convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "' union all select a.[RefNumber] as [PO Number],a.VendorCode,a.SupplierName as [Vendor Name], V.GSTCode,'' as [ProjectCode],'' as [Project Name],'' as [Customer],'' as [Project Status],a.[GINNumber],a.[SupplierInvoiceNumber] as [Invoice Number],a.[ItemCode],b.ItemDescription,b.HSNSACCode,a.[Quantity],a.[UnitCost] ,(a.[Quantity] * a.[UnitCost]) as Amount, isnull(a.[DiscRate],0) as [Disc%], isnull(a.[DiscAmount],0)  as DiscAmount, (a.UnitCost*a.[Quantity]) as TaxableAmount, isnull(a.[SGSTRate],0) as SGSTRate ,isnull(a.[SGSTAmount],0) as SGSTAmount , isnull(a.[CGSTRate],0) as CGSTRate ,isnull(a.[CGSTAmount],0) as CGSTAmount ,isnull(a.[IGSTRate],0) as IGSTRate,isnull(a.[IGSTAmount],0) as IGSTAmount , 0 as [PackingForwarding],0 as[PFIGSTRate] , 0 as[PFIGSTAmount],0 as[PFSGSTRate] , 0 as[PFSGSTAmount],0 as[PFCGSTRate] , 0 as[PFCGSTAmount],0 as [TransportationFreight],0 as[TFIGSTRate] , 0 as[TFIGSTAmount],0 as[TFSGSTRate] , 0 as[TFSGSTAmount],0 as[TFCGSTRate] , 0 as[TFCGSTAmount], 0 as [CDPercent],0 as[CDValue], 0 as[CDIGSTRate] , 0 as[CDIGSTAmount],0 as [CDCessRate],0 as CDCessAmount, 0 as [TCSAmount],'' as GrandTotal,'' as [PO Generated Date],convert(date,a.[Date],105) as [GIN Date] ,convert(date,a.[InvoiceDate],105) as [Invoice Date],'' as [Delivery Date],'' AS DeliveryMonitor,'0.0' AS Penalty,a.Ledger,'SIN' as TransactionType FROM [Receipt] a join  [ItemMaster] b  on a.ItemCode=b.ItemCode  join Vendors V on a.VendorCode=V.VendorCode where a.GINNumber='" + pono + "' and  convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "' and GINNumber like 'ITWSIN%'", SQLCon);
                }

                else if (Vendorname == null && pono != null && iSelect == 12)
                {
                    SQLCmd = new SqlCommand(@"select a.[RefNumber] as [PO Number],a.SupplierName as [Vendor Name], V.GSTCode,c.[ProjectCode],d.[ProjectDescription] as [Project Name],d.[Customer],d.Status as [Project Status],a.[GINNumber],a.[SupplierInvoiceNumber] as [Invoice Number],a.[ItemCode],b.ItemDescription,b.HSNSACCode,a.[Quantity],a.[UnitCost] ,(a.[Quantity] * a.[UnitCost]) as Amount, isnull(a.[DiscRate],0) as [Disc%], isnull(a.[DiscAmount],0)  as DiscAmount, (a.UnitCost*a.[Quantity]) as TaxableAmount, isnull(a.[SGSTRate],0) as SGSTRate ,isnull(a.[SGSTRate],0) as SGSTAmount , isnull(a.[CGSTRate],0) as CGSTRate ,isnull(a.[CGSTRate],0) as CGSTAmount ,isnull(a.[IGSTRate],0) as IGSTRate,isnull(a.[IGSTRate],0) as IGSTAmount , 0 as [PackingForwarding],0 as[PFIGSTRate] , 0 as[PFIGSTAmount],0 as[PFSGSTRate] , 0 as[PFSGSTAmount],0 as[PFCGSTRate] , 0 as[PFCGSTAmount],0 as [TransportationFreight],0 as[TFIGSTRate] , 0 as[TFIGSTAmount],0 as[TFSGSTRate] , 0 as[TFSGSTAmount],0 as[TFCGSTRate] , 0 as[TFCGSTAmount], 0 as [CDPercent],0 as[CDValue], 0 as[CDIGSTRate] , 0 as[CDIGSTAmount],0 as [CDCessRate],0 as CDCessAmount, 0 as [TCSAmount],'' as GrandTotal,convert(date,c.WOgeneratedDate,105) as [PO Generated Date],convert(date,a.[Date],105) as [GIN Date] ,convert(date,a.[InvoiceDate],105) as [Invoice Date],convert(date,c.WODeliveryDate,105) as [Delivery Date],a.DeliveryMonitor,a.Ledger,'Work Order' as TransactionType FROM [Receipt] a join  [ItemMaster] b  on a.ItemCode=b.ItemCode join WorkOrder c on a.RefNumber=c.WONumber and a.ItemCode=c.OPItemCode  join [ProjectMaster] d on c.ProjectCode=d.ProjectCode join Vendors V on a.VendorCode=V.VendorCode where a.GINNumber='" + pono + "' and  convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "'", SQLCon);
                }
                else if (Vendorname == null && pono == null && iSelect == 26)
                {
                    SQLCmd = new SqlCommand(" SET DATEFORMAT dmy;select [SupplierName],convert(date,[Date],105) as [Date]  FROM [Receipt] where convert(date,[Date],105) between '" + fromdate + "' and '" + todate + "' and SupplierName!='0' and [RefNumber] not like'WO/JW%' order by SupplierName asc", SQLCon);
                }

                else if (Vendorname != null && pono == null && iSelect == 26)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;select a.[RefNumber], a.[ItemCode],b.ItemDescription,a.[GINNumber],convert(date,a.[Date],105) as [Date] ,
                                            a.[SupplierInvoiceNumber],a.[Quantity],b.[UnitCost] ,(a.[Quantity]*b.[UnitCost]) as Amount,c.[ProjectCode],d.[ProjectDescription],
                                            d.[Customer],a.DeliveryMonitor FROM [Receipt] a join  [ItemMaster] b  on a.ItemCode=b.ItemCode join 
                                            [PurchaseOrder] c on a.RefNumber=c.[DBOMNo] and a.ItemCode=c.ItemCode  join [ProjectMaster] d on c.ProjectCode=d.ProjectCode 
                                            where a.[SupplierName]='" + Vendorname + "' and  convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "'and a.[RefNumber] not like'WO/JW%'", SQLCon);
                }
                else if (Vendorname == null && pono != null && iSelect == 26)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;select a.[RefNumber] as [PO Number],c.[ProjectCode],d.[ProjectDescription] as [Project Name],d.[Customer],
                                                REPLACE(REPLACE(REPLACE(c.ProjectStatus , 'WIP', 'WIP'), 'Shipped', 'Short Shipment'),'Installation completed','Warranty') [Project Status],
                                                 a.[GINNumber],a.[SupplierInvoiceNumber] as [Invoice Number],a.[ItemCode],b.ItemDescription,b.HSNSACCode,
                                                a.[Quantity],b.[UnitCost] ,(a.[Quantity] * b.[UnitCost]) as Amount,isnull(c.[DiscRate],0) as [Disc%],  
                                                (((b.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100) as DiscAmount,
                                                (((b.UnitCost*a.[Quantity])-(((b.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100))) as TaxableAmount, 
                                                 isnull(c.[SGSTRate],0) as SGSTRate ,((((b.UnitCost*a.[Quantity])-(((b.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100)) *isnull(c.[SGSTRate],0))/100) as SGSTAmount ,
                                                 isnull(c.[CGSTRate],0) as CGSTRate ,((((b.UnitCost*a.[Quantity])-(((b.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100)) *isnull(c.[CGSTRate],0))/100) as CGSTAmount ,
                                                 isnull(c.[IGSTRate],0) as IGSTRate,((((b.UnitCost*a.[Quantity])-(((b.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100)) *isnull(c.[IGSTRate],0))/100) as IGSTAmount ,
                                                 '' as [Packing/Forwarding],'' as [Transportation/Freight], '' as GrandTotal,convert(date,c.POGeneratedDate,105) as [POGeneratedDate],convert(date,a.[Date],105) as [Date] ,convert(date,a.[InvoiceDate],105) as [InvoiceDate],
                                                convert(date,c.PODeliveryDate,105) as [PODeliveryDate],a.DeliveryMonitor FROM [Receipt] a join  
                                                [ItemMaster] b  on a.ItemCode=b.ItemCode join [PurchaseOrder] c on a.RefNumber=c.[DBOMNo] and a.ItemCode=c.ItemCode  join [ProjectMaster] d on c.ProjectCode=d.ProjectCode 
                                            where a.GINNumber='" + pono + "' and  convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "' and a.[RefNumber] not like'WO/JW%'", SQLCon);
                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


        public DataSet GINCompletedPO(string VendorName, string pono, string fromdate, string todate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (VendorName == null && pono == null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;  select P.VendorCode,convert(date,P.POGeneratedDate,105) as POGeneratedDate,V.VendorName  FROM PurchaseOrder P join Vendors V on P.VendorCode=V.VendorCode
                                                 where convert(date,P.POGeneratedDate,105) between '" + fromdate + "' and '" + todate + "' and (P.[POGeneratedBy]!='' or P.POGeneratedBy is not null) and (P.AuthoriedBy IS NOT NULL and P.AuthoriedBy!='' and P.AuthoriedBy!='Deleted')", SQLCon);
                }
                else if (VendorName != null && pono == null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;  select P.[DBOMNo], P.VendorCode,convert(date,P.POGeneratedDate,105) as POGeneratedDate,V.VendorName  FROM PurchaseOrder P join Vendors V on P.VendorCode=V.VendorCode
                                                 where convert(date,P.POGeneratedDate,105) between '" + fromdate + "' and '" + todate + "' and  V.VendorName='" + VendorName + "' and (P.[POGeneratedBy]!='' or P.POGeneratedBy is not null) and (P.AuthoriedBy IS NOT NULL and P.AuthoriedBy!='' and P.AuthoriedBy!='Deleted')", SQLCon);
                }
                else if (VendorName == null && pono != null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;SELECT  TOP 1 P.[DBOMNo],P.[ProjectCode],PM.ProjectDescription,V.VendorName,P.[PreparedBy],P.[AuthoriedBy],convert(date,P.[POGeneratedDate],105) as [POGeneratedDate],
                                            P.[ItemCode],Im.ItemDescription,P.[UOM],P.[RequariedQty],P.[UnitPrice],P.[UnitPrice]*P.[RequariedQty] as [Amount] ,P.[POGeneratedBy],P.[Remarks]
                                             FROM [ERP_Database].[dbo].[PurchaseOrder] P join Itemmaster IM on P.ItemCode=IM.ItemCode join ProjectMaster PM on P.ProjectCode=PM.ProjectCode join Vendors V on P.VendorCode=V.VendorCode
                                            where  P.[DBOMNo]='" + pono + "' and convert(date,[POGeneratedDate],105)>= '" + fromdate + "' and  convert(date,[POGeneratedDate],105)<='" + todate + "' and AuthoriedBy!='Deleted' and  ([POGeneratedBy]!='' or POGeneratedBy is not null) and (AuthoriedBy IS NOT NULL and AuthoriedBy!='') order by [POGeneratedDate] asc", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet GINDepartmentWiseReport(int iCase, string fromdate, string todate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"select a.[RefNumber] as [PO Number],c.[ProjectCode],d.[ProjectDescription] as [Project Name],d.[Customer],
                                             a.[GINNumber],a.[SupplierInvoiceNumber] as [Invoice Number],convert(date,a.[Date],105) as [Date] ,a.[ItemCode],b.ItemDescription,
                                             a.[Quantity],a.[UnitCost] ,(a.[Quantity]*a.[UnitCost]) as Amount,a.DeliveryMonitor,a.SupplierName as VendorName,a.VendorCode,c.PreparedBy,L.Department FROM [Receipt] a join  
                                            [ItemMaster] b  on a.ItemCode=b.ItemCode  join [PurchaseOrder] c on a.RefNumber=c.[DBOMNo] and a.ItemCode=c.ItemCode join Login L on c.PreparedBy=L.UserName join [ProjectMaster] d on c.ProjectCode=d.ProjectCode where  convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "' and a.[RefNumber]  like'PO/%' union all select a.[RefNumber] as [PO Number], c.[ProjectCode], d.[ProjectDescription] as [Project Name], d.[Customer], a.[GINNumber], a.[SupplierInvoiceNumber] as [Invoice Number], convert(date, a.[Date], 105) as [Date], a.[ItemCode], b.ItemDescription, a.[Quantity], a.[UnitCost], (a.[Quantity] * a.[UnitCost]) as Amount, a.DeliveryMonitor, a.SupplierName as VendorName, a.VendorCode, c.PreparedBy, L.Department FROM[Receipt] a join [ItemMaster] b  on a.ItemCode = b.ItemCode  join WorkOrder c on a.RefNumber = c.WONumber and a.ItemCode = c.OPItemCode join Login L on c.PreparedBy = L.UserName join[ProjectMaster] d on c.ProjectCode = d.ProjectCode where  convert(date, a.[Date], 105) >= '" + fromdate + "' and  convert(date, a.[Date], 105) <= '" + todate + "' and a.[RefNumber]  like'WO/%' order by L.Department desc", SQLCon);
                        break;
                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

