        public DataSet ERPWARLogReport(int iCase, string fromdate, string todate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand(@"
                    WITH WARItems AS (
                        SELECT  
                            [TransactionLogID],
                            [TransactionNumber],
                            [TransactionBy],
                            [TransactionDate],
                            [Action],
                            [TableName],
                            [TransactionDateTime],

                            LEFT(
                                LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action))),
                                CHARINDEX(' ', LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action))) + ' ') - 1
                            ) AS WARCost,

                            LTRIM(
                                RIGHT(
                                    LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action))),
                                    LEN(LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action)))) - 
                                    CHARINDEX(' ', LTRIM(SUBSTRING(Action, LEN('Latest WAR Updated ') + 1, LEN(Action))) + ' ')
                                )
                            ) AS ItemCode
                        FROM 
                            [ERP_Database].[dbo].[ERPTransactionLog]
                        WHERE
                            Action LIKE 'Latest WAR Updated %'
                            AND CONVERT(date, TransactionDateTime, 105) >= @fromdate
                            AND CONVERT(date, TransactionDateTime, 105) <= @todate
                    )
                    SELECT * FROM WARItems
                    ORDER BY CONVERT(date, TransactionDateTime, 105) ASC
                ", SQLCon);

                        // Use parameters to avoid SQL injection
                        SQLCmd.Parameters.AddWithValue("@fromdate", fromdate);
                        SQLCmd.Parameters.AddWithValue("@todate", todate);
                        break;
                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


