        public DataSet GINJobReciept(string sProjectCode, string fromdate, string todate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sProjectCode == null && fromdate != null && todate != null)
                {
                    SQLCmd = new SqlCommand(@"  SET DATEFORMAT dmy;select a.[RefNumber],convert(date,a.[InvoiceDate],105) as [InvoiceDate], a.[ItemCode],b.ItemDescription,
                                                a.[Quantity],a.[UnitCost] ,((a.[Quantity]*a.[UnitCost])+(((a.UnitCost*a.[Quantity]) *isnull(W.[SGSTRate],0))/100)+(((a.UnitCost*a.[Quantity]) *isnull(W.[CGSTRate],0))/100)+(((a.UnitCost*a.[Quantity]) *isnull(W.[IGSTRate],0))/100)) as Amount,
                                                  isnull(W.[SGSTRate],0) as SGSTRate ,(((a.UnitCost*a.[Quantity]) *isnull(W.[SGSTRate],0))/100) as SGSTAmount ,
                                                  isnull(W.[CGSTRate],0) as CGSTRate ,(((a.UnitCost*a.[Quantity]) *isnull(W.[CGSTRate],0))/100) as CGSTAmount ,
                                                  isnull(W.[IGSTRate],0) as IGSTRate,(((a.UnitCost*a.[Quantity]) *isnull(W.[IGSTRate],0))/100) as IGSTAmount 
                                                 FROM [Receipt] a join  [ItemMaster] b  on a.ItemCode=b.ItemCode join WorkOrder W on a.RefNumber=W.WONumber and a.ItemCode=W.OPItemCode and w.OPItemCode=w.IPItemCode 
                                                where convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "' and [RefNumber]!='0' and [RefNumber] like'WO/JW%' order by convert(date,a.[InvoiceDate],105) asc", SQLCon);


                }
                else if (fromdate != null && todate != null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;select  a.[ItemCode],b.ItemDescription,b.HSNSACCode,a.[UnitCost],a.[Quantity],
                                            ((a.[Quantity]*a.[UnitCost])+(((a.UnitCost*a.[Quantity]) *isnull(W.[SGSTRate],0))/100)+(((a.UnitCost*a.[Quantity]) *isnull(W.[CGSTRate],0))/100)+(((a.UnitCost*a.[Quantity]) *isnull(W.[IGSTRate],0))/100)) as Amount,
                                                  w.PreparedBy as [WorkOrderBy],convert(date,a.[InvoiceDate],105) as [InvoiceDate],  a.[RefNumber],w.WorkDescription, isnull(W.[SGSTRate],0) as SGSTRate ,(((a.UnitCost*a.[Quantity]) *isnull(W.[SGSTRate],0))/100) as SGSTAmount ,
                                                  isnull(W.[CGSTRate],0) as CGSTRate ,(((a.UnitCost*a.[Quantity]) *isnull(W.[CGSTRate],0))/100) as CGSTAmount ,
                                                  isnull(W.[IGSTRate],0) as IGSTRate,(((a.UnitCost*a.[Quantity]) *isnull(W.[IGSTRate],0))/100) as IGSTAmount 
                                                 FROM [Receipt] a join  [ItemMaster] b  on a.ItemCode=b.ItemCode join WorkOrder W on a.RefNumber=W.WONumber and a.ItemCode=W.OPItemCode and w.OPItemCode=w.IPItemCode
                                                 where W.ProjectCode='" + sProjectCode + "' and convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "' and [RefNumber]!='0' and [RefNumber] like'WO/JW%'", SQLCon);
                }


                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet GINReportTablesVendorwise(string GinNumber, string pono, string fromdate, string todate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (GinNumber == null && pono != null)
                {
                    SQLCmd = new SqlCommand(@"SET DATEFORMAT dmy;select a.[RefNumber], a.[ItemCode],b.ItemDescription,a.[GINNumber],a.[SupplierInvoiceNumber],convert(date,a.[Date],105) as [GIN Date]
                                                ,convert(date,a.[InvoiceDate],105) as [InvoiceDate],a.[Quantity],a.[UnitCost] ,(a.[Quantity]*a.[UnitCost]) as Amount,
                                                isnull(c.[DiscRate],0) as [DiscRate],(((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100) as DiscAmount,
                                                (((a.UnitCost*a.[Quantity])-(((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100))) as TaxableAmount, 
                                                isnull(c.[SGSTRate],0) as SGSTRate ,((((a.UnitCost*a.[Quantity])-(((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100)) *isnull(c.[SGSTRate],0))/100) as SGSTAmount ,
                                                isnull(c.[CGSTRate],0) as CGSTRate ,((((a.UnitCost*a.[Quantity])-(((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100)) *isnull(c.[CGSTRate],0))/100) as CGSTAmount ,
                                                isnull(c.[IGSTRate],0) as IGSTRate,((((a.UnitCost*a.[Quantity])-(((a.UnitCost*a.[Quantity])* isnull(c.[DiscRate],0))/100)) *isnull(c.[IGSTRate],0))/100) as IGSTAmount ,
                                                '' as [Packing/Forwarding],'' as [Transportation/Freight], '' as GrandTotal,c.[ProjectCode],d.[ProjectDescription],d.[Customer],a.DeliveryMonitor
                                                FROM [Receipt] a join  [ItemMaster] b  on a.ItemCode=b.ItemCode join [PurchaseOrder] c on 
