                    SQLCmd = new SqlCommand("SET DATEFORMAT dmy;select a.[RefNumber], a.[ItemCode],b.ItemDescription,a.[GINNumber],convert(date,a.[Date],105) as [Date] ,a.[SupplierInvoiceNumber],a.[Quantity],a.[UnitCost] ,(a.[Quantity]*a.[UnitCost]) as Amount FROM [Receipt] a join  [ItemMaster] b  on a.ItemCode=b.ItemCode where a.GINNumber='" + GINNo + "' and  convert(date,a.[Date],105)>= '" + fromdate + "' and  convert(date,a.[Date],105)<='" + todate + "' and [RefNumber]!='0' and [RefNumber] like'WO/JW%'", SQLCon);

                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
