        public DataSet fnGINPOlistforview(int iCase, string GINNumber)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand("select GINNumber from [Receipt] group by GINNumber order by GINNumber desc ", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand("select Ledger,SupplierInvoiceNumber, convert(date,InvoiceDate,105) as InvoiceDate from Receipt where GINNumber='" + GINNumber + "'", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand("select Ledger from Receipt where GINNumber='" + GINNumber + "'", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand(@"SELECT R.[ItemCode], IM.ItemDescription,[Quantity],R.[UnitCost],([Quantity]*R.[UnitCost]) as Amount, [Quantity],R.[UnitCost],[SupplierName],[SupplierInvoiceNumber]
                                                ,[RefNumber],[IGSTRate],[IGSTAmount],[SGSTRate],[SGSTAmount],[CGSTRate],[CGSTAmount],TransportationFreight,[CDPercent],[CDValue],[CDIGSTRate],[CDIGSTAmount],[DiscRate],[DiscAmount],[CDCessRate],[CDCessAmount],[TCSAmount],[Currency],[FxRate]
                                                FROM [Receipt] R join ItemMaster IM on R.ItemCode=IM.ItemCode where GINNumber='" + GINNumber + "'", SQLCon);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand(@"Select top 1 'Packing & Forwarding' as [TaxDescription],[PackingForwarding],[PFIGSTRate],[PFSGSTRate],[PFCGSTRate]  FROM [Receipt] where GINNumber='" + GINNumber + "' union all Select top 1  'Transportation / Freight' as [TaxDescription],[TransportationFreight],[TFIGSTRate],[TFSGSTRate],[TFCGSTRate] FROM [Receipt] where GINNumber='" + GINNumber + "'", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }




        public int fnUpdateLedger(uint uInOrUPOrDel, string Ledger, string GINNumber, string InvoiceDate, string Itemcode)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (uInOrUPOrDel)
                {
                    case 0:
                        {
                            SQLCmd = new SqlCommand("Update [Receipt] set [Ledger]='" + Ledger + "' where  GINNumber='" + GINNumber + "' ", SQLCon);
                            break;
                        }
                    case 1:
                        {
                            SQLCmd = new SqlCommand("Insert into [GINLedgerNames] ([LedgerName],[AddedBy],[Status]) values('" + Ledger + "','" + GINNumber + "','1') ", SQLCon);
                            break;
                        }
                    case 2:
                        {
                            SQLCmd = new SqlCommand("Update [Receipt] set SupplierInvoiceNumber='" + Ledger + "',InvoiceDate='" + InvoiceDate + "' where  GINNumber='" + GINNumber + "' ", SQLCon);
                            break;
                        }

                    case 3:
                        {
                            SQLCmd = new SqlCommand("Update [Receipt] set CDPercent='" + Ledger + "',CDValue='" + InvoiceDate + "' where  GINNumber='" + GINNumber + "' and ItemCode='" + Itemcode + "' ", SQLCon);
                            break;

                        }

                    case 4:
                        {
                            SQLCmd = new SqlCommand("Update [Receipt] set CDIGSTRate='" + Ledger + "',CDIGSTAmount='" + InvoiceDate + "' where  GINNumber='" + GINNumber + "' and ItemCode='" + Itemcode + "'", SQLCon);
                            break;
                        }
                    case 5:
                        {
                            SQLCmd = new SqlCommand("Update [Receipt] set CDCessRate='" + Ledger + "',CDCessAmount='" + InvoiceDate + "' where  GINNumber='" + GINNumber + "' and ItemCode='" + Itemcode + "'", SQLCon);
                            break;
                        }


                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }
