        public DataSet fnPackingForwarding(string GINNumber, string sTaxName)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (GINNumber != null)
                {
                    if (sTaxName == "Packing & Forwarding")
                    {
                        SQLCmd = new SqlCommand(@"select    isnull([PackingForwarding],0) as [Packing/Forwarding],((COALESCE([PackingForwarding],0)+(COALESCE([PackingForwarding],0)*(COALESCE(PFIGSTRate,0)+COALESCE([PFSGSTRate],0)+COALESCE([PFCGSTRate],0)))/100)) as Amount
                                                ,isnull(PFIGSTRate,0) as[PFIGSTRate] , (isnull([PFIGSTRate],0)*isnull([PackingForwarding],0))/100 as[PFIGSTAmount]
                                                ,isnull(PFSGSTRate,0) as[PFSGSTRate] , (isnull([PFSGSTRate],0)*isnull([PackingForwarding],0))/100 as[PFSGSTAmount]
                                                ,isnull(PFCGSTRate,0) as[PFCGSTRate] , (isnull([PFCGSTRate],0)*isnull([PackingForwarding],0))/100 as[PFCGSTAmount]
                                                ,isnull([TransportationFreight],0)as [Transportation/Freight]
                                                ,isnull(TFIGSTRate,0) as[TFIGSTRate] , (isnull([TFIGSTRate],0)*isnull([TransportationFreight],0))/100 as[TFIGSTAmount]
                                                ,isnull(TFSGSTRate,0) as[TFSGSTRate] , (isnull([TFSGSTRate],0)*isnull([TransportationFreight],0))/100 as[TFSGSTAmount]
                                                ,isnull(TFCGSTRate,0) as[TFCGSTRate] , (isnull([TFCGSTRate],0)*isnull([TransportationFreight],0))/100 as[TFCGSTAmount],
                                                isnull([CDPercent],0) as [CDPercent],isnull([CDValue],0) as[CDValue],
                                                isnull([CDIGSTRate],0) as[CDIGSTRate] , isnull([CDIGSTAmount],0) as[CDIGSTAmount],isnull([CDCessRate],0) as [CDCessRate] ,
                                                isnull([CDCessAmount],0) as[CDCessAmount], isnull([TCSAmount],0) as [TCSAmount]  FROM [Receipt] where [GINNumber]='" + GINNumber + "'", SQLCon);
                    }
                    else if (sTaxName == "Transportation / Freight")
                    {
                        SQLCmd = new SqlCommand(@"select ((COALESCE(TransportationFreight,0)+(COALESCE([TransportationFreight],0)*(COALESCE([TFIGSTRate],0)+COALESCE([TFSGSTRate],0)+COALESCE([TFCGSTRate],0)))/100)) 
                                                as Amount FROM [Receipt] where [GINNumber]='" + GINNumber + "'", SQLCon);

                    }

                }
                // else
                //   SQLCmd = new SqlCommand(" select * FROM GinTax order by id desc", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

