                    SQLCmd = new SqlCommand(@"select  b.ItemCode,b.[Quantity]as RecievedQty,'' as IssuedQty,'' as ReturnQty,''as StockAdjsued,(b.[UnitCost] - b.[UnitCost]* (COALESCE(b.[DiscRate], 0)/100)) as Unitcost,((b.[UnitCost] - b.[UnitCost]* (COALESCE(b.[DiscRate], 0)/100))*b.Quantity) as Amount,d.Projectcode as ProjectCode, p.ProjectDescription as ProjectName,p.Customer,b.GINNumber as RefNumber,CONVERT(date,(b.date),105) as date ,d.PreparedBy as [User] from Receipt b join PurchaseOrder d on b.ItemCode=d.ItemCode and b.RefNumber=d.DBOMNo join ProjectMaster p on d.ProjectCode=p.ProjectCode where b.ItemCode ='" + sRepeatedItem + "' union all select DISTINCT b.ItemCode,b.[Quantity]as RecievedQty,'' as IssuedQty,'' as ReturnQty,''as StockAdjsued,b.UnitCost as UnitCost,(b.UnitCost*b.Quantity) as Amount,w.Projectcode as ProjectCode, p.ProjectDescription as ProjectName,p.Customer,b.GINNumber as RefNumber,CONVERT(date,(b.date),105) as date,w.PreparedBy from Receipt b join WorkOrder w on b.ItemCode=w.OPItemCode and b.RefNumber=w.WONumber join ProjectMaster p on w.ProjectCode=p.ProjectCode where b.ItemCode ='" + sRepeatedItem + "' union all select DISTINCT Item_Code,'' as RecievedQty,c.IssuedQuantity as IssuedQty,'' as ReturnQty,''as StockAdjsued ,'' as UnitCost ,'' as Amount,c.Project_Code  as ProjectCode,p2.ProjectDescription as ProjectName,p2.Customer, c.Indent_Number as RefNumber, CONVERT(date,(c.Issue_Date ),105) as Date,c.IndentBy from [Issued] c join ProjectMaster p2 on c.Project_Code=p2.ProjectCode where Item_Code='" + sRepeatedItem + "' union all select DISTINCT IR.ItemCode,'' as ReturnQty,'' as IssuedQty,IR.Quantity as ReturnQty,''as StockAdjsued,'' as UnitCost,'' as Amount,IR.Projectcode as ProjectCode, PM.ProjectDescription as ProjectName,PM.Customer, 'Item Reurn' as RefNumber,CONVERT(date,(IR.date),105) as date,IR.ReturnedBy from ItemReturn IR join ProjectMaster PM on IR.ProjectCode=PM.ProjectCode where IR.ItemCode='" + sRepeatedItem + "' union all select DISTINCT IRJ.ItemCode,'' as ReturnQty,'' as IssuedQty,IRJ.Quantity as ReturnQty,''as StockAdjsued,'' as UnitCost,'' as Amount,IRJ.Projectcode as ProjectCode, PM.ProjectDescription as ProjectName,PM.Customer,'Item Reurn Job Issued' as RefNumber,CONVERT(date,(IRJ.date),105) as date,IRJ.ReturnedBy from ItemReturnJobIssued IRJ join ProjectMaster PM on IRJ.ProjectCode=PM.ProjectCode where IRJ.ItemCode='" + sRepeatedItem + "' union all select DISTINCT JI.ItemCode,'' as RecievedQty,JI.IssuedQuantity as IssuedQty,'' as ReturnQty,''as StockAdjsued ,'' as UnitCost ,'' as Amount,W.ProjectCode as ProjectCode,PM.ProjectDescription as ProjectName,PM.Customer, JI.WONumber as RefNumber, CONVERT(date,(JI.IssueDate ),105) as Date,w.PreparedBy  from JobIssue JI join workorder W on JI.WONumber=W.WONumber join ProjectMaster PM on W.ProjectCode=PM.ProjectCode where JI.ItemCode='" + sRepeatedItem + "' and w.IPItemCode='" + sRepeatedItem + "' union all select DISTINCT b.ItemCode,'' as RecievedQty,'' as IssuedQty,'' as ReturnQty,b.[Quantity] as StockAdjsued,b.UnitCost as UnitCost,'' as Amount,'' as ProjectCode, '' as ProjectName,'' as Customer,b.GINNumber as RefNumber,CONVERT(date,(b.date),105) as date ,'' as [User] from Receipt b where b.ItemCode ='" + sRepeatedItem + "' and b.Type='Stock Adjusted'  union all select DISTINCT b.ItemCode,(b.ReturnQty *-1) as RecievedQty,'' as IssuedQty,'' as ReturnQty,'' as StockAdjsued,b.UnitCost as UnitCost,(b.ReturnQty *-1* b.UnitCost) as Amount,''as ProjectCode, 'Reverse GIN' as ProjectName,'' as Customer,b.GINNumber as RefNumber,CONVERT(date,(b.ReverseGINDate),105) as date ,'' as [User] from RiverseGIN b where b.ItemCode ='" + sRepeatedItem + "'", SQLCon);


                else if (sRepeatedItem != null && fromdate != null && todate != null)
                    /*
                    SQLCmd = new SqlCommand(@"select b.[Quantity]as RecievedQty,'' as IssuedQty,'' as ReturnQty,''as StockAdjsued,b.UnitCost as UnitCost,(b.UnitCost*b.Quantity) as Amount,
                                                    d.Projectcode as ProjectCode, p.ProjectDescription as ProjectName,p.Customer,b.GINNumber as RefNumber,CONVERT(date,(b.date),105) as date,d.PreparedBy as [User] from Receipt
                                                    b join PurchaseOrder d on b.ItemCode=d.ItemCode and b.RefNumber=d.DBOMNo join ProjectMaster p on d.ProjectCode=p.ProjectCode 
                                                    where b.ItemCode ='" + sRepeatedItem + "' and convert(date,[date] ,105)  between'" + fromdate + "' and '" + todate + "' union all select b.[Quantity]as RecievedQty,'' as IssuedQty,'' as ReturnQty,''as StockAdjsued,b.UnitCost as UnitCost,(b.UnitCost*b.Quantity) as Amount,w.Projectcode as ProjectCode, p.ProjectDescription as ProjectName,p.Customer,b.GINNumber as RefNumber,CONVERT(date,(b.date),105) as date,w.PreparedBy from Receipt b join WorkOrder w on b.ItemCode=w.OPItemCode and b.RefNumber=w.WONumber join ProjectMaster p on w.ProjectCode=p.ProjectCode where b.ItemCode ='" + sRepeatedItem + "' and convert(date,[date] ,105)  between'" + fromdate + "' and '" + todate + "'   union all select '' as RecievedQty,c.IssuedQuantity as IssuedQty,'' as ReturnQty,''as StockAdjsued ,'' as UnitCost ,'' as Amount,c.Project_Code  as ProjectCode,p2.ProjectDescription as ProjectName,p2.Customer,c.Indent_Number as RefNumber, CONVERT(date,(c.Issue_Date ),105) as Date,c.IndentBy  from [Issued] c join ProjectMaster p2 on c.Project_Code=p2.ProjectCode where Item_Code='" + sRepeatedItem + "' and convert(date,c.IndentDate ,105)  between'" + fromdate + "' and '" + todate + "' union all select '' as ReturnQty1,'' as IssuedQty,IR.Quantity as ReturnQty,''as StockAdjsued,'' as UnitCost,'' as Amount,IR.Projectcode as ProjectCode, PM.ProjectDescription as ProjectName,PM.Customer,'Item Reurn' as RefNumber,CONVERT(date,(IR.date),105) as date,IR.ReturnedBy from ItemReturn IR join ProjectMaster PM on IR.ProjectCode=PM.ProjectCode where IR.ItemCode='" + sRepeatedItem + "' and convert(date,IR.Date ,105)  between'" + fromdate + "' and '" + todate + "' union all select '' as ReturnQty1,'' as IssuedQty,IRJ.Quantity as ReturnQty,''as StockAdjsued,'' as UnitCost,'' as Amount,IRJ.Projectcode as ProjectCode, PM.ProjectDescription as ProjectName,PM.Customer,'Item Reurn Job Issued' as RefNumber,CONVERT(date,(IRJ.date),105) as date,IRJ.ReturnedBy from ItemReturnJobIssued IRJ join ProjectMaster PM on IRJ.ProjectCode=PM.ProjectCode where IRJ.ItemCode='" + sRepeatedItem + "' and convert(date,IRJ.Date ,105)  between'" + fromdate + "' and '" + todate + "' union all select '' as RecievedQty,JI.IssuedQuantity as IssuedQty,'' as ReturnQty ,''as StockAdjsued,'' as UnitCost ,'' as Amount,W.ProjectCode as ProjectCode,PM.ProjectDescription as ProjectName,PM.Customer,JI.WONumber as RefNumber, CONVERT(date,(JI.IssueDate ),105) as Date,w.PreparedBy  from JobIssue JI join workorder W on JI.WONumber=W.WONumber join ProjectMaster PM on W.ProjectCode=PM.ProjectCode where JI.ItemCode='" + sRepeatedItem + "' and w.IPItemCode='" + sRepeatedItem + "' and convert(date,JI.IssueDate ,105)  between'" + fromdate + "' and '" + todate + "'  union all select '' as RecievedQty,'' as IssuedQty,'' as ReturnQty,b.[Quantity] as StockAdjsued,b.UnitCost as UnitCost,'' as Amount,'' as ProjectCode, '' as ProjectName,'' as Customer,b.GINNumber as RefNumber,CONVERT(date,(b.date),105) as date ,'' as [User] from Receipt b where b.ItemCode ='" + sRepeatedItem + "' and b.Type='Stock Adjusted' and convert(date,[date] ,105)  between'" + fromdate + "' and '" + todate + "' union all select (b.ReturnQty *-1) as RecievedQty,'' as IssuedQty,'' as ReturnQty,'' as StockAdjsued,b.UnitCost as UnitCost,'' as Amount,''as ProjectCode, 'Reverse GIN' as ProjectName,'' as Customer,b.GINNumber as RefNumber,CONVERT(date,(b.ReverseGINDate),105) as date ,'' as [User] from RiverseGIN b where b.ItemCode ='" + sRepeatedItem + "'  and convert(date,[ReverseGINDate] ,105) between'" + fromdate + "' and '" + todate + "' order by date asc", SQLCon);
                */
                    SQLCmd = new SqlCommand(@"select DISTINCT b.[Quantity]as RecievedQty,'' as IssuedQty,'' as ReturnQty,''as StockAdjsued,b.UnitCost as UnitCost,(b.UnitCost * b.Quantity) as Amount,d.Projectcode as ProjectCode, p.ProjectDescription as ProjectName,p.Customer,b.GINNumber as RefNumber,CONVERT(date, (b.date), 105) as date,d.PreparedBy as [User] from Receipt b join PurchaseOrder d on b.ItemCode = d.ItemCode and b.RefNumber = d.DBOMNo join ProjectMaster p on d.ProjectCode = p.ProjectCode where b.ItemCode = '" + sRepeatedItem + "' and convert(date, [date] ,105)  between'" + fromdate + "' and '" + todate + "' union all select DISTINCT b.[Quantity] as RecievedQty,'' as IssuedQty,'' as ReturnQty, '' as StockAdjsued,b.UnitCost as UnitCost,(b.UnitCost * b.Quantity) as Amount,w.Projectcode as ProjectCode, p.ProjectDescription as ProjectName,p.Customer,b.GINNumber as RefNumber,CONVERT(date, (b.date), 105) as date,w.PreparedBy from Receipt b join WorkOrder w on b.ItemCode = w.OPItemCode and b.RefNumber = w.WONumber join ProjectMaster p on w.ProjectCode = p.ProjectCode where b.ItemCode = '" + sRepeatedItem + "' and convert(date, [date] ,105)  between'" + fromdate + "' and '" + todate + "' union all select DISTINCT '' as RecievedQty,c.IssuedQuantity as IssuedQty, '' as ReturnQty,'' as StockAdjsued ,'' as UnitCost ,'' as Amount,c.Project_Code as ProjectCode,p2.ProjectDescription as ProjectName,p2.Customer,c.Indent_Number as RefNumber, CONVERT(date, (c.Issue_Date), 105) as Date,c.IndentBy from[Issued] c join ProjectMaster p2 on c.Project_Code = p2.ProjectCode where Item_Code = '" + sRepeatedItem + "' and convert(date, c.IndentDate ,105)  between'" + fromdate + "' and '" + todate + "' union all select DISTINCT '' as ReturnQty1,'' as IssuedQty,IR.Quantity as ReturnQty,'' as StockAdjsued, '' as UnitCost,'' as Amount,IR.Projectcode as ProjectCode, PM.ProjectDescription as ProjectName,PM.Customer,'Item Reurn' as RefNumber,CONVERT(date, (IR.date), 105) as date,IR.ReturnedBy from ItemReturn IR join ProjectMaster PM on IR.ProjectCode = PM.ProjectCode where IR.ItemCode = '" + sRepeatedItem + "' and convert(date, IR.Date ,105)  between'" + fromdate + "' and '" + todate + "' union all select DISTINCT '' as ReturnQty1,'' as IssuedQty,IRJ.Quantity as ReturnQty,'' as StockAdjsued,'' as UnitCost,'' as Amount,IRJ.Projectcode as ProjectCode, PM.ProjectDescription as ProjectName,PM.Customer,'Item Reurn Job Issued' as RefNumber,CONVERT(date, (IRJ.date), 105) as date,IRJ.ReturnedBy from ItemReturnJobIssued IRJ join ProjectMaster PM on IRJ.ProjectCode = PM.ProjectCode where IRJ.ItemCode = '" + sRepeatedItem + "' and convert(date, IRJ.Date ,105)  between'" + fromdate + "' and '" + todate + "' union all select DISTINCT '' as RecievedQty,JI.IssuedQuantity as IssuedQty,'' as ReturnQty ,'' as StockAdjsued, '' as UnitCost ,'' as Amount,W.ProjectCode as ProjectCode,PM.ProjectDescription as ProjectName,PM.Customer,JI.WONumber as RefNumber, CONVERT(date, (JI.IssueDate), 105) as Date,w.PreparedBy from JobIssue JI join workorder W on JI.WONumber = W.WONumber join ProjectMaster PM on W.ProjectCode = PM.ProjectCode where JI.ItemCode = '" + sRepeatedItem + "' and w.IPItemCode = '" + sRepeatedItem + "' and convert(date, JI.IssueDate ,105)  between'" + fromdate + "' and '" + todate + "' union all select DISTINCT '' as RecievedQty,'' as IssuedQty,'' as ReturnQty,b.[Quantity] as StockAdjsued,b.UnitCost as UnitCost,'' as Amount,'' as ProjectCode, '' as ProjectName,'' as Customer,b.GINNumber as RefNumber,CONVERT(date, (b.date), 105) as date ,'' as [User] from Receipt b where b.ItemCode = '" + sRepeatedItem + "' and b.Type = 'Stock Adjusted' and convert(date, [date] ,105)  between'" + fromdate + "' and '" + todate + "' union all select DISTINCT(b.ReturnQty*-1) as RecievedQty,'' as IssuedQty,'' as ReturnQty,'' as StockAdjsued,b.UnitCost as UnitCost,'' as Amount,'' as ProjectCode, 'Reverse GIN' as ProjectName,'' as Customer,b.GINNumber as RefNumber,CONVERT(date, (b.ReverseGINDate), 105) as date ,'' as [User] from RiverseGIN b where b.ItemCode = '" + sRepeatedItem + "' and convert(date, [ReverseGINDate] ,105) between'" + fromdate + "' and '" + todate + "' order by date asc", SQLCon);
                else if (sRepeatedItem == null && fromdate != null && todate != null)

                    SQLCmd = new SqlCommand(@"select  ItemCode,ItemDescription, OpeningQuantity, AvailableQty,0 as RecievedQty,0 as IssuedQty, 0 as JobIssuedQty,0 as IssueReturnQty,
                                                0 as JobIssueReturnQty,0 as StockAdjsued,0.0 as ClosingQuantity, UnitCost,(UnitCost*AvailableQty) as Amount from ItemMaster union all
                                                select  R.ItemCode,IM.ItemDescription,0 as OpeningQuantity,0as AvailableQty,R.[Quantity]as RecievedQty,0 as IssuedQty, 
                                                0 as JobIssuedQty,0 as IssueReturnQty,0 as JobIssueReturnQty,0 as StockAdjsued,0 as ClosingQuantity,IM.UnitCost as UnitCost,
                                                (IM.UnitCost*R.Quantity) as Amount from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode join PurchaseOrder d on R.ItemCode=d.ItemCode and R.RefNumber=d.DBOMNo 
                                                where R.Type='Boughtout' and convert(date,R.[date] ,105)  between'" + fromdate + "' and '" + todate + "' union all select  R.ItemCode,IM.ItemDescription,0 as OpeningQuantity,0as AvailableQty,R.[Quantity]as RecievedQty,0 as IssuedQty, 0 as JobIssuedQty,0 as IssueReturnQty,0 as JobIssueReturnQty,0 as StockAdjsued,0 as ClosingQuantity,IM.UnitCost as UnitCost,(IM.UnitCost*R.Quantity) as Amount from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode join WorkOrder w on R.ItemCode=w.OPItemCode and R.RefNumber=w.WONumber where (R.Type='Boughtout' or R.Type='Jobwork')  and convert(date,R.[date] ,105)  between'" + fromdate + "' and '" + todate + "'  union all select  IM.ItemCode,IM.ItemDescription,0 as OpeningQuantity,0 as AvailableQty,0 as RecievedQty,C.IssuedQuantity as IssuedQty,0 as JobIssuedQty,0 as IssueReturnQty,0 as JobIssueReturnQty,0 as StockAdjsued,0 as ClosingQuantity,IM.UnitCost as UnitCost ,(IM.UnitCost*C.IssuedQuantity) as Amount from [Issued] c join  ItemMaster IM on c.Item_Code=IM.ItemCode where convert(date,c.Issue_Date ,105)  between'" + fromdate + "' and '" + todate + "' union all select  IM.ItemCode,IM.ItemDescription,0 as OpeningQuantity,0 as AvailableQty,0 as RecievedQty,0 as IssuedQty,JI.IssuedQuantity as JobIssuedQty, 0 as ReturnQty, 0 as JobIssueReturnQty,0 as StockAdjsued,0 as ClosingQuantity,IM.UnitCost as UnitCost ,(IM.UnitCost*JI.IssuedQuantity) as Amount from JobIssue JI join ItemMaster IM on JI.ItemCode=IM.ItemCode where convert(date,JI.IssueDate ,105)  between'" + fromdate + "' and '" + todate + "' union all select  IM.ItemCode,IM.ItemDescription,0 as OpeningQuantity,0 as AvailableQty,0as RecievedQty,0 as IssuedQty, 0 as JobIssuedQty, IR.Quantity as ReturnQty,0 as JobIssueReturnQty,0 as StockAdjsued,0 as ClosingQuantity,IM.UnitCost as UnitCost ,(IM.UnitCost* IR.Quantity) as Amount from ItemReturn IR join ItemMaster IM on IR.ItemCode=IM.ItemCode where convert(date,IR.Date ,105) between'" + fromdate + "' and '" + todate + "' union all select  IM.ItemCode,IM.ItemDescription,0 as OpeningQuantity,0 as AvailableQty,0 as RecievedQty,0 as IssuedQty, 0 as JobIssuedQty,0 as ReturnQty, IRJ.Quantity as JobIssueReturnQty,0 as StockAdjsued,0 as ClosingQuantity,IM.UnitCost as UnitCost ,(IM.UnitCost*IRJ.Quantity) as Amount from ItemReturnJobIssued IRJ join ItemMaster IM on IRJ.ItemCode=IM.ItemCode where convert(date,IRJ.Date ,105)  between'" + fromdate + "' and '" + todate + "' union all select  R.ItemCode,IM.ItemDescription,0 as OpeningQuantity,0 as AvailableQty,0 as RecievedQty,0 as IssuedQty, 0 as JobIssuedQty,0 as IssueReturnQty,0 as JobIssueReturnQty,R.[Quantity]as StockAdjsued,0 as ClosingQuantity,IM.UnitCost as UnitCost,(IM.UnitCost*R.Quantity) as Amount from Receipt R join ItemMaster IM on R.ItemCode=IM.ItemCode  where R.Type='Stock Adjusted' and convert(date,R.[date] ,105)  between'" + fromdate + "' and '" + todate + "' union all select  R.ItemCode,IM.ItemDescription,0 as OpeningQuantity,0 as AvailableQty,(ReturnQty *-1)as RecievedQty,0 as IssuedQty, 0 as JobIssuedQty,0 as IssueReturnQty,0 as JobIssueReturnQty,0 as StockAdjsued,0 as ClosingQuantity,IM.UnitCost as UnitCost,(IM.UnitCost*R.Quantity) as Amount from RiverseGIN R join ItemMaster IM on R.ItemCode=IM.ItemCode  where  convert(date,R.ReverseGINDate ,105) between'" + fromdate + "' and '" + todate + "'", SQLCon);

                if (sRepeatedItem != null && fromdate != null && todate == null)
                    SQLCmd = new SqlCommand(@"select DISTINCT ItemCode,OpeningQuantity from ItemMaster where ItemCode ='" + sRepeatedItem + "'", SQLCon);

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnInventoryLedgerItem(string sRepeatedItem, string fromdate, string todate)
        {
            // MessageBox.Show(fromdate, todate);
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();

                SQLCmd = new SqlCommand($@"/*  Stock-card with WAR valuation - CORRECTED with Net Available Qty (Receipts - Issues - Returns)  */
                                                SET DATEFORMAT dmy;

                                                DECLARE @SelectedDate DATE = '{fromdate}';  -- Change this to your parameter
                                                DECLARE @ItemCode VARCHAR(50) = '{sRepeatedItem}';

                                                ;WITH
                                                /* --------------------------- 0) PRE-CALCULATE INITIAL VALUES BASED ON SELECTED DATE --------------------------- */
                                                -- Get the LAST receipt unit cost on or before selected date (for initial WAR)
                                                LastReceiptBeforeDate AS (
                                                    SELECT TOP 1 
                                                        LandedUnitPrice,
                                                        GINServerDate,
                                                        [Date]
                                                    FROM (
                                                        SELECT 
                                                            b.*,
                                                            DateNorm = REPLACE(LTRIM(RTRIM(b.[Date])),'/','-'),
                                                            GINServerDate_ = CASE
                                                                               WHEN ISDATE(b.GINServerDate) = 1
                                                                                 THEN CAST(CONVERT(datetime, b.GINServerDate, 121) AS datetime2(3))
                                                                               ELSE NULL
                                                                             END,
                                                            -- Calculate LandedUnitPrice same as in your query
                                                            LandedUnitPrice = CAST(
                                                                (SUM(UnitCost * Quantity) OVER (PARTITION BY CONVERT(date, REPLACE(LTRIM(RTRIM(b.[Date])),'/','-'), 105), GINNumber)
                                                                 + SUM(ISNULL(CDValue,0)) OVER (PARTITION BY CONVERT(date, REPLACE(LTRIM(RTRIM(b.[Date])),'/','-'), 105), GINNumber)
                                                                 + SUM(ISNULL(TransportationFreight,0)) OVER (PARTITION BY CONVERT(date, REPLACE(LTRIM(RTRIM(b.[Date])),'/','-'), 105), GINNumber)
                                                                 + SUM(ISNULL(PackingForwarding,0)) OVER (PARTITION BY CONVERT(date, REPLACE(LTRIM(RTRIM(b.[Date])),'/','-'), 105), GINNumber)
                                                                ) / NULLIF(SUM(Quantity) OVER (PARTITION BY CONVERT(date, REPLACE(LTRIM(RTRIM(b.[Date])),'/','-'), 105), GINNumber),0) 
                                                                AS decimal(38,6)
                                                            )
                                                        FROM dbo.Receipt b
                                                        WHERE b.ItemCode = @ItemCode
                                                          AND LTRIM(RTRIM(ISNULL(b.[Date], ''))) <> ''
                                                          AND ISDATE(REPLACE(LTRIM(RTRIM(b.[Date])),'/','-')) = 1
                                                    ) sub
                                                    WHERE CONVERT(date, DateNorm, 105) <= @SelectedDate
                                                    ORDER BY GINServerDate_ DESC, [Date] DESC
                                                ),

                                                -- Calculate NET available quantity from FIRST receipt up to selected date
                                                -- Formula: Total Receipts - Total Issues - Total Returns (before selected date)
                                                ReceiptsUpToDate AS (
                                                    SELECT 
                                                        -- Total Receipts
                                                        (SELECT ISNULL(SUM(Quantity), 0) 
                                                         FROM dbo.Receipt b
                                                         WHERE b.ItemCode = @ItemCode
                                                           AND LTRIM(RTRIM(ISNULL(b.[Date], ''))) <> ''
                                                           AND ISDATE(REPLACE(LTRIM(RTRIM(b.[Date])),'/','-')) = 1
                                                           AND CONVERT(date, REPLACE(LTRIM(RTRIM(b.[Date])),'/','-'), 105) <= @SelectedDate
                                                        )
                                                        -
                                                        -- Total Issues (from dbo.Issued)
                                                        (SELECT ISNULL(SUM(IssuedQuantity), 0)
                                                         FROM dbo.Issued c
                                                         WHERE c.Item_Code = @ItemCode
                                                           AND CONVERT(date, c.Issue_Date, 105) <= @SelectedDate
                                                        )
                                                        -
                                                        -- Total Job Issues (from dbo.JobIssue)
                                                        (SELECT ISNULL(SUM(issuedQuantity), 0)
                                                         FROM dbo.JobIssue JI
                                                         WHERE JI.ItemCode = @ItemCode
                                                           AND CONVERT(date, JI.IssueDate, 105) <= @SelectedDate
                                                        )
                                                        -
                                                        -- Total Item Returns (from dbo.ItemReturn) - these ADD to stock, so subtract the negative
                                                        (SELECT ISNULL(SUM(-IR.Quantity), 0)
                                                         FROM dbo.ItemReturn IR
                                                         WHERE IR.ItemCode = @ItemCode
                                                           AND CONVERT(date, IR.[Date], 105) <= @SelectedDate
                                                        )
                                                        -
                                                        -- Total Item Return Job Issued (from dbo.ItemReturnJobIssued) - these ADD to stock
                                                        (SELECT ISNULL(SUM(-IRJ.Quantity), 0)
                                                         FROM dbo.ItemReturnJobIssued IRJ
                                                         WHERE IRJ.ItemCode = @ItemCode
                                                           AND CONVERT(date, IRJ.[Date], 105) <= @SelectedDate
                                                        )
                                                        AS TotalNetQty
                                                ),

                                                -- Store initial values in single row CTE for cross join
                                                InitialValues AS (
                                                    SELECT 
                                                        ISNULL((SELECT TotalNetQty FROM ReceiptsUpToDate), 0) AS InitialQty,
                                                        ISNULL((SELECT LandedUnitPrice FROM LastReceiptBeforeDate), 0) AS InitialWAR
                                                ),

                                                /* --------------------------- 1) Clean & aggregate RECEIPTS --------------------------- */
                                                Receipts_Clean AS
                                                (
                                                    SELECT
                                                        b.*,
                                                        DateNorm = REPLACE(LTRIM(RTRIM(b.[Date])),'/','-'),
                                                        GINServerDate_ = CASE
                                                                           WHEN ISDATE(b.GINServerDate) = 1
                                                                             THEN CAST(CONVERT(datetime, b.GINServerDate, 121) AS datetime2(3))
                                                                           ELSE NULL
                                                                         END
                                                    FROM dbo.Receipt b
                                                    WHERE b.ItemCode = @ItemCode
                                                      AND LTRIM(RTRIM(ISNULL(b.[Date], ''))) <> ''
                                                      AND ISDATE(REPLACE(LTRIM(RTRIM(b.[Date])),'/','-')) = 1
                                                ),
                                                Receipts_Agg AS
                                                (
                                                    SELECT
                                                        TxnDate       = CONVERT(date, DateNorm, 105),
                                                        GINServerDate = CAST(MIN(GINServerDate_) AS datetime2(3)),
                                                        ItemCode,
                                                        GINNumber,
                                                        AnyRefNumber  = MAX(RefNumber),

                                                        TotalQty          = SUM(Quantity),
                                                        SumBaseExtended   = SUM(UnitCost * Quantity),
                                                        SumCD             = SUM(ISNULL(CDValue,0)),
                                                        SumFreight        = SUM(ISNULL(TransportationFreight,0)),
                                                        SumPF             = SUM(ISNULL(PackingForwarding,0)),

                                                        BaseUnitCost   = CAST(SUM(UnitCost * Quantity) / NULLIF(SUM(Quantity),0) AS decimal(38,6)),
                                                        CDPerUnit      = CAST(SUM(ISNULL(CDValue,0)) / NULLIF(SUM(Quantity),0) AS decimal(38,6)),
                                                        FreightPerUnit = CAST(SUM(ISNULL(TransportationFreight,0)) / NULLIF(SUM(Quantity),0) AS decimal(38,6)),
                                                        PFPerUnit      = CAST(SUM(ISNULL(PackingForwarding,0)) / NULLIF(SUM(Quantity),0) AS decimal(38,6)),

                                                        LandedValue = CAST(
                                                            (SUM(UnitCost * Quantity)
                                                             + SUM(ISNULL(CDValue,0))
                                                             + SUM(ISNULL(TransportationFreight,0))
                                                             + SUM(ISNULL(PackingForwarding,0))) AS decimal(38,6)
                                                        ),
                                                        LandedUnitPrice = CAST(
                                                            (SUM(UnitCost * Quantity)
                                                             + SUM(ISNULL(CDValue,0))
                                                             + SUM(ISNULL(TransportationFreight,0))
                                                             + SUM(ISNULL(PackingForwarding,0))) / NULLIF(SUM(Quantity),0) AS decimal(38,6)
                                                        )
                                                    FROM Receipts_Clean
                                                    GROUP BY CONVERT(date, DateNorm, 105), ItemCode, GINNumber
                                                ),

                                                /* --------------------------- 2) Build each transaction set WITH initial value columns --------------------------- */
                                                PO_Receipts AS
                                                (
                                                    SELECT
                                                        ra.TxnDate                                           AS [Date],
                                                        ra.GINServerDate                                     AS [GINServerDate],
                                                        ra.ItemCode                                          AS ItemCode,
                                                        CAST(ra.TotalQty AS decimal(38,6))                   AS RecievedQty,
                                                        CAST(0 AS decimal(38,6))                             AS IssuedQty,
                                                        CAST(0 AS decimal(38,6))                             AS ReturnQty,
                                                        CAST(0 AS decimal(38,6))                             AS StockAdjsued,
                                                        CAST(ra.LandedUnitPrice AS decimal(38,6))            AS LandedUnit,
                                                        CAST(ra.LandedValue AS decimal(38,6))                AS LandedAmount,
                                                        ra.GINNumber                                         AS RefNumber,
                                                        d.PreparedBy                                         AS [User],
                                                        CAST(ra.BaseUnitCost AS decimal(38,6))               AS BasePrice,
                                                        CAST(ra.CDPerUnit AS decimal(38,6))                  AS CD,
                                                        CAST(ra.FreightPerUnit AS decimal(38,6))             AS Freight,
                                                        CAST(ra.PFPerUnit AS decimal(38,6))                  AS [Packing Frowarding],
                                                        'WAREHOUSE'                                          AS [Transaction Location],
                                                        'RECEIPT'                                            AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS InitialQty,
                                                        CAST(0 AS decimal(38,6)) AS InitialWAR
                                                    FROM Receipts_Agg ra
                                                    JOIN dbo.PurchaseOrder d
                                                      ON d.ItemCode = ra.ItemCode
                                                     AND d.DBOMNo   = ra.AnyRefNumber
                                                ),
                                                WO_Receipts AS
                                                (
                                                    SELECT
                                                        ra.TxnDate                                           AS [Date],
                                                        ra.GINServerDate                                     AS [GINServerDate],
                                                        ra.ItemCode                                          AS ItemCode,
                                                        CAST(ra.TotalQty AS decimal(38,6))                   AS RecievedQty,
                                                        CAST(0 AS decimal(38,6))                             AS IssuedQty,
                                                        CAST(0 AS decimal(38,6))                             AS ReturnQty,
                                                        CAST(0 AS decimal(38,6))                             AS StockAdjsued,
                                                        CAST(ra.LandedUnitPrice AS decimal(38,6))            AS LandedUnit,
                                                        CAST(ra.LandedValue AS decimal(38,6))                AS LandedAmount,
                                                        ra.GINNumber                                         AS RefNumber,
                                                        w.PreparedBy                                         AS [User],
                                                        CAST(ra.BaseUnitCost AS decimal(38,6))               AS BasePrice,
                                                        CAST(ra.CDPerUnit AS decimal(38,6))                  AS CD,
                                                        CAST(ra.FreightPerUnit AS decimal(38,6))             AS Freight,
                                                        CAST(ra.PFPerUnit AS decimal(38,6))                  AS [Packing Frowarding],
                                                        'WAREHOUSE'                                          AS [Transaction Location],
                                                        'RECEIPT'                                            AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS InitialQty,
                                                        CAST(0 AS decimal(38,6)) AS InitialWAR
                                                    FROM Receipts_Agg ra
                                                    JOIN dbo.WorkOrder w
                                                      ON w.OPItemCode = ra.ItemCode
                                                     AND w.WONumber   = ra.AnyRefNumber
                                                ),
                                                Issue_Trans AS
                                                (
                                                    SELECT
                                                        CONVERT(date, c.Issue_Date, 105)                     AS [Date],
                                                        CAST(
                                                            COALESCE(
                                                              CAST(c.IssuedServerDate AS datetime2(3)),
                                                              CONVERT(datetime2(3), CONVERT(datetime, c.Issue_Date, 105), 3)
                                                            ) AS datetime2(3)
                                                        )                                                    AS [GINServerDate],
                                                        c.Item_Code                                          AS ItemCode,
                                                        CAST(0 AS decimal(38,6))                             AS RecievedQty,
                                                        CAST(c.IssuedQuantity AS decimal(38,6))              AS IssuedQty,
                                                        CAST(0 AS decimal(38,6))                             AS ReturnQty,
                                                        CAST(0 AS decimal(38,6))                             AS StockAdjsued,
                                                        CAST(NULL AS decimal(38,6))                          AS LandedUnit,
                                                        CAST(0 AS decimal(38,6))                             AS LandedAmount,
                                                        c.Indent_Number                                      AS RefNumber,
                                                        c.IndentBy                                           AS [User],
                                                        CAST(NULL AS decimal(38,6))                          AS BasePrice,
                                                        CAST(NULL AS decimal(38,6))                          AS CD,
                                                        CAST(NULL AS decimal(38,6))                          AS Freight,
                                                        CAST(NULL AS decimal(38,6))                          AS [Packing Frowarding],
                                                        c.Project_Code                                       AS [Transaction Location],
                                                        'ISSUE'                                              AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS InitialQty,
                                                        CAST(0 AS decimal(38,6)) AS InitialWAR
                                                    FROM dbo.Issued c
                                                    WHERE c.Item_Code = @ItemCode
                                                ),
                                                IR_Trans AS
                                                (
                                                    SELECT
                                                        CONVERT(date, IR.[Date], 105)                        AS [Date],
                                                        CAST(CONVERT(datetime, IR.[Date], 105) AS datetime2(3)) AS [GINServerDate],
                                                        IR.ItemCode                                          AS ItemCode,
                                                        CAST(0 AS decimal(38,6))                             AS RecievedQty,
                                                        CAST(0 AS decimal(38,6))                             AS IssuedQty,
                                                        CAST(IR.Quantity AS decimal(38,6))                   AS ReturnQty,
                                                        CAST(0 AS decimal(38,6))                             AS StockAdjsued,
                                                        CAST(NULL AS decimal(38,6))                          AS LandedUnit,
                                                        CAST(0 AS decimal(38,6))                             AS LandedAmount,
                                                        'Item Return'                                        AS RefNumber,
                                                        IR.ReturnedBy                                        AS [User],
                                                        CAST(NULL AS decimal(38,6))                          AS BasePrice,
                                                        CAST(NULL AS decimal(38,6))                          AS CD,
                                                        CAST(NULL AS decimal(38,6))                          AS Freight,
                                                        CAST(NULL AS decimal(38,6))                          AS [Packing Frowarding],
                                                        'WAREHOUSE'                                          AS [Transaction Location],
                                                        'RETURN'                                             AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS InitialQty,
                                                        CAST(0 AS decimal(38,6)) AS InitialWAR
                                                    FROM dbo.ItemReturn IR
                                                    WHERE IR.ItemCode = @ItemCode
                                                ),
                                                IRJ_Trans AS
                                                (
                                                    SELECT
                                                        CONVERT(date, IRJ.[Date], 105)                       AS [Date],
                                                        CAST(CONVERT(datetime, IRJ.[Date], 105) AS datetime2(3)) AS [GINServerDate],
                                                        IRJ.ItemCode                                         AS ItemCode,
                                                        CAST(0 AS decimal(38,6))                             AS RecievedQty,
                                                        CAST(0 AS decimal(38,6))                             AS IssuedQty,
                                                        CAST(IRJ.Quantity AS decimal(38,6))                  AS ReturnQty,
                                                        CAST(0 AS decimal(38,6))                             AS StockAdjsued,
                                                        CAST(NULL AS decimal(38,6))                          AS LandedUnit,
                                                        CAST(0 AS decimal(38,6))                             AS LandedAmount,
                                                        'Item Return Job Issued'                             AS RefNumber,
                                                        IRJ.ReturnedBy                                       AS [User],
                                                        CAST(NULL AS decimal(38,6))                          AS BasePrice,
                                                        CAST(NULL AS decimal(38,6))                          AS CD,
                                                        CAST(NULL AS decimal(38,6))                          AS Freight,
                                                        CAST(NULL AS decimal(38,6))                          AS [Packing Frowarding],
                                                        'WAREHOUSE'                                          AS [Transaction Location],
                                                        'RETURN'                                             AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS InitialQty,
                                                        CAST(0 AS decimal(38,6)) AS InitialWAR
                                                    FROM dbo.ItemReturnJobIssued IRJ
                                                    WHERE IRJ.ItemCode = @ItemCode
                                                ),
                                                JI_Trans AS
                                                (
                                                    SELECT
                                                        CONVERT(date, JI.IssueDate, 105)                     AS [Date],
                                                        CAST(CONVERT(datetime, JI.IssueDate, 105) AS datetime2(3)) AS [GINServerDate],
                                                        JI.ItemCode                                          AS ItemCode,
                                                        CAST(0 AS decimal(38,6))                             AS RecievedQty,
                                                        CAST(JI.issuedQuantity AS decimal(38,6))             AS IssuedQty,
                                                        CAST(0 AS decimal(38,6))                             AS ReturnQty,
                                                        CAST(0 AS decimal(38,6))                             AS StockAdjsued,
                                                        CAST(NULL AS decimal(38,6))                          AS LandedUnit,
                                                        CAST(0 AS decimal(38,6))                             AS LandedAmount,
                                                        JI.WONumber                                          AS RefNumber,
                                                        w.PreparedBy                                         AS [User],
                                                        CAST(NULL AS decimal(38,6))                          AS BasePrice,
                                                        CAST(NULL AS decimal(38,6))                          AS CD,
                                                        CAST(NULL AS decimal(38,6))                          AS Freight,
                                                        CAST(NULL AS decimal(38,6))                          AS [Packing Frowarding],
                                                        'PRODUCTION'                                         AS [Transaction Location],
                                                        'ISSUE'                                              AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS InitialQty,
                                                        CAST(0 AS decimal(38,6)) AS InitialWAR
                                                    FROM dbo.JobIssue JI
                                                    JOIN dbo.WorkOrder w
                                                      ON w.WONumber = JI.WONumber
                                                    WHERE JI.ItemCode = @ItemCode
                                                      AND w.IPItemCode = @ItemCode
                                                ),
                                                StockAdj_Trans AS
                                                (
                                                    SELECT
                                                        CONVERT(date, rc.DateNorm, 105)                      AS [Date],
                                                        CAST(MIN(rc.GINServerDate_) AS datetime2(3))         AS [GINServerDate],
                                                        rc.ItemCode                                          AS ItemCode,
                                                        CAST(0 AS decimal(38,6))                             AS RecievedQty,
                                                        CAST(0 AS decimal(38,6))                             AS IssuedQty,
                                                        CAST(0 AS decimal(38,6))                             AS ReturnQty,
                                                        CAST(SUM(rc.Quantity) AS decimal(38,6))              AS StockAdjsued,
                                                        CAST(NULL AS decimal(38,6))                          AS LandedUnit,
                                                        CAST(0 AS decimal(38,6))                             AS LandedAmount,
                                                        rc.GINNumber                                         AS RefNumber,
                                                        ''                                                   AS [User],
                                                        CAST(MAX(rc.UnitCost) AS decimal(38,6))              AS BasePrice,
                                                        CAST(MAX(ISNULL(rc.CDValue,0)) AS decimal(38,6))     AS CD,
                                                        CAST(MAX(ISNULL(rc.TransportationFreight,0)) AS decimal(38,6)) AS Freight,
                                                        CAST(MAX(ISNULL(rc.PackingForwarding,0)) AS decimal(38,6))     AS [Packing Frowarding],
                                                        'WAREHOUSE'                                          AS [Transaction Location],
                                                        'ADJUST'                                             AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS InitialQty,
                                                        CAST(0 AS decimal(38,6)) AS InitialWAR
                                                    FROM Receipts_Clean rc
                                                    WHERE rc.Type = 'Stock Adjusted'
                                                    GROUP BY CONVERT(date, rc.DateNorm, 105), rc.ItemCode, rc.GINNumber
                                                ),
                                                RevGIN_Trans AS
                                                (
                                                    SELECT
                                                        CONVERT(date, RG.ReverseGINDate, 105)                        AS [Date],
                                                        CAST(CONVERT(datetime, RG.ReverseGINDate, 105) AS datetime2(3)) AS [GINServerDate],
                                                        RG.ItemCode                                                  AS ItemCode,
                                                        CAST(-RG.ReturnQty AS decimal(38,6))                         AS RecievedQty,
                                                        CAST(0 AS decimal(38,6))                                     AS IssuedQty,
                                                        CAST(0 AS decimal(38,6))                                     AS ReturnQty,
                                                        CAST(0 AS decimal(38,6))                                     AS StockAdjsued,
                                                        CAST(RG.UnitCost AS decimal(38,6))                           AS LandedUnit,
                                                        CAST(-RG.ReturnQty * RG.UnitCost AS decimal(38,6))           AS LandedAmount,
                                                        RG.GINNumber                                                 AS RefNumber,
                                                        ''                                                           AS [User],
                                                        CAST(RG.UnitCost AS decimal(38,6))                           AS BasePrice,
                                                        CAST(NULL AS decimal(38,6))                                  AS CD,
                                                        CAST(NULL AS decimal(38,6))                                  AS Freight,
                                                        CAST(NULL AS decimal(38,6))                                  AS [Packing Frowarding],
                                                        'WAREHOUSE'                                                  AS [Transaction Location],
                                                        'REVGIN'                                                     AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS InitialQty,
                                                        CAST(0 AS decimal(38,6)) AS InitialWAR
                                                    FROM dbo.RiverseGIN RG
                                                    WHERE RG.ItemCode = @ItemCode
                                                ),

                                                /* --------------------------- 3) Combine to one ordered stream --------------------------- */
                                                AllTrans AS
                                                (
                                                    SELECT * FROM PO_Receipts
                                                    UNION ALL SELECT * FROM WO_Receipts
                                                    UNION ALL SELECT * FROM Issue_Trans
                                                    UNION ALL SELECT * FROM IR_Trans
                                                    UNION ALL SELECT * FROM IRJ_Trans
                                                    UNION ALL SELECT * FROM JI_Trans
                                                    UNION ALL SELECT * FROM StockAdj_Trans
                                                    UNION ALL SELECT * FROM RevGIN_Trans
                                                ),

                                                /* --------------------------- 4) ADD INITIAL ROW FOR SELECTED DATE --------------------------- */
                                                Numbered AS
                                                (
                                                    SELECT
                                                        ROW_NUMBER() OVER (ORDER BY [GINServerDate], [Date], RefNumber, TransType) AS rn,
                                                        [Date],
                                                        [GINServerDate],
                                                        ItemCode,
                                                        RecievedQty,
                                                        IssuedQty,
                                                        ReturnQty,
                                                        StockAdjsued,
                                                        LandedUnit,
                                                        LandedAmount,
                                                        RefNumber,
                                                        [User],
                                                        BasePrice,
                                                        CD,
                                                        Freight,
                                                        [Packing Frowarding],
                                                        [Transaction Location],
                                                        TransType,
                                                        (ISNULL(RecievedQty,0) - ISNULL(IssuedQty,0) + ISNULL(ReturnQty,0) + ISNULL(StockAdjsued,0)) AS TransQty,
                                                        InitialQty,
                                                        InitialWAR,
                                                        CAST(0 AS bit) AS IsOpeningBalance
                                                    FROM AllTrans
                                                    WHERE [Date] >= @SelectedDate
                                                ),

                                                -- Create opening balance row with initial values from pre-calculated CTEs
                                                InitialBalance AS (
                                                    SELECT 
                                                        0 AS rn,
                                                        @SelectedDate AS [Date],
                                                        CAST(@SelectedDate AS datetime2(3)) AS [GINServerDate],
                                                        @ItemCode AS ItemCode,
                                                        CAST(0 AS decimal(38,6)) AS RecievedQty,
                                                        CAST(0 AS decimal(38,6)) AS IssuedQty,
                                                        CAST(0 AS decimal(38,6)) AS ReturnQty,
                                                        CAST(0 AS decimal(38,6)) AS StockAdjsued,
                                                        CAST(0 AS decimal(38,6)) AS LandedUnit,
                                                        CAST(0 AS decimal(38,6)) AS LandedAmount,
                                                        'OPENING BALANCE' AS RefNumber,
                                                        'SYSTEM' AS [User],
                                                        CAST(0 AS decimal(38,6)) AS BasePrice,
                                                        CAST(0 AS decimal(38,6)) AS CD,
                                                        CAST(0 AS decimal(38,6)) AS Freight,
                                                        CAST(0 AS decimal(38,6)) AS [Packing Frowarding],
                                                        'WAREHOUSE' AS [Transaction Location],
                                                        'OPENING' AS TransType,
                                                        CAST(0 AS decimal(38,6)) AS TransQty,
                                                        -- Get initial values from pre-calculated CTEs (NET available qty)
                                                        CAST(iv.InitialQty AS decimal(38,6)) AS InitialQty,
                                                        CAST(iv.InitialWAR AS decimal(38,6)) AS InitialWAR,
                                                        CAST(1 AS bit) AS IsOpeningBalance
                                                    FROM InitialValues iv
                                                ),

                                                -- Combine numbered transactions with opening balance
                                                AllNumbered AS (
                                                    SELECT * FROM Numbered
                                                    UNION ALL
                                                    SELECT * FROM InitialBalance
                                                ),

                                                -- Renumber to ensure opening balance is first
                                                FinalNumbered AS (
                                                    SELECT 
                                                        ROW_NUMBER() OVER (ORDER BY rn) AS rn,
                                                        [Date], [GINServerDate], ItemCode, RecievedQty, IssuedQty, ReturnQty, StockAdjsued,
                                                        LandedUnit, LandedAmount, RefNumber, [User], BasePrice, CD, Freight, [Packing Frowarding],
                                                        [Transaction Location], TransType, TransQty, InitialQty, InitialWAR, IsOpeningBalance
                                                    FROM AllNumbered
                                                ),

                                                /* --------------------------- 5) WAR engine (recursive) --------------------------- */
                                                WAR_Calc AS
                                                (
                                                    -- Anchor: Opening Balance row with initial values
                                                    SELECT
                                                        n.rn, n.[Date], n.[GINServerDate], n.ItemCode, n.RefNumber, n.[User],
                                                        n.RecievedQty, n.IssuedQty, n.ReturnQty, n.StockAdjsued,
                                                        n.BasePrice, n.CD, n.Freight, n.[Packing Frowarding],
                                                        n.[Transaction Location], n.TransType,
                                                        n.TransQty,

                                                        CAST(0.0 AS decimal(38,6)) AS PrevQty,
                                                        CAST(0.0 AS decimal(38,6)) AS PrevValue,
                                                        CAST(0.0 AS decimal(38,6)) AS PrevWAR,

                                                        CAST(0 AS decimal(38,6)) AS TransAmount_WAR,

                                                        -- Initial NET available quantity from pre-calculated value
                                                        n.InitialQty AS AfterQty,
        
                                                        -- Initial value = InitialQty * InitialWAR
                                                        CAST(n.InitialQty * n.InitialWAR AS decimal(38,6)) AS AfterValue,

                                                        -- Post WAR = InitialWAR
                                                        n.InitialWAR AS PostWAR,
        
                                                        n.IsOpeningBalance
                                                    FROM FinalNumbered n
                                                    WHERE n.rn = 1  -- Opening balance row (now rn=1 after renumbering)

                                                    UNION ALL

                                                    -- Recursive: All subsequent transactions
                                                    SELECT
                                                        n.rn, n.[Date], n.[GINServerDate], n.ItemCode, n.RefNumber, n.[User],
                                                        n.RecievedQty, n.IssuedQty, n.ReturnQty, n.StockAdjsued,
                                                        n.BasePrice, n.CD, n.Freight, n.[Packing Frowarding],
                                                        n.[Transaction Location], n.TransType,
                                                        n.TransQty,

                                                        w.AfterQty AS PrevQty,
                                                        w.AfterValue AS PrevValue,
                                                        CAST(CASE WHEN w.AfterQty <> 0 THEN w.AfterValue / w.AfterQty ELSE 0 END AS decimal(38,6)) AS PrevWAR,

                                                        CAST(
                                                            CASE
                                                              WHEN n.TransType IN ('RECEIPT','REVGIN') THEN ISNULL(n.LandedAmount,0)
                                                              WHEN n.TransType = 'ISSUE'               THEN - ISNULL(n.IssuedQty,0)    * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                              WHEN n.TransType = 'RETURN'              THEN   ISNULL(n.ReturnQty,0)    * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                              WHEN n.TransType = 'ADJUST'              THEN   ISNULL(n.StockAdjsued,0) * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                              ELSE 0
                                                            END AS decimal(38,6)
                                                        ) AS TransAmount_WAR,

                                                        CAST(w.AfterQty + n.TransQty AS decimal(38,6)) AS AfterQty,
                                                        CAST(w.AfterValue + (
                                                            CASE
                                                              WHEN n.TransType IN ('RECEIPT','REVGIN') THEN ISNULL(n.LandedAmount,0)
                                                              WHEN n.TransType = 'ISSUE'               THEN - ISNULL(n.IssuedQty,0)    * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                              WHEN n.TransType = 'RETURN'              THEN   ISNULL(n.ReturnQty,0)    * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                              WHEN n.TransType = 'ADJUST'              THEN   ISNULL(n.StockAdjsued,0) * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                              ELSE 0
                                                            END
                                                        ) AS decimal(38,6)) AS AfterValue,

                                                        CAST(
                                                            CASE
                                                              WHEN (w.AfterQty + n.TransQty) <> 0
                                                              THEN (w.AfterValue + (
                                                                        CASE
                                                                          WHEN n.TransType IN ('RECEIPT','REVGIN') THEN ISNULL(n.LandedAmount,0)
                                                                          WHEN n.TransType = 'ISSUE'               THEN - ISNULL(n.IssuedQty,0)    * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                                          WHEN n.TransType = 'RETURN'              THEN   ISNULL(n.ReturnQty,0)    * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                                          WHEN n.TransType = 'ADJUST'              THEN   ISNULL(n.StockAdjsued,0) * (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                                          ELSE 0
                                                                        END
                                                                   )) / NULLIF(w.AfterQty + n.TransQty,0)
                                                              ELSE (CASE WHEN w.AfterQty<>0 THEN w.AfterValue/w.AfterQty ELSE 0 END)
                                                            END AS decimal(38,6)
                                                        ) AS PostWAR,
        
                                                        n.IsOpeningBalance
                                                    FROM FinalNumbered n
                                                    INNER JOIN WAR_Calc w
                                                      ON n.rn = w.rn + 1
                                                )

                                                /* --------------------------- 6) Final output --------------------------- */
                                                SELECT
                                                   -- w.[Date],
                                                   w.[GINServerDate] as [Date],
                                                    --CONVERT(varchar(19), w.[GINServerDate], 120) AS GINServerDateText,
                                                    --w.ItemCode,
                                                    w.RecievedQty,
                                                    w.IssuedQty,
                                                    w.ReturnQty,
                                                    w.StockAdjsued,

                                                    /* WAR unit cost */
                                                    CAST(
                                                        CASE
                                                          WHEN w.IsOpeningBalance = 1 THEN w.PostWAR
                                                          WHEN w.TransType IN ('RECEIPT','REVGIN') THEN w.PostWAR
                                                          ELSE w.PrevWAR
                                                        END AS decimal(18,6)
                                                    ) AS UnitCost,

                                                    /* Transaction valuation at WAR */
                                                    CAST(w.TransAmount_WAR AS decimal(18,2)) AS Amount,

                                                    /* WAR-based running balances */
                                                    CAST(w.AfterQty   AS decimal(18,6)) AS [Closing Qty],
                                                    CAST(w.AfterValue AS decimal(18,2)) AS [Closing Value],
    
                                                    /* Show Initial Available Qty and Initial WAR Cost for reference */
                                                   -- CAST(
                                                   --     CASE 
                                                     ----       WHEN w.IsOpeningBalance = 1 THEN w.AfterQty 
                                                      --      ELSE NULL 
                                                     --   END AS decimal(18,6)
                                                   -- ) AS [Initial Available Qty],
    
                                                   -- CAST(
                                                       -- CASE 
                                                        ----    WHEN w.IsOpeningBalance = 1 THEN w.PostWAR 
                                                         --   ELSE NULL 
                                                       -- END AS decimal(18,6)
                                                   -- ) AS [Initial WAR Cost],

                                                    w.RefNumber,
                                                    --w.[Date] AS [date],
                                                    w.[User],
                                                    w.BasePrice,
                                                    w.CD,
                                                    w.Freight,
                                                    w.[Packing Frowarding],
                                                    w.[Transaction Location]
                                                   -- w.TransType,
                                                   -- w.IsOpeningBalance
                                                FROM WAR_Calc w where  w.[Date] <= '{todate}'
                                                ORDER BY w.[GINServerDate] ASC, w.[Date] ASC, w.RefNumber DESC
                                                OPTION (MAXRECURSION 32767);", SQLCon);

                SQLCmd.CommandTimeout = 0;
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnKanBanMaterialLedger(int iCase, string sRepeatedItem, string fromdate, string todate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (iCase)
                {
                    case 1:
