        public DataSet fnTransactionalspenddata(string sFromDate, string sTodate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sFromDate == null && sTodate == null)
                    SQLCmd = new SqlCommand("Select * from Vendors  order by VendorName asc", SQLCon);
                else
                    SQLCmd = new SqlCommand(@"set dateformat dmy; select 'BANINT' as [FRIDA Code] , a.[SupplierInvoiceNumber],convert(date,a.[date] ,105)as [Invoice Date],b.VendorCode ,a.[SupplierName],b.[Address1],b.[Address2]
                                              ,b.[Address3],b.District as [Supplier City],b.PinCode,b.Country ,a.[Quantity],c.Units ,a.unitcost as [UnitCost],[Total Amount]=(a.[Quantity]*a.unitcost),'INR'as [Local Currency],
	                                          a.itemcode as [ItemCode],c.ItemDescription from Receipt a join Vendors b on a.VendorCode= b.VendorCode  join ItemMaster c on a.itemcode=c.itemcode
	                                          where a.[Type]!='Stock Adjusted' and RefNumber like 'po%'  and convert(date,a.[Date],105) between '" + sFromDate + "' and '" + sTodate + "' order by SupplierName asc", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


        public DataSet fnApSpenddata(string sFromDate, string sTodate)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sFromDate == null && sTodate == null)
                    SQLCmd = new SqlCommand("Select * from Vendors  order by VendorName asc", SQLCon);
                else
                    SQLCmd = new SqlCommand(@"set dateformat dmy;  select 'BANINT'as [FRIDA CODE], VendorCode,[SupplierName],Address1,Address2,Address3,[Supplier City],[Supplier ZIP/ Post Code],
	                                        [Supplier State/Providence],[Supplier Country],sum(m) as  [Annual Spend (Purchases)],'INR'as[Local Currency],count(c)as NoofPO  from
                                            (select b.[VendorCode],a.SupplierName,b.Address1,b.Address2,b.Address3,b.District as [Supplier City],b.PinCode as [Supplier ZIP/ Post Code] 
	                                        ,b.State as[Supplier State/Providence],b.country as[Supplier Country],sum(a.[Quantity]*a.unitcost) as m,count(a.[RefNumber]) as c
	                                        from [Receipt] a join [Vendors] b on a.VendorCode= b.VendorCode 
	                                        where a.[Type]!='Stock Adjusted' and a.RefNumber like 'po%'  and convert(date,a.[Date],105) between '" + sFromDate + "' and '" + sTodate + "' group by b.vendorcode,a.[SupplierName],b.Address1,b.Address2,b.Address3,b.District,b.PinCode,b.State,b.country,a.[RefNumber]) sam group by VendorCode,[SupplierName],Address1,Address2,Address3,[Supplier City],[Supplier ZIP/ Post Code],[Supplier State/Providence],[Supplier Country] order by  LEFT(VendorCode, PATINDEX('%[0-9]%', VendorCode)-1),CONVERT(INT, SUBSTRING(VendorCode, PATINDEX('%[0-9]%', VendorCode), LEN(VendorCode)))", SQLCon);
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


