        public int fnAddPOPackingForward(uint uInORUpORDel, string sPONo, string sTaxDescription, double IGSTRate, double IGSTAmount, double SGSTRate, double SGSTAmount, double CGSTRate, double CGSTAmount, double Amount)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (uInORUpORDel)
                {
                    case Global.uINSERT:
                        {
                            SQLCmd = new SqlCommand("Insert into POPackingForwarding ([PONo],[TaxDescription],[IGSTRate],[IGSTAmount],[SGSTRate],[SGSTAmount],[CGSTRate],[CGSTAmount],Amount)Values('" + sPONo + "','" + sTaxDescription + "','" + IGSTRate + "','" + IGSTAmount + "','" + SGSTRate + "','" + SGSTAmount + "','" + CGSTRate + "','" + CGSTAmount + "','" + Amount + "')", SQLCon);
                            break;
                        }
                    case Global.uUPDATE:
                        {
                            if (sTaxDescription == "Packing & Forwarding")
                            {
                                SQLCmd = new SqlCommand("Update POPackingForwarding set IGSTRate='" + IGSTRate + "',IGSTAmount='" + IGSTAmount + "',SGSTRate='" + SGSTRate + "',SGSTAmount='" + SGSTAmount + "',CGSTRate='" + CGSTRate + "',CGSTAmount='" + CGSTAmount + "',Amount='" + Amount + "' where PONo='" + sPONo + "' and TaxDescription='" + sTaxDescription + "'", SQLCon);
                            }
                            else if (sTaxDescription == "Transportation / Freight")
                            {
                                SQLCmd = new SqlCommand("Update POPackingForwarding set IGSTRate='" + IGSTRate + "',IGSTAmount='" + IGSTAmount + "',SGSTRate='" + SGSTRate + "',SGSTAmount='" + SGSTAmount + "',CGSTRate='" + CGSTRate + "',CGSTAmount='" + CGSTAmount + "',Amount='" + Amount + "' where PONo='" + sPONo + "' and TaxDescription='" + sTaxDescription + "'", SQLCon);
                            }
                            break;
                        }
                    case Global.uDELETE:
                        {
                            if (sTaxDescription == "Packing & Forwarding")
                            {
                                SQLCmd = new SqlCommand("Delete from POPackingForwarding where PONo='" + sPONo + "' and TaxDescription='" + sTaxDescription + "'", SQLCon);
                            }
                            else if (sTaxDescription == "Transportation / Freight")
                            {
                                SQLCmd = new SqlCommand("Delete from POPackingForwarding where PONo='" + sPONo + "' and TaxDescription='" + sTaxDescription + "'", SQLCon);
                            }
                            break;
                        }
                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;

            }
        }


