        public DataSet fnElectronicsProductMaster(int iCase, string NodeID)
        {
            SQLDataset = new DataSet();
            try
            {
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:

                        SQLCmd = new SqlCommand("SELECT * FROM KBELProductTree where NodeID= '" + NodeID + "'", SQLCon);
                        break;

                    case 1:
                        SQLCmd = new SqlCommand(@"SELECT KT.[ItemCode],KFI.ItemDescription
                                            ,KT.[Quantity],KFI.UnitCost,(KT.[Quantity]*KFI.UnitCost) as Amount,KFI.AvailableQty,0.0 as RequiredQty, 0.0 as Diffrence
                                            FROM [KBELTreeItems] KT JOIN KanBanElectronicsItemMaster KFI on KT.ItemCode=KFI.ItemCode  where ParentID= '" + NodeID + "' order by (KT.[Quantity]*KFI.UnitCost) desc", SQLCon);
                        break;

                    case 11:
                        SQLCmd = new SqlCommand(@"SELECT KT.[ItemCode],KFI.ItemDescription
                                            ,KT.[Quantity],KFI.UnitCost,(KT.[Quantity]*KFI.UnitCost) as Amount,KFI.AvailableQty,0.0 as RequiredQty, 0.0 as Diffrence
                                            FROM [KBELTreeItems] KT JOIN KanBanElectronicsFinishedItemMaster KFI on KT.ItemCode=KFI.ItemCode  where ParentID= '" + NodeID + "' order by (KT.[Quantity]*KFI.UnitCost) desc", SQLCon);
                        break;
                    case 12:
                        SQLCmd = new SqlCommand(@"SELECT KT.[ItemCode],KFI.ItemDescription
                                            ,KT.[Quantity],KFI.UnitCost,(KT.[Quantity]*KFI.UnitCost) as Amount,KFI.AvailableQty,0.0 as RequiredQty, 0.0 as Diffrence
                                            FROM [KBELTreeItems] KT JOIN KanBanItemMaster KFI on KT.ItemCode=KFI.ItemCode  where ParentID= '" + NodeID + "' order by (KT.[Quantity]*KFI.UnitCost) desc", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand(@"SELECT KT.[ItemCode],KFI.ItemDescription,KFI.Units
                                            ,KFI.UnitCost,KFI.AvailableQty,KT.[Quantity]
                                            FROM [KBELTreeItems] KT JOIN KanBanElectronicsItemMaster KFI on KT.ItemCode=KFI.ItemCode  where ParentID= '" + NodeID + "' order by (KT.[Quantity]*KFI.UnitCost) desc", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand(@"SELECT KT.[ItemCode],KFI.ItemDescription,KFI.Units
                                           ,KFI.AvailableQty ,KFI.UnitCost,KT.[Quantity]
                                            FROM [KBELTreeItems] KT JOIN KanBanElectronicsFinishedItemMaster KFI on KT.ItemCode=KFI.ItemCode  where ParentID= '" + NodeID + "' order by (KT.[Quantity]*KFI.UnitCost) desc", SQLCon);
                        break;

                    case 31:
                        SQLCmd = new SqlCommand(@"SELECT KT.[ItemCode],KFI.ItemDescription,KFI.Units
                                           ,KFI.AvailableQty ,KFI.UnitCost,KT.[Quantity]
                                            FROM [KBELTreeItems] KT JOIN KanBanElectronicsItemMaster KFI on KT.ItemCode=KFI.ItemCode  where ParentID= '" + NodeID + "' order by (KT.[Quantity]*KFI.UnitCost) desc", SQLCon);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand(@"SELECT KT.[ItemCode],KFI.ItemDescription,KFI.Units
                                            ,KFI.UnitCost,KFI.AvailableQty,KT.[Quantity]
                                            FROM [KBELTreeItems] KT JOIN KanBanItemMaster KFI on KT.ItemCode=KFI.ItemCode  where ParentID= '" + NodeID + "' order by (KT.[Quantity]*KFI.UnitCost) desc", SQLCon);
                        break;

                    case 5:
                        SQLCmd = new SqlCommand(@"SELECT  PB.[ItemCode], PB.[ItemDescription], PB.[ItemType],Units,[BOMQuantity],AvailableQty, PB.[Unitprice],0 as LatestCost,[AddedBy],[AddedDate] FROM [KanBanElectronicsProjectBOM] PB join KanBanElectronicsItemMaster KB on PB.ItemCode=KB.ItemCode where  Projectcode='" + NodeID + "' and PB.ItemType='ElectronicsItem' union all SELECT  PB.[ItemCode], PB.[ItemDescription], PB.[ItemType],Units,[BOMQuantity],AvailableQty, PB.[Unitprice],0 as LatestCost,[AddedBy],[AddedDate] FROM [KanBanElectronicsProjectBOM] PB join KanBanElectronicsFinishedItemMaster KB on PB.ItemCode=KB.ItemCode where  Projectcode='" + NodeID + "' and PB.ItemType='ElectronicsFG'", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

