                                                     case when [ProductCode]='' then ''  else   [ProductDescription] end as [Description] from 
                                                     [QuoteBOMItems] where QuotationNumber='" + sQuotationNumber + "' and RevisionNumber='" + sRevisionNumber + "' order by GroupID asc", SQLCon);
                        break;

                    case 10:
                        SQLCmd = new SqlCommand(@" Select case when [ProductCode]='' then [ProductName]  else   ProductCode end as [Model Number],
                                                   case when [ProductCode]='' then ''  else   [ProductDescription] end as [Description],nullif([Quantity], 0) as Quantity,'' as [TotalPrice] from
                                                   [QuoteBOMOptionalItems] where QuotationNumber='" + sQuotationNumber + "' and RevisionNumber='" + sRevisionNumber + "' order by id asc", SQLCon);
                        break;
                    case 110:

