                    case 20:
                        SQLCmd = new SqlCommand(@"Select * from  [EnquiryRegisterDetails] where EnquiryNumber='" + sQuotationNumber + "' ", SQLCon);

                        break;

                    case 21:
                        SQLCmd = new SqlCommand(@"Select case when [ProductCode]='' then [ProductName]  else   ProductCode end as [Model Number],
                                                  case when [ProductCode]='' then ''  else   [ProductName] end as [Description],nullif([Quantity], 0) as Quantity,                                                 
                                                   case when (ProductCode!='' and ShowPrice='No') then null else TotalPrice  end as TotalPrice from
                                                  [QuoteBOMItems]   where QuotationNumber='" + sQuotationNumber + "' and RevisionNumber='" + sRevisionNumber + "' order by GroupID asc", SQLCon);
                        break;
                    // case when [BreakupTotal]> 0 then null  else (round(nullif([BreakupTotal], 0),0)) end as UnitPrice ,
                    case 22:
                        SQLCmd = new SqlCommand(@"Select case when [ProductCode]='' then [ProductName]  else   ProductCode end as [Model Number],
                                                  case when [ProductCode]='' then ''  else   [ProductDescription] end as [Description] from
