                    //                        SQLCmd = new SqlCommand(@"Select case when [ProductCode]='' then [ProductName]  else   ProductCode end as [Model Number],
                    //                                                  case when [ProductCode]='' then ''  else   [ProductName] end as [Description],nullif([Quantity], 0) as Quantity,                                               
