        public int fnAddNC(uint uInOrUPOrDel, string NCNumber, string RequestBy, string RequestDept, string ProjectCode, string AssignedTo, string AssignedDept, string Environment, string Priority, string NCType, string DescriptionOfNC, string NCDate, string sObjectiveEvidence, string Product, string SubProduct, string sObservation, string SupplierName)
        {
            Global GlobalClass = new Global();
            try
            {
                SQLCon.Open();
                switch (uInOrUPOrDel)
                {
                    case Global.uINSERT:
                        {
                            SQLCmd = new SqlCommand("Insert into NCForm([NCNumber],[RequestBy],[RequestDept],[ProjectCode],[AssignedTo],[AssignedDept],[Environment],[Priority],[NCType],[DescriptionOfNC],NCDate,ObjectiveEvidence,Product,SubProduct,Observation,SupplierName) values('" + NCNumber + "','" + RequestBy + "','" + RequestDept + "','" + ProjectCode + "','" + AssignedTo + "','" + AssignedDept + "','" + Environment + "','" + Priority + "','" + NCType + "','" + DescriptionOfNC + "','" + NCDate + "','" + sObjectiveEvidence + "','" + Product + "','" + SubProduct + "','" + sObservation + "','" + SupplierName + "')", SQLCon);
                            break;
                        }
                    case Global.uUPDATE:
                        {
                            SQLCmd = new SqlCommand("Update NCForm set  ProjectCode='" + ProjectCode + "',AssignedTo='" + AssignedTo + "',AssignedDept='" + AssignedDept + "',Environment='" + Environment + "',Priority='" + Priority + "',NCType='" + NCType + "',DescriptionOfNC='" + DescriptionOfNC + "',ObjectiveEvidence='" + sObjectiveEvidence + "',Product='" + Product + "',SubProduct='" + SubProduct + "',Observation='" + sObservation + "'  where NCNumber='" + NCNumber + "'", SQLCon);
                            break;
                        }
                    case Global.uDELETE:
                        {
                            //  SQLCmd = new SqlCommand("Delete  from Indent where IndentNo='" + sIndentNo + "'and status='Open'", SQLCon);
                            break;
                        }
                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }


