        public DataSet fnLoadNCNumber(string sUserName, string sNCNumber, int iUserList)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sUserName == null && sNCNumber != null && iUserList == 0)
                {
                    SQLCmd = new SqlCommand("Select * from NCForm Where NCNumber='" + sNCNumber + "' order by ID asc", SQLCon);
                }
                else if (sUserName != null && sNCNumber == null && iUserList == 1)
                {
                    SQLCmd = new SqlCommand("Select * from NCForm where DescriptionAcceptReject is null and AssignedTo='" + sUserName + "'  order by  ID asc", SQLCon);
                }
                else if (sUserName != null && sNCNumber == null && iUserList == 2)
                {
                    SQLCmd = new SqlCommand("Select * from NCForm where DescriptionAcceptReject=0 and RequestBy='" + sUserName + "'  order by  ID asc", SQLCon);
                }
                else if (sUserName != null && sNCNumber == null && iUserList == 3)
                {
                    SQLCmd = new SqlCommand("Select * from NCForm where DescriptionAcceptReject=1 and CorrectionRequestedAcceptReject is null and RootCauseAcceptReject is null and RequestBy='" + sUserName + "'  order by  ID asc", SQLCon);
                }
                else if (sUserName != null && sNCNumber == null && iUserList == 4)
                {
                    SQLCmd = new SqlCommand("Select * from NCForm where DescriptionAcceptReject=1 and CorrectionRequested is not null and RootCause is not null and (CorrectionRequestedAcceptReject is null or RootCauseAcceptReject is null) and RequestBy ='" + sUserName + "'  order by  ID asc", SQLCon);
                }
                else if (sUserName != null && sNCNumber == null && iUserList == 5)
                {
                    SQLCmd = new SqlCommand("Select * from NCForm where DescriptionAcceptReject=1 and CorrectionRequested is not null and RootCause is not null and (CorrectionRequestedAcceptReject=0 or RootCauseAcceptReject=0 ) and AssignedTo='" + sUserName + "'  order by  ID asc", SQLCon);
                }
                else if (sUserName != null && sNCNumber == null && iUserList == 6)
                {
                    SQLCmd = new SqlCommand("Select * from NCForm where DescriptionAcceptReject=1 and CorrectionRequested is not null and RootCause is not null and CorrectionRequestedAcceptReject=1 and  RootCauseAcceptReject=1 and AcceptNCClose is null and AssignedTo='" + sUserName + "'   order by  ID asc", SQLCon);
                }
                else if (sUserName != null && sNCNumber == null && iUserList == 7)
                {
                    SQLCmd = new SqlCommand("Select * from NCForm where DescriptionAcceptReject=1 and CorrectionRequested is not null and RootCause is not null and CorrectionRequestedAcceptReject=1 and  RootCauseAcceptReject=1 and AcceptNCClose=1 and EffectivenessofNCClosure is null order by  ID asc", SQLCon);
                }
                else if (sUserName == null && sNCNumber != null && iUserList == 8)
                {
                    SQLCmd = new SqlCommand("Select * from EscalationNC Where NCNumber='" + sNCNumber + "' order by ID asc", SQLCon);
                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

