        public DataSet fnNCUserReport(int sReportType, string sUser)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (sReportType)
                {
                    case 1:

                        SQLCmd = new SqlCommand(@"SELECT row_number() over(order by N.ID) as [SlNo],NCNumber,N.ProjectCode,ProjectDescription,convert(date,[NCDate],105) as [Date Opened],
                                              RequestBy as [Created by],AssignedTo,Priority,NCType,SupplierName, convert(date,[CloseDate],105) as [Date Closed],
                                              DescriptionOfNC as [Description],CorrectionRequested as [Correction],convert(date,[PDC1],105) as [PDC1],
                                              CASE WHEN CorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CorrectionStatus ,CorrectionDate,RootCause,
                                             CorrectiveAction,ObjectiveEvidenceFound as ObjectiveEvidence,
                                             CASE WHEN CACorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CACorrectionStatus ,CADate,
                                                Disposition,CostIncurred FROM [NCForm] N join ProjectMaster PM on N.ProjectCode=PM.ProjectCode where RequestBy='" + sUser + "' or AssignedTo='" + sUser + "'   order by N.ID asc", SQLCon);
                        break;

                    case 2:
                        SQLCmd = new SqlCommand("Select * from NCForm Where sNCNumber='" + sReportType + "' order by ID asc", SQLCon);
                        break;

                    case 3:
                        SQLCmd = new SqlCommand(@"SELECT row_number() over(order by N.ID) as [SlNo],NCNumber,N.ProjectCode,ProjectDescription,convert(date,[NCDate],105) as [Date Opened],
                                              RequestBy as [Created by],AssignedTo,Priority,NCType, convert(date,[CloseDate],105) as [Date Closed],
                                              DescriptionOfNC as [Description],CorrectionRequested as [Correction],convert(date,[PDC1],105) as [PDC1],
                                              CASE WHEN CorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CorrectionStatus ,CorrectionDate,RootCause,
                                             CorrectiveAction,ObjectiveEvidenceFound as ObjectiveEvidence,
                                             CASE WHEN CACorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CACorrectionStatus ,CADate,
                                                Disposition,CostIncurred FROM [NCForm] N join ProjectMaster PM on N.ProjectCode=PM.ProjectCode where AssignedTo='" + sUser + "' and CorrectionRequested is not null and ( CorrectionStatus is null or  CorrectionStatus='0') order by N.ID asc", SQLCon);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand(@"SELECT row_number() over(order by N.ID) as [SlNo],NCNumber,N.ProjectCode,ProjectDescription,convert(date,[NCDate],105) as [Date Opened],
                                              RequestBy as [Created by],AssignedTo,Priority,NCType, convert(date,[CloseDate],105) as [Date Closed],
                                              DescriptionOfNC as [Description],CorrectionRequested as [Correction],convert(date,[PDC1],105) as [PDC1],
                                              CASE WHEN CorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CorrectionStatus ,CorrectionDate,RootCause,
                                             CorrectiveAction,ObjectiveEvidenceFound as ObjectiveEvidence,
                                             CASE WHEN CACorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CACorrectionStatus ,CADate,
                                                Disposition,CostIncurred FROM [NCForm] N join ProjectMaster PM on N.ProjectCode=PM.ProjectCode where RequestBy='" + sUser + "' and CorrectionRequested is not null and  CorrectionStatus='1'  order by N.ID asc", SQLCon);
                        break;

                    case 5:
                        SQLCmd = new SqlCommand(@"SELECT row_number() over(order by N.ID) as [SlNo],NCNumber,N.ProjectCode,ProjectDescription,convert(date,[NCDate],105) as [Date Opened],
                                              RequestBy as [Created by],AssignedTo,Priority,NCType, convert(date,[CloseDate],105) as [Date Closed],
                                              DescriptionOfNC as [Description],CorrectionRequested as [Correction],convert(date,[PDC1],105) as [PDC1],
                                              CASE WHEN CorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CorrectionStatus ,CorrectionDate,RootCause,
                                             CorrectiveAction,ObjectiveEvidenceFound as ObjectiveEvidence,
                                             CASE WHEN CACorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CACorrectionStatus ,CADate,
                                                Disposition,CostIncurred FROM [NCForm] N join ProjectMaster PM on N.ProjectCode=PM.ProjectCode where AssignedTo='" + sUser + "' and CorrectionRequested is not null and  CorrectionStatus='1' and CorrectiveAction is not null and CACorrectionStatus is null order by N.ID asc", SQLCon);
                        break;


                    case 6:
                        SQLCmd = new SqlCommand(@"SELECT row_number() over(order by N.ID) as [SlNo],NCNumber,N.ProjectCode,ProjectDescription,convert(date,[NCDate],105) as [Date Opened],
                                              RequestBy as [Created by],AssignedTo,Priority,NCType, convert(date,[CloseDate],105) as [Date Closed],
                                              DescriptionOfNC as [Description],CorrectionRequested as [Correction],convert(date,[PDC1],105) as [PDC1],
                                              CASE WHEN CorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CorrectionStatus ,CorrectionDate,RootCause,
                                             CorrectiveAction,ObjectiveEvidenceFound as ObjectiveEvidence,
                                             CASE WHEN CACorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CACorrectionStatus ,CADate,
                                                Disposition,CostIncurred FROM [NCForm] N join ProjectMaster PM on N.ProjectCode=PM.ProjectCode where RequestBy='" + sUser + "' and CorrectionRequested is not null and  CorrectionStatus='1' and CorrectiveAction is not null and CACorrectionStatus='1' order by N.ID asc", SQLCon);
                        break;

                    case 7:
                        SQLCmd = new SqlCommand(@"SELECT row_number() over(order by N.ID) as [SlNo],NCNumber,N.ProjectCode,ProjectDescription,convert(date,[NCDate],105) as [Date Opened],AssignedDept,
                                              RequestBy as [Created by],AssignedTo,Priority,NCType, convert(date,[CloseDate],105) as [Date Closed],
                                              DescriptionOfNC as [Description],CorrectionRequested as [Correction],convert(date,[PDC1],105) as [PDC1],
                                              CASE WHEN CorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CorrectionStatus ,CorrectionDate,RootCause,
                                             CorrectiveAction,ObjectiveEvidenceFound as ObjectiveEvidence,
                                             CASE WHEN CACorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CACorrectionStatus ,CADate,
                                                Disposition,CostIncurred FROM [NCForm] N join ProjectMaster PM on N.ProjectCode=PM.ProjectCode order by N.ID asc", SQLCon);
                        break;
                    case 8:
                        SQLCmd = new SqlCommand(@"SELECT row_number() over(order by N.ID) as [SlNo],NCNumber,N.ProjectCode,ProjectDescription,convert(date,[NCDate],105) as [Date Opened],AssignedDept,
                                              RequestBy as [Created by],AssignedTo,Priority,NCType, convert(date,[CloseDate],105) as [Date Closed],
                                              DescriptionOfNC as [Description],CorrectionRequested as [Correction],convert(date,[PDC1],105) as [PDC1],
                                              CASE WHEN CorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CorrectionStatus ,CorrectionDate,RootCause,
                                             CorrectiveAction,ObjectiveEvidenceFound as ObjectiveEvidence,
                                             CASE WHEN CACorrectionStatus = 1 THEN 'Closed' ELSE 'Open' END as CACorrectionStatus ,CADate,
                                                Disposition,CostIncurred FROM [NCForm] N join ProjectMaster PM on N.ProjectCode=PM.ProjectCode where [AssignedDept]='" + sUser + "'order by N.ID asc", SQLCon);
                        break;

                    case 9:
                        SQLCmd = new SqlCommand(@"SELECT  EN.[NCNumber],[ReviewMeeting],[RequestBy],[RequestDept],EN.[ProjectCode],[AssignedTo],[AssignedDept],[SalesTerritory],[Priority],[NCType] ,[Product],[SubProduct],[DescriptionOfNC] ,[Observation],[ObjectiveEvidence],[NCReviewComments],[NCDate],[Disposition],[PDC1],[CorrectionRequested],[RootCause],[PDC2],[CorrectiveAction],[ObjectiveEvidenceFound]
                                                 ,[AcceptNCClose],[CostIncurred],[CloseDate],[CorrectionCloseDate],[CorrectiveActionCloseDate],[EffectivenessofNCClosure]
                                                    ,[CorrectionStatus],[CorrectionDate],[CACorrectionStatus],[CADate],[ManHours],[SupplierName],[Reminder],[QsrEscOwner],[ProductLine],[COESite]
                                                    ,[Location],[NCClose],[NCCloseDate],[RCAReq],[ClosureDetails],[ReviewTeam],[MOM] ,[ActionPlan] ,[ResolutionDate],[EscalationLavel],[UserDate] ,[closure],[closureDate]
                                                    FROM [EscalationNC] EN left join [EscalationReviewMeeting] EM on En.NCNumber=EM.NCNumber", SQLCon);

                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

