                        SQLCmd = new SqlCommand("Select * from TestQuoteDetails order by id desc", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand("Select * from TestQuoteDetails where QuotationNumber='" + QuotationNumber + "' order by id desc", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand("Select [SlNo],[Specifications],[Quantity],[UnitCost],[Amount],isnull(Discount,0) as Discount,SP from TestQuoteItems where QuotationNumber='" + QuotationNumber + "' order by id asc", SQLCon);
                        break;
                    case 32:
                        SQLCmd = new SqlCommand("Select '1.0' as [SlNo],[Specifications],[Quantity],[UnitCost],[Amount],isnull(Discount,0) as Discount,SP from TestQuoteItems where QuotationNumber='" + QuotationNumber + "' order by id asc", SQLCon);
                        break;
                    case 31:
                        SQLCmd = new SqlCommand("Select [SlNo],[Specifications], case when ( SP='No') then null else Quantity  end as [Quantity] , case when ( SP='No') then null else UnitCost  end as [UnitCost], case when ( SP='No') then null else Amount  end as [Amount],isnull(Discount,0) as Discount,SP from TestQuoteItems where QuotationNumber='" + QuotationNumber + "' order by id asc", SQLCon);
                        break;
                    case 4:
                        SQLCmd = new SqlCommand("Select * from TestQuoteDetails order by id asc", SQLCon);
                        break;

                    case 5:
                        SQLCmd = new SqlCommand("Select * from TestQuoteDetails where QuotationNumber like '" + QuotationNumber + "%' order by id desc", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

