                        SQLCmd = new SqlCommand(@"DECLARE @StartDate date = '" + Fromdate + "', @EndDate   date = '" + Todate + "';;WITH n(n) AS (SELECT 0 UNION ALL SELECT n + 1 FROM n WHERE n < DATEDIFF(DAY, @StartDate,  @EndDate)), d(d) AS ( SELECT DATEADD(DAY, n, @StartDate) FROM n) SELECT  DATENAME(month,(d)) as [Month], '" + sDepartment + "' as [Username], DATENAME(WEEKDAY,(d)) as [Day],concat('Week', datepart(WEEK, d)) as  [Week],d as [Date],'' as  [Software Module],'' as  [Version],'' as  [Task],'' as  [Sub Module],'' as [Remarks],0.0 as  TotalHours, '' as [Time Type]  ,'' as  [Backup Run],'' as [ProjectCode],'' as [ProjectName],'' as  [80/20],'' as [Customization] FROM d order by d asc OPTION (MAXRECURSION 0) ;", SQLCon);
