                        SQLCmd = new SqlCommand(@"SELECT OD.[QuotationNumber],OD.[RevisionNumber], QE.CustomerName,[LabType],[BusinessSector],[PrimaryInd],[PrimaryMtrl],[PrimaryMtrlDetail],[Application],[TestEnvironment],[Status],[Stage],[TypeofCustomer],0 as [OrderValue],QE.Currency,convert(date,[ExpectedOrderPlacementDate],105) as ExpectedOrderPlacementDate,[Probability],[Competition],[SpecifyOthers],[WonLost],[WonReason],[LostReason]   FROM [QuoteOpportunityDetails] OD join QuoteEnquiryDetails QE  on OD.QuotationNumber=QE.QuotationNumber and OD.RevisionNumber=QE.RevisionNumber where OD.[QuotationNumber]='" + QuotationNumber + "' and OD.[RevisionNumber]='" + RevisionNumber + "' and  convert(date,QE.[QuoteCreatedDate],105) >='" + Fromdate + "' and convert(date,QE.[QuoteCreatedDate],105) <='" + Todate + "' order by OD.QuotationNumber desc", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand(@"Select sum ([Quantity]*[UnitPrice]) as OrderValue from [QuoteBOMItems] where  QuotationNumber='" + QuotationNumber + "' and RevisionNumber='" + RevisionNumber + "'", SQLCon);
