            }
        }

        public DataSet fnComplaintList(string sComplaintNumber, int Inumber)
        {
            SQLDataset = new DataSet();
            try
            {
                SQLCon.Open();
                if (sComplaintNumber == null && Inumber == 1)
                {
                    SQLCmd = new SqlCommand("Select * from  ComplaintForm where StatusofComplaint ='' and [ComplaintRequestTo]='IT Support' order by id asc", SQLCon);
                }
                else if (sComplaintNumber == null && Inumber == 11)
                {
                    SQLCmd = new SqlCommand("Select * from  ComplaintForm where (StatusofComplaint ='' or StatusofComplaint = 'Accept') and [ComplaintRequestTo]='Maintenance Support' and CONVERT(date, ComplaintDate, 105) > '2026-01-01' and ComplaintClose is NULL order by id asc", SQLCon);
                }
                else if (sComplaintNumber != null && Inumber == 1)
                {
                    SQLCmd = new SqlCommand("Select * from ComplaintForm where ComplaintNo='" + sComplaintNumber + "' order by id desc", SQLCon);
                }
                else if (sComplaintNumber != null && Inumber == 2)
                {
                    SQLCmd = new SqlCommand(@"Select row_number() over(order by ComplaintNo) as SlNo
                                              ,[ComplaintNo],[ComaplaintBy],[Department],[Building],[WorkLocation],[WorkRequired],[TypeOfRequest],[DetailsOfWork]
                                                ,[Emergency],[ComplaintDate],[FundResourceRequired],[GMReviewRequired],[ComplaintResolvedBy],[AuthorisedBy],[AuthorisedRemarks],[StatusofComplaint] from ComplaintForm where ComaplaintBy='" + sComplaintNumber + "' order by id asc", SQLCon);
                }
                else if (sComplaintNumber == null && Inumber == 5)
                {
                    SQLCmd = new SqlCommand(@"Select row_number() over(order by ComplaintNo) as SlNo
                                              ,[ComplaintNo],[ComaplaintBy],[Department],[Building],[WorkLocation],[WorkRequired],[TypeOfRequest],[DetailsOfWork]
                                                ,[Emergency],[ComplaintDate],[FundResourceRequired],[GMReviewRequired],[ComplaintResolvedBy],[AuthorisedBy],[AuthorisedRemarks],[StatusofComplaint],CloseRemarks from ComplaintForm order by id desc", SQLCon);
                }

                else if (sComplaintNumber != null && Inumber == 3)
                {
                    SQLCmd = new SqlCommand("Select * from  ComplaintForm where ComaplaintBy='" + sComplaintNumber + "' and Rating is  null and ComplaintClose is not null order by id asc", SQLCon);
                }
                else if (Inumber == 4)
                {
                    SQLCmd = new SqlCommand("Select * from  ComplaintForm where StatusofComplaint !=''  and [ComplaintRequestTo]='IT Support' and ComplaintClose is  null order by id asc", SQLCon);
                }
                else if (Inumber == 41)
                {
                    SQLCmd = new SqlCommand("Select * from  ComplaintForm where  [ComplaintRequestTo]='Maintenance Support' and ComplaintClose is  null and CONVERT(date, ComplaintDate, 105) > '2026-01-01' order by id asc", SQLCon); //StatusofComplaint !=''
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }


