        public DataSet fnSecurityInward(int iCase, string sDocumentNumber)
        {
            SQLDataset = new DataSet();
            try
            {
                SQLCon.Open();
                switch (iCase)
                {
                    case 0:
                        SQLCmd = new SqlCommand("Select [DBOMNo] from [PurchaseOrder] where RemainingQty>0 and AuthoriedBy!='Deleted' and POGeneratedBy is not null group by [DBOMNo] order by [DBOMNo] desc", SQLCon);
                        break;
                    case 1:
                        SQLCmd = new SqlCommand(@" Select row_number() over(order by P.ID) as [SlNo], P.Itemcode,Im.ItemDescription,P.RequariedQty as RecQty,V.VendorName from [PurchaseOrder] P join ItemMaster IM on P.ItemCode=IM.ItemCode
                                                     join Vendors V on P.VendorCode=V.VendorCode Where P.DBOMNo='" + sDocumentNumber + "' and RemainingQty>0 and AuthoriedBy!='Deleted' and POGeneratedBy is not null order by P.Id asc ", SQLCon);
                        break;
                    case 2:
                        SQLCmd = new SqlCommand(" Select WONumber from WorkOrder where OPRemainingQty>0 and WOGeneratedBy is not null group by WONumber order by WONumber desc", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand(@" Select row_number() over(order by P.ID) as [SlNo], P.OPItemCode as Itemcode,Im.ItemDescription,P.OPOrderQty as RecQty,V.VendorName from WorkOrder P join ItemMaster IM on P.OPItemCode=IM.ItemCode
                                                   join Vendors V on P.VendorCode=V.VendorCode Where P.WONumber='" + sDocumentNumber + "' and OPRemainingQty>0 and WOGeneratedBy is not null order by P.Id asc ", SQLCon);
                        break;
                    case 31:
                        SQLCmd = new SqlCommand(@" Select row_number() over(order by P.ID) as [SlNo], P.IPItemCode as Itemcode,Im.ItemDescription,0 as RecievedQty,P.OPOrderQty as OrderQty,P.OPOrderQty as RecQty,V.VendorName from WorkOrder P join ItemMaster IM on P.IPItemCode=IM.ItemCode
                                                   join Vendors V on P.VendorCode=V.VendorCode Where P.WONumber='" + sDocumentNumber + "' order by P.Id asc ", SQLCon);
                        break;

                    case 4:
                        SQLCmd = new SqlCommand("Select top 1 [InwardSlNo] from SecurityInward order by InwardSlNo desc", SQLCon);
                        break;


                    case 41:
                        SQLCmd = new SqlCommand("Select top 1 [OutwardSlNo] from SecurityOutward order by OutwardSlNo desc", SQLCon);
                        break;

                    case 5:
                        SQLCmd = new SqlCommand(@"select [ItemCode], SUM([RecievingQuantity]) as [RecievingQuantity],InwardDocumentNo from [SecurityInward] where 
                                                    InwardDocumentNo='" + sDocumentNumber + "'  group by [ItemCode],InwardDocumentNo", SQLCon);
                        break;

                    case 6:
                        SQLCmd = new SqlCommand(@"select [ItemCode], SUM([SendingQuantity]) as [SendingQuantity],OutwardDocumentNo from [SecurityOutward] where 
                                                    OutwardDocumentNo='" + sDocumentNumber + "'  group by [ItemCode],OutwardDocumentNo", SQLCon);
                        break;

                    case 7:
                        SQLCmd = new SqlCommand("Select top 1 [InwardSlNo] from SecurityInward order by InwardSlNo desc", SQLCon);
                        break;

                    case 8:
                        SQLCmd = new SqlCommand("  Select OutwardNo from [SecurityOutward] order by OutwardSlNo desc", SQLCon);
                        break;

                    case 81:
                        SQLCmd = new SqlCommand(" Select * from [SecurityOutward] where OutwardNo='" + sDocumentNumber + "'", SQLCon);
                        break;
                    case 82:
                        SQLCmd = new SqlCommand(@"Select row_number() over(order by ID) as [SlNo],[ItemCode],[ItemDescription],0 as RecievedQty,
                                        [SendingQuantity] as OrderQty,[SendingQuantity] as RecQty from [SecurityOutward] where OutwardNo='" + sDocumentNumber + "'", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

