        public DataSet fnItemGinDetail(int icase, string sItemCode)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (icase)
                {
                    case 1:
                        SQLCmd = new SqlCommand("select top 5  GINNumber,CONVERT(date,(date),105) as GINDate, Quantity,UnitCost from Receipt where ItemCode='" + sItemCode + "' order by  CONVERT(date,(date),105) desc", SQLCon);
                        break;

                    case 2:
                        SQLCmd = new SqlCommand("select ItemDescription,UnitCost from ItemMaster where ItemCode='" + sItemCode + "'", SQLCon);
                        break;
                    case 3:
                        SQLCmd = new SqlCommand("select ItemCode,StdCost,UpdateBy,updatedate from ItemStdCostHistory order by ItemCode ", SQLCon);
                        break;
                    case 4:
                        SQLCmd = new SqlCommand("select top 5  GINNumber,CONVERT(date,(date),105) as GINDate, Quantity,UnitCost,LatestPurchasePrice from Receipt R join PurchaseOrder P on P.ItemCode=R.ItemCode and P.DBOMNo = R.RefNumber where  R.ItemCode='" + sItemCode + "'  and P.LatestPurchasePrice != '0' order by  CONVERT(date, (date), 105) desc ", SQLCon);
                        break;

                    case 5:
                        SQLCmd = new SqlCommand("select top 5   KANProductNo as GINNumber,CONVERT(date,(ProductionDate),105) as GINDate, Quantity,UnitCost from KanBanElectronicsProduction where ItemCode='" + sItemCode + "' order by  CONVERT(date,(ProductionDate),105) desc", SQLCon);
                        break;

                    case 6:
                        SQLCmd = new SqlCommand("select top 5  KANProductNo as GINNumber,CONVERT(date,(ProductionDate),105) as GINDate, Quantity,UnitCost from KanBanProduction where ItemCode='" + sItemCode + "' order by  CONVERT(date,(ProductionDate),105) desc", SQLCon);
                        break;
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

