        public DataSet fnJobWorkData(string fromdate, string todate, int Index)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (fromdate != null && todate != null && Index == 45)
                {
                    SQLCmd = new SqlCommand(@"select W.JWNumber,W.[WONumber] as [WorkOrder Number],convert(date,W.[WOgeneratedDate],105) as [WorkOrder Date],W.[DGRefno] as [DC NO],
                                           V.VendorName,W.[IPItemCode] as [Item Sent-JobWork],W.[IPOrderQty] as [Item Sent-JobWork Qty] ,W.[OPItemCode] as [Item-Product],
                                           Im2.ItemDescription as [Item-Product Description],W.[OPOrderQty] as [Product-Qty], W.UnitCost,W.TotalCost as Amount,W.SGSTRate,
                                           W.SGSTAmount,W.CGSTRate,W.CGSTAmount,W.IGSTRate,W.IGSTAmount,si.InwardNo, convert(date, si.[InwardDatetime], 105) as InwardDate,
                                           si.ItemCode as [Inward-Item],si.[RecievingQuantity] as [InwardQuantity],(CASE WHEN ((W.[OPOrderQty] - si.[RecievingQuantity]) = 0) 
                                           THEN 'Closed' ELSE 'Open' end) as WOStatus from WorkOrder as W  left join SecurityInward as si on si.[InwardDocumentNo] =W.WONumber 
                                           and si.ItemCode=W.OPItemCode join Vendors V on W.VendorCode = V.VendorCode join ItemMaster Im2 on W.OPItemCode=Im2.Itemcode
                                           where convert(date, W.[WOgeneratedDate],105) >= '" + fromdate + "'  and convert(date, W.[WOgeneratedDate],105) <= '" + todate + "' group by W.JWNumber,w.WONumber,convert(date,W.[WOgeneratedDate],105),W.[DGRefno],V.VendorName,W.[IPItemCode],W.[IPOrderQty],W.[OPItemCode],Im2.ItemDescription , W.[OPOrderQty],W.UnitCost,W.TotalCost,W.SGSTRate,W.SGSTAmount,W.CGSTRate,W.CGSTAmount,W.IGSTRate,W.IGSTAmount,si.InwardNo,convert(date, si.[InwardDatetime], 105),si.ItemCode,si.[RecievingQuantity],W.ID order by W.ID asc", SQLCon);

                }


                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
        public int fnaddtargetcost(int icase, string sItemCode, double targetCost, string updtedby, string Remarks)
