        public DataSet fnIndentItemCost(string ItemCode, int i)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (i == 1)
                {
                    SQLCmd = new SqlCommand("Select  [ItemCode],[ItemDescription],UnitCost FROM [ItemMaster]  where ItemCode='" + ItemCode + "' ", SQLCon);

                }
                if (i == 2)
                {
                    SQLCmd = new SqlCommand("select sum(IssuedQuantity*unitprice) as issuedamount ,(select CapexAmount from ProjectMaster where ProjectCode='" + ItemCode + "') as capexamount from Issued where Project_Code = '" + ItemCode + "' group by Project_Code ", SQLCon);
                }
                if (i == 3)
                {
                    SQLCmd = new SqlCommand("SELECT top 1 [GINNumber],sum(([Quantity]* [UnitCost]) - (COALESCE(Receipt.[DiscAmount],0)))as [Basic Value],sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / Count(GINNumber) as [Packing & Forwarding, Transportation]," +
                        "(sum(([Quantity] * [UnitCost]) - (COALESCE(Receipt.[DiscAmount], 0))) + sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))*Receipt.SGSTRate / 100 as SGSTAmount," +
                        "(sum(([Quantity] * [UnitCost]) - (COALESCE(Receipt.[DiscAmount], 0))) + sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / COUNT(GINNumber))*Receipt.CGSTRate / 100 as CGSTAmount," +
                        "(sum(([Quantity] * [UnitCost]) - (COALESCE(Receipt.[DiscAmount], 0))) + sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))*Receipt.IGSTRate / 100 as IGSTAmount," +
                        "((sum(([Quantity] * [UnitCost]) - (COALESCE(Receipt.[DiscAmount], 0)))) + ((sum(([Quantity] * [UnitCost]) - (COALESCE(Receipt.[DiscAmount], 0))) +" +
                        "(sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))) * Receipt.SGSTRate / 100) +" +
                        "((sum(([Quantity] * [UnitCost]) - (COALESCE(Receipt.[DiscAmount], 0))) + (sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))) * Receipt.CGSTRate / 100)+" +
                        "((sum(([Quantity] * [UnitCost]) - (COALESCE(Receipt.[DiscAmount], 0))) + (sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))) * Receipt.IGSTRate / 100)+" +
                        "(sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / COUNT(GINNumber))+(sum(COALESCE([CDValue], 0)))+(sum(COALESCE([CDCessAmount], 0)))+(sum(COALESCE([CDIGSTAmount], 0)))) as GrossValue " +
                        " FROM [Receipt] where GINNumber = '" + ItemCode + "' group by[GINNumber], convert(date,[Date], 105),Receipt.VendorCode ,SupplierName,Ledger,Receipt.[IGSTRate],InvoiceDate,Receipt.[SGSTRate],Receipt.[CGSTRate]", SQLCon);
                }
                if (i == 4)
                {
                    SQLCmd = new SqlCommand("SELECT [GINNumber],sum(([Quantity]* [UnitCost]) - (COALESCE(GINRt.[DiscAmount],0)))as [Basic Value],sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / Count(GINNumber) as [Packing & Forwarding, Transportation]," +
                        "(sum(([Quantity] * [UnitCost]) - (COALESCE(GINRt.[DiscAmount], 0))) + sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber)) * GINRt.SGSTRate / 100 as SGSTAmount," +
                        "(sum(([Quantity] * [UnitCost]) - (COALESCE(GINRt.[DiscAmount], 0))) + sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / COUNT(GINNumber))*GINRt.CGSTRate / 100 as CGSTAmount," +
                        "(sum(([Quantity] * [UnitCost]) - (COALESCE(GINRt.[DiscAmount], 0))) + sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))*GINRt.IGSTRate / 100 as IGSTAmount," +
                        "((sum(([Quantity] * [UnitCost]) - (COALESCE(GINRt.[DiscAmount], 0)))) + ((sum(([Quantity] * [UnitCost]) - (COALESCE(GINRt.[DiscAmount], 0))) +" +
                        "(sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))) * GINRt.SGSTRate / 100) +" +
                        "((sum(([Quantity] * [UnitCost]) - (COALESCE(GINRt.[DiscAmount], 0))) + (sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))) * GINRt.CGSTRate / 100)+" +
                        "((sum(([Quantity] * [UnitCost]) - (COALESCE(GINRt.[DiscAmount], 0))) + (sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / count(GINNumber))) * GINRt.IGSTRate / 100)+" +
                        "(sum(COALESCE([PackingForwarding], 0) + (COALESCE(TransportationFreight, 0))) / COUNT(GINNumber))) as GrossValue" +
                        " FROM GINOtherItemReceipt AS GINRt where GINNumber = '" + ItemCode + "' group by[GINNumber], GINRt.VendorCode ,VendorName,Ledger,GINRt.[IGSTRate],InvoiceDate,GINRt.[SGSTRate],GINRt.[CGSTRate]", SQLCon);
                }

                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
