                    case Global.uDELETE:
                        {
                            //  SQLCmd = new SqlCommand("Delete  from Indent where IndentNo='" + sIndentNo + "'and status='Open'", SQLCon);
                            break;
                        }
                }
                GlobalClass.iStatus = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return GlobalClass.iStatus;
            }
        }
        public DataSet fnEscalationNCNumber(int i, string sNCNumber, string level)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (i)
                {
                    case 0:
                        {
                            SQLCmd = new SqlCommand("Select top 1 ID from EscalationNC  order by  ID desc", SQLCon);
                            break;
                        }
                    case 1:
                        {
                            SQLCmd = new SqlCommand("Select top 1 Reminder1 from EscalationReminder Where NCNumber='" + sNCNumber + "' and EscalationLavel='" + level + "'  order by ID desc", SQLCon);
                            break;
                        }

