        public DataSet fnEscalationNCReport(int i, string sNCNumber, string level)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                switch (i)
                {
                    case 0:
                        {
                            SQLCmd = new SqlCommand("set dateformat dmy; Select NCNumber from EscalationNC where convert(date,NCDate,105)>='" + sNCNumber + "' and convert(date,NCDate,105)<='" + level + "' ", SQLCon);
                            break;
                        }
                    case 1:
                        {
                            SQLCmd = new SqlCommand("set dateformat dmy; select EscNC.NCNumber,PM.Customer,EscNC.ProjectCode,PM.ProjectDescription,EscNC.Location AS [Location],EscNC.DescriptionOfNC as [Description],EscNC.Product,EscNC.NCType as [Type],EscNC.NCDate as[Report Date],EscNC.RequestBy as [Reported By],EscNC.ProductLine as [Product Line],EscNC.COESite AS [COE Site],EscNC.SalesTerritory as [Sales Territory],EscNC.QsrEscOwner as[QSC/ESC Owner],EscNC.AssignedTo as [Problem Owner]," +
                                " '' as [EscalationLevel-1],'' as [ReviewMeeeting-1],'' as [ReviewTeam-1],'' [ActionPlan-1],'' as [ResolutionDate-1] , " +
                                " '' as [NC Status-2],'' as [EscalationLevel-2],'' AS [EscLevelChangeDate-2],'' as [EscalationChangeReason-2],'' as [ReviewMeeeting-2],'' as [ReviewMeetingDate-2],'' as [ReviewTeam-2],''[ActionPlan-2],'' as [ResolutionDate-2],'' as [Any Change in Closure Date-2],'' as [New Closure Date-2]," +
                                " '' as [NC Status-3],'' as [EscalationLevel-3],'' AS [EscLevelChangeDate-3],'' as [EscalationChangeReason-3],'' as [ReviewMeeeting-3],'' as [ReviewMeetingDate-3],'' as [ReviewTeam-3],''[ActionPlan-3], '' as [ResolutionDate-3],'' as [Any Change in Closure Date-3],'' as [New Closure Date-3] ," +
                                " '' as [NC Status-4],'' as [EscalationLevel-4],'' AS [EscLevelChangeDate-4],'' as [EscalationChangeReason-4],'' as [ReviewMeeeting-4],'' as [ReviewMeetingDate-4],'' as [ReviewTeam-4],''[ActionPlan-4], '' as [ResolutionDate-4],'' as [Any Change in Closure Date-4],'' as [New Closure Date-4] ," +
                                " NCClose as [ClosureStatus],ClosureDetails, NCCloseDate as [ClosureDate],RCAReq as [RCARequired ?]" +
                                " from EscalationNC as EscNC join ProjectMaster as PM on PM.ProjectCode=EscNC.ProjectCode  WHERE NCNumber='" + sNCNumber + "'", SQLCon);
                            break;
                        }

                    case 2:
                        {
                            SQLCmd = new SqlCommand("set dateformat dmy; select *,(SELECT Reason from[EscalationLevel] where[EscalationLevel].NcNumber = '" + sNCNumber + "' and[EscalationLevel].LevelCount = ER.EscalationLavel) as changereason, (SELECT ChangeDate from[EscalationLevel] where[EscalationLevel].NcNumber = '" + sNCNumber + "' and[EscalationLevel].LevelCount = ER.EscalationLavel) as changeDate from EscalationReviewMeeting as ER where ER.NCNumber = '" + sNCNumber + "' order by ID asc", SQLCon);
                            break;
                        }
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

