        public DataSet fnProjectBom(string sProjectCode, int sSearchType)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sProjectCode != null && sSearchType == 1)
                {

                    //SQLCmd = new SqlCommand("SELECT PB.[ProjectCode],POE.[PONo],POE.[PODate],POE.[ModelNumber],POE.[Remarks],QBI.[ProductDescription] AS Specification,PB.[ProductType],PB.[ProjectStatus],PB.[Version],PB.[SlNo],PB.[Deleted],QBI.QuotationNumber FROM ERP_Database.dbo.ProjectOrderEntry AS POE JOIN ERP_Database.dbo.ProjectBOM AS PB ON POE.[ProjectCode] = PB.[ProjectCode] JOIN ERP_Database.dbo.QuoteBOMItems AS QBI ON QBI.QuotationNumber = POE.[OfferNo] AND QBI.ProductCode = PB.ProductCode WHERE POE.ProjectCode='" + sProjectCode + "' order by PB.ProductCode desc", SQLCon);
                    //SQLCmd = new SqlCommand("select  QBI.[ProductDescription],QBI.QuotationNumber from ERP_Database.dbo.ProjectOrderEntry AS POE JOIN ERP_Database.dbo.QuoteBOMItems AS QBI ON QBI.QuotationNumber = POE.[OfferNo] WHERE QBI.[ProductCode] like '' and POE.[OfferNo] in (select POE.OfferNo from ERP_Database.dbo.ProjectOrderEntry AS POE  WHERE POE.ProjectCode = '" + sProjectCode + "')", SQLCon);
                    SQLCmd = new SqlCommand("SELECT DISTINCT ProductGroup,QuotationNumber FROM ERP_Database.dbo.ProjectOrderEntry AS POE JOIN ERP_Database.dbo.QuoteBOMItems AS QBI ON QBI.QuotationNumber = POE.[OfferNo] WHERE QuotationNumber IN (SELECT POE.OfferNo FROM ERP_Database.dbo.ProjectOrderEntry AS POE WHERE POE.ProjectCode = '" + sProjectCode + "') AND ProductCode IS NOT NULL AND ProductCode = ' ' ORDER BY ProductGroup ASC", SQLCon);


                }
                else if (sProjectCode != null && sSearchType == 2)
                {
                    //SQLCmd = new SqlCommand("SELECT DISTINCT ProductGroup,QuotationNumber FROM ERP_Database.dbo.ProjectOrderEntry AS POE JOIN ERP_Database.dbo.QuoteBOMItems AS QBI ON QBI.QuotationNumber = POE.[OfferNo] WHERE QuotationNumber IN (SELECT POE.OfferNo FROM ERP_Database.dbo.ProjectOrderEntry AS POE WHERE POE.ProjectCode = '" + sProjectCode + "') AND ProductCode IS NOT NULL AND ProductCode = ' ' ORDER BY ProductGroup ASC", SQLCon);
                    SQLCmd = new SqlCommand("SELECT ProjectCode, PONo, ModelNumber, ProductName, ProductDescription,'' as staus FROM ERP_Database.dbo.ProjectOrderEntry AS POE JOIN ERP_Database.dbo.QuoteBOMItems AS QBI ON QBI.QuotationNumber = POE.[OfferNo] WHERE QuotationNumber IN(SELECT POE.OfferNo FROM ERP_Database.dbo.ProjectOrderEntry AS POE WHERE POE.ProjectCode = '" + sProjectCode + "') AND ProductCode IS NOT NULL AND ProductCode = ' ' ORDER BY ProductGroup ASC", SQLCon);

                }
                else if ((sProjectCode == null && sSearchType == 3))
                {

                    SQLCmd = new SqlCommand("Select ProjectCode from ProjectBOM", SQLCon);

                }
                else if ((sProjectCode != null && sSearchType == 4))
                {
                    SQLCmd = new SqlCommand(@"
                   SELECT 
    DISTINCT B.ProductCode,
    B.ProductSerialNumber,
    B.ProductName,
    CONVERT(VARCHAR(MAX), B.ProductDescription) AS ProductDescription,  -- Convert TEXT to VARCHAR
    CONVERT(VARCHAR(MAX), B.status) AS status  -- Convert TEXT to VARCHAR
FROM (
    SELECT 
         POE.ProjectCode,
        QI.ProductCode,
        QI.ProductName,
        QI.ProductDescription,
        MP.ProductSerialNumber, 
        MP.status
    FROM 
        [ERP_Database].[dbo].[QuoteBOMItems] AS QI
    JOIN 
        [ERP_Database].[dbo].[ProjectOrderEntry] AS POE 
        ON QI.QuotationNumber = POE.OfferNo
    LEFT JOIN 
        [ERP_Database].[dbo].[MachinePassport] AS MP 
        ON QI.ProductCode = MP.ProductCodeModelNumber and POE.ProjectCode = MP.ProjectCode 
    WHERE 
        POE.ProjectCode = @ProjectCode
) AS B
WHERE 
    B.ProjectCode = @ProjectCode AND B.ProductCode != '' 

", SQLCon);

                    // Add the parameter for ProjectCode
                    SQLCmd.Parameters.AddWithValue("@ProjectCode", sProjectCode);
                }


                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        public DataSet fnQuoteBOMItemsselectsubproducttype(string sprojectcode, string sproducttype, int sSearchType)
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                if (sprojectcode != null && sSearchType == 2)
                {

                    //SQLCmd = new SqlCommand("select QBI.ProductDescription from ERP_Database.dbo.ProjectOrderEntry AS POE  JOIN ERP_Database.dbo.QuoteBOMItems AS QBI ON QBI.QuotationNumber = POE.[OfferNo] WHERE QBI.ProductCode <> '' and QBI.Productgroup='" + sproducttype + "' and POE.OfferNo='" + QuotationNumber + "'", SQLCon);

                    SQLCmd = new SqlCommand(@"SELECT GroupID, ProductName, ProductDescription FROM (SELECT QBI.GroupID, QBI.ProductName, ProductGroup, [ProductDescription], POE.ProjectCode, POE.OfferNo,ROW_NUMBER() OVER (PARTITION BY QBI.GroupID ORDER BY QBI.GroupID) AS RowNum FROM ERP_Database.dbo.ProjectOrderEntry AS POE JOIN ERP_Database.dbo.QuoteBOMItems AS QBI ON QBI.QuotationNumber = POE.[OfferNo] WHERE QuotationNumber IN (SELECT POE.OfferNo FROM ERP_Database.dbo.ProjectOrderEntry AS POE WHERE POE.ProjectCode = '" + sprojectcode + "') AND ProductCode IS NOT NULL AND ProductCode != ' ' AND ProductGroup = '" + sproducttype + "') AS Ranked WHERE RowNum = 1 ORDER BY ProductGroup ASC", SQLCon);
                }
                SQLCmd.ExecuteNonQuery();
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;

            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
