        public int fnMachinePassportUpdate(int iVal, string sprojectcode, string sprojectcatagary, string alltype, string ProductSerialNumber, string Deviation, string CapacityOrRange, string VersionNo, string ScCardType, int NoOfCards, string ConnectedTo, string ApplicationDescription, string ShuntValue, string OperatingSystem, string ServiceTag, string Remarks, string status)
        {
            Global GlobalClass = new Global();

            try
            {
                // Ensure the connection is open
                if (SQLCon.State == ConnectionState.Closed)
                {
                    SQLCon.Open();
                }

                using (SqlCommand SQLCmd = new SqlCommand())
                {
                    SQLCmd.Connection = SQLCon;

                    switch (iVal)
                    {
                        case 1: // Update case
                            SQLCmd.CommandText =
                                "UPDATE [dbo].[MachinePassport] " +
                                "SET [Deviation] = @Deviation, " +
                                "[CapacityOrRange] = @CapacityOrRange, " +
                                // "[Specification] = @Specification, " +
                                "[VersionNo] = @VersionNo, " +
                                "[ScCardType] = @ScCardType, " +
                                "[NoOfCards] = @NoOfCards, " +
                                "[ConnectedTo] = @ConnectedTo, " +
                                "[ApplicationDescription] = @ApplicationDescription, " +
                                "[ShuntValue] = @ShuntValue, " +
                                "[OperatingSystem] = @OperatingSystem, " +
                                "[ServiceTag] = @ServiceTag, " +
                                "[Remarks] = @Remarks, " +
                                "[status] = @status " +
                                "WHERE ProjectCode = @ProjectCode AND ProductCategory = @ProductCategory AND AllType = @AllType  AND ProductSerialNumber=@ProductSerialNumber";

                            // Add parameters
                            SQLCmd.Parameters.AddWithValue("@Deviation", Deviation ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@CapacityOrRange", CapacityOrRange ?? (object)DBNull.Value);
                            // SQLCmd.Parameters.AddWithValue("@Specification", Specification ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@VersionNo", VersionNo ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@ScCardType", ScCardType ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@NoOfCards", NoOfCards);
                            SQLCmd.Parameters.AddWithValue("@ConnectedTo", ConnectedTo ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@ApplicationDescription", ApplicationDescription ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@ShuntValue", ShuntValue ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@OperatingSystem", OperatingSystem ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@ServiceTag", ServiceTag ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@Remarks", Remarks ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@status", status ?? (object)DBNull.Value);
                            SQLCmd.Parameters.AddWithValue("@ProjectCode", sprojectcode);
                            SQLCmd.Parameters.AddWithValue("@ProductCategory", sprojectcatagary);
                            SQLCmd.Parameters.AddWithValue("@AllType", alltype);
                            SQLCmd.Parameters.AddWithValue("@ProductSerialNumber", ProductSerialNumber);


                            break;
                    }

                    // Execute the command and get the number of affected rows
                    GlobalClass.iSuccess = SQLCmd.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error: " + ex.Message);
                return 0; // Indicate failure
            }
            return GlobalClass.iSuccess;
        }



