        /// <summary>
        /// PO approval amount thresholds (Amount + GST).
        /// &lt;= 50,000 → PC can finalize.
        /// &gt; 50,000 and &lt;= 2,50,000 → Vivek G / OM approval.
        /// &gt; 2,50,000 → GM approval after OM.
        /// </summary>
        public const decimal PO_OM_THRESHOLD = 50000m;
        public const decimal PO_GM_THRESHOLD = 250000m;

        /// <summary>
        /// Returns TotalAmount (Amount+GST), BaseAmount, GSTAmount, ApprovalTier,
        /// NextApprover, PCApprovalCase (9 or 10), OMApprovalCase (19 or 17).
        /// </summary>
        public DataSet fnGetPOAmountWithGST(string poNumber)
        {
            try
            {
                if (SQLCon == null || string.IsNullOrWhiteSpace(SQLCon.ConnectionString))
                    fnGetConnectionString();

                SQLDataset = new DataSet();
                SQLCon.Open();
                SQLCmd = new SqlCommand(@"
SELECT
    ISNULL(SUM(ISNULL(Amount, 0) + ISNULL(IGSTAmount, 0) + ISNULL(SGSTAmount, 0) + ISNULL(CGSTAmount, 0)), 0) AS TotalAmount,
    ISNULL(SUM(ISNULL(Amount, 0)), 0) AS BaseAmount,
    ISNULL(SUM(ISNULL(IGSTAmount, 0) + ISNULL(SGSTAmount, 0) + ISNULL(CGSTAmount, 0)), 0) AS GSTAmount
FROM PurchaseOrder
WHERE DBOMNo = @poNumber", SQLCon);
                SQLCmd.Parameters.AddWithValue("@poNumber", poNumber ?? "");
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();

                // Attach approval-route columns for the UI / legacy PurchaseOrder form
                if (SQLDataset.Tables.Count > 0)
                {
                    DataTable t = SQLDataset.Tables[0];
                    if (!t.Columns.Contains("ApprovalTier")) t.Columns.Add("ApprovalTier", typeof(string));
                    if (!t.Columns.Contains("NextApprover")) t.Columns.Add("NextApprover", typeof(string));
                    if (!t.Columns.Contains("PCApprovalCase")) t.Columns.Add("PCApprovalCase", typeof(int));
                    if (!t.Columns.Contains("OMApprovalCase")) t.Columns.Add("OMApprovalCase", typeof(int));

                    foreach (DataRow row in t.Rows)
                    {
                        decimal total = row["TotalAmount"] == DBNull.Value ? 0m : Convert.ToDecimal(row["TotalAmount"]);
                        var route = GetPOApprovalRoute(total);
                        row["ApprovalTier"] = route.Tier;
                        row["NextApprover"] = route.NextApprover;
                        row["PCApprovalCase"] = route.PCCase;
                        row["OMApprovalCase"] = route.OMCase;
                    }
                }

                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show("fnGetPOAmountWithGST: " + ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        /// <summary>
        /// Approval route from PO total (Amount + GST).
        /// PCCase: 9 = PC finalizes, 10 = send to OM.
        /// OMCase: 19 = OM finalizes (Vivek G band), 17 = OM then GM.
        /// Compatible with .NET Framework 4.5 (no ValueTuple).
        /// </summary>
        public static POApprovalRoute GetPOApprovalRoute(decimal totalWithGst)
        {
            POApprovalRoute route = new POApprovalRoute();

            // <= 50,000 — Purchase Committee can fully approve
            if (totalWithGst <= PO_OM_THRESHOLD)
            {
                route.Tier = "PC_FINAL";
                route.NextApprover = "Purchase Committee (final)";
                route.PCCase = 9;
                route.OMCase = 19;
                return route;
            }

            // > 50,000 and <= 2,50,000 — Vivek G / OM can finalize
            if (totalWithGst <= PO_GM_THRESHOLD)
            {
                route.Tier = "OM_REQUIRED";
                route.NextApprover = "Vivek G / OM";
                route.PCCase = 10;
                route.OMCase = 19;
                return route;
            }

            // > 2,50,000 — GM required after OM
            route.Tier = "GM_REQUIRED";
            route.NextApprover = "GM (after OM)";
            route.PCCase = 10;
            route.OMCase = 17;
            return route;
        }

        /// <summary>Convenience: which PC DAL case (9/10) to call for this PO.</summary>
        public int fnGetPCApprovalCase(string poNumber)
        {
            DataSet ds = fnGetPOAmountWithGST(poNumber);
            if (ds == null || ds.Tables.Count == 0 || ds.Tables[0].Rows.Count == 0)
                return 10;
            return Convert.ToInt32(ds.Tables[0].Rows[0]["PCApprovalCase"]);
        }

        /// <summary>Convenience: which OM DAL case (19/17) to call for this PO (Vivek G).</summary>
        public int fnGetOMApprovalCase(string poNumber)
        {
            DataSet ds = fnGetPOAmountWithGST(poNumber);
            if (ds == null || ds.Tables.Count == 0 || ds.Tables[0].Rows.Count == 0)
                return 17;
            return Convert.ToInt32(ds.Tables[0].Rows[0]["OMApprovalCase"]);
        }

        public DataSet fnPOStatusList(string statusFilter, string poNumber, string vendor, string project, DateTime? fromDate, DateTime? toDate)
        {
            try
            {
                if (SQLCon == null || string.IsNullOrWhiteSpace(SQLCon.ConnectionString))
                    fnGetConnectionString();

                SQLDataset = new DataSet();
                SQLCon.Open();

                bool filterStatus = !string.IsNullOrWhiteSpace(statusFilter)
                    && !statusFilter.Equals("All", StringComparison.OrdinalIgnoreCase);

                var sql = new System.Text.StringBuilder();
                sql.Append(@"
;WITH Filtered AS
(
    SELECT *
    FROM PurchaseOrder P
    WHERE 1 = 1");

                if (!string.IsNullOrWhiteSpace(poNumber))
                    sql.Append(" AND P.DBOMNo LIKE @poNumber");
                if (!string.IsNullOrWhiteSpace(vendor))
                    sql.Append(" AND P.VendorCode LIKE @vendor");
                if (!string.IsNullOrWhiteSpace(project))
                    sql.Append(" AND P.ProjectCode LIKE @project");
                if (fromDate.HasValue)
                    sql.Append(" AND TRY_CONVERT(date, P.POPreparedDate, 105) >= @fromDate");
                if (toDate.HasValue)
                    sql.Append(" AND TRY_CONVERT(date, P.POPreparedDate, 105) <= @toDate");

                sql.Append(@"
),
Agg AS
(
    SELECT
        DBOMNo,
        -- Base Amount + line GST (IGST/SGST/CGST) — used for approval thresholds
        SUM(ISNULL(Amount, 0)
            + ISNULL(IGSTAmount, 0)
            + ISNULL(SGSTAmount, 0)
            + ISNULL(CGSTAmount, 0)) AS TotalAmount,
        SUM(ISNULL(Amount, 0)) AS BaseAmount,
        SUM(ISNULL(IGSTAmount, 0) + ISNULL(SGSTAmount, 0) + ISNULL(CGSTAmount, 0)) AS GSTAmount,
        SUM(ISNULL(RequariedQty, 0)) AS TotalQty,
        SUM(ISNULL(RemainingQty, 0)) AS RemainingQty,
        MAX(CAST(ISNULL(PMApproved, 0) AS INT)) AS PMApproved,
        MAX(CAST(ISNULL(MHApproved, 0) AS INT)) AS MHApproved,
        MAX(CAST(ISNULL(OMApproved, 0) AS INT)) AS OMApproved,
        MAX(CAST(ISNULL(POApproved, 0) AS INT)) AS POApproved
    FROM Filtered
    GROUP BY DBOMNo
),
Head AS
(
    SELECT *
    FROM
    (
        SELECT
            F.*,
            ROW_NUMBER() OVER (PARTITION BY F.DBOMNo ORDER BY F.ID) AS rn
        FROM Filtered F
    ) X
    WHERE X.rn = 1
),
Result AS
(
    SELECT
        H.DBOMNo AS PONumber,
        H.ProjectCode,
        H.VendorCode,
        H.PreparedBy,
        H.POPreparedDate AS PreparedDate,
        H.PODeliveryDate AS DeliveryDate,
        H.Currency,
        A.TotalAmount,
        A.BaseAmount,
        A.GSTAmount,
        A.TotalQty,
        A.RemainingQty,
        H.PMName,
        H.PMApprovedDate,
        A.PMApproved,
        CONVERT(VARCHAR(MAX), H.PMRemarks) AS PMRemarks,
        H.MHName,
        H.MHApprovedDate,
        A.MHApproved,
        CONVERT(VARCHAR(MAX), H.PMMHRemarks) AS PMMHRemarks,
        H.FinalizedBy,
        H.FinalizedDate,
        CONVERT(VARCHAR(MAX), H.FinalizedRemarks) AS FinalizedRemarks,
        H.PurchaseCommitee,
        H.PCAuthoriseDate,
        CONVERT(VARCHAR(MAX), H.PCRemarks) AS PCRemarks,
        H.OMName,
        H.OMApprovedDate,
        A.OMApproved,
        H.OMRemarks,
        H.GMName,
        H.GMApprovedDate,
        A.POApproved,
        H.POGeneratedBy,
        H.POGeneratedDate,
        H.POSenttoVendorBy,
        H.POSentVendorDate,
        ISNULL(H.FinalStatus, '') AS FinalStatus,
        ISNULL(H.FinalComment, '') AS FinalComment,
        CONVERT(VARCHAR(MAX), H.RejectReason) AS RejectReason,
        ISNULL(H.AuthoriedBy, '') AS AuthoriedBy,
        CONVERT(VARCHAR(MAX), H.Remarks) AS Remarks,
        CASE
            WHEN ISNULL(H.FinalStatus, '') = 'Cancelled'
                 OR (ISNULL(H.AuthoriedBy, '') = 'Deleted' AND ISNULL(H.FinalStatus, '') = 'Cancelled')
                THEN 'Cancelled'
            WHEN ISNULL(H.FinalStatus, '') = 'Closed'
                THEN 'Closed'
            WHEN ISNULL(H.AuthoriedBy, '') = 'Deleted'
                 OR ISNULL(H.POGeneratedBy, '') = 'Deleted'
                THEN 'Deleted'
            WHEN CONVERT(VARCHAR(MAX), H.RejectReason) IS NOT NULL
                 AND LTRIM(RTRIM(CONVERT(VARCHAR(MAX), H.RejectReason))) <> ''
                 AND A.POApproved = 0
                 AND H.PurchaseCommitee IS NULL
                THEN 'Under Review'
            WHEN H.POGeneratedBy IS NOT NULL
                 AND LTRIM(RTRIM(H.POGeneratedBy)) <> ''
                 AND H.POGeneratedBy <> 'Deleted'
                THEN
                    CASE
                        WHEN A.RemainingQty <= 0 THEN 'Fully Received'
                        WHEN A.RemainingQty < A.TotalQty THEN 'Partially Received'
                        WHEN H.POSenttoVendorBy IS NOT NULL AND LTRIM(RTRIM(H.POSenttoVendorBy)) <> ''
                            THEN 'Sent to Vendor'
                        ELSE 'PO Generated'
                    END
            WHEN A.POApproved = 1
                 AND (H.POGeneratedBy IS NULL OR LTRIM(RTRIM(ISNULL(H.POGeneratedBy, ''))) = '')
                THEN 'Ready to Generate'
            -- > 2,50,000: OM (Vivek G) done, waiting GM
            WHEN A.TotalAmount > 250000
                 AND A.OMApproved = 1
                 AND H.OMName IS NOT NULL
                 AND H.OMName <> '--'
                 AND A.POApproved = 0
                 AND (H.GMName IS NULL OR LTRIM(RTRIM(ISNULL(H.GMName, ''))) = '' OR H.GMName = '--')
                THEN 'Pending GM Approval'
            -- > 50,000: PC done, waiting Vivek G / OM
            WHEN A.TotalAmount > 50000
                 AND H.PurchaseCommitee IS NOT NULL
                 AND LTRIM(RTRIM(H.PurchaseCommitee)) <> ''
                 AND A.POApproved = 0
                 AND (A.OMApproved = 0
                      OR H.OMName IS NULL
                      OR LTRIM(RTRIM(ISNULL(H.OMName, ''))) = '')
                THEN 'Pending OM Approval'
            WHEN A.PMApproved = 1
                 AND A.MHApproved = 1
                 AND (H.PurchaseCommitee IS NULL OR LTRIM(RTRIM(ISNULL(H.PurchaseCommitee, ''))) = '')
                THEN 'Pending Purchase Committee'
            WHEN A.PMApproved = 1
                 AND A.MHApproved = 0
                THEN 'Pending MH Approval'
            WHEN H.PreparedBy IS NOT NULL
                 AND (A.PMApproved = 0 OR H.PMName IS NULL)
                THEN 'Pending PM / Dept Approval'
            ELSE 'Created'
        END AS CurrentStatus
    FROM Head H
    INNER JOIN Agg A ON A.DBOMNo = H.DBOMNo
)
SELECT * FROM Result
");
                if (filterStatus)
                    sql.Append(" WHERE CurrentStatus = @statusFilter");
                sql.Append(" ORDER BY PONumber DESC");

                SQLCmd = new SqlCommand(sql.ToString(), SQLCon);
                if (!string.IsNullOrWhiteSpace(poNumber))
                    SQLCmd.Parameters.AddWithValue("@poNumber", "%" + poNumber.Trim() + "%");
                if (!string.IsNullOrWhiteSpace(vendor))
                    SQLCmd.Parameters.AddWithValue("@vendor", "%" + vendor.Trim() + "%");
                if (!string.IsNullOrWhiteSpace(project))
                    SQLCmd.Parameters.AddWithValue("@project", "%" + project.Trim() + "%");
                if (fromDate.HasValue)
                    SQLCmd.Parameters.AddWithValue("@fromDate", fromDate.Value.Date);
                if (toDate.HasValue)
                    SQLCmd.Parameters.AddWithValue("@toDate", toDate.Value.Date);
                if (filterStatus)
                    SQLCmd.Parameters.AddWithValue("@statusFilter", statusFilter);

                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show("fnPOStatusList: " + ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        /// <summary>Line items for a selected PO — PurchaseOrder table only.</summary>
        public DataSet fnPOStatusLines(string poNumber)
        {
            try
            {
                if (SQLCon == null || string.IsNullOrWhiteSpace(SQLCon.ConnectionString))
                    fnGetConnectionString();

                SQLDataset = new DataSet();
                SQLCon.Open();
                SQLCmd = new SqlCommand(@"
SELECT
    ItemCode,
    RequariedQty,
    RemainingQty,
    UnitPrice,
    Amount AS BaseAmount,
    ISNULL(IGSTAmount, 0) AS IGSTAmount,
    ISNULL(SGSTAmount, 0) AS SGSTAmount,
    ISNULL(CGSTAmount, 0) AS CGSTAmount,
    (ISNULL(Amount, 0) + ISNULL(IGSTAmount, 0) + ISNULL(SGSTAmount, 0) + ISNULL(CGSTAmount, 0)) AS AmountWithGST,
    ISNULL(Currency, '') AS Currency,
    CONVERT(VARCHAR(MAX), BOMProjectList) AS BOMProjects,
    ISNULL(IGSTRate, 0) AS IGSTRate,
    ISNULL(SGSTRate, 0) AS SGSTRate,
    ISNULL(CGSTRate, 0) AS CGSTRate
FROM PurchaseOrder
WHERE DBOMNo = @poNumber
ORDER BY ItemCode", SQLCon);
                SQLCmd.Parameters.AddWithValue("@poNumber", poNumber ?? "");
                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show("fnPOStatusLines: " + ex.Message);
                SQLCon.Close();
                return null;
            }
        }

        /// <summary>Summary counts by computed CurrentStatus for dashboard chips.</summary>
        public DataSet fnPOStatusSummary()
        {
            try
            {
                var list = fnPOStatusList("All", null, null, null, null, null);
                if (list == null || list.Tables.Count == 0)
                    return null;

                DataTable src = list.Tables[0];
                DataTable summary = new DataTable();
                summary.Columns.Add("Status", typeof(string));
                summary.Columns.Add("Count", typeof(int));

                var groups = new System.Collections.Generic.Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                foreach (DataRow row in src.Rows)
                {
                    string st = row["CurrentStatus"]?.ToString() ?? "Unknown";
                    if (!groups.ContainsKey(st)) groups[st] = 0;
                    groups[st]++;
                }
                foreach (var kv in groups)
                    summary.Rows.Add(kv.Key, kv.Value);

                SQLDataset = new DataSet();
                SQLDataset.Tables.Add(summary);
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show("fnPOStatusSummary: " + ex.Message);
                return null;
            }
        }

        public int CancelPurchaseOrder(string poNumber, string finalStatus, string finalComment, string cancelledBy, string cancelledDate)
        {
            try
            {
                SQLCon.Open();
                SQLCmd = new SqlCommand(@"
            UPDATE PurchaseOrder 
            SET FinalStatus = @finalStatus, 
                FinalComment = @finalComment, 
                CancelledBy = @cancelledBy, 
                CancelledDate = @cancelledDate,
                AuthoriedBy = 'Deleted',
                POGeneratedBy = 'Deleted'
            WHERE DBOMNo = @poNumber", SQLCon);

                SQLCmd.Parameters.AddWithValue("@finalStatus", finalStatus);
                SQLCmd.Parameters.AddWithValue("@finalComment", finalComment);
                SQLCmd.Parameters.AddWithValue("@cancelledBy", cancelledBy);
                SQLCmd.Parameters.AddWithValue("@cancelledDate", cancelledDate);
                SQLCmd.Parameters.AddWithValue("@poNumber", poNumber);

                int result = SQLCmd.ExecuteNonQuery();
                SQLCon.Close();
                return result;
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error cancelling PO: " + ex.Message);
                SQLCon.Close();
                return 0;
            }
        }


        public DataSet fnGetReminderPOs()
        {
            try
            {
                SQLDataset = new DataSet();
                SQLCon.Open();
                SQLCmd = new SqlCommand(@"
            SELECT 
                PO.DBOMNo,
                V.VendorCode,
                V.VendorName,
                V.EmailAddress AS VendorEmail,
                PO.POGeneratedDate,
                PO.PODeliveryDate,
                PO.PreparedBy,
                L1.emailid AS PreparedByEmail,
                PO.PurchaseCommitee,
                L2.emailid AS PurchaseCommiteeEmail,
                PO.POGeneratedBy,
                L3.emailid AS POGeneratedByEmail,
                DATEDIFF(DAY, GETDATE(), CONVERT(DATE, PO.PODeliveryDate, 105)) AS DaysUntilDelivery
            FROM 
                ERP_Database.dbo.PurchaseOrder PO
            INNER JOIN 
                ERP_Database.dbo.Vendors V ON PO.VendorCode = V.VendorCode
            LEFT JOIN 
                ERP_Database.dbo.Login L1 ON L1.UserName = PO.PreparedBy
            LEFT JOIN 
                ERP_Database.dbo.Login L2 ON L2.UserName = PO.PurchaseCommitee
            LEFT JOIN 
                ERP_Database.dbo.Login L3 ON L3.UserName = PO.POGeneratedBy
            WHERE 
                PO.AuthoriedBy != 'Deleted' AND 
                PO.POGeneratedBy != 'Deleted' AND 
                PO.RemainingQty != 0 AND
                DATEDIFF(DAY, GETDATE(), CONVERT(DATE, PO.PODeliveryDate, 105)) IN (7, 15)   AND
    (PO.ReminderSent IS NULL OR PO.ReminderSent = 0) AND
    PO.ReminderSentDate IS NULL GROUP BY  DBOMNo, v.VendorCode,    POGeneratedDate,	 V.EmailAddress,	 v.VendorName,    PODeliveryDate,	PreparedBy,	PurchaseCommitee,POGeneratedBy,	L1.emailid,	L2.emailid,	L3.emailid", SQLCon);

                SQLDadpr = new SqlDataAdapter(SQLCmd);
                SQLDadpr.Fill(SQLDataset);
                SQLCon.Close();
                return SQLDataset;
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message);
                SQLCon.Close();
                return null;
            }
        }
        public void UpdateReminderStatus(string poNumber)
        {
            try
            {
                SQLCon.Open();

                using (SqlCommand cmd = new SqlCommand(@"
            UPDATE ERP_Database.dbo.PurchaseOrder
            SET ReminderSent = 1, ReminderSentDate = GETDATE()
            WHERE DBOMNo = @poNumber", SQLCon))
                {
                    cmd.Parameters.AddWithValue("@poNumber", poNumber);
                    cmd.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error updating ReminderSent: " + ex.Message, "Update Error", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
            finally
            {
                if (SQLCon.State == System.Data.ConnectionState.Open)
                    SQLCon.Close();
            }
        }



